    ["Khemu"] = {
        ["If I just... stretch... a bit more... I can ALMOST touch the bottom of the oasis!"] = "Si tan sólo... me estiro... un poco más... ¡CASI puedo tocar el fondo del oasis!",
        ["Couldn't you just swim to the bottom?"] = "¿No podrías simplemente nadar hasta el fondo?",
        ["Of course, but that's no fun!"] = "Por supuesto, ¡pero eso no es divertido!",
        ["Yummy!"] = "¡Delicioso!",
        ["Khemu gobbles the steak up in the blink of an eye."] = "Khemu devora el filete en un abrir y cerrar de ojos.",
        ["Khemu! Where are your manners?"] = "¡Khemu! ¿Dónde están tus modales?",
