    ["Khorvak, a dwarven engineer"] = {
        ["Hello there."] = "Hola.",
        ["Ooooh, heeellooo! Anyshing a bright dwarf like me can help you with?"] = "¡Ooooh, holahola! ¿En qué te puede ayudar un enano brillante como yo?",
        ["The only thing you can help me with is finding the nearest place to get a drink, I think..."] = "Lo único en lo que puedes ayudarme es en encontrar el lugar más cercano para tomar una copa, creo...",
        ["That ish shimple! Help yourshelf to the dwarvern shtout! I mean dwarfen! I mean... I'm not shure what I mean."] = "¡Eso es shimple! ¡Ayúdate a luchar contra los enanos! ¡Quiero decir enano! Quiero decir... no estoy seguro de lo que quiero decir.",
    },
    ["Kili"] = {
        ["Hello Player, what can I do for you today?"] = "Hola Player, ¿qué puedo hacer por ti hoy?",
        ["Choose an option:"] = "Elige una opción:",
        ["Talk about active equipment upgrade task."] = "Hable sobre la tarea de actualización de equipo activo.",
        ["I don't have any upgrade tasks available for you at the moment."] = "No tengo ninguna tarea de actualización disponible para usted en este momento.",
        ["[You need level [number] Necromancy for the next upgrade task.]"] = "[Necesita el nivel [número] Necromancy para la siguiente tarea de actualización.]",
        ["[You need level [number] Necromancy, and must have completed 'The Spirit of War' for the next upgrade task.]"] = "[Necesita el nivel [número] Necromancy y debe haber completado 'El Spirit de War' para la siguiente tarea de actualización.]",
        ["Which upgrade would you like to work on?"] = "¿En qué actualización te gustaría trabajar?",
        ["Tier 70"] = "Nivel 70",
        ["Tier 70 (power)"] = "Nivel 70 (potencia)",
        ["Tier 80"] = "Nivel 80",
        ["Tier 80 (power)"] = "Nivel 80 (potencia)",
        ["Tier 90"] = "Nivel 90",
        ["Tier 90 (power)"] = "Nivel 90 (potencia)",
        ["Talk about equipment upgrades."] = "Hable sobre actualizaciones de equipos.",
        ["I'd like to know more about equipment upgrades."] = "Me gustaría saber más sobre las actualizaciones de equipos.",
        ["Equipment upgrades... What would you like to know about them?"] = "Mejoras de equipos... ¿Qué te gustaría saber sobre ellas?",
        ["Select an Option"] = "Selecciona una opción",
        ["How can I learn more upgrades?"] = "¿Cómo puedo obtener más actualizaciones?",
        ["How can I learn more equipment upgrades?"] = "¿Cómo puedo obtener más actualizaciones de equipo?",
        ["As you grow more powerful as a necromancer, just return to me and ask about equipment upgrade tasks."] = "A medida que te vuelvas más poderoso como nigromante, regresa conmigo y pregúntame sobre las tareas de mejora del equipo.",
        ["If you haven't grown much since completing your last task, I won't have anything more for you to do."] = "Si no has crecido mucho desde que completaste tu última tarea, no tendré nada más que hacer.",
        ["How many tasks are there?"] = "¿Cuántas tareas hay?",
        ["Hmm... I can teach you how to upgrade your necromancer's equipment from tier 20, all the way up to tier 90."] = "Hmm... Puedo enseñarte cómo mejorar el equipo de tu nigromante desde el nivel 20 hasta el nivel 90.",
        ["Once you've reached tier 70 and above, I can also teach you how to craft power armour... So that would make for a total of 10 tasks altogether!"] = "Una vez que hayas alcanzado el nivel 70 y superior, también puedo enseñarte cómo fabricar servoarmaduras... ¡Eso daría un total de 10 tareas en total!",
        ["I've already taught you everything there is to know!"] = "¡Ya te he enseñado todo lo que hay que saber!",
        ["How can I apply the upgrades I've learned?"] = "¿Cómo puedo aplicar las actualizaciones que he aprendido?",
        ["How can I apply the equipment upgrades that I've learned to my necromancer's equipment?"] = "¿Cómo puedo aplicar las mejoras de equipo que aprendí al equipo de mi nigromante?",
        ["It's simple. You'll just want to take your necromancer's equipment to my soul forge that's just over there. It will tell you what materials you'll need."] = "Es simple. Sólo querrás llevar el equipo de tu nigromante a mi forja de almas que está justo por allí. Le dirá qué materiales necesitará.",
        ["Do you need me to give you directions to the soul forge?"] = "¿Necesitas que te dé indicaciones para llegar a Soul Forge?",
        ["Would you like directions to the soul forge?"] = "¿Quieres indicaciones para llegar a Soul Forge?",
        ["Yes please."] = "Sí por favor.",
        ["No thanks, I can find it myself."] = "No gracias, puedo encontrarlo yo mismo.",
        ["Where can I get the materials needed?"] = "¿Dónde puedo conseguir los materiales necesarios?",
        ["Where can I get the materials needed to upgrade my necromancer's equipment?"] = "¿Dónde puedo conseguir los materiales necesarios para mejorar el equipo de mi nigromante?",
        ["The main things you'll need are ensouled materials - cloth, thread, and bars. These come in lesser, normal, and greater variants."] = "Lo principal que necesitarás son materiales con alma: tela, hilo y barras. Estos vienen en variantes menores, normales y mayores.",
        ["As I taught you, you'll be able to get ahold of these by performing ensoul rituals on various items from the overworld, to imbue them with necromantic energy."] = "Como te enseñé, podrás conseguirlos realizando rituales de alma en varios objetos del supramundo, para imbuirlos de energía nigromántica.",
        ["It's worth mentioning that to ensoul bars, you'll first need to smelt a variety of metals together in a furnace."] = "Vale la pena mencionar que para darle vida a las barras, primero necesitarás fundir una variedad de metales juntos en un horno.",
        ["Some upgrades may also need necromancy runes, which you can get by runecrafting impure essence to the northeast of Um, or through trading with other players."] = "Algunas mejoras también pueden necesitar runas de nigromancia, que puedes obtener elaborando runas con esencia impura al noreste de Um o intercambiando con otros jugadores.",
        ["What about a Hermodic plate?"] = "¿Qué tal un plato hermódico?",
        ["Ah yes, a Hermodic plate. You'll only need those for the higher tiered upgrades - defeating Hermod should get you some."] = "Ah, sí, un plato hermódico. Solo los necesitarás para las actualizaciones de niveles superiores; derrotar a Hermod debería conseguir algunas.",
        ["Nevermind."] = "No importa.",
        ["Show me the hard Underworld tasks I can do."] = "Muéstrame las tareas difíciles de Underworld que puedo hacer.",
        ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
        ["I've completed all the tasks in the hard Underworld task set."] = "He completado todas las tareas del conjunto de tareas difíciles de Underworld.",
        ["Well done Player, I've kept some rewards aside for you."] = "Bien hecho Player, he reservado algunas recompensas para ti.",
        ["Lupe has also agreed to provide you with a daily supply of dragon bones, greater ghostly ink and greater ritual candles in recognition of your efforts. She's also started selling a small amount of buckets of slime."] = "Lupe también acordó proporcionarte un suministro diario de huesos de dragón, tinta fantasmal mayor y velas rituales mayores en reconocimiento a tus esfuerzos. También empezó a vender una pequeña cantidad de cubos de baba.",
        ["I'm afraid you don't have enough backpack space to claim all your rewards. Speak to me again when you have 2 spaces."] = "Me temo que no tienes suficiente espacio backpack para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 2 espacios.",
        ["[You are given some rewards for completing the hard Underworld task set!]"] = "[¡Recibirás algunas recompensas por completar el difícil conjunto de tareas de Underworld!]",
        ["There you go, looks like that's everything."] = "Ahí lo tienes, parece que eso es todo.",
        ["You don't have any rewards to claim!"] = "¡No tienes ninguna recompensa que reclamar!",
        ["I lost the Underworld Grimoire 3 you gave me..."] = "Perdí el Underworld Grimoire 3 que me diste...",
        ["You don't seem to have any room for a new one, come back to me when you do."] = "Parece que no tienes espacio para uno nuevo, vuelve conmigo cuando lo tengas.",
        ["Lucky for you I have a spare. Take better care of this one."] = "Por suerte para ti, tengo uno de repuesto. Cuida mejor este.",
        ["[You're handed another Underworld Grimoire 3.]"] = "[Te entregan otro Underworld Grimoire 3.]",
        ["Ask about the Task System."] = "Pregunta por el Sistema de Tareas.",
        ["Tell me about the Task System."] = "Cuéntame sobre el sistema de tareas.",
        ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["For completing the Underworld set, you are presented with the Underworld Grimoire."] = "Por completar el conjunto Underworld, se te presenta el Grimorio de Underworld.",
        ["This book will become increasingly useful with each difficulty level of the set that you complete."] = "Este libro será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
        ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
        ["[You may also see what rewards a set item provides by hovering over the rewards icon on its corresponding achievement in the Achievements interface.]"] = "[También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de recompensas en su logro correspondiente en la interfaz de Logros.]",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["You need to complete all of the tasks in the set of a particular difficulty, then you can claim your reward. Some of the Underworld tasks are straightforward, some will require skill levels, and some might require quests to be started or completed."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. Algunas de las tareas de Underworld son sencillas, algunas requerirán skill levels y otras pueden requerir que se inicien o completen misiones.",
        ["To claim the Underworld set reward, speak to Icthlarin, Frank, Crunchy or myself."] = "Para reclamar la recompensa del conjunto Underworld, habla con Icthlarin, Frank, Crunchy o conmigo mismo.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Underworld Grimoire 1"] = "Grimorio del inframundo 1",
        ["You'll need space in your inventory."] = "Necesitarás espacio en tu inventario.",
        ["Underworld Grimoire 1? Yes, but I'm afraid it would cost you 5,000 coins."] = "¿Grimorio del inframundo 1? Sí, pero me temo que te costaría 5.000 coins.",
        ["Purchase another for 5,000 coins?"] = "¿Comprar otro por 5.000 coins?",
        ["Yes"] = "si",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["It doesn't look like you can afford it right now, though. Come back to me when you can."] = "Sin embargo, no parece que puedas permitírtelo en este momento. Vuelve conmigo cuando puedas.",
        ["[You're handed another Underworld Grimoire 1.]"] = "[Te entregan otro Grimorio 1 de Underworld.]",
        ["No thanks."] = "No, gracias.",
        ["Underworld Grimoire 2"] = "Grimorio del inframundo 2",
        ["Underworld Grimoire 2? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Grimorio del inframundo 2? Sí, pero me temo que te costaría 10.000 coins.",
        ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
        ["[You're handed another Underworld Grimoire 2.]"] = "[Te entregan otro Underworld Grimoire 2.]",
        ["Underworld Grimoire 3"] = "Grimorio del inframundo 3",
        ["Underworld Grimoire 3? Yes, but I'm afraid it would cost you 25,000 coins."] = "¿Grimorio del inframundo 3? Sí, pero me temo que te costaría 25.000 coins.",
        ["Purchase another for 25,000 coins?"] = "¿Comprar otro por 25.000 coins?",
        ["Underworld Grimoire 4"] = "Grimorio del inframundo 4",
        ["Underworld Grimoire 4? Yes, but I'm afraid it would cost you 50,000 coins."] = "¿Grimorio del inframundo 4? Sí, pero me temo que te costaría 50.000 coins.",
        ["Purchase another for 505,000 coins?"] = "¿Comprar otro por 505.000 coins?",
        ["[You're handed another Underworld Grimoire 4.]"] = "[Te entregan otro Underworld Grimoire 4.]",
        ["Choose an Option:"] = "Elige una opción:",
        ["Talk about Kili."] = "Habla de Kili.",
        ["Can you tell me a bit about yourself?"] = "¿Puedes contarme un poco sobre ti?",
        ["Ha! There's not much to know."] = "¡Ja! No hay mucho que saber.",
        ["Well, er, what do you like about Um?"] = "Bueno, ejem, ¿qué es lo que te gusta de Um?",
        ["It's nice that I get to be the sole blacksmith..."] = "Es bueno poder ser el único herrero...",
        ["Soul blacksmith?"] = "¿Herrero del alma?",
        ["As I was saying, it's nice that I get to be the only blacksmith here in the city - I get to provide for all sorts of people that pass through here!"] = "Como decía, es bueno poder ser el único herrero aquí en la ciudad. ¡Puedo atender a todo tipo de personas que pasan por aquí!",
        ["And Thalmund, ever the traveller, gets to explore all over the Underworld."] = "Y Thalmund, siempre el viajero, puede explorar todo el inframundo.",
        ["Have you ever thought of passing on?"] = "¿Alguna vez has pensado en fallecer?",
        ["Thalmund and I talk about it every now and again. Um has been our home for so long, that makes it hard to leave."] = "Thalmund y yo hablamos de ello de vez en cuando. Um ha sido nuestro hogar durante tanto tiempo que hace que sea difícil salir.",
        ["I'm sure we'll pass over at some point, but not just yet."] = "Estoy seguro de que lo pasaremos por alto en algún momento, pero no todavía.",
        ["Ask when Thalmund is visiting."] = "Pregunte cuando Thalmund esté de visita.",
        ["When is Thalmund next visiting?"] = "¿Cuándo será la próxima visita de Thalmund?",
        ["He'll be popping by in [number] days."] = "Pasará por aquí en los días [número].",
        ["He'll be popping by in 1 day."] = "Llegará en 1 día.",
        ["He's here today, just over there with his cart."] = "Hoy está aquí, justo por allá con su carrito.",
        ["Make sure to visit! He always has a good stock of wares from his travels across the Underworld."] = "¡Asegúrate de visitarlo! Siempre tiene un buen stock de mercancías de sus viajes por el inframundo.",
        ["Goodbye."] = "Adiós.",
        ["Bye!"] = "¡Adiós!",
        ["What can I help you with?"] = "¿En qué puedo ayudarte?",
        ["I'd like to learn more equipment upgrades, please!"] = "¡Me gustaría conocer más actualizaciones de equipos, por favor!",
        ["Let's get started then! The next step is to learn the tier 30 upgrade."] = "¡Empecemos entonces! El siguiente paso es aprender la actualización de nivel 30.",
        ["What's the maximum tier I can upgrade my equipment to?"] = "¿Cuál es el nivel máximo al que puedo actualizar mi equipo?",
        ["You can upgrade it every 10 tiers until it's tier 90. For tiers 70, 80, and 90 I can also give you the option of power armour, or the standard tank armour."] = "Puedes actualizarlo cada 10 niveles hasta que sea el nivel 90. Para los niveles 70, 80 y 90 también puedo darte la opción de servoarmadura o armadura de tanque estándar.",
        ["But let's not get ahead of ourselves just yet!"] = "¡Pero no nos adelantemos todavía!",
        ["Right, so where were we... Tier 30."] = "Bien, entonces, ¿dónde estábamos?... Nivel 30.",
        ["Similar to when I taught you the first upgrade, I'll need you to take this soul urn and fill it with some souls."] = "Al igual que cuando te enseñé la primera actualización, necesitaré que tomes esta urna de almas y la llenes con algunas almas.",
        ["This urn will only accept souls from killing trolls using necromancy, or completing lesser communion rituals. I need 25 troll souls, or 3 lesser communion souls."] = "Esta urna solo aceptará almas provenientes de matar trolls usando nigromancia o completando rituales de comunión menores. Necesito 25 almas troll, o 3 almas de comunión menor.",
        ["Ah, it looks like you don't have space for the soul urn. Come back when you do."] = "Ah, parece que no tienes espacio para la urna del alma. Vuelve cuando lo hagas.",
        ["Kili gives you a soul urn."] = "Kili te regala una urna para el alma.",
        ["Easy peasy. Let me just find a pen and paper to write this down..."] = "Fácil. Déjame buscar papel y lápiz para escribir esto...",
        ["Way ahead of you! I've already noted it down on a list so you can easily keep track of what's needed."] = "¡Muy por delante de ti! Ya lo he anotado en una lista para que puedas realizar un seguimiento de lo que se necesita fácilmente.",
        ["Ah, it looks like you don't have space for the equipment upgrade task list. Come back when you do."] = "Ah, parece que no tienes espacio para la lista de tareas de actualización de equipo. Vuelve cuando lo hagas.",
        ["Kili gives you an equipment upgrade task list."] = "Kili le ofrece una lista de tareas de actualización de equipos.",
        ["Nevermind then! I'll go and get those souls for you."] = "¡No importa entonces! Iré a buscar esas almas para ti.",
        ["**Select an Option**"] = "**Seleccione una opción**",
        ["Ask about your current task."] = "Pregunta sobre tu tarea actual.",
        ["I need to reclaim my equipment upgrade task list."] = "Necesito recuperar mi lista de tareas de actualización de equipo.",
        ["I can replace it for you, but you'll need to come back when you have a free space in your backpack."] = "Puedo reemplazarlo por ti, pero tendrás que regresar cuando tengas espacio libre en tu backpack.",
        ["Kili hands you a new equipment upgrade task list."] = "Kili le entrega una nueva lista de tareas de actualización de equipos.",
        ["I need to reclaim my soul urn."] = "Necesito recuperar la urna de mi alma.",
        ["Kili hands you a new soul urn."] = "Kili te entrega una nueva urna para el alma.",
        ["What do I need to do again?"] = "¿Qué debo hacer de nuevo?",
        ["Don't you have the list I gave you?"] = "¿No tienes la lista que te di?",
        ["Well, yes, but I prefer the human interaction."] = "Bueno, sí, pero prefiero la interacción humana.",
        ["Er, human-dwarf-ghost interaction."] = "Er, interacción humano-enano-fantasma.",
        ["Alright, well, I just need you to bring me some souls in that soul urn I gave you."] = "Muy bien, solo necesito que me traigas algunas almas en esa urna de almas que te di.",
        ["The urn is modified to only accept souls from killing trolls using necromancy, or completing lesser communion rituals. I need 25 troll souls, or 3 lesser communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar trolls usando nigromancia o completando rituales de comunión menores. Necesito 25 almas troll, o 3 almas de comunión menor.",
        ["Ok! I'll be off again then."] = "¡Vale! Entonces me iré de nuevo.",
        ["I filled up the soul urn!"] = "¡Lléne la urna del alma!",
        ["Great!"] = "¡Genial!",
        ["Kili takes the soul urn."] = "Kili toma la urna del alma.",
        ["So, er, what now?"] = "Entonces, eh, ¿y ahora qué?",
        ["More or less the same as the first upgrade."] = "Más o menos igual que la primera actualización.",
        ["Just follow me over to the soul forge and I'll teach you what you need to know..."] = "Sígueme hasta Soul Forge y te enseñaré lo que necesitas saber...",
        ["Kili imbues her forge with energy from the soul urn. She then explains the tier 30 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma. Luego explica con gran profundidad el proceso de actualización al nivel 30.",
        ["...You'll want to hold the fabric this way around, that way you won't lose a finger..."] = "...Querrás sujetar la tela de esta manera, así no perderás ni un dedo...",
        ["You take notes, ensuring you won't forget anything."] = "Toma notas, asegurándote de no olvidar nada.",
        ["... And that should be everything. Easy as redberry pie!"] = "... Y eso debería ser todo. ¡Tan fácil como pastel de frutos rojos!",
        ["Ah, there's nothing to worry about! All you need to remember is to gather the ensouled items required for your upgrade, and then return to the soul forge to perform it."] = "¡Ah, no hay nada de qué preocuparse! Todo lo que necesitas recordar es reunir los elementos con alma necesarios para tu actualización y luego regresar a la forja de almas para realizarla.",
        ["Come and check in with me whenever you want to learn the next upgrade!"] = "¡Ven y consúltame cuando quieras conocer la próxima actualización!",
        ["Congratulations! You have completed: 'Kili's Knowledge I' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 30 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento I de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 30 de Kili.",
        ["Thanks!"] = "¡Gracias!",
        ["Cancel your current task."] = "Cancela tu tarea actual.",
        ["Are you sure you want to stop working on your current upgrade task?"] = "¿Está seguro de que desea dejar de trabajar en su tarea de actualización actual?",
        ["Yes, I want to stop working on my current upgrade task."] = "Sí, quiero dejar de trabajar en mi tarea de actualización actual.",
        ["No problem. You can come back anytime to work on a new task."] = "No hay problema. Puede volver en cualquier momento para trabajar en una nueva tarea.",
        ["No, I want to continue working on my current upgrade task."] = "No, quiero seguir trabajando en mi tarea de actualización actual.",
        ["Great. You know where to find me if you need any help."] = "Genial. Ya sabes dónde encontrarme si necesitas ayuda.",
        ["Ok, time to teach you tier 40!"] = "Ok, ¡es hora de enseñarte el nivel 40!",
        ["As before, you'll need to go and fill this soul urn up with some souls."] = "Como antes, tendrás que ir y llenar esta urna de almas con algunas almas.",
        ["This time, the urn will only accept souls from killing any undead creatures using necromancy, or completing lesser communion rituals. I need 50 undead souls, or 5 lesser communion souls."] = "Esta vez, la urna solo aceptará almas provenientes de matar criaturas no muertas usando nigromancia o completando rituales de comunión menores. Necesito 50 almas de no-muertos o 5 almas de comunión menor.",
        ["Also, I'd like a meat pie."] = "Además, me gustaría un pastel de carne.",
        ["A meat pie?"] = "¿Un pastel de carne?",
        ["A meat pie."] = "Un pastel de carne.",
        ["Not that there's anything wrong with a meat pie, but why not a redberry pie?"] = "No es que haya nada malo con un pastel de carne, pero ¿por qué no un pastel de frutos rojos?",
        ["Well, I don't want to go diving in head first."] = "Bueno, no quiero lanzarme de cabeza.",
        ["It's been so long since I've had any sort of pie, so I'll start off by dipping my toes in the water."] = "Ha pasado mucho tiempo desde que comí algún tipo de pastel, así que comenzaré sumergiendo los dedos de los pies en el agua.",
        ["Right. And this will help upgrade my equipment how, exactly?"] = "Correcto. ¿Y esto ayudará a mejorar mi equipo, cómo exactamente?",
        ["Everyone needs a bit of sustenance, don't they? Even ghosts."] = "Todo el mundo necesita un poco de sustento, ¿no? Incluso fantasmas.",
        ["Moving on. Here's the task list for you."] = "Continuando. Aquí está la lista de tareas para usted.",
        ["Oh, and one last thing. Only bring me what I need once you have everything, rather than in dribs and drabs. We like to keep our home tidy, and Thalmund gets grumpy when the living room is full of items from adventurers."] = "Ah, y una última cosa. Sólo tráeme lo que necesito una vez que lo tengas todo, en lugar de poco a poco. Nos gusta mantener nuestra casa ordenada y Thalmund se pone de mal humor cuando la sala está llena de objetos de aventureros.",
        ["Noted. I guess I'll go get those souls and that pie, then."] = "Anotado. Supongo que entonces iré a buscar esas almas y ese pastel.",
        ["Don't you have that list I gave you?"] = "¿No tienes esa lista que te di?",
        ["Well, yes, but I guess I just wanted to see your face."] = "Bueno, sí, pero supongo que solo quería ver tu cara.",
        ["Er, well, I just need you to bring me some souls in that soul urn I gave you."] = "Er, bueno, solo necesito que me traigas algunas almas en esa urna de almas que te di.",
        ["The urn is modified to only accept souls from killing any undead creatures using necromancy, or completing lesser communion rituals. I need 50 undead souls, or 5 lesser communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar criaturas no muertas usando nigromancia o completando rituales de comunión menores. Necesito 50 almas de no-muertos o 5 almas de comunión menor.",
        ["Oh, and a meat pie!"] = "¡Ah, y un pastel de carne!",
        ["Ok! Goodbye then."] = "¡Vale! Adiós entonces.",
        ["I've got the full soul urn and that meat pie for you."] = "Tengo la urna de alma llena y ese pastel de carne para ti.",
        ["Lovely stuff."] = "Cosas preciosas.",
        ["Kili takes the meat pie and the soul urn."] = "Kili se lleva el pastel de carne y la urna del alma.",
        ["Kili chows down on the meat pie."] = "Kili come el pastel de carne.",
        ["How was it?"] = "¿Cómo estuvo?",
        ["A good first choice, I'd say. You can't go wrong with the rich flavours of the meat, combined with the milder flaky crust."] = "Una buena primera opción, diría yo. No te puedes equivocar con los ricos sabores de la carne, combinados con la corteza hojaldrada más suave.",
        ["Now, time to teach you the upgrade!"] = "¡Ahora es el momento de enseñarte la actualización!",
        ["Kili imbues her forge with energy from the soul urn and explains the tier 40 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 40 con gran profundidad.",
        ["Her hands shine with greasy meat drippings."] = "Sus manos brillan con la grasa de la carne.",
        ["...You'll want to sew the thread in this direction, so you don't poke an eye out..."] = "...Querrás coser el hilo en esta dirección, para no sacar un ojo...",
        ["...And that's it! There's a little more work required, but nothing too challenging."] = "...¡Y listo! Se requiere un poco más de trabajo, pero nada demasiado desafiante.",
        ["Shouldn't be much harder than the last upgrade."] = "No debería ser mucho más difícil que la última actualización.",
        ["Come back and let me know when you're ready to learn tier 50."] = "Vuelve y avísame cuando estés listo para aprender el nivel 50.",
        ["Congratulations! You have completed: 'Kili's Knowledge II' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 40 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento II de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 40 de Kili.",
        ["Will do!"] = "¡Lo haré!",
        ["So, now for tier 50."] = "Entonces, ahora para el nivel 50.",
        ["You know the drill - I need you to gather some souls in this soul urn."] = "Ya conoces el procedimiento: necesito que reúnas algunas almas en esta urna de almas.",
        ["The urn will only accept souls from killing demons using necromancy, or completing lesser communion rituals. I need 75 demon souls, or 10 lesser communion souls."] = "La urna solo aceptará almas provenientes de matar demonios usando nigromancia o completando rituales de comunión menores. Necesito 75 almas de demonios, o 10 almas de comunión menor.",
        ["There's a couple of additional things this time as well..."] = "Esta vez también hay un par de cosas adicionales...",
        ["Let me guess, another pie?"] = "Déjame adivinar, ¿otro pastel?",
        ["Indeed! An apple pie this time, though."] = "¡Efectivamente! Pero esta vez, una tarta de manzana.",
        ["I'm not very familiar with, I guess you'd call them, 'dessert pies'. And so I'd like to try one."] = "No estoy muy familiarizado con, supongo que los llamarías, 'pasteles de postre'. Y entonces me gustaría probar uno.",
        ["That's not it, though!"] = "¡Pero eso no es todo!",
        ["Two pies?!"] = "¡¿Dos pasteles?!",
        ["No, not two pies. I'm only a small dwarf!"] = "No, dos pasteles no. ¡Soy sólo un pequeño enano!",
        ["I also need you to get some necromancer's flippers."] = "También necesito que consigas unas aletas de nigromante.",
        ["Er... what?"] = "Er... ¿qué?",
        ["You know, flippers? The things you wear on your feet?"] = "Ya sabes, ¿aletas? ¿Las cosas que usas en tus pies?",
        ["Yes, I know what flippers are, but what on Gielinor are necromancer's flippers? And where am I meant to get them from?"] = "Sí, sé qué son las aletas, pero ¿qué son las aletas de nigromante en Gielinor? ¿Y de dónde debo sacarlos?",
        ["Well, they're just like normal flippers, but to wear if you're a necromancer."] = "Bueno, son como aletas normales, pero para usar si eres un nigromante.",
        ["Mogres will probably drop them, if you kill them using necromancy."] = "Mogres probablemente los dejará caer si los matas usando nigromancia.",
        ["I guess I'll go and get these flippers then."] = "Supongo que entonces iré a buscar estas aletas.",
        ["Here's a list of everything so you don't forget!"] = "¡Aquí tienes una lista de todo para que no lo olvides!",
        ["Thanks."] = "Gracias.",
        ["Well, yes, but it's less boring talking to you than looking at a sheet of paper."] = "Bueno, sí, pero es menos aburrido hablar contigo que mirar una hoja de papel.",
        ["Thanks. Well, I just need you to bring me some souls in that soul urn I gave you."] = "Gracias. Bueno, sólo necesito que me traigas algunas almas en esa urna que te di.",
        ["The urn is modified to only accept souls from killing demons using necromancy, or completing lesser communion rituals. I need 75 undead souls, or 10 lesser communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar demonios usando nigromancia o completando rituales de comunión menores. Necesito 75 almas de no-muertos o 10 almas de comunión menor.",
        ["I'd also like an apple pie, and some necromancer's flippers, which you should be able to get by killing mogres with necromancy."] = "También me gustaría una tarta de manzana y unas aletas de nigromante, que deberías poder conseguir matando mogres con nigromancia.",
        ["Got it!"] = "¡Entendido!",
        ["I've filled up the soul urn, got your apple pie, and the er, necromancer's flippers."] = "Llené la urna del alma, compré tu pastel de manzana y, eh, las aletas del nigromante.",
        ["You actually managed to get the flippers, eh? I'm impressed."] = "De hecho lograste conseguir las aletas, ¿eh? Estoy impresionado.",
        ["Kili takes the necromancer's flippers, the apple pie, and the soul urn."] = "Kili se lleva las aletas del nigromante, la tarta de manzana y la urna del alma.",
        ["So, what do you need the flippers for?"] = "Entonces, ¿para qué necesitas las aletas?",
        ["Don't you worry about that. Ah, best try out this pie before it gets cold!"] = "No te preocupes por eso. ¡Ah, será mejor que pruebes este pastel antes de que se enfríe!",
        ["Kili digs into the apple pie."] = "Kili se sumerge en la tarta de manzana.",
        ["Pretty good. Not sure I prefer it over savoury pies, but I'm glad I tried it nonetheless."] = "Bastante bien. No estoy seguro de preferirlo a los pasteles salados, pero de todos modos me alegro de haberlo probado.",
        ["Now, let's teach you that upgrade."] = "Ahora, vamos a enseñarte esa actualización.",
        ["Kili imbues her forge with energy from the soul urn and explains the tier 50 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 50 con gran profundidad.",
        ["Her apple pie breath wafts over to you, smothering you."] = "Su aliento a tarta de manzana flota hacia ti, asfixiándote.",
        ["...You'll want to hammer the bar into this shape, so you don't accidentally whack your fingernails off..."] = "...Querrás martillar la barra para darle esta forma, para no arrancarte las uñas accidentalmente...",
        ["...And that's all there is to it!"] = "... ¡Y eso es todo!",
        ["Come back and let me know when you're ready to learn tier 60."] = "Vuelve y avísame cuando estés listo para aprender el nivel 60.",
        ["Congratulations! You have completed: 'Kili's Knowledge III' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 50 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento III de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 50 de Kili.",
        ["Sure thing."] = "Claro.",
        ["It's time for tier 60 then!"] = "¡Entonces es hora del nivel 60!",
        ["As always, you'll need to gather some souls in this soul urn."] = "Como siempre, necesitarás reunir algunas almas en esta urna de almas.",
        ["The urn will only accept souls from killing any monster that is at least level 70 using necromancy, or completing greater communion rituals. I need 50 monster souls, or 10 greater communion souls."] = "La urna solo aceptará almas provenientes de matar cualquier monstruo que tenga al menos nivel 70 usando nigromancia o completando rituales de comunión mayores. Necesito 50 almas de monstruos, o 10 almas de comunión mayores.",
        ["I also need some more things... And yes, one of the things is a pie."] = "También necesito algunas cosas más... Y sí, una de ellas es un pastel.",
        ["A garden pie!"] = "¡Un pastel de jardín!",
        ["The meat pie you got me a while back was lovely, but I'd like to try out the vegetarian option this time."] = "El pastel de carne que me regalaste hace un tiempo estaba delicioso, pero esta vez me gustaría probar la opción vegetariana.",
        ["Fair enough, the Lumbridge cow population is getting a bit sparse. What else?"] = "Es cierto, la población de Lumbridge cow se está volviendo un poco escasa. ¿Qué otra cosa?",
        ["Nothing as ridiculous as flippers this time, I hope..."] = "Nada tan ridículo como las aletas esta vez, espero...",
        ["No no, not to worry! I just need you to take this device and use it on an ankou."] = "¡No, no, no te preocupes! Sólo necesito que tomes este dispositivo y lo uses en un ankou.",
        ["Ah, it looks like you don't have space for the ankou agitator. Come back when you do."] = "Ah, parece que no tienes espacio para el agitador ankou. Vuelve cuando lo hagas.",
        ["Kili gives you an ankou agitator."] = "Kili te ofrece un agitador ankou.",
        ["It's a device I fiddled with that measures what kind of necromantic magic is being used on them. You might need to use it on a few to get what's needed... I think 10 should do it."] = "Es un dispositivo con el que jugué y que mide qué tipo de magia nigromántica se está usando en ellos. Es posible que necesites usarlo en algunos para obtener lo que se necesita... Creo que 10 deberían ser suficientes.",
        ["I suppose that sounds more purposeful than flippers."] = "Supongo que eso suena más útil que las aletas.",
        ["Ok. So, 50 souls, a garden pie, and... something from ankou."] = "Vale. Entonces, 50 almas, un pastel de jardín y... algo de ankou.",
        ["And that's it! Don't forget your list."] = "¡Y listo! No olvides tu lista.",
        ["I'll be back later."] = "Volveré más tarde.",
        ["I need to reclaim my ankou agitator."] = "Necesito recuperar mi agitador ankou.",
        ["Kili hands you a new ankou agitator."] = "Kili te entrega un nuevo agitador ankou.",
        ["Well, yes, but you smell much nicer than a sheet of paper."] = "Bueno, sí, pero hueles mucho mejor que una hoja de papel.",
        ["I try. Well, I need you to bring me some souls in that soul urn I gave you."] = "Lo intento. Bueno, necesito que me traigas algunas almas en esa urna que te di.",
        ["The urn is modified to only accept souls from killing monsters that are at least level 70 using necromancy, or completing greater communion rituals. I need 50 monster souls, or 10 greater communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar monstruos que tengan al menos nivel 70 usando nigromancia o completando rituales de comunión mayores. Necesito 50 almas de monstruos, o 10 almas de comunión mayores.",
        ["I'd also like a garden pie, and for you to use that ankou agitator on a few  for me... Around 10 should do it."] = "También me gustaría un pastel de jardín, y si usas ese agitador ankou en algunos para mí... Alrededor de las 10 deberían ser suficientes.",
        ["Righto."] = "Correcto.",
        ["Ok, I'm back with the full soul urn, a garden pie, and some... residue from an ankou. It was left behind by one after using your agitator doodad on it, so I think it's what you need?"] = "Ok, he vuelto con la urna del alma llena, un pastel de jardín y algunos... residuos de un ankou. Uno lo dejó atrás después de usar su adorno agitador, así que creo que es lo que necesita.",
        ["It dropped some residue? Er... great! I'll just take all of that then."] = "¿Se le cayó algún residuo? Eh... ¡genial! Entonces me quedo con todo eso.",
        ["Kili takes the ankou residue, the garden pie, and the soul urn."] = "Kili toma el residuo de ankou, el pastel de jardín y la urna del alma.",
        ["Will the residue give you the information you needed? Will it help improve my equipment?"] = "¿El residuo le dará la información que necesitaba? ¿Ayudará a mejorar mi equipo?",
        ["Yep! It'll uh, give it a magical protection-y boost that your equipment was missing."] = "¡Sí! Le dará un impulso mágico de protección que le faltaba a su equipo.",
        ["Well, I'm glad it has some value then."] = "Bueno, entonces me alegro de que tenga algún valor.",
        ["It sure does. Now, let's try out this pie."] = "Seguro que sí. Ahora, probemos este pastel.",
        ["Kili munches on the garden pie."] = "Kili mastica el pastel de la huerta.",
        ["Hmm."] = "Mmm.",
        ["A good 'hmm'? A bad 'hmm'?"] = "¿Un buen 'hmm'? ¿Un mal 'hmm'?",
        ["It's actually pretty good! The tomatoes are lovely and juicy, and the onion gives a nice crunch."] = "¡En realidad es bastante bueno! Los tomates son deliciosos y jugosos, y la cebolla queda crujiente.",
        ["Better than the meat pie?"] = "¿Mejor que el pastel de carne?",
        ["Possibly not, but a strong contender at least."] = "Posiblemente no, pero al menos es un fuerte contendiente.",
        ["Anyway! Enough about pies, let's teach you the upgrade."] = "¡De todos modos! Ya basta de pasteles, vamos a enseñarte la actualización.",
        ["Kili imbues her forge with energy from the soul urn and explains the tier 60 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 60 con gran profundidad.",
        ["Her hands drip with tomato juice, and her breath stinks of onion."] = "Sus manos gotean jugo de tomate y su aliento apesta a cebolla.",
        ["...Make sure to imbue the runic energy for this exact amount of time, so you don't burn your hair off..."] = "...Asegúrate de imbuir la energía rúnica durante este período de tiempo exacto, para no quemarte el cabello...",
        ["...That should be all!"] = "... ¡Eso debería ser todo!",
        ["Come back and let me know when you're ready to learn tier 70."] = "Vuelve y avísame cuando estés listo para aprender el nivel 70.",
        ["See you later!"] = "¡Hasta luego!",
        ["Alright, so you want to upgrade to tier 70."] = "Muy bien, entonces quieres actualizar al nivel 70.",
        ["Of course, I'll need some more souls in this soul urn."] = "Por supuesto, necesitaré más almas en esta urna de almas.",
        ["The urn will only accept souls from killing dragons using necromancy, or completing greater communion rituals. I need 100 dragon souls, or 20 greater communion souls."] = "La urna solo aceptará almas provenientes de matar dragones usando nigromancia o completando rituales de comunión mayores. Necesito 100 almas de dragón, o 20 almas de comunión mayor.",
        ["This time, I'd also like to try a fish pie."] = "Esta vez también me gustaría probar un pastel de pescado.",
        ["Back when I was living, fish pies were one of my favourites. I'm curious if they taste any better now that I'm dead."] = "Cuando yo vivía, los pasteles de pescado eran uno de mis favoritos. Tengo curiosidad por saber si saben mejor ahora que estoy muerto.",
        ["Ok, soul urn and pie. Standard. What's the last thing you need?"] = "Ok, urna del alma y pastel. Estándar. ¿Qué es lo último que necesitas?",
        ["Am I that predictable?"] = "¿Soy tan predecible?",
        ["A little."] = "Un poco.",
        ["Well, the last thing I need is some necroplasm. Necroplasm from the original Barrows brothers, specifically."] = "Bueno, lo último que necesito es algo de necroplasma. Necroplasma de los hermanos Barrows originales, específicamente.",
        ["How can I get it?"] = "¿Cómo puedo conseguirlo?",
        ["Firstly, you'll need some greater necroplasm. Around 20 for each brother should be enough."] = "En primer lugar, necesitarás un necroplasma mayor. Unas 20 por cada hermano deberían ser suficientes.",
        ["Once you have that, take it to their crypts. The energy from their sarcophagi should be enough to transform the necroplasm."] = "Una vez que tengas eso, llévalo a sus criptas. La energía de sus sarcófagos debería ser suficiente para transformar el necroplasma.",
        ["But... I don't want the individual brothers' necroplasm. You'll need to find a way to combine them into a singular necroplasm."] = "Pero... No quiero el necroplasma de los hermanos individuales. Necesitarás encontrar una manera de combinarlos en un necroplasma singular.",
        ["That sounds doable, I think."] = "Creo que eso parece factible.",
        ["Perfect. Here's the list."] = "Perfecto. Aquí está la lista.",
        ["Be back soon!"] = "¡Vuelve pronto!",
        ["Well, yes, but I was hoping you might have some leftover pie to share."] = "Bueno, sí, pero esperaba que te sobrara algo de pastel para compartir.",
        ["I do not."] = "No lo hago.",
        ["But, to answer your question, I need you to bring me some souls in that soul urn I gave you."] = "Pero, para responder a tu pregunta, necesito que me traigas algunas almas en esa urna de almas que te di.",
        ["The urn is modified to only accept souls from killing dragons using necromancy, or completing greater communion rituals. I need 100 dragon souls, or 20 greater communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar dragones usando nigromancia o completando rituales de comunión mayores. Necesito 100 almas de dragón, o 20 almas de comunión mayor.",
        ["I'd also like a fish pie, and some necroplasm from the Barrows brothers."] = "También me gustaría un pastel de pescado y un poco de necroplasma de los hermanos Barrows.",
        ["You'll need 20 greater necroplasm for each brother, and to take it to each of their sarcophagi."] = "Necesitarás 20 necroplasmas mayores para cada hermano, y llevarlos a cada uno de sus sarcófagos.",
        ["After that, you're a bit on your own - I want the necroplasm to be combined, rather than individual ones."] = "Después de eso, estarás un poco solo. Quiero que los necroplasmas estén combinados, en lugar de individualmente.",
        ["I'll see what I can do."] = "Veré qué puedo hacer.",
        ["Alright! I have your soul urn, fish pie, and I figured out how to combine the necroplasm."] = "¡Muy bien! Tengo tu urna del alma, pastel de pescado y descubrí cómo combinar el necroplasma.",
        ["Amazing!"] = "¡Increíble!",
        ["Kili takes the barrows necroplasm, the fish pie, and the soul urn."] = "Kili se lleva el necroplasma de los túmulos, el pastel de pescado y la urna del alma.",
        ["So, what will you use the necroplasm for?"] = "Entonces, ¿para qué usarás el necroplasma?",
        ["Ah, you know, to imbue the forge! And such."] = "¡Ah, ya sabes, para imbuir la fragua! Y tal.",
        ["Anyway, I can't wait to try out the pie any longer."] = "De todos modos, no puedo esperar más para probar el pastel.",
        ["Kili horks down the fish pie."] = "Kili devora el pastel de pescado.",
        ["Wonderful. Simply wonderful."] = "Maravilloso. Simplemente maravilloso.",
        ["Better than when you were living?"] = "¿Mejor que cuando vivías?",
        ["I think so? The aroma of the fish. The butteriness of the pastry..."] = "¿Creo que sí? El aroma del pescado. La mantecosidad de la masa...",
        ["Or maybe it tastes so good because I haven't had it for so long."] = "O tal vez sabe tan bien porque hace mucho que no lo pruebo.",
        ["Or maybe it IS because I'm dead, and my senses are heightened..."] = "O tal vez ES porque estoy muerto y mis sentidos están intensificados...",
        ["OR maybe the batch you brought me just used especially high-quality fish..."] = "O tal vez el lote que me trajiste solo usaba pescado de especialmente alta calidad...",
        ["OR-"] = "O-",
        ["Er, can you teach me the upgrade now?"] = "Er, ¿puedes enseñarme la actualización ahora?",
        ["Kili snaps out of her pie-induced trance."] = "Kili sale del trance inducido por el pastel.",
        ["Sorry, yes, come with me..."] = "Lo siento, sí, ven conmigo...",
        ["Kili imbues her forge with energy from the soul urn and explains the tier 70 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 70 con gran profundidad.",
        ["Vague scents of cod and trout fill the air around you."] = "Vagos aromas a bacalao y trucha llenan el aire a tu alrededor.",
        ["...Be careful to measure out this exact length of thread, so it doesn't get tangled around your ears..."] = "...Ten cuidado de medir esta longitud exacta de hilo, para que no se enrede alrededor de tus orejas...",
        ["...There we go!"] = "... ¡Allá vamos!",
        ["Come back and let me know when you're ready to learn tier 80."] = "Vuelve y avísame cuando estés listo para aprender el nivel 80.",
        ["Bye for now."] = "Adiós por ahora.",
        ["Congratulations! You have completed: 'Kili's Knowledge V' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 70 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento V de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 70 de Kili.",
        ["Alright, so you want to upgrade to tier 70, into some power armour."] = "Muy bien, entonces quieres actualizar al nivel 70 y ponerte una servoarmadura.",
        ["So, this time you'll need a soul urn, a pie, and..."] = "Entonces, esta vez necesitarás una urna para el alma, un pastel y...",
        ["Not this time!"] = "¡Esta vez no!",
        ["The power armour works a little differently, so no soul urn needed. And I can do without the pie for a bit."] = "La servoarmadura funciona un poco diferente, por lo que no se necesita una urna de alma. Y puedo prescindir del pastel por un tiempo.",
        ["Instead, you'll need to get some materials from some of the great beasts of Gielinor."] = "En su lugar, necesitarás conseguir algunos materiales de algunas de las grandes bestias de Gielinor.",
        ["I need you to get me 5 royal chitin, which can be obtained from the Kalphite Queen, and 5 hideous moleskins, which can be obtained from the Giant Mole."] = "Necesito que me consigas 5 quitina real, que se pueden obtener del Kalphite Queen, y 5 horribles pieles de topo, que se pueden obtener del topo gigante.",
        ["You should know that they'll only shed them when fought with necromancy, though."] = "Sin embargo, debes saber que solo los arrojarán cuando luchen contra la nigromancia.",
        ["Kalphite Queen... Giant Mole... Necromancy... Got it."] = "Kalphite Queen... Topo gigante... Necromancy... Entendido.",
        ["Anything else? You're really sure you don't want a pie?"] = "¿Algo más? ¿Estás realmente seguro de que no quieres un pastel?",
        ["Nope. That's all!"] = "No. ¡Eso es todo!",
        ["A drop of sweat falls from Kili's forehead as she shows great restraint in turning down your offer of a pie."] = "Una gota de sudor cae de la frente de Kili mientras muestra gran moderación al rechazar tu oferta de un pastel.",
        ["Be off, before I change my mind. Here's the list."] = "Vete antes de que cambie de opinión. Aquí está la lista.",
        ["Whatever you say!"] = "¡Lo que tú digas!",
        ["Well, yes, but I thought I'd check that you really don't want a pie this time."] = "Bueno, sí, pero pensé en comprobar que esta vez realmente no quieres un pastel.",
        ["No. No pie!"] = "No. ¡Sin pastel!",
        ["Moving on, you'll need to get me 5 royal chitin from the Kalphite Queen, and 5 hideous moleskins from the Giant Mole."] = "Continuando, necesitarás conseguirme 5 quitina real del Kalphite Queen y 5 horribles pieles de topo del topo gigante.",
        ["They should only shed them when fought with necromancy, though."] = "Sin embargo, solo deberían deshacerse de ellos cuando luchen con nigromancia.",
        ["Thanks, I'll be off then."] = "Gracias, entonces me voy.",
        ["I'm back with the royal chitin and hideous moleskins!"] = "¡Estoy de vuelta con la quitina real y las horribles pieles de topo!",
        ["Nice work!"] = "¡Buen trabajo!",
        ["Kili takes the royal chitin and the hideous moleskins."] = "Kili toma la quitina real y las horribles pieles de topo.",
        ["Onto the upgrade!"] = "¡A la actualización!",
        ["Wait, what are you going to do with the chitin and moleskins?"] = "Espera, ¿qué vas a hacer con la quitina y las pieles de topo?",
        ["It's a secret."] = "Es un secreto.",
        ["A secret?"] = "¿Un secreto?",
        ["Yes. Top secret knowledge that only dwarves of the Imcando clan can know."] = "Sí. Conocimiento ultrasecreto que sólo los enanos del clan Imcando pueden conocer.",
        ["Back to what I was saying, let's teach you the upgrade!"] = "Volviendo a lo que estaba diciendo, ¡vamos a enseñarte la actualización!",
        ["Kili explains the tier 70 upgrade process for power armour in great depth."] = "Kili explica con gran profundidad el proceso de actualización de nivel 70 para servoarmadura.",
        ["...Make sure you cut the fabric to this specific size, so you don't have any overhang that could trip you up and cause a nasty concussion..."] = "...Asegúrate de cortar la tela a este tamaño específico, para que no quede ningún saliente que pueda hacerte tropezar y causar una conmoción cerebral desagradable...",
        ["...And that's all!"] = "... ¡Y eso es todo!",
        ["Congratulations! You have completed: 'Kili's Knowledge V (power)' - Learn how to upgrade your Death Skull equipment to tier 70, and upgrade your Deathwarden equipment to tier 70 Deathdealer from Kili."] = "¡Felicitaciones! Ha completado: 'Conocimiento V (poder) de Kili': aprenda cómo actualizar su equipo Death Skull al nivel 70 y actualizar su equipo Deathwarden al nivel 70 Deathdealer de Kili.",
        ["So, you want to upgrade to tier 80."] = "Entonces, deseas actualizar al nivel 80.",
        ["First off, I'll need some more souls in this soul urn."] = "En primer lugar, necesitaré más almas en esta urna de almas.",
        ["The urn will only accept souls from killing monsters assigned as your Slayer task using necromancy, or completing greater communion rituals. I need 150 Slayer task souls, or 30 greater communion souls."] = "La urna solo aceptará almas provenientes de matar monstruos asignados como tu tarea Slayer usando nigromancia o completando rituales de comunión mayores. Necesito 150 almas de tarea Slayer, o 30 almas de comunión mayor.",
        ["I also need you to recharge this special hammer of mine, with some powerful soul energy."] = "También necesito que recargues este martillo especial mío, con una poderosa energía del alma.",
        ["Ah, it looks like you don't have space for the spiritbound hammer (uncharged). Come back when you do."] = "Ah, parece que no tienes espacio para el martillo vinculado al espíritu (sin carga). Vuelve cuando lo hagas.",
        ["Kili gives you a spiritbound hammer (uncharged)."] = "Kili te da un martillo vinculado al espíritu (sin carga).",
        ["Powerful, eh? Do I need to defeat an elder god? An average god? A demi-god?"] = "Potente, ¿eh? ¿Necesito derrotar a un dios mayor? ¿Un dios promedio? ¿Un semidiós?",
        ["Er, not exactly. Just some of their followers."] = "Er, no exactamente. Sólo algunos de sus seguidores.",
        ["Powerful followers, though! I was thinking of the four generals in God Wars Dungeon."] = "¡Pero poderosos seguidores! Estaba pensando en los cuatro generales de God Wars Dungeon.",
        ["Defeat them, and then charge up my hammer with residual energy from their altars. It depletes quickly after their defeat though, so you'll have to be fast."] = "Derrótalos y luego carga mi martillo con la energía residual de sus altares. Sin embargo, se agota rápidamente después de su derrota, así que tendrás que ser rápido.",
        ["Fast as lightning, noted."] = "Rápido como un rayo, señaló.",
        ["And last but not least..."] = "Y por último, pero no menos importante...",
        ["A pie?"] = "¿Un pastel?",
        ["A pie!"] = "¡Un pastel!",
        ["But not any old pie..."] = "Pero no cualquier pastel viejo...",
        ["A redberry pie!"] = "¡Un pastel de frutos rojos!",
        ["I was wondering how long it would take for you to ask for one."] = "Me preguntaba cuánto tiempo te tomaría pedir uno.",
        ["I've exercised a lot of restraint by trying the other pies first, but I think it's time."] = "He ejercido mucha moderación al probar los otros pasteles primero, pero creo que es el momento.",
        ["Now here's your list."] = "Ahora aquí está tu lista.",
        ["Hurry back!"] = "¡Vuelve rápido!",
        ["I need to reclaim my spiritbound hammer (uncharged)."] = "Necesito recuperar mi martillo vinculado al espíritu (descargado).",
        ["Kili hands you a new spiritbound hammer (uncharged)."] = "Kili te entrega un nuevo martillo vinculado al espíritu (sin carga).",
        ["Well, yes, but I was hoping you might have changed your mind and are now willing to teach me the upgrade for no effort on my behalf."] = "Bueno, sí, pero esperaba que hubieras cambiado de opinión y ahora estés dispuesto a enseñarme la actualización sin ningún esfuerzo por mi parte.",
        ["The urn is modified to only accept souls from killing monsters assigned as your Slayer task using necromancy, or completing greater communion rituals. I need 150 Slayer task souls, or 30 greater communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar monstruos asignados como tu tarea Slayer usando nigromancia o completando rituales de comunión mayores. Necesito 150 almas de tarea Slayer, o 30 almas de comunión mayor.",
        ["I also need you to charge up my hammer from the altars of the four God Wars Dungeon generals. You'll have to be quick after defeating them, though."] = "También necesito que cargues mi martillo desde los altares de los cuatro generales de God Wars Dungeon. Sin embargo, tendrás que ser rápido después de derrotarlos.",
        ["And, most important of all, I need you to get me a redberry pie."] = "Y, lo más importante de todo, necesito que me traigas una tarta de frutos rojos.",
        ["I'll continue getting your things."] = "Seguiré recogiendo tus cosas.",
        ["Ok, I'm back with the filled soul urn, charged hammer, and redberry pie."] = "Ok, he vuelto con la urna del alma llena, el martillo cargado y el pastel de frutos rojos.",
        ["Pie..."] = "Pastel...",
        ["Kili takes the charged hammer, the redberry pie, and the soul urn."] = "Kili toma el martillo cargado, el pastel de frutos rojos y la urna del alma.",
        ["Be careful, the pie is quite ho-"] = "Cuidado, el pastel está bastante ho-",
        ["Kili gobbles up the redberry pie before you have a chance to react."] = "Kili devora el pastel de frutos rojos antes de que tengas oportunidad de reaccionar.",
        ["Ahh. That hits the spot."] = "Ahh. Eso da en el clavo.",
        ["As I was trying to say, the pie was quite hot. Just wanted to make sure you didn't burn yourself."] = "Como intentaba decir, el pastel estaba bastante caliente. Sólo quería asegurarme de que no te quemaras.",
        ["Kili pokes around her mouth."] = "Kili se asoma alrededor de la boca.",
        ["Ah, I guess I did burn myself. Well you know what they say, no pain, no gain!"] = "Ah, supongo que me quemé. Bueno, ya sabes lo que dicen, ¡sin dolor no hay ganancia!",
        ["I mean, you could have waited for the pie to cool down, and then just had the gain without the pain but..."] = "Quiero decir, podrías haber esperado a que el pastel se enfriara y luego obtener la ganancia sin el dolor, pero...",
        ["I think the molten hot redberry sauce added to the gain, though."] = "Sin embargo, creo que la salsa picante de frutos rojos fundida contribuyó a la ganancia.",
        ["Suit yourself."] = "Haz lo que quieras.",
        ["Pie aside, let's go and teach you the upgrade."] = "Dejando a un lado el pastel, vamos a enseñarte la actualización.",
        ["Kili imbues her forge with energy from the soul urn and explains the tier 80 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 80 con gran profundidad.",
        ["A rich scent of redberry coats the air around you."] = "Un rico aroma a frutos rojos envuelve el aire que te rodea.",
        ["...You'll want to stand in this exact position when hammering, so you don't fracture a bone..."] = "...Querrás pararte exactamente en esta posición al martillar, para no fracturarte un hueso...",
        ["...And that's all done!"] = "... ¡Y listo!",
        ["One last thing I should mention. If you choose to upgrade your equipment from an augmented version, you should know that any augmentations will also be applied to the upgraded version."] = "Una última cosa que debo mencionar. Si elige actualizar su equipo desde una versión aumentada, debe saber que cualquier aumento también se aplicará a la versión mejorada.",
        ["So no need to worry about losing anything."] = "Así que no hay necesidad de preocuparse por perder nada.",
        ["Come back and let me know when you're ready to learn tier 90."] = "Vuelve y avísame cuando estés listo para aprender el nivel 90.",
        ["Congratulations! You have completed: 'Kili's Knowledge VI' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 80 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento VI de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 80 desde Kili.",
        ["Right. You want to learn tier 80, power armour."] = "Correcto. Quieres aprender servoarmadura de nivel 80.",
        ["So, as it's power armour, I won't need you to gather me any souls."] = "Entonces, como es una servoarmadura, no necesitaré que me recojas almas.",
        ["Phew."] = "Uf.",
        ["Instead, you'll need to defeat Nex and the Queen Black Dragon!"] = "¡En lugar de eso, tendrás que derrotar a Nex y a la Reina Dragón Negro!",
        ["So much for an easy task."] = "Hasta aquí es una tarea fácil.",
        ["First of all, I'm in need of 5 Zaryte fragments. You should be able to get these from Nex."] = "Primero que nada, necesito 5 fragmentos de Zaryte. Debería poder obtenerlos de Nex.",
        ["Second of all, I'd like 5 tortured soul essences. I believe the Queen Black Dragon will possess these."] = "En segundo lugar, me gustaría 5 esencias de almas torturadas. Creo que la Reina Dragón Negro los poseerá.",
        ["Poor souls."] = "Pobres almas.",
        ["Another thing to note, is that they'll probably only drop the things I need if you defeat them with necromancy."] = "Otra cosa a tener en cuenta es que probablemente solo dejarán caer las cosas que necesito si los derrotas con nigromancia.",
        ["Probably?"] = "¿Probablemente?",
        ["Almost certainly, according to my research..."] = "Casi seguro, según mi investigación...",
        ["A definite guarantee would be appreciated, before I charge in all gung-ho."] = "Se agradecería una garantía definitiva antes de cargar con todo entusiasmo.",
        ["Well, we don't always get what we want in life. Or the afterlife."] = "Bueno, no siempre conseguimos lo que queremos en la vida. O la otra vida.",
        ["...And that should be all I need! Here's the list."] = "...¡Y eso debería ser todo lo que necesito! Aquí está la lista.",
        ["I'll go and prepare to get your things then."] = "Entonces iré y me prepararé para recoger tus cosas.",
        ["Well, yes, but I just wanted to come and bother you."] = "Bueno, sí, pero solo quería venir a molestarte.",
        ["Well, you need to get me 5 Zaryte fragments from Nex, and 5 tortured soul essences from the Queen Black Dragon."] = "Bueno, necesitas conseguirme 5 fragmentos de Zaryte de Nex y 5 esencias de alma torturadas de la Reina Dragón Negro.",
        ["You should also know that they'll only drop them when defeated using necromancy."] = "También debes saber que solo los soltarán cuando sean derrotados usando nigromancia.",
        ["I've got those Zaryte fragments and tortured soul essences for you!"] = "¡Tengo esos fragmentos de Zaryte y esencias de almas torturadas para ti!",
        ["Good job."] = "Buen trabajo.",
        ["Kili takes the Zaryte fragments and the tortured soul essences."] = "Kili toma los fragmentos de Zaryte y las esencias del alma torturada.",
        ["What are you going to do with them?"] = "¿Qué vas a hacer con ellos?",
        ["Ah, I'm glad you asked! You see..."] = "¡Ah, me alegra que lo hayas preguntado! Ya ves...",
        ["Kili starts talking about some extremely in depth Smithing-related gobbledygook."] = "Kili comienza a hablar sobre algunas palabrerías extremadamente profundas relacionadas con Smithing.",
        ["...And then I'll instil the essence into the alloys, whilst infusing the fragments into the welding bucket..."] = "...Y luego infundiré la esencia en las aleaciones, mientras infundo los fragmentos en el cubo de soldadura...",
        ["She continues to talk in terms you hadn't heard before. You assume you don't know of these terms because she's the master smith here, not you."] = "Ella continúa hablando en términos que no habías escuchado antes. Asumes que no conoces estos términos porque ella es la maestra herrera aquí, no tú.",
        ["You regret asking in the first place."] = "Te arrepientes de haber preguntado en primer lugar.",
        ["...And that's how we'll make you the best armour to ever exist!"] = "... ¡Y así es como te haremos la mejor armadura que jamás haya existido!",
        ["Oop, sorry, I must have zoned out. What was that?"] = "Vaya, lo siento, debo haberme desconectado. ¿Qué fue eso?",
        ["Nevermind. Now follow me, and I'll teach you the upgrade..."] = "No importa. Ahora sígueme y te enseñaré la actualización...",
        ["Kili explains the tier 80 upgrade process for power armour in great depth."] = "Kili explica con gran profundidad el proceso de actualización de nivel 80 para servoarmadura.",
        ["...Don't forget to put on goggles before bashing the bars, otherwise you might make yourself blind..."] = "...No olvides ponerte gafas antes de golpear las barras, de lo contrario podrías quedar ciego...",
        ["...And that should be it!"] = "... ¡Y eso debería ser todo!",
        ["Congratulations! You have completed: 'Kili's Knowledge VI (power)' - Learn how to upgrade your Death Skull and Deathdealer equipment to tier 80 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento VI (poder) de Kili': aprende cómo actualizar tu equipo Death Skull y Deathdealer al nivel 80 de Kili.",
        ["So you've chosen to upgrade to tier 90."] = "Entonces has elegido actualizar al nivel 90.",
        ["To start, you'll need to fill up this soul urn for me."] = "Para empezar, tendrás que llenar esta urna del alma por mí.",
        ["The urn will only accept souls from powerful communion rituals, of which I need 50. Alternatively, you can fill it up by just completing a Soul Reaper task using necromancy."] = "La urna solo aceptará almas de poderosos rituales de comunión, de las cuales necesito 50. Alternativamente, puedes llenarla simplemente completando una tarea de Soul Reaper usando nigromancia.",
        ["[Kili gives you a soul urn.]"] = "[Kili te regala una urna para el alma.]",
        ["Next, I need 10 empowered necromantic seals from each of the generals of the Heart of Gielinor."] = "A continuación, necesito 10 sellos nigrománticos potenciados de cada uno de los generales del Corazón de Gielinor.",
        ["This is a complex process that's taken a lot of time to perfect, so pay attention."] = "Este es un proceso complejo que requiere mucho tiempo para perfeccionarse, así que preste atención.",
        ["First off, you'll need to defeat the boss to gain the unpowered seals. Make sure to bring along 25 greater necroplasm too."] = "En primer lugar, tendrás que derrotar al jefe para obtener los sellos sin poder. Asegúrate de llevar también 25 necroplasmas mayores.",
        ["Now, once you have a bunch of their seals, they'll each require a different process to empower..."] = "Ahora, una vez que tengas varios de sus sellos, cada uno necesitará un proceso diferente para potenciarlos...",
        ["The seals from Helwyr should be empowered through opening a crystal chest."] = "Los sellos de Helwyr deben potenciarse abriendo un cofre de cristal.",
        ["Gregorovic's seals will need you to craft some miasmic runes."] = "Los sellos de Gregorovic necesitarán que crees algunas runas miasmáticas.",
        ["Vindicta's seals will need you to use Bone Shield against a dragonfire attack."] = "Los sellos de Vindicta necesitarán que uses Escudo óseo contra un ataque de fuego de dragón.",
        ["And last but not least, the Twin Furies seals will need you to restore some Zamorakian artefacts."] = "Y por último, pero no menos importante, los sellos de las Furias Gemelas necesitarán que restaures algunos artefactos zamorakianos.",
        ["That is... a lot of work."] = "Eso es... mucho trabajo.",
        ["Oh, I'm not finished yet!"] = "¡Oh, todavía no he terminado!",
        ["I also need a pulsating onyx. You'll be able to craft this by combining an uncut onyx and a special crystal."] = "También necesito un ónix pulsante. Podrás crear esto combinando un ónix sin cortar y un cristal especial.",
        ["Lucky for you, I already have the crystal here with me."] = "Por suerte para ti, ya tengo el cristal aquí conmigo.",
        ["Ah, it looks like you don't have space for the inert necromantic crystal. Come back when you do."] = "Ah, parece que no tienes espacio para el cristal nigromántico inerte. Vuelve cuando lo hagas.",
        ["[Kili gives you an inert necromantic crystal.]"] = "[Kili te ofrece un cristal nigromántico inerte.]",
        ["Unlucky for you, it needs powering up. The energies from defeating TzTok-Jad in the TzHaar Fight Cave should be enough for that."] = "Por desgracia para ti, es necesario encenderlo. Las energías obtenidas al derrotar a TzTok-Jad en la cueva de lucha de TzHaar deberían ser suficientes para eso.",
        ["Great."] = "Genial.",
        ["So that's it, right? I'll be off now!"] = "Entonces eso es todo, ¿verdad? ¡Me voy ahora!",
        ["Not so fast!"] = "¡No tan rápido!",
        ["Lastly, I would like a blueberry pie."] = "Por último, me gustaría un pastel de arándanos.",
        ["A BLUEberry pie?"] = "¿Un pastel de arándanos?",
        ["I'm not sure exactly what Gielinor was like during your time alive, but I can tell you now that we don't have such a thing as a blueberry."] = "No estoy seguro exactamente de cómo era Gielinor durante tu época de vida, pero puedo decirte ahora que no tenemos algo llamado arándano.",
        ["I'm sure you can figure it out. Maybe some inhabitants around the city can help you."] = "Estoy seguro de que puedes resolverlo. Quizás algunos habitantes de la ciudad puedan ayudarte.",
        ["So that's..."] = "Así que eso es...",
        ["[You take a deep breath.]"] = "[Respiras profundamente.]",
        ["A full soul urn, 10 empowered necromantic seals from each of the 4 Heart of Gielinor generals, a pulsating onyx..."] = "Una urna de alma llena, 10 sellos nigrománticos potenciados de cada uno de los 4 generales del Corazón de Gielinor, un ónix pulsante...",
        ["[You breathe out.]"] = "[Exhalas.]",
        ["... And a blueberry pie."] = "... Y una tarta de arándanos.",
        ["That's everything!"] = "¡Eso es todo!",
        ["You've got a lot of work ahead of you, so no need to hang around. Here's the list."] = "Tienes mucho trabajo por delante, así que no necesitas perder el tiempo. Aquí está la lista.",
        ["I'd best get started then."] = "Entonces será mejor que empiece.",
        ["I'm back with some information that may help me find some blueberries."] = "Regresé con información que puede ayudarme a encontrar algunos arándanos.",
        ["Oh?"] = "¿Ah?",
        ["Someone suggested that as blue is the opposite of red, then I would simply have to find a land of opposites."] = "Alguien sugirió que como el azul es lo opuesto al rojo, entonces simplemente tendría que encontrar una tierra de opuestos.",
        ["They were joking, but I also talked to someone else who mentioned a land where things work backwards."] = "Estaban bromeando, pero también hablé con alguien más que mencionó una tierra donde las cosas funcionan al revés.",
        ["Something about an evil cat, and uncooked fish..."] = "Algo sobre un gato malvado y pescado crudo...",
        ["Oh no."] = "Oh, no.",
        ["You know something?"] = "¿Sabes algo?",
        ["A pest. Evil Bob."] = "Una plaga. Evil Bob.",
        ["He resides in a land of opposites, reigning over humans. A place called ScapeRune."] = "Reside en una tierra de opuestos, reinando sobre los humanos. Un lugar llamado ScapeRune.",
        ["More than once has he tried to imprison me over there."] = "Más de una vez ha intentado encarcelarme allí.",
        ["But you should be fine! Just do as he says."] = "¡Pero deberías estar bien! Simplemente haz lo que él dice.",
        ["How can I get there?"] = "¿Cómo puedo llegar?",
        ["That I can't help you with, as I never actually visited myself. It's a different realm to Gielinor, though, so it should be accessible via magical means."] = "En eso no puedo ayudarte, ya que nunca fui a visitarme. Sin embargo, es un reino diferente a Gielinor, por lo que debería ser accesible a través de medios mágicos.",
        ["Thanks for the help."] = "Gracias por la ayuda.",
        ["I need to reclaim my inert necromantic crystal."] = "Necesito recuperar mi cristal nigromántico inerte.",
        ["Kili hands you a new inert necromantic crystal."] = "Kili te entrega un nuevo cristal nigromántico inerte.",
        ["Well, yes, but I just wanted to talk to a friend."] = "Bueno, sí, pero solo quería hablar con un amigo.",
        ["First of all, I need you to bring me some souls in that soul urn I just gave you."] = "Primero que nada, necesito que me traigas algunas almas en esa urna de almas que te acabo de dar.",
        ["It can be filled through 50 powerful communion rituals, or completing a Soul Reaper task with necromancy."] = "Se puede completar a través de 50 poderosos rituales de comunión o completando una tarea de Soul Reaper con nigromancia.",
        ["Next, I need 10 empowered necromantic seals from the general of the Heart of Gielinor."] = "A continuación, necesito 10 sellos nigrománticos potenciados del general del Corazón de Gielinor.",
        ["Then, to empower them, each requires a different process."] = "Luego, para potenciarlos, cada uno requiere un proceso diferente.",
        ["The Twin Furies seals will need you to restore some Zamorakian artefacts."] = "Los sellos de las Furias Gemelas necesitarán que restaures algunos artefactos zamorakianos.",
        ["Secondly, I need a pulsating onyx. You'll be able to craft this by combining an uncut onyx and that crystal I gave you."] = "En segundo lugar, necesito un ónix pulsante. Podrás crear esto combinando un ónix sin cortar y el cristal que te di.",
        ["The crystal first needs charging up by defeating TzTok-Jad in the TzHaar Fight Cave, though."] = "Sin embargo, primero es necesario cargar el cristal al derrotar a TzTok-Jad en la cueva de lucha de TzHaar.",
        ["And last but not least, I want a blueberry pie. Some inhabitants of the city may be able to help you figure that one out."] = "Y por último, pero no menos importante, quiero una tarta de arándanos. Algunos habitantes de la ciudad pueden ayudarte a resolverlo.",
        ["I'll get back to it then."] = "Volveré a ello entonces.",
        ["Ok, I finally managed to gather all the things you needed."] = "Ok, finalmente logré reunir todas las cosas que necesitabas.",
        ["So you did manage to find a blueberry?"] = "Entonces, ¿conseguiste encontrar un arándano?",
        ["I could barely believe it myself, but yes. I did manage to find a blueberry."] = "Yo mismo apenas podía creerlo, pero sí. Logré encontrar un arándano.",
        ["[Kili takes the pulsating onyx, the necromantic seals, the blueberry pie, and the soul urn.]"] = "[Kili toma el ónix pulsante, los sellos nigrománticos, el pastel de arándanos y la urna del alma.]",
        ["What did you need this abundance of items for?"] = "¿Para qué necesitabas esta abundancia de artículos?",
        ["Something very exciting."] = "Algo muy emocionante.",
        ["That I can't tell you about yet."] = "Eso no puedo contarte todavía.",
        ["Really? I went to all that effort, you could at least give me a crumb of knowledge."] = "¿En serio? Hice todo ese esfuerzo, al menos podrías darme una migaja de conocimiento.",
        ["That's true..."] = "Eso es cierto...",
        ["I suppose I can tell you after you've learnt all of the upgrades."] = "Supongo que podré decírtelo después de que hayas aprendido todas las actualizaciones.",
        ["Fine."] = "Bien.",
        ["Can we eat the pie now?"] = "¿Podemos comer el pastel ahora?",
        ["We?"] = "¿Nosotros?",
        ["I've never tasted a blueberry. I didn't even know they existed until this task."] = "Nunca he probado un arándano. Ni siquiera sabía que existían hasta esta tarea.",
        ["Alright, I guess we can share the pie this time."] = "Muy bien, supongo que esta vez podemos compartir el pastel.",
        ["[Kili chomps down half of the pie, leaving the remaining half for you.]"] = "[Kili muerde la mitad del pastel y deja la mitad restante para ti.]",
        ["[You chomp down on the other half of the pie, leaving nothing but crumbs.]"] = "[Muerdes la otra mitad del pastel, dejando nada más que migajas.]",
        ["Thoughts?"] = "¿Pensamientos?",
        ["Hmm. That was pretty good! A hint of sourness, combined with a unique tinge of sugary goodness."] = "Mmm. ¡Eso estuvo bastante bien! Un toque de acidez, combinado con un matiz único de bondad azucarada.",
        ["I couldn't have said it better myself."] = "Ni yo mismo podría haberlo dicho mejor.",
        ["Now! Let's head over to the workshop so I can teach you the upgrade."] = "¡Ahora! Vayamos al taller para poder enseñarte la actualización.",
        ["[Kili imbues her forge with energy from the soul urn and explains the tier 90 upgrade process in great depth.]"] = "[Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 90 con gran profundidad.]",
        ["[A novel fragrance fills your nose. You can only assume that it's blueberry.]"] = "[Una fragancia novedosa llena tu nariz. Sólo puedes asumir que es arándano.]",
        ["...Make sure to hydrate before starting the process, so you don't pass out..."] = "...Asegúrate de hidratarte antes de iniciar el proceso, para no desmayarte...",
        ["[You take notes, ensuring you won't forget anything.]"] = "[Toma notas, asegurándote de no olvidar nada.]",
        ["...And that's it!"] = "...¡Y listo!",
        ["I haven't taught you all there is to know yet, so come back whenever you'd like to learn more."] = "Aún no te he enseñado todo lo que hay que saber, así que vuelve cuando quieras aprender más.",
        ["Will do."] = "Lo haré.",
        ["Congratulations! You have completed: 'Kili's Knowledge VII' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 90 from Kili."] = "¡Felicidades! Has completado: 'Conocimiento VII de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 90 de Kili.",
        ["Hmm.."] = "Mmmm..",
        ["Tier 70... tank.... power... Tier 80... Tier 90...."] = "Nivel 70... tanque... potencia... Nivel 80... Nivel 90....",
        ["And with that, I believe I've taught you everything you need to know!"] = "¡Y con eso, creo que te he enseñado todo lo que necesitas saber!",
        ["The student becomes the master!"] = "¡El alumno se convierte en el maestro!",
        ["You were a wonderful student, Player. I'll see you around!"] = "Fuiste un estudiante maravilloso, Player. ¡Nos vemos por ahí!",
        ["Hold on a minute."] = "Espera un minuto.",
        ["Yes?"] = "¿Sí?",
        ["What exactly did you end up doing with all the miscellaneous items I painstakingly collected for you?"] = "¿Qué terminaste haciendo exactamente con todos los artículos diversos que recopilé minuciosamente para ti?",
        ["The residue, the flippers, the chitin, the fragments?"] = "¿El residuo, las aletas, la quitina, los fragmentos?",
        ["Ah. But didn't I tell you at the time?"] = "Ah. ¿Pero no te lo dije en ese momento?",
        ["You really expected me to believe the things you were telling me? Things like 'only the Imcando are allowed to know of some top secret use for hideous moleskins'?"] = "¿Realmente esperabas que creyera las cosas que me decías? ¿Cosas como 'sólo los Imcando pueden conocer algún uso ultrasecreto de horribles pieles de topo'?",
        ["You got me."] = "Me tienes.",
        ["I just wanted to see how far you'd go to learn the upgrades, really."] = "Sólo quería ver hasta dónde llegarías para aprender las actualizaciones, de verdad.",
        ["Turns out, quite far!"] = "¡Resulta que está bastante lejos!",
        ["Unnecessarily slaughtering mogres... Annoying ankou... You even went and defeated the Ambassador!"] = "Matando mogres innecesariamente... Ankou molesto... ¡Incluso fuiste y derrotaste a the Ambassador!",
        ["After all those pies I gathered for you, and this is how you repaid me."] = "Después de todos esos pasteles que reuní para ti, y así es como me pagaste.",
        ["The pies were much appreciated."] = "Los pasteles fueron muy apreciados.",
        ["Well, at least I can fully upgrade my equipment now. Thanks, I guess."] = "Bueno, al menos ahora puedo actualizar completamente mi equipo. Gracias, supongo.",
        ["Anytime!"] = "¡En cualquier momento!",
        ["I'm not going anywhere, so you know where to find me should you need anything."] = "No voy a ir a ningún lado, así que ya sabes dónde encontrarme si necesitas algo.",
        ["See you around!"] = "¡Nos vemos!",
        ["So, now we're onto tier 90, power armour."] = "Entonces, ahora estamos en el nivel 90, servoarmadura.",
        ["This time you won't need to fill up any soul urns for me."] = "Esta vez no necesitarás llenar ninguna urna de almas para mí.",
        ["Instead, I need a few items which will require some challenging tasks."] = "En cambio, necesito algunos elementos que requerirán algunas tareas desafiantes.",
        ["I'm up for anything."] = "Estoy dispuesto a cualquier cosa.",
        ["That's the spirit!"] = "¡Ese es el espíritu!",
        ["To start with then, I need a piece of greater ensouled cloth, dripping with venom."] = "Entonces, para empezar, necesito un trozo de tela con mayor alma, que gotea veneno.",
        ["Using the cloth on the corpse of Araxxi should be sufficient."] = "Usar la tela sobre el cadáver de Araxxi debería ser suficiente.",
        ["The next thing I need is a fragment of anima. You should just be able to get one of these from defeating either Vorago, Telos, or Solak, with necromancy."] = "Lo siguiente que necesito es un fragmento de ánima. Deberías poder obtener uno de estos al derrotar a Vorago, Telos o Solak con nigromancia.",
        ["A piece of cake."] = "Pan comido.",
        ["Really? Well, I still need one more thing..."] = "¿En serio? Bueno, todavía necesito una cosa más...",
        ["A special pie infused with the power of the gods, which I can only get by defeating Zamorak?"] = "¿Un pastel especial infundido con el poder de los dioses, que solo puedo obtener derrotando a Zamorak?",
        ["I wish!"] = "¡Ojalá!",
        ["But no. The last thing I need is some ulthven necroplasm, which you'll be able to get from defeating the Ambassador with necromancy."] = "Pero no. Lo último que necesito es un poco de necroplasma ultimo, que podrás obtener al derrotar a the Ambassador con nigromancia.",
        ["I hope this upgrade is worth it."] = "Espero que esta actualización valga la pena.",
        ["Maybe. Before you go, here's the list."] = "Quizás. Antes de irte, aquí tienes la lista.",
        ["I'll go and get started then."] = "Entonces iré y empezaré.",
        ["[Kili hands you a new equipment upgrade task list.]"] = "[Kili le entrega una nueva lista de tareas de actualización de equipos.]",
        ["Well, yes, but I missed looking at your dazzling eyes and glowing hair."] = "Bueno, sí, pero extrañaba tus ojos deslumbrantes y tu cabello resplandeciente.",
        ["Or, glowing everything I guess."] = "O, supongo que brillando todo.",
        ["I'll take that as a compliment."] = "Lo tomaré como un cumplido.",
        ["So, first thing I need is some greater ensouled cloth, dripping in venom."] = "Entonces, lo primero que necesito es una tela con mayor alma, goteando veneno.",
        ["Using the cloth on the corpse of Araxxi should do the job."] = "Usar la tela sobre el cadáver de Araxxi debería funcionar.",
        ["The second thing I need is a fragment of anima. Defeating Vorago, Telos, or Solak, with necromancy, should yield one of these."] = "Lo segundo que necesito es un fragmento de ánima. Derrotar a Vorago, Telos o Solak con nigromancia debería dar como resultado uno de estos.",
        ["The third and final thing I need is some ulthven necroplasm. You'll be able to get this by defeating the Ambassador with necromancy."] = "La tercera y última cosa que necesito es un necroplasma definitivo. Podrás conseguirlo derrotando a the Ambassador con nigromancia.",
        ["Alright!"] = "¡Muy bien!",
        ["I've got the venomous cloth, fragment of anima, and ulthven necroplasm for you!"] = "¡Tengo la tela venenosa, el fragmento de ánima y el último necroplasma para ti!",
        ["Good work."] = "Buen trabajo.",
        ["[Kili takes the venomous greater ensouled cloth, fragment of anima, and ulthven necroplasm.]"] = "[Kili toma la venenosa tela con alma mayor, un fragmento de ánima y el último necroplasma.]",
        ["Sorry, what was that?"] = "Lo siento, ¿qué fue eso?",
        ["I asked what you're going to do w-"] = "Te pregunté qué vas a hacer con-",
        ["Player, I think you're breaking up."] = "Player, creo que estás rompiendo.",
        ["What? I'm right next to you."] = "¿Qué? Estoy justo a tu lado.",
        ["Maybe their amulet of ghostspeak stopped working."] = "Quizás su amuleto de habla fantasmal dejó de funcionar.",
        ["I don't even need that in the underworld!"] = "¡Ni siquiera necesito eso en el inframundo!",
        ["Maybe they've faded out from the underworld, because they're not dead."] = "Tal vez se hayan desvanecido del inframundo, porque no están muertos.",
        ["Nope, I'm still fully here."] = "No, todavía estoy completamente aquí.",
        ["Well, it was nice to know them."] = "Bueno, fue un placer conocerlos.",
        ["Hey! I'm still here! Can we just get the upgrade out of the way?"] = "¡Oye! ¡Todavía estoy aquí! ¿Podemos eliminar la actualización?",
        ["Ah, Player, there you are! Great suggestion, let's teach you the upgrade."] = "¡Ah, Player, ahí estás! Gran sugerencia, vamos a enseñarte la actualización.",
        ["[Kili explains the tier 90 upgrade process for power armour in great depth.]"] = "[Kili explica con gran detalle el proceso de actualización de nivel 90 para servoarmadura.]",
        ["...Make sure you wear some steel-toed boots, so you don't burn your toes off..."] = "...Asegúrate de usar botas con punta de acero para no quemarte los dedos...",
        ["I haven't taught you everything there is to know yet, so come back whenever you'd like to learn more."] = "Aún no te he enseñado todo lo que hay que saber, así que vuelve cuando quieras aprender más.",
        ["Congratulations! You have completed: 'Kili's Knowledge VII (power)' - Learn how to upgrade your Death Skull and Deathdealer equipment to tier 90 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento VII de Kili (poder)': aprende cómo actualizar tu equipo Death Skull y Deathdealer al nivel 90 de Kili.",
        ["Congratulations! You have completed: 'Student Becomes the Master' - Learn all of Kili's equipment upgrade tasks."] = "¡Felicitaciones! Ha completado: 'El estudiante se convierte en maestro': aprenda todas las tareas de actualización de equipos de Kili.",
    },
    ["Kilron"] = {
        ["Hello there."] = "Hola.",
        ["Hello."] = "Hola.",
        ["How are you?"] = "¿Cómo estás?",
        ["Busy."] = "Ocupado.",
        ["Hello Kilron."] = "Hola Kilron.",
        ["Hello traveller. Do you need to go back over?"] = "Hola viajero. ¿Necesitas volver?",
        ["Select an Option"] = "Selecciona una opción",
        ["Not yet Kilron."] = "Aún no Kilron.",
        ["Okay, just give me the word."] = "Está bien, solo dame la palabra.",
        ["Yes I do."] = "Sí, lo hago.",
        ["Okay, quickly now!"] = "¡Bien, rápido!",
        ["Looks like you won't be needing the rope ladder any more, adventurer. I heard it was you who started the revolution and freed West Ardougne!"] = "Parece que ya no necesitarás la escalera de cuerda, aventurero. ¡Escuché que fuiste tú quien inició la revolución y liberó a West Ardougne!",
    },
    ["Kimberly"] = {
        ["Hello."] = "Hola.",
        ["Hi! I'm Kimberly, I'm new around here."] = "¡Hola! Soy Kimberly, soy nuevo por aquí.",
        ["Hi, Kimberly. Pleased to meet you. How do you like living in Witchaven?"] = "Hola, Kimberly. Encantado de conocerte. ¿Qué te parece vivir en Witchaven?",
        ["Well, it's a bit slug-y, and the locals aren't that friendly, but it's mostly fine. I guess."] = "Bueno, es un poco lento y los lugareños no son tan amigables, pero en general está bien. Supongo.",
        ["I'm glad to hear that. Well, I have to be going, but it was nice to meet you."] = "Me alegra oír eso. Bueno, tengo que irme, pero fue un placer conocerte.",
        ["Sure, I'll see you later."] = "Claro, nos vemos luego.",
        ["Hello, Kimberly. How are you doing?"] = "Hola, Kimberly. ¿Cómo estás?",
        ["I'm doing well, thank you, Player. Things are much better down here. No sea slugs and no horrid little boys to scare me. Although, I do miss the sky and the fresh air."] = "Estoy bien, gracias, Player. Las cosas están mucho mejor aquí abajo. No hay babosas marinas ni niños horribles que me asusten. Aunque sí extraño el cielo y el aire fresco.",
        ["I can imagine. Hopefully soon, your parents will feel safe enough to move back up to Witchaven."] = "Me lo imagino. Con suerte, pronto tus padres se sentirán lo suficientemente seguros como para regresar a Witchaven.",
        ["That would be nice. Maybe the sea slugs will go away soon?"] = "Eso estaría bien. ¿Quizás las babosas marinas desaparezcan pronto?",
        ["*(Before Salt in the Wound:)*"] = "*(Antes de Sal en la Herida:)*",
        ["I hope so, Kimberly. I hope so."] = "Eso espero, Kimberly. Eso espero.",
        ["*(After Salt in the Wound:)*"] = "*(Después de Sal en la herida:)*",
        ["Perhaps they're already gone."] = "Quizás ya se hayan ido.",
    },
    ["King Arthur"] = {
        ["Thank you for retrieving the Grail! You shall long be remembered as one of the greatest heroes amongst the Knights of the Round Table!"] = "¡Gracias por recuperar el Grial! ¡Serás recordado durante mucho tiempo como uno de los mayores héroes entre los Caballeros de la Mesa Redonda!",
        ["Welcome, brave knight. I am always happy to see you back at my court. Please feel free to roam the castle and make use of the training grounds."] = "Bienvenido, valiente caballero. Siempre me alegro de verte de nuevo en mi corte. Siéntete libre de recorrer el castillo y utilizar los campos de entrenamiento.",
        ["You have chosen...poorly."] = "Has elegido... mal.",
        ["Excuse me?"] = "¿Perdón?",
        ["Sorry, I meant to say 'thank you'. Most refreshing."] = "Lo siento, quería decir \"gracias\". Lo más refrescante.",
        ["Are you sure that stuff is safe to drink?"] = "¿Estás seguro de que es seguro beber esas cosas?",
        ["Oh yes, Stankers' creations may be dangerous for those with weak constitutions, but, personally, I find them rather invigorating."] = "Oh, sí, las creaciones de Stankers pueden ser peligrosas para aquellos con constituciones débiles, pero, personalmente, las encuentro bastante estimulantes.",
    },
    ["King Bolren"] = {
        ["Hello again Bolren."] = "Hola de nuevo Bolren.",
        ["Well hello, it's good to see you again."] = "Bueno, hola, es un placer verte de nuevo.",
        ["I've lost my amulet."] = "He perdido mi amuleto.",
        ["Oh dear. Here, take another. We are truly indebted to you."] = "Dios mío. Toma, toma otro. Estamos realmente en deuda con usted.",
        ["Not Right Now"] = "No ahora mismo",
        ["Accept Quest"] = "Aceptar misión",
        ["You do not meet the requirements to start : 'The Path of Glouphrie'."] = "No cumples los requisitos para empezar: 'El Camino de Glouphrie'.",
        ["I think I know where Arposandra is now!"] = "¡Creo que ya sé dónde está Arposandra!",
        ["Really? Have you been there?"] = "¿En serio? ¿Has estado allí?",
        ["Not exactly. I've found a way in, although I can't open the vent to get in there yet."] = "No exactamente. Encontré una manera de entrar, aunque todavía no puedo abrir el respiradero para entrar.",
        ["So, you haven't actually been there. Well, I'm still not convinced that it's a real place. There's something about lost cities that gets explorers and adventurers obsessed."] = "Entonces, en realidad no has estado allí. Bueno, todavía no estoy convencido de que sea un lugar real. Hay algo en las ciudades perdidas que obsesiona a los exploradores y aventureros.",
        ["I'm not obsessed, but I *will* find a way in. Eventually."] = "No estoy obsesionado, pero *encontraré* una manera de entrar. Con el tiempo.",
        ["Of course you will."] = "Por supuesto que sí.",
        ["I found Arposandra!"] = "¡Encontré a Arposandra!",
        ["Really? You've actually been there?"] = "¿En serio? ¿De verdad has estado allí?",
        ["Briefly, yes. It really is a dangerous place."] = "Brevemente, sí. Realmente es un lugar peligroso.",
        ["I don't believe you! You've got to be joking."] = "¡No te creo! Tienes que estar bromeando.",
        ["Maybe, one day, you'll believe me."] = "Quizás algún día me creas.",
        ["Congratulations, human!"] = "¡Felicitaciones, humano!",
        ["[King Bolren has given you your next clue scroll!]"] = "[¡King Bolren te ha dado tu próximo pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Thank you. I don't have any gnome cooks here. I should really do something about that."] = "Gracias. Aquí no tengo cocineros gnomos. Realmente debería hacer algo al respecto.",
    },
    ["King Lathas"] = {
        ["Hello King Lathas."] = "Hola King Lathas.",
        ["Adventurer, thank Saradomin or your arrival!"] = "¡Aventurero, gracias a Saradomin por tu llegada!",
        ["Have your scouts found a way through the mountains?"] = "¿Tus exploradores han encontrado un camino a través de las montañas?",
        ["Not quite, we found a path to where we expected to find the Well of Voyage, an ancient portal to the western mainland. However during recent times a cluster of cultists have settled there, run by a madman named Iban."] = "No del todo, encontramos un camino hacia donde esperábamos encontrar el Pozo del Viaje, un antiguo portal al continente occidental. Sin embargo, recientemente se ha establecido allí un grupo de cultistas, dirigidos por un loco llamado Iban.",
        ["*(Quest acceptance screen)*"] = "*(Pantalla de aceptación de misión)*",
        ["*Before obtaining the Letter from the Messenger*"] = "*Antes de obtener la Carta del Mensajero*",
        ["Well hello there traveller. The magi are still resurrecting the Well of Voyage, but I'll have word sent to you as soon as it's ready."] = "Bueno, hola viajero. Los magos todavía están resucitando el Pozo del Viaje, pero te avisaré tan pronto como esté listo.",
        ["Ok then, take care."] = "Ok, entonces, cuídate.",
        ["You too."] = "Tú también.",
        ["Good day my lord."] = "Buenos días mi señor.",
        ["Hello Player. I've got nothing for you right now."] = "Hola Player. No tengo nada para ti ahora mismo.",
        ["Good day."] = "Buenos días.",
        ["What are you doing here? All Mourners should know that if they need to contact me, they need to use the proper channels!"] = "¿Qué haces aquí? ¡Todos los dolientes deben saber que si necesitan comunicarse conmigo, deben utilizar los canales adecuados!",
        ["Sorry, I'm a new recruit."] = "Lo siento, soy un nuevo recluta.",
        ["Well do not let it happen again."] = "Bueno, no dejes que vuelva a suceder.",
    },
    ["King Narnode Shareen"] = {
        ["Hello, Your Highness!"] = "¡Hola, alteza!",
        ["Well, hello again Traveller! How are you?"] = "Bueno, ¡hola de nuevo, Viajero! ¿Cómo estás?",
        ["I'm good thanks, how's the tree?"] = "Estoy bien gracias, ¿cómo está el árbol?",
        ["Better than ever, thanks to you!"] = "¡Mejor que nunca, gracias a ti!",
        ["Hello there, King Narnode."] = "Hola, Rey Narnode.",
        ["Good of you to stop by, human."] = "Qué bueno que pasaste por aquí, humano.",
        ["How fares the kingdom today?"] = "¿Cómo le va al reino hoy?",
        ["Everything seems fine, as far as I can tell... I will let you know if there is trouble."] = "Todo parece estar bien, hasta donde sé... Te avisaré si hay algún problema.",
    },
    ["King Roald"] = {
        ["Greetings, your majesty."] = "Saludos, majestad.",
        ["Well hello there. What do you want?"] = "Bueno, hola. ¿Qué deseas?",
        ["I am looking for a quest!"] = "¡Estoy buscando una misión!",
        ["What do you want to do?"] = "¿Qué quieres hacer?",
        ["Talk about Priest in Peril."] = "Habla sobre Sacerdote en peligro.",
        ["Ah, it's you again. Hello there."] = "Ah, eres tú otra vez. Hola.",
        ["Hello, Your Majesty. I am happy to report that the situation at the Temple of Paterdomus has been sorted. Misthalin's borders should once again be fully protected against the threats from Morytania."] = "Hola, Su Majestad. Me complace informarles que la situación en el Templo de Paterdomus se ha solucionado. Las fronteras de Misthalin deberían volver a estar completamente protegidas contra las amenazas de Morytania.",
        ["Excellent, excellent. The Kingdom of Misthalin is in your debt."] = "Excelente, excelente. El Reino de Misthalin está en deuda contigo.",
        ["In my debt? Does that mean you're going to give me fabulous rewards for my efforts?"] = "¿Estás en deuda conmigo? ¿Eso significa que me vas a dar fabulosas recompensas por mis esfuerzos?",
        ["Of course not; however, if it's rewards you're after, it occurs to me that you could be of even more service to the kingdom."] = "Por supuesto que no; sin embargo, si lo que buscas son recompensas, se me ocurre que podrías ser de aún más servicio para el reino.",
        ["Although, you might need a little more experience tending fires, first. If you're interested, come talk to me when you've had a bit more practice."] = "Aunque es posible que primero necesites un poco más de experiencia en el cuidado de incendios. Si estás interesado, ven a hablar conmigo cuando hayas practicado un poco más.",
        ["[You need to have at least 43 Firemaking to start All Fired Up.]"] = "[Necesitas tener al menos 43 Firemaking para iniciar All Fired Up.]",
        ["Greet the king."] = "Saluda al rey.",
        ["What do you want to do?{{anchor"] = "¿Qué quieres hacer?{{anchor",
        ["Talk about River of Blood."] = "Hablando de Río de Sangre.",
        ["Varrock has survived many attacks since its founding, but I'm thankful this vampyre situation was resolved peacefully."] = "Varrock ha sobrevivido a muchos ataques desde su fundación, pero estoy agradecido de que esta situación de vampyre se haya resuelto pacíficamente.",
        ["For now, at least. The brokered peace may not hold."] = "Al menos por ahora. Es posible que la paz negociada no se mantenga.",
        ["And if it doesn't, we shall deal with the situation. I am taking steps that, should it not hold, Varrock will be in a much stronger position to deal with it."] = "Y si no es así, nos ocuparemos de la situación. Estoy tomando medidas que, si no se cumplen, Varrock estará en una posición mucho más fuerte para afrontarlo.",
        ["For example, Aeonisig is offering aid to the citizens of Meiyerditch in exchange for shipments of blisterwood."] = "Por ejemplo, Aeonisig ofrece ayuda a los ciudadanos de Meiyerditch a cambio de envíos de blisterwood.",
        ["Truth be told, my worries have moved on to other matters. If it's not one thing, it's another, so they say."] = "La verdad es que mis preocupaciones han pasado a otros asuntos. Si no es una cosa, es otra, eso dicen.",
        ["Such as?"] = "¿Por ejemplo?",
        ["It appears that your intervention at the Salve targets only vampyres. Werewolves, on the other hand, are free to cross."] = "Parece que su intervención en Salve está dirigida únicamente a vampyres. Los hombres lobo, por otro lado, son libres de cruzar.",
        ["The reports state that they have effectively declared independence from the vampyres. We shall need to keep a close watch on what they do with this newfound freedom."] = "Los informes afirman que efectivamente han declarado su independencia de vampyres. Tendremos que vigilar de cerca lo que hacen con esta nueva libertad.",
        ["Replay Cutscene - Would you like to replay the Siege of Paterdomus?"] = "Repetir escena: ¿Te gustaría volver a reproducir el asedio de Paterdomus?",
        ["Cancel"] = "Cancelar",
        ["Ask about the beacons."] = "Pregunta por las balizas.",
        ["Do you have anything of importance to say?"] = "¿Tienes algo importante que decir?",
        ["...Not really."] = "...En realidad no.",
        ["You will have to excuse me, I am very busy."] = "Tendrás que disculparme, estoy muy ocupado.",
        ["I must keep a fixed eye on Morytania to the east."] = "Debo mantener un ojo fijo en Morytania al este.",
        ["Or both eyes, perhaps?"] = "¿O quizás ambos ojos?",
        ["Indeed, we cannot all be heroes, wandering from one crisis to another."] = "De hecho, no todos podemos ser héroes y pasar de una crisis a otra.",
        ["Ever since Kara-Meir and her friends became famous, adventuring has become a career of choice amongst our youth. Yet, people forget that her tale is a cautionary one."] = "Desde que Kara-Meir y sus amigos se hicieron famosos, las aventuras se han convertido en una carrera preferida entre nuestros jóvenes. Sin embargo, la gente olvida que su historia es una advertencia.",
        ["Why? What happened to her?"] = "¿Por qué? ¿Qué pasó con ella?",
        ["She withheld important information about one of her associates, and it very nearly led to disaster for all of us: every man, woman and child."] = "Ocultó información importante sobre uno de sus asociados, y eso estuvo a punto de provocar un desastre para todos nosotros: cada hombre, mujer y niño.",
        ["And?"] = "¿Y?",
        ["And what? I have spent enough time on you, adventurer. You will have to excuse me, I have a kingdom to run."] = "¿Y qué? He dedicado suficiente tiempo a ti, aventurero. Tendrás que disculparme, tengo un reino que administrar.",
        ["I was wondering if you could tell me more about the beacons."] = "Me preguntaba si podría contarme más sobre las balizas.",
        ["Of course. What would you like to know?"] = "Por supuesto. ¿Qué te gustaría saber?",
        ["Select an Option"] = "Selecciona una opción",
        ["I'm here to claim my reward."] = "Estoy aquí para reclamar mi recompensa.",
        ["I'm here to claim my reward!"] = "¡Estoy aquí para reclamar mi recompensa!",
        ["For keeping six beacons alight simultaneously, I present you with the Ring of Fire."] = "Para mantener seis balizas encendidas simultáneamente, te presento el Anillo de Fuego.",
        ["Thank you very much!"] = "¡Muchas gracias!",
        ["Lost the Ring of Fire have you? Luckily I seem to have a spare."] = "¿Perdiste el Anillo de Fuego, verdad? Por suerte parece que tengo uno de repuesto.",
        ["Hmm, you seem to have misplaced your Flame Gloves, good thing we have more!"] = "Hmm, parece que has extraviado tus guantes Flame, ¡qué bueno que tenemos más!",
        ["This recently turned up in the lost and found, your Inferno Adze."] = "Esto apareció recientemente en el objeto perdido y encontrado, tu Inferno Adze.",
        ["Thank you again, Player. Misthalin is truly in your debt."] = "Gracias de nuevo, Player. Misthalin está verdaderamente en deuda contigo.",
        ["Is there anything else you'd like to ask me?"] = "¿Hay algo más que quieras preguntarme?",
        ["What else needs to be done to test the beacon network?"] = "¿Qué más hay que hacer para probar la red de balizas?",
        ["What *doesn't* need to be done is more like it! We need to make sure the entire beacon network is as robust as possible."] = "¡Lo que *no* es necesario hacer es más bien! Necesitamos asegurarnos de que toda la red de balizas sea lo más sólida posible.",
        ["I'd be extremely grateful if you'd help us by trying to keep as many beacons alight simultaneously as you possibly can."] = "Le agradecería mucho que nos ayudara intentando mantener encendidas tantas balizas simultáneamente como sea posible.",
        ["How does that help?"] = "¿Cómo ayuda eso?",
        ["Well, obviously, it helps us verify that all the beacons are in good working order, of course."] = "Bueno, obviamente, nos ayuda a verificar que todas las balizas estén en buen estado de funcionamiento, por supuesto.",
        ["The more testing, the better, Player. I have generous rewards for you if you manage to keep six, ten and all fourteen beacons alight simultaneously."] = "Cuantas más pruebas, mejor, Player. Tengo generosas recompensas para ti si logras mantener seis, diez y catorce balizas encendidas simultáneamente.",
        ["However, I'd be positively delighted if you continued on testing them day and night, over and over, relentlessly and without ceasing!"] = "Sin embargo, estaría encantado si continuaras probándolos día y noche, una y otra vez, sin descanso y sin cesar.",
        ["I see this means a great deal to you."] = "Veo que esto significa mucho para ti.",
        ["Oh, it does. The safety of one's kingdom is of paramount importance, you know."] = "Oh, así es. La seguridad del reino de uno es de suma importancia, ¿sabes?",
        ["Do you have any other questions for me, Player?"] = "¿Tienes alguna otra pregunta para mí, Player?",
        ["Tell me about rewards."] = "Cuéntame sobre las recompensas.",
        ["Talk to me about rewards."] = "Háblame sobre las recompensas.",
        ["Ahem, well. It's all well and good having a network of beacons, but it's important to make sure it works properly...and remains working. Thus, I'm willing to offer various rewards if you are willing to help me out. There are rewards available for keeping six, ten and all fourteen beacons alight simultaneously."] = "Ejem, bueno. Está muy bien tener una red de balizas, pero es importante asegurarse de que funcione correctamente... y siga funcionando. Por lo tanto, estoy dispuesto a ofrecer varias recompensas si estás dispuesto a ayudarme. Hay recompensas disponibles por mantener encendidas seis, diez y catorce balizas simultáneamente.",
        ["For keeping six beacons alight, I'm prepared to grant you a ring that will aid you in Firemaking."] = "Por mantener seis balizas encendidas, estoy dispuesto a otorgarte un anillo que te ayudará en Firemaking.",
        ["I've granted you the Ring of Fire for keeping six beacons alight."] = "Te he concedido el Anillo de Fuego por mantener encendidas seis balizas.",
        ["For keeping ten beacons alight, I will grant you a pair of gloves that will work in combination with the ring."] = "Por mantener diez balizas encendidas, te daré un par de guantes que funcionarán en combinación con el anillo.",
        ["You've already claimed the Flame Gloves for keeping ten beacons alight."] = "Ya has reclamado los guantes de llamas por mantener encendidas diez balizas.",
        ["For keeping all fourteen beacons alight, well, I have the magnificent Inferno Adze - a fire-enchanting tool for both Woodcutting and Mining - that I'm prepared to part with. I think you'll find it of great use."] = "Para mantener encendidas las catorce balizas, bueno, tengo el magnífico Inferno Adze, una herramienta de encantamiento de fuego tanto para Woodcutting como para Mining, de la que estoy dispuesto a desprenderme. Creo que lo encontrarás de gran utilidad.",
        ["For keeping all fourteen beacons alight simultaneously, you've been granted the Inferno Adze. Is there anything else?"] = "Por mantener las catorce balizas encendidas simultáneamente, se te ha otorgado el Inferno Adze. ¿Hay algo más?",
        ["I'd like a few more details, please."] = "Me gustaría tener más detalles, por favor.",
        ["Why have you created all these beacons?"] = "¿Por qué has creado todas estas balizas?",
        ["You've already had a glimpse of the dangers we face from Morytania. Further dangers threaten from the Wilderness in the north."] = "Ya has vislumbrado los peligros que enfrentamos desde Morytania. Más peligros amenazan desde el Wilderness en el norte.",
        ["Because of these mounting threats, the southern kingdoms have banded together to take action."] = "Debido a estas crecientes amenazas, los reinos del sur se han unido para tomar medidas.",
        ["We have constructed a network of beacons that stretch all the way from the source of the River Salve to the northwestern-most edge of the Wilderness."] = "Hemos construido una red de balizas que se extiende desde el nacimiento del río Salve hasta el extremo noroeste del Wilderness.",
        ["Should there be any threat from these uncivilised lands, we'll be able to spread the word as fast as the light of the flames can travel."] = "Si hubiera alguna amenaza proveniente de estas tierras incivilizadas, podremos correr la voz tan rápido como la luz de las llamas pueda viajar.",
        ["How will these beacons work in an emergency?"] = "¿Cómo funcionarán estas balizas en caso de emergencia?",
        ["Simple. I've equipped each fire tender with a stockpile of gnomish firelighters. In the case of a real emergency, the beacons will burn with coloured flame."] = "Sencillo. He equipado a cada bombero con una reserva de encendedores gnomos. En caso de una emergencia real, las balizas arderán con llamas de colores.",
        ["I see. I don't suppose you have any extra firelighters lying around that you want to get rid of, do you?"] = "Ya veo. Supongo que no tendrás ningún encendedor extra por ahí del que quieras deshacerte, ¿verdad?",
        ["Don't bother me with idle chatter. Is there anything else?"] = "No me molestes con charlas ociosas. ¿Hay algo más?",
        ["Who are these fire tenders?"] = "¿Quiénes son estos bomberos?",
        ["These are special recruits from all around the civilised world. They've been carefully selected for their sharp eyes and long-distance vision."] = "Estos son reclutas especiales de todo el mundo civilizado. Han sido cuidadosamente seleccionados por sus ojos agudos y su visión de larga distancia.",
        ["Not to mention their dedication and reliability. We couldn't entrust such an important job to just anyone, you know!"] = "Sin mencionar su dedicación y confiabilidad. No podíamos confiar un trabajo tan importante a cualquiera, ¿sabes?",
        ["I don't have anything more to talk about, actually."] = "En realidad, no tengo nada más de qué hablar.",
        ["Then begone; I am a busy man."] = "Entonces vete; Soy un hombre ocupado.",
        ["Is there a reason for you being here?"] = "¿Hay alguna razón para que estés aquí?",
        ["Well, I'm on a Treasure Trail."] = "Bueno, estoy siguiendo la pista del tesoro.",
        ["Oh! Good, then you can answer this question for me."] = "¡Oh! Bien, entonces puedes responderme esta pregunta.",
        ["[King Roald has given you a challenge scroll!]"] = "[¡King Roald te ha dado un pergamino de desafío!]",
        ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
        ["Enter amount:<br>[Input field]"] = "Ingrese la cantidad:<br>[Input field]",
        ["Err, that sounds a little wrong to me."] = "Err, eso me suena un poco mal.",
        ["[King Roald has given you another clue scroll!]"] = "[¡King Roald te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Correct!"] = "¡Correcto!",
        ["Ask about the kingdom."] = "Pregunta sobre el reino.",
        ["Greetings, your majesty. How fares the kingdom?"] = "Saludos, majestad. ¿Cómo le va al reino?",
        ["It's terrible! Have you not heard? Zamorak and Saradomin are fighting near Lumbridge! They've destroyed much of the castle! That's royal property! I'm very annoyed."] = "¡Es terrible! ¿No lo has oído? ¡Zamorak y Saradomin están peleando cerca de Lumbridge! ¡Han destruido gran parte del castillo! ¡Eso es propiedad real! Estoy muy molesto.",
        ["I've tasked Duke Horacio with sorting out the problem, and he claims he needs more troops."] = "Le he encargado a Duke Horacio que solucione el problema y él afirma que necesita más tropas.",
        ["So as you can see I'm very busy right now. Please don't waste my time."] = "Como puedes ver, estoy muy ocupado en este momento. Por favor, no me hagas perder el tiempo.",
        ["The kingdom is at peace again after the battle of Lumbridge! I'm glad to see Saradomin and Zamorak are both gone from there now."] = "¡El reino vuelve a estar en paz después de la batalla de Lumbridge! Me alegra ver que Saradomin y Zamorak ya no están allí.",
        ["I really hope that sort of thing doesn't happen again in my kingdom! There is a lot to tidy up!"] = "¡Realmente espero que ese tipo de cosas no vuelvan a suceder en mi reino! ¡Hay mucho que ordenar!",
        ["Ask about the protected tree."] = "Pregunta por el árbol protegido.",
        ["Your majesty, I bring troubling news. The tree you are protecting near Varrock's west bank has become diseased!"] = "Su majestad, traigo noticias preocupantes. ¡El árbol que estás protegiendo cerca de la ribera occidental de Varrock ha enfermado!",
        ["Thank you for bringing this to my attention. I have already sent for a master gardener to restore it."] = "Gracias por informarme sobre esto. Ya he mandado llamar a un maestro jardinero para restaurarlo.",
        ["Oh good. I'd hate for anything else to happen to that tree."] = "Oh, bien. Odiaría que le pasara algo más a ese árbol.",
        ["Your majesty, I bring troubling news. The tree you are protecting near Varrock's west bank has died!"] = "Su majestad, traigo noticias preocupantes. ¡El árbol que estás protegiendo cerca de la ribera occidental de Varrock ha muerto!",
        ["How did this happen? I sent for a master gardener to restore it over a week ago! He's got some explaining to do. Once he shows up, at least."] = "¿Cómo sucedió esto? ¡Mandé llamar a un maestro jardinero para restaurarlo hace más de una semana! Tiene algunas explicaciones que dar. Una vez que él aparezca, al menos.",
        ["Another tree gone..."] = "Otro árbol desaparecido...",
        ["Greetings, your majesty. How fares the tree west of Varrock bank?"] = "Saludos, majestad. ¿Cómo le va al árbol al oeste del banco Varrock?",
        ["I received reports that the tree had died. I visited the tree myself and have seen a healthy tree growing."] = "Recibí informes de que el árbol había muerto. Yo mismo visité el árbol y vi crecer un árbol sano.",
        ["Yes, that is because Farmer Jimbo replaced the dead tree!"] = "Sí, ¡eso es porque Farmer Jimbo reemplazó el árbol muerto!",
        ["Silence! I'll hear no more of this rumour-mongering."] = "¡Silencio! No volveré a oír más rumores sobre estos rumores.",
    },
    ["King Slime"] = {
        ["You are part of the problem."] = "Eres parte del problema.",
        ["You are part of the solution."] = "Eres parte de la solución.",
        ["This isn't working out..."] = "Esto no está funcionando...",
        ["Okay."] = "Está bien.",
        ["You should go check out the crates of explosives near the wizards."] = "Deberías ir a revisar las cajas de explosivos cerca de los magos.",
        ["Alright."] = "Muy bien.",
        ["I have decided to accept our new slime overlord."] = "He decidido aceptar a nuestro nuevo señor supremo del limo.",
        ["GLOOP GLOOP GLOOP!"] = "¡GLOOP GLOOP GLOOP!",
        ["Would you like to try and communicate with King Slime?"] = "¿Te gustaría intentar comunicarte con King Slime?",
        ["You should try and deal with the mini slimes today."] = "Deberías intentar lidiar con los mini slimes hoy.",
        ["GLOOP GLOOP GLOOP GLOOP GLOOP!"] = "¡GLOOP GLOOP GLOOP GLOOP GLOOP!",
        ["Do you have any final words for King Slime?"] = "¿Tiene alguna última palabra para King Slime?",
        ["It's about slime you left us alone!"] = "¡Se trata de limo que nos dejaste en paz!",
        ["You should help the wizards by channelling the portal!"] = "¡Deberías ayudar a los magos canalizando el portal!",
        ["I have prepared a poem."] = "He preparado un poema.",
        ["Roses are red. We are almost free. The question we're all asking... Where is the tree?"] = "Las rosas son rojas. Somos casi libres. La pregunta que todos nos hacemos... ¿Dónde está el árbol?",
        ["I've enjoyed our time together."] = "He disfrutado nuestro tiempo juntos.",
        ["I've enjoyed our time together. Don't forget to write!"] = "He disfrutado nuestro tiempo juntos. ¡No olvides escribir!",
    },
    ["King Vargas"] = {
        ["Thank you for your work in bringing back peace to these islands, [Fremennik Name]."] = "Gracias por tu trabajo para devolver la paz a estas islas, [Fremennik Name].",
        ["I hear that the Etceterians have also pledged to give you some of their resources, as thanks for preventing war once again."] = "He oído que los etceterianos también se han comprometido a darte algunos de sus recursos, como agradecimiento por evitar la guerra una vez más.",
        ["How is the kingdom faring?"] = "¿Cómo le va al reino?",
        ["Everything is fine, Your Majesty."] = "Todo está bien, Su Majestad.",
        ["Remember, speak to Ghrim if you require assistance."] = "Recuerda, habla con Ghrim si necesitas ayuda.",
    },
    ["Kitten (Pieces of Hate)"] = {
        ["Do you really think you can skip 'Pieces of Hate'? You can't. There is a swashbuckling grind against which your soul shall be lathed. And this is meow cat."] = "¿De verdad crees que puedes saltarte 'Piezas de odio'? No puedes. Hay una rutina de capa y espada contra la cual tu alma será torneada. Y este es el gato maullido.",
    },
    ["Kitten"] = {
        ["Do you really think you can skip 'Pieces of Hate'? You can't. There is a swashbuckling grind against which your soul shall be lathed. And this is meow cat."] = "¿De verdad crees que puedes saltarte 'Piezas de odio'? No puedes. Hay una rutina de capa y espada contra la cual tu alma será torneada. Y este es el gato maullido.",
