        ["Get out of here, outerlander!"] = "¡Fuera de aquí, extranjero!",
        ["Select an option"] = "Selecciona una opción",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["The barbarian village. Go away."] = "El pueblo bárbaro. Irse.",
        ["Who are you?"] = "¿Quién eres?",
        ["My name is Kjell. Go away."] = "Mi nombre es Kjell. Irse.",
        ["What is in this hut that you're guarding?"] = "¿Qué hay en esta cabaña que estás custodiando?",
