        ["Goodbye then."] = "Adiós entonces.",
        ["*(Kjell opens with one of the following lines:)*"] = "*(Kjell se abre con una de las siguientes líneas:)*",
        ["...love you like the stars above..."] = "...te amo como las estrellas de arriba...",
        ["...fall for pretty strangers..."] = "...enamórate de lindas desconocidas...",
        ["...but I'd do anything for you..."] = "...pero haría cualquier cosa por ti...",
        ["...there's a place for us..."] = "...hay un lugar para nosotros...",
        ["...you exploded into my heart..."] = "...explotaste en mi corazón...",
        ["...I dreamed your dream for you..."] = "...Soñé tu sueño para ti...",
        ["...fall for chains of gold..."] = "...enamórate de las cadenas de oro...",
        ["...when you gonna realise..."] = "...cuando te vas a dar cuenta...",
        ["Blast!"] = "¡Explosión!",
        ["Having trouble there?"] = "¿Tienes problemas allí?",
        ["I don't need the advice of an outerlander."] = "No necesito el consejo de un extranjero.",
        ["This music isn't very restful."] = "Esta música no es muy relajante.",
        ["Get out of here!"] = "¡Fuera de aquí!",
        ["Maybe you should take some lessons."] = "Quizás deberías tomar algunas lecciones.",
        ["I'll leave you in peace."] = "Te dejaré en paz.",
