        ["Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "Bueno, el orden ha disminuido bastante con los años, es un proceso muy largo aprender las habilidades de un Void Knight. Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar, y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
        ["How can I help?"] = "¿Cómo puedo ayudar?",
        ["We send launchers from our outpost to the nearby islands. If you go and wait in the lander there that'd really help."] = "Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas en el módulo de aterrizaje, eso sería de gran ayuda.",
        ["Sorry, but I can't."] = "Lo siento, pero no puedo.",
        ["What's 'Gielinor'?"] = "¿Qué es 'Gielinor'?",
        ["It is the name that Guthix gave to this world, so we honour him with its use."] = "Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
        ["I'd rather not, sorry."] = "Preferiría no hacerlo, lo siento.",
        ["Good luck with that."] = "Buena suerte con eso.",
        ["Uh huh, sure."] = "Ajá, claro.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is our outpost. From here we send launches out to the nearby islands to beat back the invaders."] = "Este es nuestro puesto de avanzada. Desde aquí enviamos lanchas a las islas cercanas para hacer retroceder a los invasores.",
        ["What invaders?"] = "¿Qué invasores?",
        ["Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
        ["I'm fine, thanks."] = "Estoy bien, gracias.",
        ["Player! Good timing. Commodore Tyr was looking for you."] = "¡Player! Buen momento. El comodoro Tyr te estaba buscando.",
    },
    ["Kortan"] = {
        ["Hello, you look like a bold adventurer. You've come to the right place for adventurers' equipment."] = "Hola, pareces un aventurero audaz. Has venido al lugar correcto para encontrar equipo para aventureros.",
        ["Select an option"] = "Seleccione una opción",
        ["Oh, that sounds interesting."] = "Oh, eso suena interesante.",
        ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
        ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
        ["No, sorry, I've come to the wrong place."] = "No, lo siento, he venido al lugar equivocado.",
        ["Hmph. Well, perhaps next time you'll need something from me?"] = "Hmph. Bueno, ¿quizás la próxima vez necesites algo de mí?",
    },
    ["Kotahi"] = {
        ["Isn't Banky cute?<br/>An explorer found him on one of the uncharted isles. Not sure how he wound up with a chest on his back, but I've put him to good use."] = "¿No es lindo Banky?<br/>Un explorador lo encontró en una de las islas inexploradas. No estoy seguro de cómo terminó con un cofre en la espalda, pero le he dado un buen uso.",
        ["Have you seen Banky?<br/>I really need to put a leash on that little fella."] = "¿Has visto a Banky? <br/>Realmente necesito ponerle una correa a ese pequeño.",
    },
    ["Kragen"] = {
        ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
        ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
        ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
        ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
        ["Yes."] = "Sí.",
        ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
        ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
        ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
        ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
        ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
        ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
        ["Choose an option:"] = "Elige una opción:",
        ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
        ["I might. Which one were you thinking of?"] = "Podría hacerlo. ¿En cuál estabas pensando?",
        ["Select an Option"] = "Selecciona una opción",
        ["The northern allotment."] = "La parcela del norte.",
        ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
        ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
        ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
        ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
        ["Okay, it's a deal."] = "Está bien, es un trato.",
        ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
        ["No, that's too much."] = "No, eso es demasiado.",
        ["The southern allotment."] = "La parcela del sur.",
        ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
        ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
        ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
        ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
        ["Can you sell me something?"] = "¿Puedes venderme algo?",
        ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["Some plant cure."] = "Alguna cura vegetal.",
        ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
        ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
        ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
        ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
        ["A bucket of compost."] = "Un balde de abono.",
        ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
        ["A rake."] = "Un rastrillo.",
        ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["(See more items)"] = "(Ver más artículos)",
        ["A watering can"] = "una regadera",
        ["A watering can."] = "Una regadera.",
        ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
        ["A gardening trowel"] = "Una paleta de jardinería",
        ["A gardening trowel."] = "Una paleta de jardinería.",
        ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["A seed dibber"] = "Un zambullidor de semillas",
        ["A seed dibber."] = "Un arrancador de semillas.",
        ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
        ["(See previous items)"] = "(Ver artículos anteriores)",
        ["Forget it."] = "Olvídalo.",
        ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
        ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
        ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    },
    ["Krar Jnr"] = {
        ["You hear a howling in the distance!"] = "¡Se oye un aullido a lo lejos!",
        ["You manage to catch the runaway beast!"] = "¡Logras atrapar a la bestia fugitiva!",
        ["You have unlocked a new pet!"] = "¡Has desbloqueado una nueva mascota!",
        ["One of these things is handful enough, trying to deal with two of them would be madness!"] = "Una de estas cosas es bastante difícil, ¡tratar de lidiar con dos de ellas sería una locura!",
        ["Do you miss your home?"] = "¿Extrañas tu hogar?",
        ["Grooaoar brrrr, hisssss!"] = "¡Groooar brrrr, sissss!",
        ["I SAID, DO YOU MISS YOUR HOME?"] = "DIJE, ¿Extrañas tu casa?",
        ["What do you want to do today?"] = "¿Qué quieres hacer hoy?",
        ["I SAID, WHAT DO YOU WANT TO DO TODAY?"] = "DIJE, ¿QUÉ QUIERES HACER HOY?",
        ["How are you today, Krar Jnr?"] = "¿Cómo estás hoy, Krar Jnr?",
        ["I SAID, HOW ARE YOU?"] = "DIJE, ¿CÓMO ESTÁS?",
        ["Category:NPC dialogue"] = "Categoría: Diálogo NPC",
    },
    ["Kree'gal"] = {
        ["You hear the spiritual warrior's voice in your head: \"Uu'Son."] = "Escuchas la voz del guerrero espiritual en tu cabeza: \"Uu'Son\".",
        ["*(The player responds with one of the following, at random, and then the dialogue ends.)*"] = "*(el player responde con una de las siguientes opciones, al azar, y luego finaliza el diálogo.)*",
        ["Hello?"] = "¿Hola?",
        ["I beg your pardon?"] = "¿Perdón?",
        ["Sorry, what?"] = "Lo siento, ¿qué?",
        ["What does that mean?"] = "¿Qué significa eso?",
    },
    ["Kringk"] = {
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["Me very busy. No have time to talk to puny creature like you."] = "Estoy muy ocupado. No tengo tiempo para hablar con una criatura insignificante como tú.",
        ["Well, excuse me!"] = "Bueno, ¡disculpe!",
        ["No excuse for you - you in my way."] = "No hay excusa para ti, estás en mi camino.",
        ["I would offer haircut, but it hard to do style for puny human with puny head."] = "Ofrecería un corte de pelo, pero es difícil hacer un estilo para un humano insignificante con una cabeza insignificante.",
        ["Me know. You want wig intead? Me give you big-big discount!"] = "Ya lo sé. ¿Quieres peluca en su lugar? ¡Te doy un gran descuento!",
        ["Would you like to buy an ogre wig for 50 gp?"] = "¿Te gustaría comprar una peluca de ogro por 50 po?",
        ["Yes, please."] = "Sí, por favor.",
        ["You no have enough shiny pretties, human."] = "No tienes suficientes bellezas brillantes, humano.",
        ["There you go. Nice wig for you, made from de freshest wolfsie bones."] = "Ahí lo tienes. Bonita peluca para ti, hecha con los huesos de lobo más frescos.",
        ["You no have enough room to hold it, human. Come back when you have space."] = "No tienes suficiente espacio para sostenerlo, humano. Vuelve cuando tengas espacio.",
        ["No, thank you."] = "No, gracias.",
        ["So, how do you like what's, um, being done to your head?"] = "Entonces, ¿qué te parece lo que te están haciendo en la cabeza?",
        ["Quit talking to goblin, Player. If she moves her head, she mess up work."] = "Deja de hablar con el duende, Player. Si mueve la cabeza, arruina el trabajo.",
        ["Oh, sorry! I would never dream of interfering in the creative process."] = "¡Oh, lo siento! Nunca se me ocurriría interferir en el proceso creativo.",
    },
    ["Kristlin"] = {
        ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
        ["Who are you?"] = "¿Quién eres?",
        ["My name is Kristlin, and this is the tent where I tell fortunes. What is your name, seeker of truth?"] = "Mi nombre es Kristlin y esta es la tienda donde cuento la buenaventura. ¿Cómo te llamas, buscador de la verdad?",
        ["Player{{Sic}}"] = "Jugador{{Sic}}",
        ["Glad tidings to you, Player, may your path be clear and guide you towards happiness."] = "Buenas noticias para ti, Player, que tu camino sea claro y te guíe hacia la felicidad.",
        ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
        ["I'd like my fortune read."] = "Me gustaría que leyeran mi fortuna.",
        ["*(If not enough tokens are owned:)*"] = "*(Si no tienes suficientes tokens:)*",
        ["You're welcome to a reading but first you have to cross my palm with forty tokens. Helps get the mystic forces flowing."] = "Eres bienvenido a una lectura, pero primero tienes que cruzar mi palma con cuarenta fichas. Ayuda a que las fuerzas místicas fluyan.",
        ["You can get more fayre tokens and tickets from the stall by the Bucking Baroo."] = "Puede obtener más fichas y boletos de Fayre en el puesto junto al Bucking Baroo.",
        ["*(If enough tokens are owned, and there isn't currently an active cloud of destiny:)*"] = "*(Si se poseen suficientes tokens y actualmente no hay una nube de destino activa:)*",
        ["*(If the warning hasn't been toggled off:)*"] = "*(Si la advertencia no se ha desactivado:)*",
        ["This activity will cost 40 fayre attraction tokens. Are you sure you want to continue?"] = "Esta actividad costará 40 fichas de atracción de Fayre. ¿Estás seguro de que quieres continuar?",
        ["Get a fortune?"] = "¿Conseguir una fortuna?",
        ["Yes."] = "Sí.",
        ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
        ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
        ["*(If the warning has been toggled off:)*"] = "*(Si la advertencia se ha desactivado:)*",
        ["*(If enough tokens are owned, and there is currently an active cloud of destiny:)*"] = "*(Si se poseen suficientes tokens y actualmente hay una nube de destino activa:)*",
        ["Would you like to buy a new reading?"] = "¿Quieres comprar una nueva lectura?",
        ["Yes"] = "si",
        ["*(Dialogue from getting a fortune occurs.)*"] = "*(Se produce un diálogo sobre cómo conseguir una fortuna.)*",
        ["Why are you here?"] = "¿Por qué estás aquí?",
        ["I travel with Menowin, and his group of friends. It allows me to talk to many different people, and to impart my knowledge as I go. In fact, meeting so many different people seems to increase my abilities. The more I travel the clearer my fortunes become."] = "Viajo con Menowin y su grupo de amigos. Me permite hablar con muchas personas diferentes e impartir mis conocimientos sobre la marcha. De hecho, conocer tanta gente diferente parece aumentar mis habilidades. Cuanto más viajo, más clara se vuelve mi suerte.",
        ["What abilities do you have?"] = "¿Qué habilidades tienes?",
        ["I have only one ability, and that is to read the fortunes of people; to know what their destiny is. It's still only in the short-term at the moment, but as my powers increase so does the length of time I can see into the future for people."] = "Sólo tengo una habilidad, y es leer la suerte de las personas; saber cuál es su destino. Por el momento, todavía es solo a corto plazo, pero a medida que mis poderes aumentan, también aumenta el tiempo que puedo ver el futuro de las personas.",
        ["How do you read fortunes?"] = "¿Cómo se lee la fortuna?",
        ["I have a deck of fortune cards. All you need to do is choose the three cards that call to you the strongest after I spread them out on the table. You should go with your instinct. There are no right or wrong answers."] = "Tengo una baraja de cartas de la fortuna. Todo lo que necesitas hacer es elegir las tres cartas que te llamen más fuerte después de que las extienda sobre la mesa. Debes seguir tu instinto. No hay respuestas correctas o incorrectas.",
        ["Where did you get your cards from?"] = "¿De dónde sacaste tus tarjetas?",
        ["I created my deck of fortune cards myself. The names and images of the cards came to me in my dreams, over several months. I realized when I focused on those images my ability to read the future for people became stronger, and clearer. This was the best way I could think of to hone my focus. It seems to work quite well."] = "Yo mismo creé mi mazo de cartas de la fortuna. Los nombres y las imágenes de las tarjetas me llegaron en sueños durante varios meses. Me di cuenta de que cuando me concentraba en esas imágenes mi capacidad para leer el futuro de las personas se hacía más fuerte y más clara. Esta fue la mejor manera que se me ocurrió para perfeccionar mi enfoque. Parece funcionar bastante bien.",
        ["Are you cards based on anything in-particular?"] = "¿Están sus tarjetas basadas en algo en particular?",
        ["Just the flashes of images and concepts that come to me as I dream. They have been coming to me since I was a little girl. I believe one day I will understand what they truly are, but until that day I am a{{Sic}} happy to be a servant to their power."] = "Sólo los destellos de imágenes y conceptos que me vienen mientras sueño. Han estado viniendo a mí desde que era niña. Creo que algún día entenderé lo que realmente son, pero hasta ese día estoy muy feliz de ser un servidor de su poder.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["What is your fortune?"] = "¿Cuál es tu fortuna?",
        ["Alas, I dont now know that. I cannnot read my own fortune. I have tried many times, but the cards never give me a clear answer. I have come to accept this, though, and believe that my future is wrapped up in the fortunes of others, and through my work I am fulfilling my destiny."] = "Por desgracia, ahora no lo sé. No puedo leer mi propia fortuna. Lo he intentado muchas veces, pero las tarjetas nunca me dan una respuesta clara. Sin embargo, he llegado a aceptar esto y creo que mi futuro está envuelto en la suerte de los demás y que a través de mi trabajo estoy cumpliendo mi destino.",
        ["What does my fortune mean?"] = "¿Qué significa mi fortuna?",
        ["*(If a cloud of destiny isn't active:)*"] = "*(Si una nube del destino no está activa:)*",
        ["Ah well, to understand your fortune you would first need to get a reading. Would you like me to read your fortune?"] = "Ah, bueno, para entender tu fortuna primero necesitarás hacer una lectura. ¿Quieres que te lea la fortuna?",
        ["*(If a cloud of destiny is active:)*"] = "*(Si una nube del destino está activa:)*",
        ["Your fortune is your own, and can only truly be deciphered by you. All answers will come in time."] = "Tu fortuna es tuya y solo tú puedes descifrarla verdaderamente. Todas las respuestas llegarán con el tiempo.",
        ["However, looking at your aura, you appear to be in a positive state, and I am sure that the fortune will become clear to you and will be a rewarding experience."] = "Sin embargo, al observar tu aura, pareces estar en un estado positivo y estoy seguro de que la fortuna se te aclarará y será una experiencia gratificante.",
        ["What does cloud of destiny mean?"] = "¿Qué significa nube del destino?",
        ["Ah! Lucky people, when they receive a fortune, receive a 'cloud of destiny'. If they then do what the cloud of destiny portends, they receive a boon."] = "¡Ah! Las personas afortunadas, cuando reciben una fortuna, reciben una \"nube del destino\". Si luego hacen lo que presagia la nube del destino, recibirán una bendición.",
        ["More."] = "Más.",
        ["How did you meet Menowin?"] = "¿Cómo conociste a Menowin?",
        ["He and his band of friends came through my village one day, looking for shelter as they traveled on to the next city. I was working in a bar the the time. Menowin was the last customer to leave that night, and as I was clearing up I offered to read his fortune. It was the strongest feeling I had ever got from a fortune and it was like fate was pushing me towards him. I believe he felt the same as he offered to let me join him on his travels."] = "Él y su grupo de amigos pasaron por mi pueblo un día en busca de refugio mientras viajaban hacia la siguiente ciudad. Estaba trabajando en un bar en ese momento. Menowin fue el último cliente en irse esa noche y, mientras estaba limpiando, me ofrecí a leer su fortuna. Fue el sentimiento más fuerte que jamás había tenido de una fortuna y era como si el destino me estuviera empujando hacia él. Creo que él sintió lo mismo cuando se ofreció a dejarme acompañarlo en sus viajes.",
        ["*(Only if nothing has been asked before:)*"] = "*(Solo si no se ha preguntado nada antes:)*",
        ["Do you have any cookies?"] = "¿Tienes galletas?",
        ["*(If the player does not have a cookie in their inventory or bank:)*"] = "*(Si el player no tiene una cookie en su inventario o banco:)*",
        ["Would you like a cookie?"] = "¿Quieres una galleta?",
        ["Is there a fortune inside the cookie?"] = "¿Hay una fortuna dentro de la galleta?",
        ["What a strange idea. I might have to look into that for the future."] = "Qué idea más extraña. Quizás tenga que investigar eso para el futuro.",
        ["*(If the player already has a cookie in their inventory or bank:)*"] = "*(Si el player ya tiene una cookie en su inventario o banco:)*",
        ["I'd offer you another, but it looks like you haven't eaten your last one."] = "Te ofrecería otro, pero parece que no te has comido el último.",
        ["*(Only after asking something else:)*"] = "*(Solo después de preguntar algo más :)*",
        ["Bye."] = "Adiós.",
        ["May your path be clear and guide you towards happiness."] = "Que tu camino sea claro y te guíe hacia la felicidad.",
        ["*(If a tarot card token isn't owned, and there isn't currently an active cloud of destiny:)*"] = "*(Si no se posee una ficha de carta del tarot y actualmente no hay una nube del destino activa:)*",
        ["You're welcome to a reading but first you have to cross my palm with a tarot card token. Helps get the mystic forces flowing."] = "Eres bienvenido a una lectura, pero primero tienes que cruzar mi palma con una ficha de carta del tarot. Ayuda a que las fuerzas místicas fluyan.",
        ["You can get tarot card tokens by taking part in activities at the fayre."] = "Puedes conseguir fichas de cartas del tarot participando en actividades en la feria.",
        ["*(If a tarot card token isn't owned, and there is currently an active cloud of destiny:)*"] = "*(Si no se posee una ficha de carta del tarot y actualmente hay una nube del destino activa:)*",
        ["Use a tarot card to reroll your fortune?"] = "¿Usar una carta del tarot para volver a tirar tu fortuna?",
        ["*(If a tarot card token is owned, and there isn't currently an active cloud of destiny:)*"] = "*(Si se posee una ficha de carta del tarot y actualmente no hay una nube del destino activa:)*",
        ["*(If a tarot card token is owned, and there is currently an active cloud of destiny:)*"] = "*(Si se posee una ficha de carta del tarot y actualmente hay una nube de destino activa:)*",
        ["What happened to the cavern of tainted memories?"] = "¿Qué pasó con la caverna de los recuerdos contaminados?",
        ["The portal became too unstable and broke down."] = "El portal se volvió demasiado inestable y se rompió.",
        ["I believe that the cavern is there, waiting for brave adventurers to find it again, but I do not know when it might make itself visible again."] = "Creo que la caverna está ahí, esperando que valientes aventureros la encuentren nuevamente, pero no sé cuándo podrá volver a hacerse visible.",
        ["Cross my palm with tokens to know your future."] = "Cruza mi palma con fichas para conocer tu futuro.",
        ["*(If enough tokens are owned:)*"] = "*(Si tienes suficientes tokens:)*",
        ["Cross my palm with a tarot card token to know your future."] = "Cruza mi palma con una ficha de carta del tarot para conocer tu futuro.",
        ["*(If a tarot card token isn't owned:)*"] = "*(Si no tienes una ficha de carta del tarot:)*",
        ["*(If a tarot card token is owned:)*"] = "*(Si posee una ficha de carta del tarot:)*",
        ["*(If a cookie isn't owned:)*"] = "*(Si una cookie no es de su propiedad:)*",
        ["*(If a cookie is owned:)*"] = "*(Si es propiedad de una cookie:)*",
        ["Hello there my darling! I seem to have uncovered a special cavern in my quest to further my divining knowledge!"] = "¡Hola, cariño! ¡Parece que he descubierto una caverna especial en mi búsqueda por ampliar mis conocimientos de adivinación!",
        ["What makes this cavern so special?"] = "¿Qué hace que esta caverna sea tan especial?",
        ["It appears to be home to a certain kind of rare wisp. They have been corrupted with the evil memories of the world."] = "Parece ser el hogar de cierto tipo de brizna poco común. Han sido corrompidos por los malos recuerdos del mundo.",
        ["However it isn't all doom and gloom. It turns out these wisps can be harvested for a type of essence that can be cleansed and forged into some rather lovely weaponry."] = "Sin embargo, no todo es pesimismo. Resulta que estos mechones se pueden recolectar para obtener un tipo de esencia que se puede limpiar y convertir en un arma bastante encantadora.",
        ["That sounds pretty awesome!"] = "¡Eso suena increíble!",
        ["Quite. But I can't just be allowing this precious resource to be harvested unchecked. We don't know whether it is finite or not."] = "Bastante. Pero no puedo simplemente permitir que este valioso recurso sea cosechado sin control. No sabemos si es finito o no.",
        ["I will allove you a short period of time in there in each day. If you bring me a cavern entry token, I'll allow you in again!"] = "Te dejaré un breve período de tiempo allí cada día. ¡Si me traes una ficha de entrada a la caverna, te permitiré entrar otra vez!",
        ["When entering the cavern, you will have 2 minutes 30 seconds to collect as much tainted essence as you can before you are removed from the area. <span style=\"color:#008C2A\">Stand in multiplier locations to recieve{{Sic}} increased XP and essence. Collect tainted chronicles from afar to gather a lump of essence.</span>"] = "Al ingresar a la caverna, tendrás 2 minutos y 30 segundos para recolectar tanta esencia contaminada como puedas antes de que te retiren del área. <span style=\"color:#008C2A\">Párate en ubicaciones multiplicadoras para recibir {{Sic}} mayor XP y esencia. Recoge crónicas contaminadas desde lejos para reunir un trozo de esencia.</span>",
        ["If you don't want to receive Divination XP from the cavern, I could give you a bundle of other rewards instead."] = "Si no quieres recibir XP Divination de la caverna, podría darte un paquete de otras recompensas.",
        ["Would you like to receive Divination XP or mystery rewards?"] = "¿Le gustaría recibir Divination XP o recompensas misteriosas?",
        ["Divination XP"] = "DivinationXP",
        ["Very well. You will now receive Divination XP whilst you are in the cavern."] = "Muy bien. Ahora recibirás Divination XP mientras estés en la caverna.",
        ["Mystery rewards"] = "Recompensas misteriosas",
        ["Very well. You will now receive some mystery rewards when you leave the cavern."] = "Muy bien. Ahora recibirás algunas recompensas misteriosas cuando salgas de la caverna.",
        ["<span style=\"color:red\">Note :</span> You will still have to earn your rewards. The amount you receive will be based on the amount of XP you would have earned."] = "<span style=\"color:red\">Nota: </span> Aún tendrás que ganar tus recompensas. La cantidad que reciba se basará en la cantidad de XP que habría ganado.",
        ["*(Continues as above.)*"] = "*(Continúa como arriba.)*",
    },
    ["Ksenia"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
        ["Strange how?"] = "¿Qué extraño cómo?",
        ["Like a human!"] = "¡Como un humano!",
        ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["Get lost!"] = "¡Piérdete!",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["Leave me alone."] = "Déjame en paz.",
        ["*Dialogue 7*"] = "*Diálogo 7*",
        ["Have you no manners?"] = "¿No tienes modales?",
        ["*Dialogue 8*"] = "*Diálogo 8*",
        ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
        ["*Dialogue 9*"] = "*Diálogo 9*",
        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
        ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
        ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
        ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
        ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
        ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
        ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
        ["Good day to you, my friend."] = "Buenos días, amigo mío.",
        ["You smell familiar..."] = "Hueles familiar...",
        ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    },
    ["Kuradal"] = {
        ["Heya, can I help you?"] = "Oye, ¿puedo ayudarte?",
        ["Select an option"] = "Seleccione una opción",
        ["I need another assignment."] = "Necesito otra tarea.",
        ["Sorry, but you're not strong enough to be taught by me."] = "Lo siento, pero no eres lo suficientemente fuerte para que yo te enseñe.",
        ["Can we talk about items and incentives?"] = "¿Podemos hablar de artículos e incentivos?",
        ["Of course, what would you like to discuss: items for sale or incentives?"] = "Por supuesto, ¿de qué le gustaría hablar: artículos en venta o incentivos?",
        ["Let's talk items."] = "Hablemos de elementos.",
        ["I have a wide selection of Slayer equipment - take a look!"] = "Tengo una amplia selección de equipos Slayer. ¡Échale un vistazo!",
        ["Let's talk incentives."] = "Hablemos de incentivos.",
        ["Select an Option"] = "Selecciona una opción",
        ["View rewards."] = "Ver recompensas.",
        ["How do I earn co-op points to spend on rewards?"] = "¿Cómo gano puntos cooperativos para gastarlos en recompensas?",
        ["You'll gain co-op reward points if you complete at least half of your contribution to a task with a friend. That means you need to be in a group for most of the time you're working on the task, but it doesn't matter if your friend beats you to the majority of kills! You'll still have been in a group for most of your contribution, so you're still entitled to a co-op reward point."] = "Obtendrás puntos de recompensa cooperativa si completas al menos la mitad de tu contribución a una tarea con un amigo. Eso significa que debes estar en un grupo la mayor parte del tiempo que estés trabajando en la tarea, ¡pero no importa si tu amigo te gana en la mayoría de las muertes! Aún habrás estado en un grupo durante la mayor parte de tu contribución, por lo que aún tendrás derecho a un punto de recompensa cooperativa.",
        ["Where can I use the co-op food and potion rewards?"] = "¿Dónde puedo usar las recompensas cooperativas de comida y pociones?",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["The rewards can be used in most of the areas we commonly send you to complete your tasks."] = "Las recompensas se pueden usar en la mayoría de las áreas que comúnmente te enviamos para completar tus tareas.",
        ["Tell me about your skillcape, please."] = "Cuéntame sobre tu skillcape, por favor.",
        ["This is a Slayer's Skillcape. Only a true Slayer master is permitted to wear one. You need more training before you earn that honour."] = "Este es un Skillcape de Slayer. Sólo un verdadero Slayer master puede usar uno. Necesitas más entrenamiento antes de ganar ese honor.",
        ["Can you sell me a Slayer skillcape?"] = "¿Puedes venderme un Slayer skillcape?",
        ["Well you have performed well as a student. I guess you have earned the right to wear such a prestigious cape now. That will be 99,000 coins, please."] = "Bueno, te has desempeñado bien como estudiante. Supongo que ahora te has ganado el derecho a llevar una capa tan prestigiosa. Serán 99.000 coins, por favor.",
        ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins para este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
        ["I see you have one of Hans' cape inversion tokens! I'll take that off your hands, and will sell you any inverted cape you're eligible for."] = "¡Veo que tienes una de las fichas de inversión de capa de Hans! Te quitaré eso de las manos y te venderé cualquier inverted cape para el que seas elegible.",
        ["Choose an option:"] = "Elige una opción:",
        ["99,000 coins? That's much too expensive. ((or 92,000 coins with Ring of charos (a)))"] = "¿99.000 coins? Eso es demasiado caro. ((o 92.000 coins con Ring of charos (a)))",
        ["Not at all; there are many other adventurers who would love the opportunity to purchase such a prestigious item! You can find me here if you change your mind."] = "En absoluto; ¡Hay muchos otros aventureros a quienes les encantaría tener la oportunidad de comprar un artículo tan prestigioso! Puedes encontrarme aquí si cambias de opinión.",
        ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
        ["*(If the player has at least two free backpack spaces:)*"] = "*(Si el player tiene al menos dos espacios backpack libres:)*",
        ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
        ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some inventory space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en el inventario antes de que pueda venderte uno.",
        ["I'd like a skillcape with the colours inverted."] = "Me gustaría un skillcape con los colores invertidos.",
        ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
        ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
        ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
        ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
        ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Slayer master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderte una capa Slayer master.",
        ["Buy Slayer master cape for 120,000 coins?"] = "¿Comprar capa Slayer master por 120.000 coins?",
        ["Yes."] = "Sí.",
        ["*(If the player has at least one free backpack space:)*"] = "*(Si el player tiene al menos un espacio backpack libre:)*",
        ["*(If the player does not have at least one free backpack space:)*"] = "*(Si el player no tiene al menos un espacio libre en backpack:)*",
        ["You do not have enough room in your inventory. Please come back when you have some more."] = "No tienes suficiente espacio en tu inventario. Por favor regresa cuando tengas más.",
        ["I'd like a master cape with the colours inverted."] = "Me gustaría un master cape con los colores invertidos.",
        ["I've noticed there are a couple versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
        ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
        ["*(If the player has chosen the new skillcape models:)*"] = "*(Si el player ha elegido los nuevos modelos skillcape :)*",
        ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes optar por usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
        ["Yes, I would like to wear the old version of the skillcape."] = "Sí, me gustaría usar la versión antigua del skillcape.",
        ["Would you like to wear the old model for just this cape, or for the Quest point cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo antiguo solo para esta capa, o para la capa de puntos Quest y todos los skillcapes que tienes?",
        ["I would just like to change the Slayer skillcape."] = "Solo me gustaría cambiar el Slayer skillcape.",
        ["No problem, you will now use the older model for your Slayer skillcape."] = "No hay problema, ahora utilizarás el modelo anterior para tu Slayer skillcape.",
        ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
        ["No problem, you will now use the older model for all of your skillcapes!"] = "No hay problema, ¡ahora usarás el modelo anterior para todos tus skillcapes!",
        ["I've changed my mind!"] = "¡He cambiado de opinión!",
        ["No, thank you."] = "No, gracias.",
        ["Great! I'm glad you're enjoying our new version!"] = "¡Genial! ¡Me alegra que estés disfrutando de nuestra nueva versión!",
        ["*(If the player is using the old skillcape models except for the Slayer cape:)*"] = "*(Si el player está usando los modelos skillcape antiguos excepto la capa Slayer :)*",
        ["If you want, I can make it so you use the newer model for all of the skillcapes you own!"] = "¡Si quieres, puedo hacerlo para que uses el modelo más nuevo para todos los skillcapes que tienes!",
        ["Ok, I'd like to wear the newer version for all my skillcapes."] = "Ok, me gustaría usar la versión más nueva para todos mis skillcapes.",
        ["Great, you will now use the newer model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo más nuevo para todos tus skillcapes!",
        ["No, thanks."] = "No, gracias.",
        ["*(If the player has chosen the old skillcape models:)*"] = "*(Si el player ha elegido los modelos antiguos skillcape :)*",
        ["It looks like you're currently using the old model for your Slayer skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Slayer skillcape. ¿Quieres cambiar a uno más nuevo?",
        ["Yes, I would like to wear the new version of the skillcape."] = "Sí, me gustaría usar la nueva versión del skillcape.",
        ["Would you like to wear the newer model for just this cape, or all of the skillcapes you own?"] = "¿Te gustaría usar el modelo más nuevo solo para esta capa o para todos los skillcapes que tienes?",
        ["No problem, you will now use the newer model for your Slayer skillcape."] = "No hay problema, ahora utilizarás el modelo más nuevo para tu Slayer skillcape.",
        ["No problem, you will now use the newer model for all of your skillcapes!"] = "No hay problema, ¡ahora usarás el modelo más nuevo para todos tus skillcapes!",
        ["Great! I'm glad you're still enjoying the old version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión anterior!",
        ["*(If the player is using the new skillcape models except for the Slayer cape:)*"] = "*(Si el player está usando los nuevos modelos skillcape excepto la capa Slayer :)*",
        ["If you want, I can make it so you use the old model for all of the skillcapes you own!"] = "¡Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas!",
        ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
        ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
        ["Let's talk about you."] = "Hablemos de ti.",
        ["I'm Kuradal, daughter of Duradel. What more would you like to know?"] = "Soy Kuradal, hija de Duradel. ¿Qué más te gustaría saber?",
        ["Tell me more about your background."] = "Cuéntame más sobre tus antecedentes.",
        ["If you so desire. As I said, I am Kuradal, daughter of Duradel - another great master of Slayer. Unlike the others, though, I ventured out not only to slay, but also to capture. I've caught many different types of creatures and I hold them within this dungeon, reserved exclusively for my pupils to slay."] = "Si así lo deseas. Como dije, soy Kuradal, hija de Duradel - otro gran maestro de Slayer. Sin embargo, a diferencia de los demás, me aventuré no sólo a matar, sino también a capturar. He capturado muchos tipos diferentes de criaturas y las mantengo dentro de esta mazmorra, reservada exclusivamente para que mis alumnos las maten.",
        ["So slaying runs in the family, then?"] = "Entonces, ¿matar es cosa de familia?",
        ["Of course. One cannot simply 'grow up' with someone like my father. My childhood was all combat training, taking on the beasts of this land side by side with my father."] = "Por supuesto. Uno no puede simplemente \"crecer\" con alguien como mi padre. Mi infancia fue toda entrenamiento de combate, enfrentándome a las bestias de esta tierra al lado de mi padre.",
        ["So who is your mother?"] = "Entonces, ¿quién es tu madre?",
        ["I'd rather not say. Can we talk about something else?"] = "Preferiría no decirlo. ¿Podemos hablar de otra cosa?",
        ["About your father..."] = "Sobre tu padre...",
        ["*(Same as below)*"] = "*(Igual que a continuación)*",
        ["That's all for now."] = "Eso es todo por ahora.",
        ["Fine. I'll be here if you need me."] = "Bien. Estaré aquí si me necesitas.",
        ["Sounds like you had a hectic childhood!"] = "¡Parece que tuviste una infancia agitada!",
        ["You could say that, but I am thankful for it as it made me the person I am today."] = "Se podría decir eso, pero estoy agradecido por ello, ya que me convirtió en la persona que soy hoy.",
        ["*(Same as above)*"] = "*(Igual que arriba)*",
        ["*If you have not yet completed While Guthix Sleeps*"] = "*Si aún no has completado Mientras Guthix duerme*",
        ["About your father... How come you aren't with him now?"] = "Sobre tu padre... ¿Cómo es que no estás con él ahora?",
        ["We are still close, but combat and competition runs deep in both our veins. I strive to be the best, so took up a Slayer Master position and want to give people a greater challenge than that of my father."] = "Todavía estamos cerca, pero el combate y la competencia corren profundamente en nuestras venas. Me esfuerzo por ser el mejor, por eso asumí un puesto en Slayer Master y quiero brindarles a las personas un desafío mayor que el de mi padre.",
        ["*If you have completed Ritual of the Mahjarrat*"] = "*Si has completado el Ritual del Mahjarrat*",
        ["About your father... Lucien is dead!"] = "Acerca de tu padre... ¡Lucien está muerto!",
        ["I know. I saw his corpse up at the ritual site."] = "Lo sé. Vi su cadáver en el lugar del ritual.",
        ["What? You were there? I didn't see you."] = "¿Qué? ¿Estabas allí? No te vi.",
        ["Nor I you, but I was there, fighting off Mahjarrat and their minions. None of them were Lucien, though. I chased one of them into a cave, full of ice elementals called glacors. After killing a couple hundred of those, I managed to escape, but by then it was all over: everyone had gone."] = "Yo tampoco, pero yo estaba allí, luchando contra Mahjarrat y sus secuaces. Sin embargo, ninguno de ellos era Lucien. Perseguí a uno de ellos hasta una cueva llena de elementales de hielo llamados glacors. Después de matar a un par de cientos de ellos, logré escapar, pero para entonces todo había terminado: todos se habían ido.",
        ["You sound angry. I'd have thought you'd be glad he's dead!"] = "Suenas enojado. ¡Pensé que te alegrarías de que estuviera muerto!",
        ["I am, but Lucien was my kill! Mine alone! No one had the right to take that from me! No one! ... How will I honour my father's memory?"] = "Lo soy, ¡pero Lucien fue mi presa! ¡Solo mío! ¡Nadie tenía derecho a quitarme eso! ¡Nadie! ... ¿Cómo honraré la memoria de mi padre?",
        ["You honour him every day."] = "Lo honras todos los días.",
        ["Bah! Any more of that touchy-feely nonsense and I'll be forced to revoke your Slayer licence..."] = "¡Bah! Si sigues con esas tonterías sensibleras me veré obligado a revocar tu licencia de Slayer...",
        ["But, yo-"] = "Pero, yo-",
        ["Hahaha! The look on your face! That cheered me up some. Thanks, Player. 'You honour him every day."] = "¡Jajaja! ¡La expresión de tu cara! Eso me animó un poco. Gracias, Player. \"Lo honras todos los días\".",
        ["I'm, er, glad I could help."] = "Me alegro de poder ayudar.",
        ["Now, can I help with anything else?"] = "Ahora, ¿puedo ayudar con algo más?",
        ["By helping to defeat what killed Lucien!"] = "¡Ayudando a derrotar a lo que mató a Lucien!",
        ["Which was what, exactly?"] = "¿Qué era exactamente?",
        ["A dragonkin. Three of them, in fact."] = "Un dragonante. De hecho, tres de ellos.",
        ["Hmm, now that sounds like a challenge worthy of a slayer master. I've got some preparations to make. Collecting those for a dungeon could be tricky..."] = "Hmm, eso suena como un desafío digno de un slayer master. Tengo algunos preparativos que hacer. Recolectarlos para una mazmorra podría ser complicado...",
        ["Collecting them? You're crazy!"] = "¿Coleccionarlos? ¡Estás loco!",
        ["So what's in this dungeon then?"] = "Entonces, ¿qué hay en esta mazmorra?",
        ["Well, I've been all over and managed to capture hellhounds, greater demons, gargoyles, abyssal demons, airut, dark beasts, blue, iron, and steel dragons."] = "Bueno, estuve por todas partes y logré capturar perros del infierno, demonios mayores, gárgolas, demonios abisales, airut, bestias oscuras, dragones azules, de hierro y de acero.",
        ["*If you're playing as male character* **Player:** You caught them single-handedly?"] = "*Si juegas como un personaje masculino* **Player:** ¿Los atrapaste sin ayuda de nadie?",
        ["You doubt my skills?"] = "¿Dudas de mis habilidades?",
        ["I didn't mean anything by it."] = "No quise decir nada con eso.",
        ["I'm glad to hear so. *(continues as below)*"] = "Me alegra saberlo. *(continúa como a continuación)*",
        ["Well, come on. You are just a girl and I'm a tough warrior!"] = "Bueno, vamos. ¡Tú eres solo una niña y yo soy un guerrero duro!",
        ["Just a girl, am I? Right? *(Kuradal knocks you out, and you wake up outside the ancient caverns.)*"] = "Sólo una niña, ¿verdad? ¿Bien? *(Kuradal te noquea y te despiertas fuera de las antiguas cavernas.)*",
        ["So is there anything else that's special about this dungeon?"] = "Entonces, ¿hay algo más que sea especial en esta mazmorra?",
        ["I'm glad you asked. You might find creatures inside the dungeon drop something called a ferocious ring - they must have foraged them from remains in the area."] = "Me alegra que lo hayas preguntado. Es posible que encuentres criaturas dentro de la mazmorra que dejen caer algo llamado anillo feroz; deben haberlos recolectado de los restos del área.",
        ["Well, that's great and all, but what exactly does it do?"] = "Bueno, eso es genial y todo, pero ¿qué hace exactamente?",
        ["Well, for one thing, they are bound to these caves, so you'll find it has teleport charges that will return you to this place if you command it."] = "Bueno, por un lado, están vinculados a estas cuevas, por lo que encontrarás que tiene cargas de teletransporte que te devolverán a este lugar si lo ordenas.",
        ["Sounds good, but is that it?"] = "Suena bien, pero ¿es eso todo?",
        ["Oh, no. As I said, it is bound to this area, so you'll find that you do more damage to creatures in the dungeon if you are wearing it. Also, if you happen to be near death in the dungeon, it'll save you in a similar manner to a ring of life, teleporting you back to the safety of my presence."] = "Oh, no. Como dije, está vinculado a esta área, por lo que encontrarás que haces más daño a las criaturas en la mazmorra si lo llevas puesto. Además, si estás cerca de la muerte en la mazmorra, te salvará de manera similar a un anillo de vida, teletransportándote de regreso a la seguridad de mi presencia.",
        ["Even if I'm using ranged or magical combat? And what if I'm not in the dungeon when I die wearing it?"] = "¿Incluso si estoy usando combate a distancia o mágico? ¿Y qué pasa si no estoy en el calabozo cuando muera usándolo?",
        ["Calm down, one question at a time. First, it is a powerful artefact and will affect all combat styles. Second, I would be careful about dying outside wearing it. I do not believe it will work anywhere but inside the dungeon here."] = "Cálmate, una pregunta a la vez. Primero, es un artefacto poderoso y afectará a todos los estilos de combate. En segundo lugar, tendría cuidado de no morir afuera usándolo. No creo que funcione en ningún otro lugar que no sea dentro de la mazmorra aquí.",
        ["Thanks for your help, Kuradal."] = "Gracias por tu ayuda, Kuradal.",
        ["No problem. Anything else?"] = "No hay problema. ¿Algo más?",
        ["Can I receive special slayer assignments again?"] = "¿Puedo volver a recibir asignaciones especiales de asesino?",
        ["Sure, I will now start giving you special slayer assignments again."] = "Claro, ahora comenzaré a darte tareas especiales de cazador nuevamente.",
        ["Er...nothing..."] = "Eh... nada...",
        ["*Without a task from her:*"] = "*Sin tarea de ella:*",
        ["Sorry, my dungeon is exclusive only to those who need to go in there."] = "Lo siento, mi mazmorra es exclusiva solo para aquellos que necesitan entrar allí.",
        ["Exclusive?"] = "¿Exclusivo?",
        ["Yes, I only allow pupils of Slayer into this dungeon and only if they need to slayer the creatures I've caught inside."] = "Sí, solo permito que los alumnos de Slayer entren en esta mazmorra y solo si necesitan matar a las criaturas que he atrapado dentro.",
        ["I see. So what creatures do I need to be assigned to kill; what creatures are inside?"] = "Ya veo. Entonces, ¿qué criaturas necesito que me asignen para matar? ¿Qué criaturas hay dentro?",
        ["Well, I took a holiday tour of Gielinor and brought back some 'souvenirs'. Of course, as a Slayer master, 'souvenirs' means hellhounds, greater demons, gargoyles, abyssal demons, airut, dark beasts, and blue, iron, and steel dragons."] = "Bueno, hice un recorrido navideño por Gielinor y traje algunos 'souvenirs'. Por supuesto, como Slayer master, \"souvenirs\" significa perros del infierno, demonios mayores, gárgolas, demonios abisales, airut, bestias oscuras y dragones azules, de hierro y acero.",
        ["I'd usually keep it simple with a postcard."] = "Normalmente lo mantendría sencillo con una postal.",
        ["What was that?"] = "¿Qué fue eso?",
        ["I said that must have been hard."] = "Dije que debe haber sido difícil.",
        ["*With a cannon:*"] = "*Con un cañón:*",
        ["Sorry, no cannons allowed in there. Now I've rounded all these creatures up, I don't particularly want their lair being blasted apart."] = "Lo sentimos, no se permiten cañones allí. Ahora que he reunido a todas estas criaturas, no quiero particularmente que destruyan su guarida.",
        ["Hello there, Player, what can I help you with?"] = "Hola, Player, ¿en qué puedo ayudarte?",
        ["How am I doing so far?"] = "¿Cómo estoy hasta ahora?",
        ["*If you are currently on a Slayer task that is not yet complete: *"] = "*Si actualmente estás en una tarea Slayer que aún no está completa: *",
        ["You're currently assigned to kill [assigned creatures]; only X more to go."] = "Actualmente estás asignado para matar a [assigned creatures]; sólo faltan X más.",
        ["Who are you?"] = "¿Quién eres?",
        ["Where are you?"] = "¿Dónde estás?",
        ["Got any tips for me?"] = "¿Tienes algún consejo para mí?",
        ["That's all thanks."] = "Eso es todo gracias.",
        ["*If you have completed your most recent Slayer task: *"] = "*Si has completado tu tarea Slayer más reciente: *",
        ["My name is Kuradal; I'm a Slayer Master."] = "Mi nombre es Kuradal; Soy un Slayer Master.",
        ["You'll find me in the ancient cavern, near the Dragonkin Forge. I'll be here when you need a new task."] = "Me encontrarás en la caverna antigua, cerca de Dragonkin Forge. Estaré aquí cuando necesites una nueva tarea.",
        ["The last [assigned creature] I killed I found [weapons] took them down effectively."] = "El último [assigned creature] que maté descubrí que [weapons] los derribó de manera efectiva.",
        ["[Task hint]"] = "[sugerencia de tarea]",
        ["Nothing really."] = "En realidad, nada.",
        ["Hello?"] = "¿Hola?",
        ["Ello, who's this?"] = "Hola, ¿quién es?",
        ["It's Player. I'm using my magic to communicate with you."] = "Soy Player. Estoy usando mi magia para comunicarme contigo.",
        ["A useful application of magical talent. How can I help?"] = "Una aplicación útil del talento mágico. ¿Cómo puedo ayudar?",
        ["Er...nothing."] = "Eh... nada.",
        ["Aberrant spectres are fetid, vile ghosts. The very smell of them will paralyse and harm you. A nosepeg will help ignore their stink when fighting them. They can be found in the Slayer Tower near Canifis and I have heard rumours that they also live beneath Pollnivneach in the desert."] = "Los espectros aberrantes son fantasmas fétidos y viles. El solo olor de ellos te paralizará y te hará daño. Una clavija ayudará a ignorar su hedor cuando luches contra ellos. Se pueden encontrar en la Torre Slayer cerca de Canifis y he escuchado rumores de que también viven debajo de Pollnivneach en el desierto.",
        ["Abyssal demons are nasty creatures to deal with. They aren't really part of this realm and are able to move very quickly to trap their prey. I've managed to trap a few in the dungeon I'm guarding."] = "Los demonios abisales son criaturas desagradables con las que lidiar. En realidad, no son parte de este reino y pueden moverse muy rápidamente para atrapar a sus presas. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
        ["Acheron Mammoths are honourable yet powerful beasts from the frozen north. When they charge you, get out of the way! They can be found on an iceberg that is accessible from a dock near Rellekka."] = "Los mamuts de Acheron son bestias honorables pero poderosas del norte helado. Cuando te cobren, ¡apártate del camino! Se pueden encontrar en un iceberg al que se puede acceder desde un muelle cerca de Rellekka.",
        ["Adamant dragons are even more dangerous than mithril dragons. Look for them in Brimhaven dungeon, beneath a staircase north-west of the iron and steel dragons."] = "Los dragones Adamant son incluso más peligrosos que los dragones de mithril. Búscalos en la mazmorra Brimhaven, debajo de una escalera al noroeste de los dragones de hierro y acero.",
        ["The Airut are aggressive creatures from another world. They have powerful arms and attack with great vigour, certain abilities are able to counter and stun the Airut."] = "Los Airut son criaturas agresivas de otro mundo. Tienen brazos poderosos y atacan con gran vigor, ciertas habilidades son capaces de contrarrestar y aturdir al Airut.",
        ["Aquanites are amphibious creatures that attract prey using the glowing lures on their heads. They attack stronger opponents from a distance with water magic, and dislike those who pray against it. They dwell in the Fremennik Slayer Dungeon, in a chamber past the kurasks."] = "Los acuanitas son criaturas anfibias que atraen a sus presas utilizando los señuelos brillantes que tienen en la cabeza. Atacan a oponentes más fuertes desde la distancia con magia de agua y no les agradan aquellos que rezan en contra de ella. Habitan en la mazmorra Fremennik Slayer, en una cámara más allá de los kurasks.",
        ["The Order of Ascension are magic users. It is strongly suggested you use ranged attacks. Their tactics can make them tough one-on-one, so bringing a friend along would be beneficial."] = "La Orden de la Ascensión son usuarios de magia. Se recomienda encarecidamente utilizar ataques a distancia. Sus tácticas pueden hacerlos difíciles uno a uno, por lo que sería beneficioso traer a un amigo.",
        ["Aviansies can be found in the Godwars Dungeon north of Trollheim. As they are flying, you'll find melee attacks are not going to cut it."] = "Los aviansies se pueden encontrar en Godwars Dungeon al norte de Trollheim. Mientras vuelan, descubrirás que los ataques cuerpo a cuerpo no serán suficientes.",
        ["Black demons are weak to ranged attacks. They're still the strongest demon and very dangerous, however. Seek them out in the Edgeville or Brimhaven dungeons."] = "Los demonios negros son débiles ante los ataques a distancia. Sin embargo, siguen siendo el demonio más fuerte y muy peligroso. Búscalos en las mazmorras Edgeville o Brimhaven.",
        ["Black dragons are among the strongest dragons and are very fierce. Watch out for their fiery breath. I am sure you will have seen them in your travels and have honed your techniques on lesser dragons."] = "Los dragones negros se encuentran entre los dragones más fuertes y son muy feroces. Cuidado con su aliento de fuego. Estoy seguro de que los habrás visto en tus viajes y habrás perfeccionado tus técnicas con dragones menores.",
        ["Bloodvelds are strange, demonic creatures. They use their long, rasping tongue to feed on just about anything they can find. Remember that their tongues are magical in nature, but, more so, they deserve to die."] = "Los Bloodvelds son criaturas extrañas y demoníacas. Utilizan su lengua larga y áspera para alimentarse de casi cualquier cosa que encuentren. Recuerda que sus lenguas son de naturaleza mágica, pero, más aún, merecen morir.",
        ["Blue dragons aren't as strong as other dragons, but they're still very powerful. I've managed to trap a few in the dungeon I'm guarding."] = "Los dragones azules no son tan fuertes como otros dragones, pero siguen siendo muy poderosos. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
        ["Camel warriors can use ancient magics to attack you. They also have the blessings of Akthanakos and can create powerful, disorientating mirages.  They can be found in the deep desert."] = "Los guerreros Camel pueden usar magia antigua para atacarte. También cuentan con las bendiciones de Akthanakos y pueden crear espejismos poderosos y desorientadores.  Se pueden encontrar en lo profundo del desierto.",
        ["Celestial dragons are one of the strangest dragons I assign. They use melee but have a powerful dragonfire as well as a fascinating ability to momentarily stop time. You can find them in the depths of Dragontooth Island."] = "Los dragones celestiales son uno de los dragones más extraños que asigno. Usan combate cuerpo a cuerpo pero tienen un poderoso fuego de dragón, así como una habilidad fascinante para detener el tiempo momentáneamente. Puedes encontrarlos en las profundidades de la isla Dragontooth.",
        ["You can find Chaos giants out in the Barendir tunnels, beyond Keldagrim. Be careful, as they can launch their Dragon throwing axe at range or take a swipe at you if you get close. Perhaps you could recover some."] = "Puedes encontrar gigantes del Caos en los túneles de Barendir, más allá de Keldagrim. Ten cuidado, ya que pueden lanzar su hacha arrojadiza Dragón a distancia o golpearte si te acercas. Quizás puedas recuperar algo.",
        ["You can find corrupted creatures in the Sophanem Slayer Dungeon."] = "Puedes encontrar criaturas corruptas en la mazmorra Sophanem Slayer.",
        ["Without their master, Cres's automatons roam Guthix's chambers, attacking any who enter. They are programmed to use magic, melee or ranged and do a violent area-of-effect attack. Guthix's chambers may be reached via his shrine, or the excavation west of the Legends' Guild."] = "Sin su maestro, los autómatas de Cres deambulan por las cámaras de Guthix, atacando a cualquiera que entre. Están programados para usar magia, cuerpo a cuerpo o a distancia y realizar un violento ataque de área de efecto. Se puede llegar a las cámaras de Guthix a través de su santuario o de la excavación al oeste de Legends' Guild.",
        ["Dagannoth are large, sea-dwelling creatures that are very aggressive. You'll often find them in caves near sea water. There is no joy so great as to cleanse these from the face of Gielinor."] = "Los Dagannoth son criaturas marinas grandes que son muy agresivas. A menudo los encontrarás en cuevas cerca del agua de mar. No hay alegría tan grande como limpiar estos de the face de Gielinor.",
        ["The last Dark beast I killed I found a crossbow with bolts took them down effectively."] = "La última bestia oscura que maté encontré una ballesta con pernos que los derribó de manera efectiva.",
        ["[Dark beasts are large, dog-like predators with massively muscled bodies that protect them from crushing weapons. I've managed to trap a few in the dungeon I'm guarding.]"] = "[Las bestias oscuras son depredadores grandes, parecidos a perros, con cuerpos enormemente musculosos que los protegen de las armas aplastantes. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.]",
        ["You'll find these East of Al Kharid, atop the mountain. Watch out for their vicious ranged attacks!"] = "Los encontrarás al este de Al Kharid, en la cima de la montaña. ¡Cuidado con sus feroces ataques a distancia!",
        ["Dust devils use clouds of dust, sand, ash and whatever else they can inhale to blind and disorientate their victims. Good luck on obtaining a dragon chainmail from their dusty remains."] = "Los remolinos de polvo utilizan nubes de polvo, arena, cenizas y cualquier otra cosa que puedan inhalar para cegar y desorientar a sus víctimas. Buena suerte para obtener una cota de malla de dragón a partir de sus restos polvorientos.",
        ["Edimmu are ghosts which failed to escape their body. They're ghosts and zombies, yet somehow different altogether. They use ranged attacks and are highly aggressive. You can find them in a resource dungeon, which the Meilyr clan in Prifddinas has access to."] = "Edimmu son fantasmas que no lograron escapar de su cuerpo. Son fantasmas y zombis, pero de alguna manera completamente diferentes. Usan ataques a distancia y son muy agresivos. Puedes encontrarlos en una mazmorra de recursos a la que tiene acceso el clan Meilyr en Prifddinas.",
        ["Elves are skilled fighters across all disciplines from whom you could learn a lot. I recommend challenging only one type of elf combatant at a time."] = "Los elfos son luchadores expertos en todas las disciplinas de los que puedes aprender mucho. Recomiendo desafiar sólo a un tipo de combatiente elfo a la vez.",
        ["Like other giants, fire giants often wield large weapons. Learn to recognise what kind of weapon it is and act accordingly. Remember the days when these were a challenge to you and laugh."] = "Al igual que otros gigantes, los gigantes de fuego suelen empuñar armas grandes. Aprende a reconocer qué tipo de arma es y actúa en consecuencia. Recuerda los días en que estos eran un desafío para ti y ríe.",
        ["Ganodermic beasts and runts live in the depths of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Las bestias ganodermicas y los enanos viven en las profundidades de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que debes luchar contra ellas desde la distancia. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
        ["Gargoyles are winged creatures of stone. You'll need to fight them until they are close to death before breaking them apart with a rock hammer. I've managed to trap a few in the dungeon I'm guarding."] = "Las gárgolas son criaturas aladas de piedra. Tendrás que luchar contra ellos hasta que estén al borde de la muerte antes de romperlos con un martillo de piedra. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
        ["You can find gemstone dragons beneath the gem mine in Shilo Village."] = "Puedes encontrar dragones de piedras preciosas debajo de la mina de gemas en Shilo Village.",
        ["Glacors were brought to this world by Lucien. They use magic, ranged and melee attacks. You can find them in an underground cavern on the Frozen Plateau."] = "Lucien trajo los glacors a este mundo. Usan ataques mágicos, a distancia y cuerpo a cuerpo. Puedes encontrarlos en una caverna subterránea en Frozen Plateau.",
        ["Greater demons are weak to ranged attacks. Though not the strongest of demons, they are still dangerous. I've managed to trap a few in the dungeon I'm guarding."] = "Los demonios mayores son débiles ante los ataques a distancia. Aunque no son los demonios más fuertes, siguen siendo peligrosos. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
        ["Grifolapines live in the depths of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance, and dodge when they charge at you. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Los grifolapinos viven en las profundidades de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que debes luchar contra ellas desde la distancia y esquivar cuando cargan contra ti. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
        ["Grifolaroos live in the depths of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance, although they'll try to hop over obstacles towards you. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Los grifolaroos viven en las profundidades de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que deberás luchar contra ellas desde la distancia, aunque intentarán saltar los obstáculos hacia ti. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
        ["Grotworms have recently been spotted in a cave near Rimmington. They will bite and attack with some sort of acid spit. Be careful - they are very aggressive."] = "Recientemente se han visto gusanos grot en una cueva cerca de Rimmington. Morderán y atacarán con una especie de saliva ácida. Tenga cuidado, son muy agresivos.",
        ["Hellhounds are a cross between dogs and demons; they are also dangerous with a fierce bite. I've managed to trap a few in the dungeon I'm guarding."] = "Los Hellhounds son un cruce entre perros y demonios; También son peligrosos con un mordisco feroz. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
        ["The coldest of their kind, they are found beneath the Fremennik mountains. As they are beings of ice, I've found that fire spells inflict far more damage against them."] = "Los más fríos de su tipo, se encuentran debajo de las montañas Fremennik. Como son seres de hielo, descubrí que los hechizos de fuego les infligen mucho más daño.",
        ["Iron dragons are some of the weaker metallic dragons, with iron scales that are far thicker than normal iron armour. Their fiery breath and sharp claws can be negated by a number of means. I've managed to trap a few in the dungeon I'm guarding."] = "Los dragones de hierro son algunos de los dragones metálicos más débiles, con escamas de hierro que son mucho más gruesas que las armaduras de hierro normales. Su aliento de fuego y sus afiladas garras pueden anularse de diversas formas. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
        ["These tricky creatures burrow beneath the jungle north west of Oo'glog. Be careful, as these poisonous jungle wyrms like to use magical attacks from a distance, while they should be weak to stab attacks."] = "Estas engañosas criaturas se esconden bajo la jungla al noroeste de Oo'glog. Ten cuidado, ya que a estos venenosos wyrms de la jungla les gusta usar ataques mágicos desde la distancia, mientras que deberían ser débiles para apuñalar ataques.",
        ["Kal'gerion demons are powerful creatures that use both magic and melee. They reside in a storage dungeon near Daemonheim. I would recommend you take cover when they smash the ground, or when they use magic to pull you towards them."] = "Los demonios Kal'gerion son criaturas poderosas que usan tanto magia como cuerpo a cuerpo. Residen en un calabozo de almacenamiento cerca de Daemonheim. Te recomendaría que te cubrieras cuando rompan el suelo o cuando usen magia para atraerte hacia ellos.",
        ["Kalphites are large insects that live in hives under the desert sands. I am sure that, by now, you have seen them to the south-west of Shantay Pass."] = "Los calfitos son insectos grandes que viven en colmenas bajo las arenas del desierto. Estoy seguro de que ya los habrás visto al suroeste del paso Shantay.",
        ["Lava strykewyrms are the most powerful of their kind. They attack with all combat styles and are weak to nothing. They can be found deep within the Wilderness so I would watch your back while slaying them."] = "Los strykewyrms de lava son los más poderosos de su tipo. Atacan con todos los estilos de combate y son débiles o nada. Se pueden encontrar en lo profundo de Wilderness, por lo que yo te cuidaría las espaldas mientras los mato.",
        ["Found beneath the Dwarven mines, these are tough beings of rock. They can use ranged or melee attacks against you, so plan accordingly!"] = "Estos son seres duros de roca que se encuentran debajo de las minas enanas. Pueden usar ataques a distancia o cuerpo a cuerpo contra ti, ¡así que planifica en consecuencia!",
        ["Living wyverns breathe a poison that will kill you rapidly unless you are freezing. But watch out; the colder you are the harder their regular attacks will hit you.  They can be found in the Asgarnia Ice dungeon."] = "Los wyverns vivos respiran un veneno que te matará rápidamente a menos que te congeles. Pero cuidado; cuanto más frío tengas, más duro te golpearán sus ataques habituales.  Se pueden encontrar en la mazmorra de hielo de Asgarnia.",
        ["Mithril dragons are very dangerous opponents. They live just north of where we are now. You are a battle master - test your skills."] = "Los dragones de mitril son oponentes muy peligrosos. Viven justo al norte de donde estamos ahora. Eres un maestro de batalla: prueba tus habilidades.",
        ["Muspah are creatures born of nightmares. Ancient magic is the most effective thing to use against them. You can find them by travelling to Freneskae. They'll be aggressive unless you wear your shard of Zaros."] = "Los muspah son criaturas nacidas de pesadillas. La magia antigua es lo más eficaz que se puede utilizar contra ellos. Puedes encontrarlos viajando a Freneskae. Serán agresivos a menos que uses tu fragmento de Zaros.",
        ["These warped jade vine creatures will not hesitate to use their environment to help them in combat if they cannot retaliate otherwise. The baby jadinkos are easiest to kill, but the males offer the greatest rewards. Ranged weapons made from vines are best against them."] = "Estas criaturas deformadas de enredadera de jade no dudarán en utilizar su entorno para ayudarles en el combate si no pueden tomar represalias de otra manera. Las crías de jadinkos son más fáciles de matar, pero los machos ofrecen las mayores recompensas. Las armas Ranged hechas de enredaderas son mejores contra ellos.",
        ["Nechryael are demons of decay that summon small winged beings to help them fight their victims. They can be found in the Chaos Tunnels or in Canifis Slayer Tower."] = "Nechryael son demonios de la decadencia que convocan a pequeños seres alados para que les ayuden a luchar contra sus víctimas. Se pueden encontrar en los Túneles del Caos o en la Torre Canifis Slayer.",
        ["You can find nightmare creatures on Freneskae, which can be accessed through the world gate."] = "Puedes encontrar criaturas de pesadilla en Freneskae, a las que se puede acceder a través de la puerta del mundo.",
        ["The surviving subjects of Zaros's experiments. They have powerful charge attacks and fight in packs of four. You can find them by travelling to Freneskae. They'll be aggressive unless you wear your shard of Zaros."] = "Los sujetos supervivientes de los experimentos de Zaros. Tienen poderosos ataques cargados y luchan en grupos de cuatro. Puedes encontrarlos viajando a Freneskae. Serán agresivos a menos que uses tu fragmento de Zaros.",
        ["Ripper Demons are driven crazy by the scent of blood. They will hit you harder the worse your injuries are. And watch out; they can sometimes drop on you from above, which is lethal.  They can be found in a fissure near Al Kharid."] = "Los demonios destripadores se vuelven locos por el olor a sangre. Te golpearán más fuerte cuanto peores sean tus lesiones. Y cuidado; A veces pueden caer sobre ti desde arriba, lo cual es letal.  Se pueden encontrar en una fisura cerca de Al Kharid.",
        ["The last Sanguine werewolf I killed I found earth spells took them down effectively."] = "El último hombre lobo Sanguine que maté descubrí que los hechizos de tierra los derribaron de manera efectiva.",
        ["[Sanguine werewolves are werewolves twisted by the Sanguine. You will find them in Berylbrook on Havenhythe.]"] = "[Los hombres lobo sanguinarios son hombres lobo retorcidos por los sanguinarios. Los encontrarás en Berylbrook en Havenhythe.]",
        ["Skeletal wyverns are extremely dangerous, and they are hard to hit with arrows as they slip right through. To stand a good chance of surviving, you'll need some elemental shielding from their icy breath."] = "Los wyverns esqueléticos son extremadamente peligrosos y es difícil golpearlos con flechas cuando se deslizan a través de ellos. Para tener buenas posibilidades de sobrevivir, necesitarás algo de protección elemental contra su aliento helado.",
        ["You can find soul devourers in the Sophanem Slayer Dungeon."] = "Puedes encontrar devoradores de almas en la mazmorra Sophanem Slayer.",
        ["Spiritual mages are the strongest of the spiritual guardians. They are devastating against warriors, but a smart ranger can sometimes defeat them. Of course, Prayer might serve you well, too. They can be found in the icy caverns near Trollheim, supporting the cause of their chosen god."] = "Los magos espirituales son los más fuertes de los guardianes espirituales. Son devastadores contra los guerreros, pero un explorador inteligente a veces puede derrotarlos. Por supuesto, Prayer también podría resultarle útil. Se pueden encontrar en las cavernas heladas cerca de Trollheim, apoyando la causa de su dios elegido.",
        ["The last Soulgazer I killed I found a bow and arrows took them down effectively."] = "El último Soulgazer que maté encontré un arco y las flechas lo derribaron de manera efectiva.",
        ["[You can find stalker creatures within Zamorak's hideout.]"] = "[Puedes encontrar criaturas acosadoras dentro del escondite de Zamorak.]",
        ["Steel dragons are dangerous and metallic, with steel scales that are far thicker than normal steel armour. I've managed to trap a few in the dungeon I'm guarding."] = "Los dragones de acero son peligrosos y metálicos, con escamas de acero que son mucho más gruesas que las armaduras de acero normales. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
        ["Suqahs can only be found on the mystical Lunar Isle. They use melee and magical attacks, and they often drop hide, teeth and herbs."] = "Las suqahs solo se pueden encontrar en el místico Lunar Isle. Usan ataques cuerpo a cuerpo y mágicos y, a menudo, dejan caer piel, dientes y hierbas.",
        ["Terror dogs are, unsurprisingly, dogs that terrorise the weak. You'll find them in the Haunted Mine, near Tarn's lair."] = "Los perros del terror son, como era de esperar, perros que aterrorizan a los débiles. Los encontrarás en la Mina Encantada, cerca de la guarida de Tarn.",
        ["Tormented demons are powerful creatures that use magic, ranged and melee attacks. They also have the ability to shield themselves. You can find them below the Tears of Guthix cave."] = "Los demonios atormentados son criaturas poderosas que usan ataques mágicos, a distancia y cuerpo a cuerpo. También tienen la capacidad de protegerse. Puedes encontrarlos debajo de la cueva Lágrimas de Guthix.",
        ["The TzHaar contains some mighty warriors, prove yourself against them. You'll find them deep within the Karamja volcano."] = "El TzHaar contiene algunos guerreros poderosos, ponte a prueba contra ellos. Los encontrarás en lo profundo del volcán Karamja.",
        ["These are the creatures that live within the TzHaar fightcaves. You'll have to venture down into the cave in the Karamja volcano to take them on."] = "Estas son las criaturas que viven dentro de las cuevas de lucha de TzHaar. Tendrás que aventurarte en la cueva del volcán Karamja para enfrentarte a ellos.",
        ["These foul creatures can be found throughout Meiyerditch and Darkmeyer in Morytania. They have a telepathic ability which enables them to dodge incoming attacks, so you'll need a weapon specially created to harm them."] = "Estas repugnantes criaturas se pueden encontrar en Meiyerditch y Darkmeyer en Morytania. Tienen una habilidad telepática que les permite esquivar los ataques entrantes, por lo que necesitarás un arma especialmente creada para dañarlos.",
        ["Warped tortoises are creatures tainted by magical waste. They are vulnerable to an elven chime. I know you have seen them in your adventures, so go crack some carapace."] = "Las tortugas deformadas son criaturas contaminadas por desechos mágicos. Son vulnerables a un timbre élfico. Sé que los has visto en tus aventuras, así que ve a romper un caparazón.",
        ["Waterfiends are creatures of water that live just north of us. Those followed by familiars are keen to slay these elemental forces."] = "Los Waterfiends son criaturas acuáticas que viven justo al norte de nosotros. Aquellos seguidos por familiares están deseosos de acabar con estas fuerzas elementales.",
    },
    ["Kurask head (furniture)"] = {
        ["I KILL YOU!"] = "¡TE MATÉ!",
        ["No, I kill you!"] = "¡No, te mato!",
        ["UUUHRG! Now I kill you!"] = "¡UUUURG! ¡Ahora te mato!",
        ["How are you going to do that? You're just a head on a wall!"] = "¿Cómo vas a hacer eso? ¡Eres sólo una cabeza en la pared!",
        ["Uhhhhrrr..."] = "Uhhhhrr...",
        ["Why are you so violent?"] = "¿Por qué eres tan violento?",
        ["You kill me! Uuurgh! That make me angry!"] = "¡Me matas! ¡Uuugh! ¡Eso me hace enojar!",
        ["You seemed pretty angry before I killed you."] = "Parecías bastante enojado antes de que te matara.",
        ["I like angry!"] = "¡Me gusta estar enojado!",
        ["I'm sorry I killed you."] = "Lamento haberte matado.",
        ["I hate sorry! Makes me more angry! WANT TO KILL YOU!"] = "¡Odio lo siento! ¡Me enoja más! ¡QUIERO MATARTE!",
        ["Please try to calm down."] = "Por favor, intenta calmarte.",
        ["Hate calm! Smash it! Hur hur hur!"] = "¡Odio la calma! ¡Aplastalo! ¡Hurra, hur, hur!",
        ["I'm not really sorry."] = "Realmente no lo siento.",
        ["That make me more angry! Uuuurgh!"] = "¡Eso me enoja más! ¡Uuuurgh!",
        ["Is there anything that doesn't make you angry?"] = "¿Hay algo que no te haga enojar?",
        ["No! I like angry! Hur hur hur!"] = "¡No! ¡Me gusta enojado! ¡Hurra, hur, hur!",
        ["I killed you really easily!"] = "¡Te maté muy fácilmente!",
        ["Yeah! I could kill you again in my sleep!I think I might go off and kill some other kurask!"] = "¡Sí! ¡Podría volver a matarte mientras duermo! ¡Creo que podría salir y matar a algún otro kurask!",
        ["Uuuurrrh! Hate you!"] = "¡Uuuurrra! ¡Te odio!",
        ["What are you going to do about it? Eh? I totally owned you!"] = "¿Qué vas a hacer al respecto? ¿Eh? ¡Te poseo totalmente!",
        ["Hate you hate you hate you!"] = "¡Odio, te odio, te odias!",
        ["What do you think about up there?"] = "¿Qué piensas de allá arriba?",
        ["Think?"] = "¿Piensas?",
        ["You know, what goes through your tiny stuffed head?"] = "Ya sabes, ¿qué pasa por tu pequeña cabeza de peluche?",
        ["Little bugs..."] = "Pequeños bichitos...",
        ["You have bugs living in you? Eww!"] = "¿Tienes insectos viviendo dentro de ti? ¡Uf!",
        ["Little bugs! Stomp and crush and stomp!"] = "¡Pequeños bichitos! ¡Pisotea, aplasta y pisotea!",
        ["Yeah! Stomp the bugs!"] = "¡Sí! ¡Pisotea a los insectos!",
        ["Stomp crush splat!"] = "¡Pisotón aplastante!",
        ["Smash! Destroy! Crunch break tear destroy splunch! Hurt wound kill hit punch stab slash kill!"] = "¡Aplasta! ¡Destruir! ¡Crujido, rotura, lágrima, destrucción, splunch! ¡Herir, herir, matar, golpear, puñetazo, cortar, matar!",
        ["Splunch'? That is not a word!"] = "¿'Splunch'? ¡Esa no es una palabra!",
        ["I HATE WORDS! Kill all words!"] = "¡ODIO LAS PALABRAS! ¡Mata todas las palabras!",
        ["You said 'kill' twice{{Sic}}"] = "Dijiste 'matar' dos veces{{Sic}}",
        ["I like kill! Hur hur hur!"] = "¡Me gusta matar! ¡Hurra, hur, hur!",
        ["Yeah! Kill smash destroy!"] = "¡Sí! ¡Mata, aplasta, destruye!",
        ["Kill smash destroy! Hur hur hur!"] = "¡Mata, aplasta, destruye! ¡Hurra, hur, hur!",
        ["What have the bugs done to you?"] = "¿Qué te han hecho los errores?",
        ["Skitter skitter through head noise in ears behind eyes."] = "Skitter se desliza a través del ruido de la cabeza en los oídos detrás de los ojos.",
        ["HATE THEM! Kill kill kill!"] = "¡LOS ODIO! ¡Mata, mata, mata!",
        ["You can't, you've got no feet!"] = "¡No puedes, no tienes pies!",
        ["No feet..."] = "Sin pies...",
        ["Hate lack of feet! Stomp lack of feet! Kill crush destroy smash!"] = "¡Odio la falta de pies! ¡Pisotea la falta de pies! ¡Mata, aplasta, destruye, aplasta!",
        ["That makes no sense! You can't destroy the absence of something!"] = "¡Eso no tiene sentido! ¡No se puede destruir la ausencia de algo!",
        ["Hate requirement to make sense! Smash it kill it destroy kill kill!"] = "¡Odio que el requisito tenga sentido! ¡Aplastalo, mátalo, destruye, mata, mata!",
        ["You can't physically destroy an abstract concept. It's impossible!"] = "No se puede destruir físicamente un concepto abstracto. ¡Es imposible!",
        ["Hate abstract concepts! hate impossible! Kill kill kill destroy smash!"] = "¡Odio los conceptos abstractos! odio imposible! ¡Mata, mata, mata, destruye, aplasta!",
        ["This is getting both surreal and repetitive."] = "Esto se está volviendo surrealista y repetitivo.",
        ["No, *house owner* kill you!"] = "¡No, *el dueño de la casa* te mata!",
    },
