    ["Well, I hope you're pleased with yourself."] = "Bueno, espero que estés satisfecho contigo mismo.",
    ["One day, the Burnt Lobster will be avenged!"] = "¡Un día, la langosta quemada será vengada!",
    ["You're in my personal space, Player."] = "Estás en mi espacio personal, Player.",
    ["Ah, another beautiful day at the oasis!"] = "¡Ah, otro hermoso día en el oasis!",
    ["This day just keeps getting better and better!"] = "¡Este día sigue mejorando cada vez más!",
    ["I'm glad!"] = "¡Me alegro!",
    ["Congratulations! You have completed: 'Vegan Unfriendly' - Feed all the crocodiles some steak."] = "¡Felicitaciones! Has completado: 'Vegan Unfriendly': alimenta a todos los cocodrilos con un poco de filete.",
    ["You have unlocked the title: {{Colour {{Colour|#FFFFFF|Player}}|color=#00FF00}}"] = "Has desbloqueado el título: {{Colour ZZCMD0ZZPlayer}}|color=#00FF00}}",
    ["You can activate this via the 'Titles' tab in the 'Customisations' interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz 'Personalizaciones'.",
    ["The Warmonger steals your Turmoil effects!"] = "¡El belicista te roba los efectos de Turmoil!",
    ["You've been injured and can't use protection prayers!"] = "¡Has resultado herido y no puedes usar oraciones de protección!",
    ["You've been injured and can't use deflect curses!"] = "¡Has resultado herido y no puedes desviar maldiciones!",
    ["You hear the spiritual warrior's voice in your head: \"Ulen'Son."] = "Escuchas la voz del guerrero espiritual en tu cabeza: \"Ulen'Son\".",
    ["*(The player responds with one of the following, at random, and then the dialogue ends.)*"] = "*(el player responde con una de las siguientes opciones, al azar, y luego finaliza el diálogo.)*",
    ["Hello?"] = "¿Hola?",
    ["I beg your pardon?"] = "¿Perdón?",
    ["Sorry, what?"] = "Lo siento, ¿qué?",
    ["What does that mean?"] = "¿Qué significa eso?",
    ["I'm getting out of here Bwana, the place is infested with zombies."] = "Me voy de aquí Bwana, el lugar está infestado de zombies.",
    ["Hello."] = "Hola.",
    ["Hello Bwana, What{{Sic}} can I do for you today?"] = "Hola Bwana, ¿Qué puedo hacer {{Sic}} por ti hoy?",
    ["Select an Option"] = "Selecciona una opción",
    ["Can you tell me a bit about this this place?"] = "¿Puedes contarme un poco sobre este lugar?",
    ["Of course Bwana, you look like a traveller!"] = "¡Por supuesto Bwana, pareces un viajero!",
    ["Yes I am actually!"] = "¡Sí, de hecho lo soy!",
    ["Well, I am a traveller myself, and I have set up this hostel for adventurers and travellers who are weary from their journey."] = "Bueno, yo también soy un viajero y he creado este albergue para aventureros y viajeros que están cansados del viaje.",
    ["There is a dormitory upstairs if you are tired, it costs 35 gold pieces which covers the cost of laundry and cleaning."] = "Hay un dormitorio arriba si estás cansado, cuesta 35 piezas de oro que cubren el costo de lavandería y limpieza.",
    ["Buy something."] = "Compra algo.",
    ["Buy some wine: 1 Gold.{{Sic}}"] = "Compra vino: 1 Gold.{{Sic}}",
    ["Very good [sir/madam]!"] = "¡Muy bien [sir/madam]!",
    ["Sorry Bwana, you don't have enough money."] = "Lo siento Bwana, no tienes suficiente dinero.",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["You purchase a jug of wine."] = "Compras una jarra de vino.",
    ["Buy some Beer: 2 Gold.{{Sic}}"] = "Compra cerveza: 2 de oro.{{Sic}}",
    ["You purchase a frothy glass of beer."] = "Compras un vaso de cerveza espumosa.",
    ["Buy a nights rest: 35 Gold{{Sic}}"] = "Comprar una noche de descanso: 35 Gold{{Sic}}",
    ["You purchase a ticket to access the dormitory."] = "Compras un boleto para acceder al dormitorio.",
    ["Buy a pack of 5 Dorm tickets: 175 Gold{{Sic}}"] = "Compra un paquete de 5 entradas para dormitorios: 175 Gold{{Sic}}",
    ["You purchase 5 tickets to access the dormitory."] = "Compras 5 entradas para acceder al dormitorio.",
    ["About the Task System..."] = "Acerca del sistema de tareas...",
    ["I've done all the Medium Tasks in the Karamja set."] = "He realizado todas las tareas medianas del conjunto Karamja.",
    ["Ahh, yes, you have! Congratulations!"] = "¡Ahh, sí, lo has hecho! ¡Felicidades!",
    ["How can I enchant your Karamja gloves if you don't have them with you? Bring me the Karamja gloves you earned from completing the Easy Tasks."] = "¿Cómo puedo encantar tus guantes Karamja si no los tienes contigo? Tráeme los guantes Karamja que obtuviste al completar las tareas fáciles.",
    ["Kaleb takes the Karamja gloves and mutters something over them. They seem to shimmer. He hands them back."] = "Kaleb toma los guantes Karamja y murmura algo sobre ellos. Parecen brillar. Él se los devuelve.",
    ["The enchantment I've placed on these gloves is a symbol of your further exploration of the island. As well as the benefits of the previous ones, you can also earn more rewards in the Agility Arena. Oh, there's a little added extra for all your hard work too."] = "El encantamiento que he colocado en estos guantes es un símbolo de tu futura exploración de la isla. Además de los beneficios de los anteriores, también podrás ganar más recompensas en Agility Arena. Oh, también hay un pequeño extra por todo tu arduo trabajo.",
    ["Wow, thanks!"] = "¡Vaya, gracias!",
    ["If you lose them, come back to me to reclaim them."] = "Si los pierdes, vuelve conmigo para reclamarlos.",
    ["Oh...wait a minute, I remember you from last time - didn’t I bless your Karamja gloves?"] = "Oh... espera un minuto, te recuerdo de la última vez. ¿No bendije tus guantes Karamja?",
    ["Yes, but I lost them."] = "Sí, pero los perdí.",
    ["Thought as much. Here, have another pair."] = "Lo mismo pensé. Toma, toma otro par.",
    ["Choose an option:"] = "Elige una opción:",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Tasks in the Karamja set, you are presented with a pair of gloves."] = "Para completar las tareas del conjunto Karamja, se te entregará un par de guantes.",
    ["Completing each difficulty level of the set will allow your gloves to be improved."] = "Completar cada nivel de dificultad del conjunto permitirá mejorar tus guantes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all of the Tasks in the set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Karamja set's Tasks are simple, some will require certain skill levels, and some might require quests to be started or completed."] = "Algunas de las tareas del conjunto Karamja son simples, algunas requerirán cierto skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["You can claim your Karamja set reward from Jackie the Fruit at the Brimhaven Agility Arena, me, or one of the jungle foresters to the south."] = "Puedes reclamar tu recompensa del conjunto Karamja a Jackie the Fruit en el Brimhaven Agility Arena, a mí o a uno de los guardabosques de la jungla del sur.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Karamja gloves 1"] = "guantes Karamja 1",
    ["Karamja gloves 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿Guantes Karamja 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
    ["Yes"] = "si",
    ["[You're handed another Karamja gloves 1.]"] = "[Te entregan otros guantes Karamja 1.]",
    ["No thanks."] = "No, gracias.",
    ["Karamja gloves 2"] = "guantes Karamja 2",
    ["Karamja gloves 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "¿Guantes Karamja 2? Sí, pero me temo que te costaría 2500 coins.",
    ["Purchase another for 2,500 coins?"] = "¿Comprar otro por 2500 coins?",
    ["[You're handed another Karamja gloves 2.]"] = "[Te entregan otros guantes Karamja 2.]",
    ["Karamja gloves 3"] = "Guantes Karamja 3",
    ["Karamja gloves 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿Guantes Karamja 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
    ["[You're handed another Karamja gloves 3.]"] = "[Te entregan otros guantes Karamja 3.]",
    ["Karamja gloves 4"] = "Guantes Karamja 4",
    ["Karamja gloves 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "¿Guantes Karamja 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["Purchase another for 15,000 coins?"] = "¿Comprar otro por 15.000 coins?",
    ["[You're handed another Karamja gloves 4.]"] = "[Te entregan otros guantes Karamja 4.]",
    ["The barman takes your ticket and allows you up to the dormitory."] = "El barman toma tu billete y te permite subir al dormitorio.",
    ["You can buy a ticket to the dormitory from me. And have a lovely nights rest."] = "Puedes comprarme un boleto para el dormitorio. Y que tengas un agradable descanso nocturno.",
    ["Soft-thing! How dare you approach the queen of the kalphite?"] = "¡Cosa suave! ¿Cómo te atreves a acercarte a la reina de la kalfita?",
    ["Player killed you! I can do what I like."] = "¡Player te mató! Puedo hacer lo que me gusta.",
    ["Player killed me but you could not. My successor will be as strong as me. Come down to meet her, she is unafraid."] = "Player me mató pero no pudiste. Mi sucesor será tan fuerte como yo. Baja a su encuentro, no tiene miedo.",
    ["I killed you, remember?"] = "Yo te maté, ¿recuerdas?",
    ["Yes you killed the queen, but by now another will have risen up! One kalphite may die but the hive goes on!"] = "Sí, mataste a la reina, ¡pero ya se habrá levantado otra! ¡Un kalphite puede morir pero la colmena continúa!",
    ["The kalphite race grows stronger everyday, and our young feed on the blood of the soft-things that invade from above!"] = "¡La raza kalfita se fortalece cada día y nuestras crías se alimentan de la sangre de las cosas blandas que invaden desde arriba!",
    ["Someday we will overrun the world again and all soft creatures will die. But we will reserve the worst fate for those who have killed a queen and hung her head in their house."] = "Algún día invadiremos el mundo nuevamente y todas las criaturas suaves morirán. Pero reservaremos el peor destino para aquellos que hayan matado a una reina y agachado su cabeza en su casa.",
    ["We will lay eggs in your brain and you will not die until it explodes and a million kalphites emerge to make a grand hive of all the world!"] = "¡Pondremos huevos en tu cerebro y no morirás hasta que explote y surja un millón de calfitos para formar una gran colmena en todo el mundo!",
    ["You don't scare me!"] = "¡No me asustas!",
    ["Your pitiful misplaced confidence is irrelevant. You will all die!"] = "Tu lamentable confianza fuera de lugar es irrelevante. ¡Todos moriréis!",
    ["Please don't kill me!"] = "¡Por favor no me mates!",
    ["Ha ha ha! It is too late for pleading now, pathetic mammal! Your fate is sealed!"] = "¡Ja, ja, ja! ¡Ya es demasiado tarde para suplicar, patético mamífero! ¡Tu destino está sellado!",
    ["You have killed [number] Kalphite Queen."] = "Has matado a [número] Kalphite Queen.",
    ["Congratulations! You have completed: 'Bug Swatter VI' - Defeat the Kalphite Queen. (100/100)"] = "¡Felicitaciones! Has completado: 'Bug Swatter VI' - Derrota al Kalphite Queen. (100/100)",
    ["Milestone: You have killed 100 Kalphite Queen!"] = "Hito: ¡Has matado a 100 Kalphite Queen!",
    ["Gotta find a way out. We built this maze for protection but I can't get used to it. I'm always getting lost."] = "Tengo que encontrar una salida. Construimos este laberinto para protegerme pero no puedo acostumbrarme. Siempre me estoy perdiendo.",
    ["Hello there, you look lost."] = "Hola, pareces perdido.",
    ["Are you trying to be funny?"] = "¿Estás intentando ser gracioso?",
    ["Hmmm."] = "Mmmm.",
    ["He looks a little drunk."] = "Parece un poco borracho.",
    ["Hi there, you okay?"] = "Hola, ¿estás bien?",
    ["Ooooh, my head ...I'm fried."] = "Ooooh, mi cabeza... estoy frita.",
    ["What's wrong?"] = "¿Qué pasa?",
    ["Too much of this home brew my friend. We make it from plant roots, but it blows your head off. You don't wanna put it near any naked flames. Want some?"] = "Demasiada de esta cerveza casera, amigo mío. Lo hacemos a partir de raíces de plantas, pero te vuela la cabeza. No querrás ponerlo cerca de llamas desnudas. ¿Quieres un poco?",
    ["Okay then."] = "Está bien, entonces.",
    ["Here you go... Hic!"] = "Aquí tienes... ¡Hic!",
    ["The dwarf kindly gives you some food to help you recover from the ghastly drink."] = "El enano amablemente te da algo de comida para ayudarte a recuperarte de la espantosa bebida.",
    ["Ha ha! I warned you - it's strong stuff. Have a good meal; it may sober you up a bit."] = "¡Ja, ja! Te lo advertí: es algo fuerte. Que tengas una buena comida; puede que te ponga un poco sobrio.",
    ["Your losh... Hic! Well maybe a good meal? I could part with some food for a few coins."] = "Tu pérdida... ¡Hic! Bueno, ¿tal vez una buena comida? Podría desprenderme de algo de comida por unos coins.",
    ["75 coins pleashe."] = "75 coins por favor.",
    ["Here you go."] = "Aquí tienes.",
    ["Thanks... Eat well."] = "Gracias... Come bien.",
    ["Oh dear, I haven't enough money..."] = "Dios mío, no tengo suficiente dinero...",
    ["Sorry, I can't just give it away to anyone that walks past."] = "Lo siento, no puedo regalárselo a cualquiera que pase.",
    ["Well come back any time."] = "Bueno, vuelve cuando quieras.",
    ["Talk about advanced defenders."] = "Habla de defensores avanzados.",
    ["My eye sees you have yourself a dragon defender!"] = "¡Mis ojos ven que tienes un dragón defensor!",
    ["Is that another cyclops pun?"] = "¿Es otro juego de palabras de cíclope?",
    ["Sorry. Force of habit."] = "Lo siento. Fuerza de la costumbre.",
    ["I have heard that if you take the dragon defender with you to a certain challenge you can get even better defenders!"] = "¡He oído que si llevas al defensor del dragón contigo a un determinado desafío, puedes conseguir defensores aún mejores!",
    ["Any hints on where?"] = "¿Alguna pista sobre dónde?",
    ["I heard of a group of brothers, east of Mort'ton. Rumors say they have Corruption sigil that is used in the construction of the defender!"] = "Escuché de un grupo de hermanos, al este de Mort'ton. ¡Los rumores dicen que tienen un sello de corrupción que se utiliza en la construcción del defensor!",
    ["Any other information?"] = "¿Alguna otra información?",
    ["It's also said that you can construct ranged and magic versions too, and all these defenders can get you even more powerful ones!"] = "También se dice que puedes construir versiones mágicas y a distancia, ¡y todos estos defensores pueden conseguirte defensores aún más poderosos!",
    ["Wow, that's incredible! How do you know about those?"] = "¡Guau, eso es increíble! ¿Cómo sabes sobre eso?",
    ["I like to keep my eye on things."] = "Me gusta estar atento a las cosas.",
    ["Stop that."] = "Deja eso.",
    ["Sorry."] = "Lo siento.",
    ["Where are the others?"] = "¿Dónde están los demás?",
    ["Nex has an Ancient emblem that can be combined with a Chaotic splint can get you an advanced defender in your choice of combat style."] = "Nex tiene un emblema antiguo que se puede combinar con una férula caótica y puede brindarte un defensor avanzado en el estilo de combate que elijas.",
    ["Oooo, any more?"] = "Oooo, ¿algo más?",
    ["Of course, the best defenders I've heard of are made from perfect chitin from the Kalphite King. Just like the other defenders, you'll need to bring along the previous defender or better for a chance to get the required pieces."] = "Por supuesto, los mejores defensores que he oído hablar están hechos de quitina perfecta del Rey Calfita. Al igual que los demás defensores, tendrás que traer al defensor anterior o mejor para tener la oportunidad de conseguir las piezas necesarias.",
    ["Great! Thanks!"] = "¡Genial! ¡Gracias!",
    ["Talk about Kamfreena."] = "Habla de Kamfreena.",
    ["Why hello there! I'm Kamfreena. Like the look of my pets? I think they're eyeing you up."] = "¡Hola! Soy Kamfreena. ¿Te gusta el aspecto de mis mascotas? Creo que te están mirando.",
    ["That was a really bad pun."] = "Ese fue un juego de palabras realmente malo.",
    ["Sorry... I don't get to see the rest of the guild much, stuck up here. The Cyclopes don't talk much you see."] = "Lo siento... No puedo ver mucho al resto del gremio, atrapados aquí. Los cíclopes no hablan mucho, ¿ves?",
    ["Shouldn't that be cyclopses?"] = "¿No deberían ser cíclopes?",
    ["Nope! Cyclopes is the plural of cyclops. One cyclops, many cyclopes."] = "¡No! Cíclopes es el plural de cíclope. Un cíclope, muchos cíclopes.",
    ["Oh, right, thanks."] = "Ah, claro, gracias.",
    ["Talk about the cyclopses."] = "Habla de los cíclopes.",
    ["Where are they from?"] = "¿De dónde son?",
    ["They're from the far-eastern lands. Indeed, the slayer masters have been in contact with us and are very interested in them. Vannaka and Chaeldar were especially interested."] = "Son de las tierras del lejano oriente. De hecho, los slayer masters han estado en contacto con nosotros y están muy interesados ​​en ellos. Vannaka y Chaeldar estaban especialmente interesados.",
    ["How did they get here?"] = "¿Cómo llegaron aquí?",
    ["Ahh.. our guildmaster, Harrallak, went on an expedition there. He brought them back with him."] = "Ahh... nuestro maestro del gremio, Harrallak, fue de expedición allí. Los trajo consigo.",
    ["Why are they here?"] = "¿Por qué están aquí?",
    ["For the warriors to train on of course! They also drop a rather nice blade."] = "¡Para que los guerreros entrenen, por supuesto! También dejan caer una hoja bastante bonita.",
    ["Oh? What would that be?"] = "¿Ah? ¿Qué sería eso?",
    ["Defenders."] = "Defensores.",
    ["Err what are they?"] = "Err, ¿qué son?",
    ["It's a blade you can defend with using your shield hand, like I have."] = "Es una espada que puedes defender usando tu mano protectora, como lo hice yo.",
    ["Wow!"] = "¡Guau!",
    ["For every 50 tokens you collect around the guild, you can spend one minute with my pets. As you obtain defenders, you can show them to me and obtain even better ones, but remember: if you lose them, you'll have to start at bronze all over again. I'd advise keeping a spare in the bank."] = "Por cada 50 fichas que recolectes en el gremio, podrás pasar un minuto con mis mascotas. A medida que vayas obteniendo defensores, podrás mostrármelos y obtener otros aún mejores, pero recuerda: si los pierdes, tendrás que empezar de nuevo en bronce. Aconsejaría tener uno de repuesto en el banco.",
    ["Okay!"] = "¡Está bien!",
    ["Oh, by the way, you'll need to earn 200 tokens of one type or 30 tokens of each type before I'll let you in!"] = "Ah, por cierto, ¡necesitarás ganar 200 tokens de un tipo o 30 tokens de cada tipo antes de que te deje entrar!",
    ["Right, I'd better go play some games then!"] = "Bien, ¡será mejor que vaya a jugar algunos juegos entonces!",
    ["Bye!"] = "¡Adiós!",
    ["See you back here soon I hope!"] = "¡Nos vemos pronto aquí, espero!",
    ["[You don't have enough Warrior Guild tokens to enter the cyclops enclosure yet. Collect at least 200 of one type of token, or 30 of each type, then come back.]"] = "[Aún no tienes suficientes fichas del Gremio de Guerreros para entrar al recinto de los cíclopes. Recoge al menos 200 de un tipo de ficha, o 30 de cada tipo, y luego regresa.]",
    ["Well, since you haven't shown me a defender to prove your prowess as a warrior,"] = "Bueno, ya que no me has mostrado un defensor para demostrar tu destreza como guerrero,",
    ["I'll release some cyclopes which might drop bronze defenders for you to start off with, unless you show me another. Have fun in there."] = "Lanzaré algunos cíclopes que podrían arrojar defensores de bronce para que empieces, a menos que me muestres otro. Diviértete ahí dentro.",
    ["Ah, I see that you have one of the defenders already! Well done."] = "¡Ah, veo que ya tienes a uno de los defensores! Bien hecho.",
    ["I'll release some cyclopes that might drop the next defender for you. Have fun in there."] = "Lanzaré algunos cíclopes que podrían eliminar al próximo defensor por ti. Diviértete ahí dentro.",
    ["Oh, and be careful: the cyclopes will occasionally summon a cyclossus. They are rather mean, and can only be hurt with a rune or better defender."] = "Ah, y ten cuidado: los cíclopes ocasionalmente convocarán a un cícloso. Son bastante malos y sólo se les puede herir con una runa o un defensor mejor.",
    ["Ah, I see that you have an excellent defender already! Well done."] = "¡Ah, veo que ya tienes un excelente defensor! Bien hecho.",
    ["I'll release some cyclopes that drop dragon defenders! Have fun in there."] = "¡Lanzaré algunos cíclopes que soltarán dragones defensores! Diviértete ahí dentro.",
    ["Oh, and be careful: the cyclopes will occasionally summon a cyclossus. They are rather mean, and can only be hurt with a rune or dragon defender."] = "Ah, y ten cuidado: los cíclopes ocasionalmente convocarán a un cícloso. Son bastante malos y sólo pueden ser heridos con una runa o un dragón defensor.",
    ["I remember you...."] = "Te recuerdo....",
    ["You don't have the defender you earned last time."] = "No tienes el defensor que ganaste la última vez.",
    ["I have one in the bank, I'll go get it!"] = "Tengo uno en el banco, ¡iré a buscarlo!",
    ["Ok!"] = "¡Vale!",
    ["Err.. no, don't have it on me. I kind of... lost it."] = "Err... no, no lo lleves conmigo. En cierto modo... lo perdí.",
    ["Sorry, but as you've lost any that you earned before I can only let you in to kill the cyclopes that drop the bronze defenders. Go on in when you're ready."] = "Lo siento, pero como has perdido todo lo que ganaste antes, solo puedo dejarte entrar para matar a los cíclopes que dejan caer a los defensores de bronce. Entra cuando estés listo.",
    ["I have a [metal] defender, please let me in to kill some more cyclopes!"] = "Tengo un defensor [metal], ¡déjame entrar para matar más cíclopes!",
    ["Bronze eh? The next cyclopes are ready, toddle in when you're ready."] = "Bronce, ¿eh? Los próximos cíclopes están listos, entra cuando estés listo.",
    ["Wow, iron eh? The next cyclopes are ready, toddle in when you're ready."] = "Vaya, hierro, ¿eh? Los próximos cíclopes están listos, entra cuando estés listo.",
    ["Strong as steel eh? The next cyclopes are ready, toddle in when you're ready."] = "Fuerte como el acero, ¿eh? Los próximos cíclopes están listos, entra cuando estés listo.",
    ["Black, hmmm, about half way to Rune then! Keep going! Cyclopes have been released, enter when you're ready."] = "Negro, hmmm, ¡entonces aproximadamente a la mitad del camino hacia Rune! ¡Sigue adelante! Los cíclopes han sido liberados, ingresa cuando estés listo.",
    ["Mithril? Getting good at this aren't you? Ok, I've released those cyclopes that sometimes drop adamant defenders, enter when you're ready."] = "¿Mithril? Te estás volviendo bueno en esto, ¿no? Ok, liberé esos cíclopes que a veces derriban defensores inflexibles, ingresa cuando estés listo.",
    ["An adamant defender, eh? Trying for the Rune defender I'm betting. Ok, I've released those cyclopes, enter when you're ready."] = "Un defensor inflexible, ¿eh? Estoy apostando por el defensor de Rune. Ok, he liberado a esos cíclopes, ingresa cuando estés listo.",
    ["Well done, you truly are a brilliant warrior! I've released some cyclopes that may well drop a dragon defender, enter when you're ready."] = "¡Bien hecho, realmente eres un guerrero brillante! He lanzado algunos cíclopes que bien pueden dejar caer un dragón defensor, ingresa cuando estés listo.",
    ["Well done! You truly are a warrior of the highest order! I've released the cyclopes; enter when you're ready."] = "¡Bien hecho! ¡Realmente eres un guerrero del más alto nivel! He liberado a los cíclopes; entra cuando estés listo.",
    ["Your time is up. Please make your way to the exit."] = "Se acabó tu tiempo. Dirígete hacia la salida.",
    ["Next time, please leave as soon as your time is up."] = "La próxima vez, vete tan pronto como se acabe el tiempo.",
    ["Hello there! Want to fight for freedom, and learn some snippets about divination to boot? Then get cracking and talk to the recruiter!"] = "¡Hola! ¿Quieres luchar por la libertad y, además, aprender algunos fragmentos sobre adivinación? ¡Entonces ponte manos a la obra y habla con el reclutador!",
    ["Why, hello there, brave soldier of Armadyl! What can I do for you?"] = "¡Hola, valiente soldado de Armadyl! ¿Qué puedo hacer por ti?",
    ["I have some questions about you."] = "Tengo algunas preguntas sobre ti.",
    ["What do you want to know?"] = "¿Qué quieres saber?",
    ["Who are you?"] = "¿Quién eres?",
    ["Call me Kamiee. I'm the head diviner of the Armadyleans."] = "Llámame Kamiee. Soy el jefe adivino de los Armadyleanos.",
    ["I've been experimenting with divination since wisps started popping up. Armadyl noticed me and asked me to help. Very convincing bird he is, too!"] = "He estado experimentando con la adivinación desde que empezaron a aparecer mechones. Armadyl se fijó en mí y me pidió ayuda. ¡Él también es un pájaro muy convincente!",
    ["I construct items and weapons to assist in the battle against Bandos."] = "Construyo objetos y armas para ayudar en la batalla contra Bandos.",
    ["I study it all the time - even in my free time, you know? I'm relied on, you see. It's important we achieve Armadyl's vision of peace between mortals and gods."] = "Lo estudio todo el tiempo, incluso en mi tiempo libre, ¿sabes? Confío en mí, ya ves. Es importante que logremos la visión de paz entre mortales y dioses de Armadyl.",
    ["Where are you from?"] = "¿De dónde eres?",
    ["I was born here. I mean, I was born in Varrock. It was tough. We didn't have two slices of cheese to rub together, and we had to make do with our wits and empty tummies."] = "Nací aquí. Quiero decir, nací en Varrock. Fue duro. No teníamos dos rebanadas de queso para untar y tuvimos que conformarnos con nuestro ingenio y nuestros estómagos vacíos.",
    ["It was hard, no doubt about that. It got harder when a gang murdered my parents."] = "Fue difícil, de eso no hay duda. Se volvió más difícil cuando una pandilla asesinó a mis padres.",
    ["I survived on my own. Aubury sneaked me the odd rune to practice with, hidden in loaves of bread. Almost choked the first time!"] = "Sobreviví por mi cuenta. Aubury me dio alguna que otra runa para practicar, escondida en hogazas de pan. ¡Casi me ahogo la primera vez!",
    ["I'd got a decent grasp on magic. But when divination energy started popping up, I was a natural."] = "Tenía un conocimiento decente de la magia. Pero cuando la energía de adivinación comenzó a aparecer, lo hice de forma natural.",
    ["I met Taka'ra, who introduced me to Armadyl. They explained what they wanted to do with the world and... Well, you can't knock it, can you? Peace beats war every time."] = "Conocí a Taka'ra, quien me presentó a Armadyl. Explicaron lo que querían hacer con el mundo y... Bueno, no se puede dejar de lado, ¿verdad? La paz siempre gana a la guerra.",
    ["Why do you follow Armadyl?"] = "¿Por qué sigues a Armadyl?",
    ["I've been a scrapper all my life. Staying alive by kicking people where it hurts and running away, you know? But Armadyl showed me that living can't be about running away."] = "He sido un luchador toda mi vida. Mantenerse con vida pateando a la gente donde más le duele y huyendo, ¿sabes? Pero Armadyl me mostró que vivir no puede consistir en huir.",
    ["He told me about when he ran away, hopping from world to world when he thought his aviansie were dead. He came to realise that running was achieving nothing. If he wanted to mean anything, he had to stand."] = "Me habló de cuando se escapó, saltando de mundo en mundo cuando pensó que sus aviansie estaban muertos. Llegó a darse cuenta de que correr no conseguía nada. Si quería significar algo, tenía que ponerse de pie.",
    ["So he stands against warmongers. And I'm doing the same. He's come back as a phoenix, and I'm back as a phoenix too! At least, if I can get some slightly redder feathers."] = "Así que se opone a los belicistas. Y yo estoy haciendo lo mismo. ¡Él ha regresado como un fénix y yo también he regresado como un fénix! Al menos, si consigo conseguir unas plumas un poco más rojas.",
    ["This is why I follow Armadyl. He's striving to end the constant wars between the gods, so that one day we can all live in peace. It's a lovely thought."] = "Por eso sigo a Armadyl. Se esfuerza por poner fin a las constantes guerras entre los dioses, para que algún día todos podamos vivir en paz. Es un pensamiento encantador.",
    ["Can I ask something else?"] = "¿Puedo preguntar algo más?",
    ["I have questions about divination."] = "Tengo preguntas sobre adivinación.",
    ["What is it?"] = "¿Qué es?",
    ["Divination is as far as I've got to grips with it - the process of gathering the life juice of Guthix and weaving it into divine energy. The energy's a kind of magic matter that can be made into various gubbins."] = "Divination es lo más lejos que puedo entender: el proceso de reunir el jugo vital de Guthix y tejerlo en energía divina. La energía es una especie de materia mágica que puede convertirse en varios gubbins.",
    ["You'll create things like portents, signs and divine locations. Things that can help you with your day-to-day life."] = "Crearás cosas como portentos, señales y ubicaciones divinas. Cosas que pueden ayudarte con tu día a día.",
    ["In our case, we're powering a building-sized ritual to stop Bandos. A war-ender. We call it the Divine Focus."] = "En nuestro caso, estamos impulsando un ritual del tamaño de un edificio para detener a Bandos. Un finalizador de la guerra. Lo llamamos el Enfoque Divino.",
    ["Why are you using it?"] = "¿Por qué lo usas?",
    ["*If you have a Bronze, Silver, or Gold Armadylean token.*"] = "*Si tienes una ficha Armadylean de Bronce, Plata u Oro.*",
    ["I'd rather not say to just anyone."] = "Preferiría no decírselo a cualquiera.",
    ["*If you have a Runite or Dragon Armadylean token.*"] = "*Si tienes una ficha Runite o Dragon Armadylean.*",
    ["I've always been a fan of learning new things. As a girl, I had to adapt to survive."] = "Siempre me ha gustado aprender cosas nuevas. De niña tuve que adaptarme para sobrevivir.",
    ["So when I came across some wisps, I wondered how I could use them. Or make money from them, you know."] = "Entonces, cuando encontré algunos mechones, me pregunté cómo podía usarlos. O ganar dinero con ellos, ya sabes.",
    ["But I'm an Armadylean now. It's been great for creating items that have helped my new tribe, and beating Bandos of course."] = "Pero ahora soy un armadyleano. Ha sido fantástico crear elementos que han ayudado a mi nueva tribu y, por supuesto, vencer a Bandos.",
    ["With a little luck, everyone will live in peace and harmony once the battle is over."] = "Con un poco de suerte, todos vivirán en paz y armonía una vez que termine la batalla.",
    ["Where did it come from?"] = "¿De dónde vino?",
    ["I'm told that divination has only come about since the death of Guthix. So, some smart fellas are saying that it's Guthix's life force."] = "Me han dicho que la adivinación solo ha surgido desde la muerte de Guthix. Algunos tipos inteligentes dicen que es la fuerza vital de Guthix.",
    ["Or it could be the barrier that Guthix put up to stop the gods from returning."] = "O podría ser la barrera que Guthix levantó para evitar que los dioses regresaran.",
    ["Or it could be the energy from the world, and it's been leaking out since the Battle of Lumbridge."] = "O podría ser la energía del mundo, y se ha estado filtrando desde la Batalla de Lumbridge.",
    ["Whatever it is, diviners are putting the lifeforce back into the world and hoping that nothing bad happens."] = "Sea lo que sea, los adivinos están devolviendo la fuerza vital al mundo y esperando que no pase nada malo.",
    ["I have questions about the Divine Focus."] = "Tengo preguntas sobre el Enfoque Divino.",
    ["That's need to know information, and only trusted supporters need to know. Sorry."] = "Esa es la información necesaria, y sólo los seguidores de confianza necesitan saberla. Lo siento.",
    ["We need all this divine energy so that we can power the weapon we've created to stop Bandos."] = "Necesitamos toda esta energía divina para poder impulsar el arma que hemos creado para detener a Bandos.",
    ["The tower we're standing in contains a beam of energy. We're making a gizmo...spell...thing that will redirect that energy."] = "La torre en la que estamos contiene un rayo de energía. Estamos creando un artilugio... un hechizo... algo que redirigirá esa energía.",
    ["Then we'll point it at Bandos's tower and bring an end to the battle."] = "Luego apuntaremos a la torre de Bandos y pondremos fin a la batalla.",
    ["It couldn't be closer. We need to gather all the divination we can. Let's get there before Bandos."] = "No podría estar más cerca. Necesitamos reunir toda la adivinación que podamos. Lleguemos antes de Bandos.",
    ["That's all I have to say."] = "Eso es todo lo que tengo que decir.",
    ["Get divining! In the name of Armadyl!"] = "¡Empieza a adivinar! ¡En nombre de Armadyl!",
    ["Stay away, blasphemer! Armadyl will strike you down! Just you see."] = "¡Aléjate, blasfemo! ¡Armadyl te derribará! Sólo ya ves.",
    ["Hello there."] = "Hola.",
    ["Hel-lo?"] = "¿Hola, hola?",
    ["Right. Goodbye."] = "Correcto. Adiós.",
    ["Bye?"] = "¿Adiós?",
    ["Many greetings esteemed thief."] = "Muchos saludos estimado ladrón.",
    ["Hey."] = "Hola.",
    ["Congrats. Here!"] = "Felicitaciones. ¡Aquí!",
    ["[Kangai Mau has given you another clue scroll!]"] = "[¡Kangai Mau te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Talk about Druidic Ritual."] = "Habla sobre el ritual druídico.",
    ["Can you tell me what I need to do to earn a skillcape of Herblore?"] = "¿Puedes decirme qué debo hacer para ganar un skillcape de Herblore?",
    ["Sure, to earn the right to wear any skillcape you need to have mastered the skill to the highest level possible and it is no different for Herblore. When you have achieved a level of 99, come back and talk to me again."] = "Claro, para ganarte el derecho a usar cualquier skillcape necesitas haber dominado la habilidad al más alto nivel posible y no es diferente para Herblore. Cuando hayas alcanzado el nivel 99, vuelve y habla conmigo otra vez.",
    ["Talk about general things."] = "Habla de cosas generales.",
    ["Welcome back to our circle."] = "Bienvenido de nuevo a nuestro círculo.",
    ["Tell me, how are you progressing with your Herblore?"] = "Cuéntame, ¿cómo vas progresando con tu Herblore?",
    ["Very well, thank you."] = "Muy bien, gracias.",
    ["That is good to hear."] = "Es bueno escuchar eso.",
    ["Choose an option: {{anchor"] = "Elige una opción: {{anchor",
    ["I feel it has. The hand of Guthix is upon the land now, and in time he will turn the tide to favour us again."] = "Siento que sí. La mano de Guthix está ahora sobre la tierra y con el tiempo cambiará la situación para favorecernos de nuevo.",
    ["How long do you think that will take?"] = "¿Cuánto tiempo crees que llevará?",
    ["These things will happen at the allotted pace. A year seems as but a moment to Guthix."] = "Estas cosas sucederán al ritmo asignado. Un año parece sólo un momento para Guthix.",
    ["A year? You mean I went running around to gather all those items when it could be a year until anything happens?"] = "¿Un año? ¿Quieres decir que salí corriendo para reunir todos esos artículos cuando podría pasar un año hasta que sucediera algo?",
    ["I am unsure what you expected. Did you think we would perform the ritual and Guthix would leap out of the sky and beat the trolls personally?"] = "No estoy seguro de lo que esperabas. ¿Pensaste que realizaríamos el ritual y Guthix saltaría del cielo y vencería a los trolls personalmente?",
    ["Well..."] = "Bueno...",
    ["I find your grasp of theology to be a little tenuous. I suggest you study the mysteries of the gods and seek wisdom through meditation."] = "Creo que tu comprensión de la teología es un poco débil. Te sugiero que estudies los misterios de los dioses y busques la sabiduría a través de la meditación.",
    ["Can you explain the fundamentals of Herblore?"] = "¿Puedes explicar los fundamentos de Herblore?",
    ["I need more practice at it..."] = "Necesito más práctica en eso...",
    ["Persistence is key to success."] = "La persistencia es la clave del éxito.",
    ["Indeed I will... I will now explain the fundamentals of Herblore:"] = "De hecho lo haré... Ahora explicaré los fundamentos de Herblore:",
    ["Herblore is the skill of working with herbs and other ingredients to make useful potions and poison."] = "Herblore es la habilidad de trabajar con hierbas y otros ingredientes para hacer pociones y venenos útiles.",
    ["First you will need a vial, which can be made with the Crafting skill, found or bought."] = "Primero necesitarás un vial, que puedes hacer con la habilidad Crafting, encontrarlo o comprarlo.",
    ["Next, you must gather the herbs needed to make the potion you want."] = "A continuación, debes reunir las hierbas necesarias para hacer la poción que deseas.",
    ["Refer to the Herblore skill guide for the items needed to make a particular kind of potion."] = "Consulta la guía de habilidades de Herblore para conocer los elementos necesarios para hacer un tipo particular de poción.",
    ["You must fill your vial with water and add the ingredients you need. There are normally two ingredients for each type of potion."] = "Debes llenar tu vial con agua y agregar los ingredientes que necesites. Normalmente hay dos ingredientes para cada tipo de poción.",
    ["Bear in mind that you must first clean each herb before you can use it."] = "Ten en cuenta que primero debes limpiar cada hierba antes de poder utilizarla.",
    ["You may also have to grind some herbs before you can use them - you will need a pestle and mortar to do this."] = "Es posible que también tengas que moler algunas hierbas antes de poder usarlas; necesitarás un mortero y un mortero para hacerlo.",
    ["Herbs can be found on the ground and are also dropped by some monsters when you kill them."] = "Las hierbas se pueden encontrar en el suelo y algunos monstruos también las dejan caer cuando los matas.",
    ["Let's use Attack potion as an example: The first ingredient is guam leaf; the second is eye of newt."] = "Usemos la poción Attack como ejemplo: el primer ingrediente es la hoja de guam; el segundo es ojo de tritón.",
    ["Mix these two ingredients in your water-filled vial and you will produce an Attack potion."] = "Mezcla estos dos ingredientes en tu vial lleno de agua y producirás una poción Attack.",
    ["Drink this potion to temporarily increase your Attack level."] = "Bebe esta poción para aumentar temporalmente tu nivel de Attack.",
    ["Different potions also require different Herblore levels before you can make them."] = "Diferentes pociones también requieren diferentes niveles de Herblore antes de poder prepararlas.",
    ["Once again, check the instructions found in the Herblore skill guide for the levels needed to make a particular potion."] = "Una vez más, consulta las instrucciones que se encuentran en la guía de habilidades de Herblore para conocer los niveles necesarios para hacer una poción en particular.",
    ["Good luck with your Herblore; good day, adventurer."] = "Buena suerte con tu Herblore; Buenos días, aventurero.",
    ["Thanks for your help."] = "Gracias por tu ayuda.",
    ["I believe you can sell me a skillcape of Herblore?"] = "¿Creo que puedes venderme un skillcape de Herblore?",
    ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins para este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
    ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
    ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
    ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar espacio en backpack antes de que pueda venderte uno.",
    ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
    ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
    ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
    ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
    ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
    ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
    ["You say you're a master. Stand straight, let me take a look at you."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo.",
    ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Herblore master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Herblore master cape.",
    ["Buy Herblore master cape for 120,000 coins?"] = "¿Comprar Herblore master cape por 120.000 coins?",
    ["Yes."] = "Sí.",
    ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
    ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
    ["Most certainly; it has been a pleasure to watch you grow as a herbalist. I am privileged to have been instrumental in your learning, but I must ask for a donation of 99,000 coins to cover the expense of the cape."] = "Sin duda; Ha sido un placer verte crecer como herbolario. Tengo el privilegio de haber contribuido decisivamente a tu aprendizaje, pero debo pedir una donación de 99.000 coins para cubrir los gastos de la capa.",
    ["I see you have one of Hans' cape inversion tokens! I'll take that off your hands, and will sell you any inverted cape you're eligible for."] = "¡Veo que tienes una de las fichas de inversión de capa de Hans! Te quitaré eso de las manos y te venderé cualquier inverted cape para el que seas elegible.",
    ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
    ["I'd like a skillcape with the colours inverted."] = "Me gustaría un skillcape con los colores invertidos.",
    ["Unfortunately you'll need to free up some backpack space before I can sell you one."] = "Desafortunadamente necesitarás liberar algo de espacio en backpack antes de que pueda venderte uno.",
    ["I'd like a master cape with the colours inverted."] = "Me gustaría un master cape con los colores invertidos.",
    ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
    ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
    ["It looks like you're currently using the old model for your Herblore skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Herblore skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes optar por usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
    ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
    ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
    ["I would just like to change the Herblore skillcape."] = "Solo me gustaría cambiar el Herblore skillcape.",
    ["No problem, you will now use the [older/newer] model for your Herblore skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Herblore skillcape.",
    ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
    ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
    ["I've changed my mind!"] = "¡He cambiado de opinión!",
    ["No, thank you."] = "No, gracias.",
    ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
    ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
    ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    ["No, thanks."] = "No, gracias.",
    ["Hi, I'd like to access my account."] = "Hola, me gustaría acceder a mi cuenta.",
    ["Today's bank is brought to you by Aubury's Rune Shop, your one stop shop for that last rune drop!"] = "El banco de hoy te lo ofrece Rune Shop de Aubury, ¡tu ventanilla única para conseguir la última runa!",
    ["Oh, it's you Dave. Did you you know that we have a special competition on today?"] = "Oh, eres tú, Dave. ¿Sabías que hoy tenemos una competencia especial?",
    ["That's nice, but I just want to access my account."] = "Eso es bueno, pero solo quiero acceder a mi cuenta.",
    ["We're being sponsored by Aubury's Rune Shop. You could win a prize!"] = "Estamos patrocinados por Rune Shop de Aubury. ¡Podrías ganar un premio!",
    ["I just want to access... wait, prize? What prize?"] = "Sólo quiero acceder... espera, ¿premio? ¿Qué premio?",
    ["An earth rune."] = "Una runa de tierra.",
    ["A whole earth rune?"] = "¿Una runa de toda la tierra?",
    ["That's right! A magnificent prize!"] = "¡Eso es! ¡Un premio magnífico!",
    ["I'm in!! What do I have to do?"] = "¡¡Estoy dentro!! ¿Qué tengo que hacer?",
    ["Well Dave, all you have to do is correctly guess the number of runes in this jar."] = "Bueno, Dave, todo lo que tienes que hacer es adivinar correctamente la cantidad de runas en este frasco.",
    ["The banker holds up an almost entirely empty jar."] = "El banquero sostiene un frasco casi completamente vacío.",
    ["As you can see, we've already given out quite a lot of prizes."] = "Como puedes ver, ya hemos repartido bastantes premios.",
    ["Would you care to take a guess?"] = "¿Te importaría adivinar?",
    ["But there's only one rune in that jar."] = "Pero solo hay una runa en ese frasco.",
    ["Final answer?"] = "¿Respuesta final?",
    ["Yes. There's clearly only one rune in the jar."] = "Sí. Claramente sólo hay una runa en el frasco.",
    ["I'm sorry Dave, but I'm going to have to press you. Are you *quite sure*?"] = "Lo siento, Dave, pero tendré que presionarte. ¿Estás *bastante seguro*?",
    ["Yes. Wait, no. Yes! One rune!"] = "Sí. Espera, no. ¡Sí! ¡Una runa!",
    ["You win!"] = "¡Tú ganas!",
    ["One earth rune to you, congratulations!"] = "Una runa terrestre para ti, ¡felicidades!",
    ["The banker removes the earth rune from the jar and hands it over to you."] = "El banquero saca la runa de tierra del frasco y te la entrega.",
    ["Aubury's Rune Shop, your one stop shop for that last rune drop!"] = "Tienda de runas de Aubury, ¡tu ventanilla única para conseguir la última runa!",
    ["Is there anything else I can help you with today?"] = "¿Hay algo más en lo que pueda ayudarte hoy?",
    ["My account?"] = "¿Mi cuenta?",
    ["Of course."] = "Por supuesto.",
    ["Of course. Visit the Varrock Sword Shop today for a fine steal on some fine steel. They're slashing prices!"] = "Por supuesto. Visite la tienda de espadas Varrock hoy para obtener una excelente ganga en acero fino. ¡Están bajando los precios!",
    ["Here we go again. Warmongering gods, trying to claim the world again."] = "Aquí vamos de nuevo. Dioses belicosos, intentando reclamar el mundo otra vez.",
    ["What is happening here?"] = "¿Qué está pasando aquí?",
    ["The Lumbridge crater has been drained of energy, so the gods are using other methods to gain energy and weaponise it."] = "Al cráter Lumbridge se le ha drenado la energía, por lo que los dioses están usando otros métodos para ganar energía y convertirla en un arma.",
    ["It's further proof that the gods are a blight on Gielinor. We can't live in peace while these maniacs stomp about the world."] = "Es una prueba más de que los dioses son una plaga para Gielinor. No podemos vivir en paz mientras estos maníacos pisotean el mundo.",
    ["Who is fighting?"] = "¿Quién está peleando?",
    ["Armadyl and Bandos. Armadyl preaches peace, and yet the faithful flock to join his army. Ironic, yes?"] = "Armadyl y Bandos. Armadyl predica la paz y, sin embargo, los fieles acuden en masa para unirse a su ejército. Irónico, ¿no?",
    ["Bandos is out to destroy all the gods - a sentiment I agree with. Unfortunately, he's also a tyrant, and would happily watch us all burn."] = "Bandos quiere destruir a todos los dioses, un sentimiento con el que estoy de acuerdo. Desafortunadamente, él también es un tirano y felizmente nos vería a todos arder.",
    ["They're both guiding their mindless followers onto the battlefield, in order to gain the advantage."] = "Ambos están guiando a sus seguidores sin sentido al campo de batalla para obtener ventaja.",
    ["Neither god will stop until the other is dead. It's a welcome outcome, I suppose: the fewer gods, the better."] = "Ninguno de los dioses se detendrá hasta que el otro esté muerto. Supongo que es un resultado bienvenido: cuantos menos dioses, mejor.",
    ["As you know, the gods are going along with Sliske's game, in an effort to gain their precious Stone of Jas."] = "Como sabes, los dioses están de acuerdo con el juego de Sliske, en un esfuerzo por obtener su preciosa Piedra de Jas.",
    ["Do you want me to help?"] = "¿Quieres que te ayude?",
    ["Of course! First walk over there and kill Bandos. Then walk over there and kill Armadyl. I would forever be in your debt."] = "¡Por supuesto! Primero camina hacia allí y mata a Bandos. Luego camina hacia allí y mata a Armadyl. Siempre estaré en deuda contigo.",
    ["But that might be asking to much. Instead, join an army and help bring down either."] = "Pero eso podría ser pedir demasiado. En lugar de eso, únete a un ejército y ayuda a derrotar a cualquiera de ellos.",
    ["The sooner we remove them, the more likely that humanity survives."] = "Cuanto antes los eliminemos, más probabilidades habrá de que la humanidad sobreviva.",
    ["Who should I join?"] = "¿A quién debería unirme?",
    ["I cannot speak of the merits of either side. They're both repugnant."] = "No puedo hablar de los méritos de ninguna de las partes. Ambos son repugnantes.",
    ["You could join the stronger of the two to ensure the weaker dies, but that guarantees a powerful god's survival."] = "Podrías unirte al más fuerte de los dos para asegurarte de que el más débil muera, pero eso garantiza la supervivencia de un dios poderoso.",
    ["Joining the weaker god may seem like a folly, but it could help turn the tides. Either way, as long as we bring war to a swift end, we will have succeeded."] = "Unirse al dios más débil puede parecer una locura, pero podría ayudar a cambiar el rumbo. De cualquier manera, siempre que pongamos fin rápidamente a la guerra, habremos tenido éxito.",
    ["As before, the choice remains yours and yours alone."] = "Como antes, la elección sigue siendo tuya y sólo tuya.",
    ["If you wish to change sides at any point, though, I can help."] = "Sin embargo, si deseas cambiar de bando en algún momento, puedo ayudarte.",
    ["Can you give me directions?"] = "¿Puedes darme direcciones?",
    ["Bandos's Tower"] = "Torre de Bandos",
    ["This is the way to Bandos's tower"] = "Este es el camino a la torre de Bandos.",
    ["Armadyl's Tower"] = "Torre de Armadyl",
    ["This is the way to Armadyl's tower"] = "Este es el camino a la torre de Armadyl.",
    ["Whose side are you on?"] = "¿De qué lado estás?",
    ["I am on the side of the Godless! Gielinor is our world, and the gods should find their own."] = "¡Estoy del lado de los Sin Dios! Gielinor es nuestro mundo y los dioses deberían encontrar el suyo.",
    ["Gods want nothing more than power, and for whatever reason, they feel that Gielinor is worth fighting over. None of them care about us, we're just pieces on a chess board."] = "Los dioses no quieren nada más que poder y, por alguna razón, sienten que vale la pena luchar por Gielinor. Ninguno de ellos se preocupa por nosotros, solo somos piezas en un tablero de ajedrez.",
    ["Look at what they are doing now. One day they will be gone. Whether at the hands of my comrade, or my own."] = "Mira lo que están haciendo ahora. Un día se habrán ido. Ya sea a manos de mi camarada o a manos mías.",
    ["What can you do for me?"] = "¿Qué puedes hacer por mí?",
    ["The Godless are everywhere; ready in case an opportunity presents itself. But we keep ourselves hidden."] = "Los impíos están en todas partes; listo en caso de que se presente una oportunidad. Pero nos mantenemos ocultos.",
    ["I am known in these lands. My influence will allow you to declare allegiance to either side on a moment's notice."] = "Soy conocido en estas tierras. Mi influencia le permitirá declarar lealtad a cualquiera de las partes en cualquier momento.",
    ["Be warned: if you change sides, you will lose your progress with your old faction, so choose wisely."] = "Ten cuidado: si cambias de bando, perderás tu progreso con tu antigua facción, así que elige sabiamente.",
    ["I wish to change sides."] = "Deseo cambiar de bando.",
    ["I can change your allegiance to that of Armadyl/Bandos. Are you sure you want to do this?"] = "Puedo cambiar tu lealtad a la de Armadyl/Bandos. ¿Estás seguro de que quieres hacer esto?",
    ["**Player: Yes:**"] = "**Player: Sí:**",
    ["I am here if you change your mind."] = "Estoy aquí si cambias de opinión.",
    ["I am Kara-Meir, one of the godless. I am waiting for our chance to strike, should one arise."] = "Soy Kara-Meir, uno de los impíos. Estoy esperando nuestra oportunidad de atacar, en caso de que surja.",
    ["Why are you with the Godless?"] = "¿Por qué estás con los Godless?",
    ["Mortals are made to be free. I am no hurry to be led by an imbecile who craves nothing but power. Why should anyone but me decide my fate?"] = "Los mortales están hechos para ser libres. No tengo prisa por dejarme guiar por un imbécil que sólo anhela poder. ¿Por qué alguien más que yo debería decidir mi destino?",
    ["We've lived too long in fear of these gods. We are many and they are few. It's time we took advantage of that state of affairs, before we become the few."] = "Hemos vivido demasiado tiempo con miedo a estos dioses. Somos muchos y ellos son pocos. Es hora de que aprovechemos esa situación, antes de que seamos unos pocos.",
    ["A mere mortal cannot destroy a god, but in our legions we are stronger. Our first step should be to aid the death of Bandos or Armadyl."] = "Un simple mortal no puede destruir a un dios, pero en nuestras legiones somos más fuertes. Nuestro primer paso debería ser ayudar a la muerte de Bandos o Armadyl.",
    ["Perhaps if we can manage to kill a god, mortals will be rewarded with the Stone of Jas. Imagine! I could destroy the gods and free us all from their tyranny!"] = "Quizás si logramos matar a un dios, los mortales serán recompensados con la Piedra de Jas. ¡Imaginar! ¡Podría destruir a los dioses y liberarnos a todos de su tiranía!",
    ["To replace it with what?"] = "¿Para reemplazarlo con qué?",
    ["*Kara-Meir looks away, her jaw clenched*"] = "*Kara-Meir mira hacia otro lado, con la mandíbula apretada*",
    ["A noble goal."] = "Un objetivo noble.",
    ["*Kara-Meir simply nods, eyes intent.*"] = "*Kara-Meir simplemente asiente, con los ojos atentos.*",
    ["I don't believe the stone should be used by anyone."] = "No creo que nadie deba usar la piedra.",
    ["*Kara-Meir Raises one eyebrow, but says nothing.*"] = "*Kara-Meir levanta una ceja, pero no dice nada.*",
    ["Wouldn't that make you no better than them?"] = "¿Eso no te haría mejor que ellos?",
    ["*Kara-Meir looks troubled at the retort, and offers no response.*"] = "*Kara-Meir parece preocupado por la respuesta y no ofrece respuesta.*",
    ["What do they represent?"] = "¿Qué representan?",
    ["Biehn, our leader, set up the Godless in the hope that we might free mortals from tyranny of the gods. We do not need to worship them."] = "Biehn, nuestro líder, creó a los Sin Dios con la esperanza de que pudiéramos liberar a los mortales de la tiranía de los dioses. No necesitamos adorarlos.",
    ["The gods have shown, repeatedly, that war follows them closely. To save ourselves from that war, we need to defeat them. The sonner we do this, the sooner we can return to peace."] = "Los dioses han demostrado, repetidamente, que la guerra los sigue de cerca. Para salvarnos de esa guerra, necesitamos derrotarlos. Cuanto más hagamos esto, antes podremos volver a la paz.",
    ["Garlandia has the ear of Biehn. She believes that we shouldn't fight the gods - that, if we stop worshipping them, then they'll have no one to rule. That they will leave."] = "Garlandia tiene el oído de Biehn. Ella cree que no debemos luchar contra los dioses; que, si dejamos de adorarlos, no tendrán a nadie a quien gobernar. Que se irán.",
    ["She is wrong."] = "Ella está equivocada.",
    ["The Gods cannot be reasoned with. They crave power, and will not leave if we stop worshipping them - they will merely destroy us. Look at what they're doing for a simple stone."] = "No se puede razonar con los dioses. Anhelan poder y no se irán si dejamos de adorarlos; simplemente nos destruirán. Mira lo que están haciendo por una simple piedra.",
    ["I hear you know Sir Theodore?"] = "He oído que ¿conoce a Sir Theodore?",
    ["I... am surprised you have heard of him. He rescued me after my encounter with the Kinshra. He... understood me."] = "Me... sorprende que hayas oído hablar de él. Él me rescató después de mi encuentro con Kinshra. Él... me entendió.",
    ["We shared many great adventures. Gunnarsgrunn, Morytania and many more. Those were exhilarating carefree times - no gods interfering in our world."] = "Compartimos muchas grandes aventuras. Gunnarsgrunn, Morytania y muchos más. Fueron tiempos emocionantes y sin preocupaciones: ningún dios interfería en nuestro mundo.",
    ["Were?"] = "¿Eran?",
    ["Yes, Sir Theodore is no longer with us."] = "Sí, Sir Theodore ya no está con nosotros.",
    ["I am sorry to hear that."] = "Lamento oír eso.",
    ["I'm fine! It's fine. We were friends. It has not affected my judgement or ability to gut an opponent. What else do you want to know?"] = "¡Estoy bien! Está bien. Éramos amigos. No ha afectado mi juicio ni mi capacidad para destripar a un oponente. ¿Qué más quieres saber?",
    ["*Note: This conversation takes place post-quest.*"] = "*Nota: Esta conversación tiene lugar después de la misión.*",
    ["Hero."] = "Héroe.",
    ["Hang on a second, what IS that weapon you're carrying? The cruel-looking sword?"] = "Espera un segundo, ¿qué ES esa arma que llevas? ¿La espada de aspecto cruel?",
    ["You mean this spearhead? It's called Sunspear - a fabled vampyre-killing weapon, apparently."] = "¿Te refieres a esta punta de lanza? Se llama Sunspear, aparentemente un arma legendaria para matar vampyre.",
    ["I thought it looked familiar, but that's NOT Sunspear. I have Sunspear, and it's a dagger not a sword."] = "Pensé que me resultaba familiar, pero NO es Sunspear. Tengo Sunspear y es un dagger, no una espada.",
    ["I'm pretty sure you don't - I took this off Lord Drakan himself."] = "Estoy bastante seguro de que no. Se lo quité al mismísimo Lord Drakan.",
    ["Yes, and I used my dagger to kill Prince Tenebra himself."] = "Sí, y usé mi dagger para matar al mismísimo Príncipe Tenebra.",
    ["Don't you think it a bit odd that yours is a dagger, yet it's called SunSPEAR? Mine WAS once part of an actual spear."] = "¿No te parece un poco extraño que el tuyo sea un dagger y se llame SunSPEAR? La mía FUE alguna vez parte de una lanza real.",
    ["Yes, very odd. Perhaps my dagger was once part of a spear too?"] = "Sí, muy extraño. ¿Quizás mi dagger también fue parte de una lanza?",
    ["Maybe even the same spear, who knows?"] = "Quizás incluso la misma lanza, ¿quién sabe?",
    ["Hello there...thanks for helping out Trufitus commune with the gods Bwana. We've been able to return to the village thanks to your help."] = "Hola... gracias por ayudar a Trufitus a comunicarse con los dioses Bwana. Hemos podido regresar al pueblo gracias a vuestra ayuda.",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["Oh, I'm a fisherman by trade and I sometimes help out my father, Safta Doc."] = "Oh, soy pescador de profesión y a veces ayudo a mi padre, Safta Doc.",
    ["Is there anything interesting to do here?"] = "¿Hay algo interesante que hacer aquí?",
    ["Bwana, if anyone else asks me that question today, I'll explode! Go and ask Murcaily!"] = "Bwana, si alguien más me hace esa pregunta hoy, ¡explotaré! ¡Ve y pregúntale a Murcaily!",
    ["I'm just enjoying the sunshine, Bwana. Try asking Murcaily."] = "Solo estoy disfrutando del sol, Bwana. Intente preguntarle a Murcaily.",
    ["Well, I think that there's some work to be done...perhaps Murcaily can help you. He usually tends to the hardwood grove to the east of Trufitus' hut."] = "Bueno, creo que hay trabajo por hacer... tal vez Murcaily pueda ayudarte. Por lo general, atiende el bosquecillo de madera al este de la cabaña de Trufitus.",
    ["Sorry Bwana, I'm already busy, why not go and talk to Murcaily! He's around the village somewhere."] = "Lo siento Bwana, ya estoy ocupado, ¿por qué no vas y hablas con Murcaily? Está en alguna parte del pueblo.",
    ["I've been doing some work around the village."] = "He estado trabajando en el pueblo.",
    ["Hey, I've seen you working around the village. You've been doing a lot of good work around here for us. Let me give you something for your trouble."] = "Oye, te he visto trabajando en el pueblo. Has estado haciendo un muy buen trabajo aquí para nosotros. Déjame darte algo por tu molestia.",
    ["I've already given you some trading sticks and I don't have any more on me at the moment. Why not go and talk to some of the other villagers and get some contributions?"] = "Ya te he dado algunos palitos de intercambio y no tengo ninguno más en este momento. ¿Por qué no vas y hablas con algunos de los otros aldeanos y consigues algunas contribuciones?",
    ["Ok, thanks."] = "Vale, gracias.",
    ["You get [number] trading sticks. Your remaining favour totals [percentage]."] = "Obtienes palos comerciales [número]. El favor restante asciende a [percentage].",
    ["Ahhhhhhhh - Get away from me you beast!"] = "Ahhhhhhhh - ¡Aléjate de mí, bestia!",
    ["Ahhhhhhhh!"] = "¡Ahhhhhhhh!",
    ["Ahhhhhhhh - It's a monster!"] = "Ahhhhhhhh - ¡Es un monstruo!",
    ["Waahhhhh! - It's da evil broodoo beast come ta eat my very soul!"] = "¡Waahhhhh! - ¡Es una bestia malvada que viene a comerse mi alma!",
    ["What's the problem... oh, I'm wearing this big scary mask! I'd better take it off before I start talking to the natives."] = "¿Cuál es el problema? ¡Oh, estoy usando esta gran máscara aterradora! Será mejor que me lo quite antes de empezar a hablar con los nativos.",
    ["Kardia doesn't seem interested in talking."] = "Kardia no parece interesado en hablar.",
    ["Could you enchant this broom for me?"] = "¿Podrías encantarme esta escoba?",
    ["[You receive 14,979 Magic experience.]"] = "[Recibes 14,979 experiencia Magic.]",
    ["Many thanks."] = "Muchas gracias.",
    ["Oh, right  - I already had this enchanted here. Sorry to bother you."] = "Ah, claro, ya tenía esto encantado aquí. Lamento molestarlo.",
    ["Would you like to buy a nice kebab? Only one gold."] = "¿Te gustaría comprar un buen kebab? Sólo un oro.",
    ["I think I'll give it a miss."] = "Creo que lo dejaré pasar.",
    ["Yes please."] = "Sí, por favor.",
    ["I don't have enough room, sorry."] = "No tengo suficiente espacio, lo siento.",
    ["You buy a kebab."] = "Compras un kebab.",
    ["Oops, I forgot to bring any money with me."] = "Vaya, olvidé traer dinero conmigo.",
    ["Come back when you have some."] = "Vuelve cuando tengas algo.",
    ["What do you think of Ali Morrisane?"] = "¿Qué opinas de Ali Morrisane?",
    ["I don't like him. He makes all these claims about being the best salesman in the world, and he even has some thugs that he's hired to threaten us."] = "No me gusta. Hace todas esas afirmaciones de ser el mejor vendedor del mundo, e incluso tiene algunos matones que contrató para amenazarnos.",
    ["One of them came round here and threatened to cut my head off if I didn't cooperate with them!"] = "¡Uno de ellos vino por aquí y amenazó con cortarme la cabeza si no cooperaba con ellos!",
    ["I've also heard some rumours about them from my friend Isma'il in Pollnivneach..."] = "También escuché algunos rumores sobre ellos de mi amigo Isma'il en Pollnivneach...",
    ["What sort of rumours?"] = "¿Qué tipo de rumores?",
    ["Apparently he has men there as well, who have also been threatening people."] = "Aparentemente también tiene hombres allí, que también han estado amenazando a la gente.",
    ["And it's said that they even intend to steal from the ruler of Al Kharid himself!"] = "¡Y se dice que incluso tienen la intención de robarle al mismísimo gobernante de Al Kharid!",
    ["Really?"] = "¿En serio?",
    ["That's what I've heard. Anyway, are you sure you wouldn't like a kebab?"] = "Eso es lo que he oído. De todos modos, ¿estás seguro de que no te apetece un kebab?",
    ["I've got a little problem for you to solve."] = "Tengo un pequeño problema que debes resolver.",
    ["[The salesman has given you a challenge scroll!]"] = "[¡El vendedor te ha dado un pergamino de desafío!]",
    ["Please enter the answer to the riddle."] = "Ingresa la respuesta al acertijo.",
    ["Enter amount:<br>[Input field]"] = "Ingrese la cantidad:<br>[Input field]",
    ["No that's not right, think again."] = "No, eso no está bien, piénsalo de nuevo.",
    ["[The salesman has given you another clue scroll!]"] = "[¡El vendedor te ha dado otro pergamino de pistas!]",
    ["Correct!"] = "¡Correcto!",
    ["I am not here for you."] = "No estoy aquí para ti.",
    ["Congratulations, adventurer! You are Super Happy Wonder Lamp's millionth customer, and get a genie blessing completely free of charge! Choose from the following options:"] = "¡Felicitaciones, aventurero! ¡Eres el cliente número un millón de Super Happy Wonder Lamp y recibes una bendición de genio completamente gratis! Elija entre las siguientes opciones:",
    ["Woah! Where am I? Oh goodness, there must be a glitch somewhere! The small print says that since I'm here, you are eligible for another blessing. Oh dear."] = "¡Guau! ¿Dónde estoy? ¡Dios mío, debe haber un problema en alguna parte! La letra pequeña dice que ya que estoy aquí, eres elegible para recibir otra bendición. Oh querido.",
    ["Of course, <player>. Again. Go on then, get another blessing while you can. This clerical error can't last forever."] = "Por supuesto, <player>. De nuevo. Continúe entonces, obtenga otra bendición mientras pueda. Este error administrativo no puede durar para siempre.",
    ["**Blessing of Fate!**"] = "**¡Bendición del destino!**",
    [":*An animation occurs, she disappears and the chat window says:*"] = ":*Se produce una animación, ella desaparece y la ventana de chat dice:*",
    [":The genie departs to give out more blessings."] = ":El genio parte para repartir más bendiciones.",
    ["**Blessing of Free Will!**"] = "**¡Bendición del libre albedrío!**",
    ["**Blessing of Fortune!**"] = "**¡Bendición de la Fortuna!**",
    ["**I have a question about the blessings.**"] = "**Tengo una pregunta sobre las bendiciones.**",
    [":**Blessing of Fate**"] = ":**Bendición del destino**",
    ["::***Karima:** A Blessing of Fate gives you twice as much XP as a Blessing of Free Will, but in a random non-maxed skill."] = "::***Karima:** Una Bendición del Destino te otorga el doble de XP que una Bendición del Libre Albedrío, pero en una habilidad aleatoria no máxima.",
    ["::*(Loops back to the first selection screen.)*"] = "::*(Regresa a la primera pantalla de selección.)*",
    [":**Blessing of Free Will**"] = ":**Bendición del Libre Albedrío**",
    ["::***Karima:** A Blessing of Free Will gives half as much XP as a Blessing of Fate, but you can choose the skill."] = "::***Karima:** Una Bendición del libre albedrío otorga la mitad de XP que una Bendición del destino, pero puedes elegir la habilidad.",
    [":**Blessing of Fortune**"] = ":**Bendición de la Fortuna**",
    ["::***Karima:** A Blessing of Fortune will give you a healthy number of gold coins."] = "::***Karima:** Una Bendición de la Fortuna te dará una cantidad saludable de gold coins.",
    ["Um. Excuse me? Your blessing is a time limited offer, and I'm afraid I will be summoned back to head office in less than thirty seconds! Are you sure you don't want it?"] = "Mmm. ¿Disculpe? Su bendición es una oferta por tiempo limitado y me temo que me llamarán de regreso a la oficina central en menos de treinta segundos. ¿Estás seguro de que no lo quieres?",
    ["Okay, I'll take my blessing."] = "Está bien, aceptaré mi bendición.",
    ["*Shows options from above*"] = "*Muestra opciones desde arriba*",
    ["No thanks, I don't want it."] = "No gracias, no lo quiero.",
    ["The genie departs to give out more blessings."] = "El genio parte para repartir más bendiciones.",
    ["Hi there! It's great to see you."] = "¡Hola! Es genial verte.",
    ["What do you want to do?"] = "¿Qué quieres hacer?",
    ["Ask her about herself."] = "Pregúntale sobre ella misma.",
    ["You want to know about me? Sure - ask away."] = "¿Quieres saber de mí? Claro, pregunta.",
    ["Ask her about her background."] = "Pregúntale sobre sus antecedentes.",
    ["I'm Karima, a representative of Super Happy Wonder Lamp. We provide peerless wish services to mortals of this plane. I myself am from the Vetal caste of Djinn. We are aligned with the magical power of air. See how I'm floating? That's bona fide genie power for you!"] = "Soy Karima, un representante de Super Happy Wonder Lamp. Brindamos servicios de deseos incomparables a los mortales de este plano. Yo mismo soy de la casta Vetal de Djinn. Estamos alineados con el poder mágico del aire. ¿Ves cómo estoy flotando? ¡Ese es un verdadero poder de genio para ti!",
    ["Ask her about wishes."] = "Pregúntale sobre los deseos.",
    ["Super Happy Wonder Lamp is proud to provide a superb service to you today! You can trade keys to me in return for some fabulous prizes. We currently have a special offer on lamps! You'll find a corny... corner... coro... A lot! You'll find a lot of lamps hidden in these chests!"] = "¡Super Happy Wonder Lamp se enorgullece de brindarle un excelente servicio hoy! Puedes intercambiarme las llaves a cambio de fabulosos premios. ¡Actualmente tenemos una oferta especial en lámparas! Encontrarás un rincón cursi... coro... ¡Mucho! ¡Encontrarás muchas lámparas escondidas en estos cofres!",
    ["What kind of lamps you ask? All kinds! huge{{Sic}} lamps, small lamps, bright lamps, dark lamps. Every kind of lamp you can imagine, even our prized celebration lamps if you're very lucky!"] = "¿Qué tipo de lámparas preguntas? ¡Todo tipo! lámparas enormes{{Sic}}, lámparas pequeñas, lámparas brillantes, lámparas oscuras. Todo tipo de lámpara que puedas imaginar, ¡incluso nuestras preciadas lámparas de celebración si tienes mucha suerte!",
    ["Ask her about Alice"] = "Pregúntale sobre Alice",
    ["We've performed an *teehee* aggressive takeover of the Treasure Hunter business previously owned by one... ...Princess Alessandra. I'm sure she's completely safe, unharmed, totally not toast."] = "Hemos realizado una *teehee* agresiva adquisición del negocio Treasure Hunter que anteriormente pertenecía a una... ...la princesa Alessandra. Estoy seguro de que está completamente a salvo, ilesa y completamente sana.",
    ["Change the subject."] = "Cambia de tema.",
    ["Ask her about Treasure Hunter."] = "Pregúntale sobre Treasure Hunter.",
    ["It's very easy - if you've got a Treasure Hunter key, you can open a chest and win a prize."] = "Es muy fácil: si tienes una llave Treasure Hunter, puedes abrir un cofre y ganar un premio.",
    ["What do you want to ask?"] = "¿Qué quieres preguntar?",
    ["How do I play?"] = "¿Cómo juego?",
    ["Just click on a chest, and see what you win! It's very simple. One key opens one chest to win one prize."] = "¡Simplemente haz clic en un cofre y mira lo que ganas! Es muy sencillo. Una llave abre un cofre para ganar un premio.",
    ["What can I win?"] = "¿Qué puedo ganar?",
    ["There's loads of prizes to be won! You could win a falling star for some bonus XP, or some resources to help you train a skill. If you're really lucky you could win a super-rare prize and show off to all your friends!"] = "¡Hay muchos premios que ganar! Podrías ganar una estrella fugaz para obtener XP adicional o algunos recursos que te ayudarán a entrenar una habilidad. ¡Si tienes mucha suerte, podrás ganar un premio excepcional y presumir ante todos tus amigos!",
    ["You can see the prizes that could be in your next chest on the ticker below the chests."] = "Puedes ver los premios que podrían estar en tu próximo cofre en el símbolo debajo de los cofres.",
    ["How do I get keys?"] = "¿Cómo obtengo llaves?",
    ["Keys are all over the place! You can also find them around the world as you adventure. Not only that, but I'll give you a free key every day you're here - two if you're a member. You can also buy keys directly, and you can earn them through quests and challenges."] = "¡Las llaves están por todos lados! También puedes encontrarlos en todo el mundo mientras te aventuras. No sólo eso, sino que te daré una clave gratis cada día que estés aquí (dos si eres miembro). También puedes comprar claves directamente y ganarlas a través de misiones y desafíos.",
    ["What do Hearts of Ice do?"] = "¿Qué hacen Corazones de Hielo?",
    ["Hearts of Ice are magical crystals that you can use to freeze prize categories. If the prize in the chest you choose is in a frozen category, I'll give you a prize from an unfrozen category instead. You can find out more by clicking on the categories button."] = "Los corazones de hielo son cristales mágicos que puedes usar para congelar categorías de premios. Si el premio del cofre que eliges está en una categoría congelada, te daré un premio de una categoría no congelada. Puedes obtener más información haciendo clic en el botón de categorías.",
    ["You can get them when you buy Treasure Hunter keys directly, find keys around the world, or open at least five chests per day."] = "Puedes obtenerlas comprando llaves Treasure Hunter directamente, encontrando llaves en todo el mundo o abriendo al menos cinco cofres por día.",
    ["Ask about organising your won items."] = "Pregunte sobre la organización de sus artículos ganados.",
    ["I have created a way for you to see all of the items you have won on Treasure Hunter and Squeal of Fortune. You can find out information on all of the items and then decide if you want to keep them. Would you like me to open the interface?"] = "He creado una forma para que puedas ver todos los artículos que has ganado en Treasure Hunter y Squeal of Fortune. Puede encontrar información sobre todos los artículos y luego decidir si desea conservarlos. ¿Quieres que abra la interfaz?",
    ["Open the interface."] = "Abra la interfaz.",
    ["*(Opens Treasure Hunter Item Information interface.)*"] = "*(Abre la interfaz de información del artículo Treasure Hunter.)*",
    ["Say goodbye."] = "Di adiós.",
    ["Hello there, human! Come in, come in!"] = "¡Hola, humano! ¡Entra, entra!",
    ["Hi, nice to see you!"] = "Hola, ¡encantado de verte!",
    ["Tell me, what brings you here?"] = "Dime, ¿qué te trae por aquí?",
    ["Well, first I came to this city just for the adventure and excitement, but then I knocked over this statue, you see. Well, I didn't really knock it over myself, I was on this boat."] = "Bueno, primero vine a esta ciudad solo por la aventura y la emoción, pero luego derribé esta estatua, ¿sabes? Bueno, realmente no lo derribé yo mismo, estaba en este barco.",
    ["A boat! Fascinating, go on!"] = "¡Un barco! Fascinante, ¡adelante!",
    ["Yes, well, this boatman was a bit rubbish, or there was something wrong with the ship, I don't know. And then I got arrested by the Black Guard."] = "Sí, bueno, este barquero era un poco basura, o le pasaba algo al barco, no lo sé. Y luego me arrestó el Black Guard.",
    ["Not the Black Guard!"] = "¡No el Black Guard!",
    ["Yes, and they took me to this Veldaban person, who pretended to be really angry but actually he was really nice and he asked me for my help."] = "Sí, y me llevaron con esta persona de Veldaban, quien fingió estar muy enojado pero en realidad fue muy amable y me pidió ayuda.",
    ["So here I am, helping to rebuild the statue."] = "Así que aquí estoy, ayudando a reconstruir la estatua.",
    ["And after a whole lot of running around, I finally managed to get the statue to be rebuilt."] = "Y después de mucho correr, finalmente logré reconstruir la estatua.",
    ["Such an interesting tale!"] = "¡Qué historia tan interesante!",
    ["Now how did you come to be in Keldagrim again?"] = "Ahora, ¿cómo llegaste a estar en Keldagrim nuevamente?",
    ["Never mind."] = "No importa.",
    ["WHAT WOULD YOU LIKE TO DO?"] = "¿QUÉ TE GUSTARÍA HACER?",
    ["Ask about their request."] = "Pregunta sobre su solicitud.",
    ["What're you requesting today?"] = "¿Qué pides hoy?",
    ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
    ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal].",
    ["I'm also looking for some produce, so I'll need : [Produce] x [number]"] = "También estoy buscando algunos productos, así que necesitaré: [Produce] x [número]",
    ["If you complete this, I'll give you : Rune bar x 20. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Barra de runas x 20. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] days, [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido!, solo estoy aquí por [número] días, [número] horas y [número] minutos. Para ser exactos.",
    ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
    ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
    ["For completing this request you've received Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación para Brassica.",
    ["You've received : Rune bar x 20<br>And 5,500 farming reputation."] = "Has recibido: Barra de runas x 20<br>Y 5500 de reputación agrícola.",
    ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
    ["A new request will be available in [number] days, [number] hours and [number] minutes{{Sic|..}}"] = "Una nueva solicitud estará disponible en [número] días, [número] horas y [número] minutos{{Sic|..}}",
    ["For completing this request you've recieved Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación Brassica.",
    ["[You've received : Rune bar x 20<br>And 5,500 farming reputation]"] = "[Has recibido: Barra de runas x 20<br>Y 5500 de reputación agrícola.]",
    ["You've already completed this request, there will be a new tri-daily request in [number] days, [number] hours and [number] minutes{{Sic|..}}"] = "Ya has completado esta solicitud, habrá una nueva solicitud tridiaria en [número] días, [número] horas y [número] minutos{{Sic|..}}",
    ["Hsssssss ssssshssssss hssss hsss hssss!"] = "¡Hsssssss ssssshssssss hssss hsss hssss!",
    ["Hssshsss hssssh sssshssss sss.<br>(Party on, dude!)"] = "Hssshsss hssssh sssshssss sss.<br>(¡Fiesta, amigo!)",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["Hssshsss hssssh sssshssss sss.<br>(My name's Karma. I'm Pete's pet.)"] = "Hssshsss hssssh sssshssss sss.<br>(Mi nombre es Karma. Soy la mascota de Pete.)",
    ["That's nice."] = "Eso es bueno.",
    ["Hssshsss hssssh sssshssss sss.<br>(Oh yeah, man, it majorly rocks!)"] = "Hssshsss hssssh sssshssss sss.<br> (¡Oh, sí, hombre, es genial!)",
    ["Rock on!"] = "¡Sigue adelante!",
    ["Hssshsss hssssh sssshssss sss.<br>(You betcha!)"] = "Hssshsss hssssh sssshssss sss.<br> (¡Puedes apostarlo!)",
    ["*(Only if not selected last:)*"] = "*(Sólo si no fue seleccionado en último lugar:)*",
    ["I'm Karri. I was once a great warrior, roaming these lands lost, with no solid purpose. Then one day I met Menowin, and he helped me find a much more fun side to life."] = "Soy Karri. Una vez fui un gran guerrero, vagando por estas tierras perdidas, sin un propósito sólido. Entonces, un día conocí a Menowin y él me ayudó a encontrar un lado mucho más divertido de la vida.",
    ["Now, I get to watch people having fun going through this castle course."] = "Ahora puedo ver a la gente divertirse en este recorrido del castillo.",
    ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
    ["How does the Agility funhouse work? *(With a non-capitalised \"Agility\" if \"Who are you?\" was asked last.)*"] = "¿Cómo funciona la casa de la diversión Agility? *(Con \"Agility\" sin mayúscula si se preguntó \"¿Quién eres?\" en último lugar.)*",
    ["It's so much fun! You get to run around a crazy castle and slide down snakes, and dodge obstacles. Its{{Sic}} like the happiest workout ever."] = "¡Es muy divertido! Puedes correr por un castillo loco, deslizarte por serpientes y esquivar obstáculos. Its{{Sic}} es como el entrenamiento más feliz jamás realizado.",
    ["*(Only in 2017:)*"] = "*(Solo en 2017 :)*",
    ["You will be charged 10 tokens when you start a lap of the funhouse."] = "Se te cobrarán 10 fichas cuando comiences una vuelta en la casa de la diversión.",
    ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
    ["You will receive Agility XP for each obstacle, and then a chunk of XP when you reach the end."] = "Recibirás Agility XP por cada obstáculo y luego una parte de XP cuando llegues al final.",
    ["How are things going?"] = "¿Cómo van las cosas?",
    ["Life is so full of fun for me now. I recommend forgetting your cares and having a few trips around the castle!"] = "La vida está muy llena de diversión para mí ahora. ¡Recomiendo olvidarse de sus preocupaciones y dar unas cuantas vueltas por el castillo!",
    ["I sneak in a few laps myself when people aren't looking."] = "Yo mismo doy algunas vueltas cuando la gente no mira.",
    ["Hi there. I'm studying for the Earth Sciences exam."] = "Hola. Estoy estudiando para el examen de Ciencias de la Tierra.",
    ["Interesting... This exam seems to be a popular one!"] = "Interesante... ¡Este examen parece ser muy popular!",
    ["I don't think I should try to steal from this poor student."] = "No creo que deba intentar robarle a este pobre estudiante.",
    ["Perhaps I should try talking to her first."] = "Quizás debería intentar hablar con ella primero.",
    ["Nothing interesting happens."] = "No pasa nada interesante.",
    ["**Katarina (student)** Hi there! Thanks again. Hey, maybe I'll be asking you for help next time. It seems you are something of an expert now!"] = "**Katarina (estudiante)** ¡Hola! Gracias de nuevo. Oye, tal vez te pida ayuda la próxima vez. ¡Parece que ahora eres una especie de experto!",
    ["**Player** How would you like to be part of my new research team?"] = "**Player** ¿Te gustaría formar parte de mi nuevo equipo de investigación?",
    ["**Katarina (student)** Sounds great! Just one problem... I'm not an intern yet. Acting Guildmaster Reiniger wants me to make a notable discovery."] = "**Katarina (estudiante)** ¡Suena genial! Sólo un problema... todavía no soy pasante. Acting Guildmaster Reiniger quiere que haga un descubrimiento notable.",
    ["**Katarina (student)** Ideally, something in my field of effigies, icons and simulacra. I've heard that Kharid-et has these training dummies modelled after chthonian demons..."] = "**Katarina (estudiante)** Idealmente, algo de mi campo de efigies, íconos y simulacros. He oído que Kharid-et tiene estos dummies de entrenamiento inspirados en demonios cthonianos...",
    ["**Player** I've got you covered. You helped me out a lot with my exams, it's only fair."] = "**Player** Te tengo cubierto. Me ayudaste mucho con mis exámenes, es justo.",
    ["**Katarina (student)** Tell you what - if you can bring me a restored Zarosian training dummy from Kharid-et, I'll head straight to research!"] = "**Katarina (estudiante)** Te diré una cosa: si puedes traerme un muñeco de entrenamiento zarosiano restaurado de Kharid-et, ¡iré directamente a investigar!",
    ["**Player** I'm on it!"] = "**Player** ¡Estoy en ello!",
    ["**Player** I have a restored Zarosian training dummy from Kharid-et..."] = "**Player** Tengo un muñeco de entrenamiento Zarosiano restaurado de Kharid-et...",
    ["Give Zarosian training dummy to Katarina?"] = "¿Darle el muñeco de entrenamiento zarosiano a Katarina?",
    ["Katrina has joined your research team!"] = "¡Katrina se ha unido a tu equipo de investigación!",
    ["**Katarina (student)**  Ooh, it's so cuddly! I mean, it's perfect, thanks, boss!"] = "**Katarina (estudiante)** ¡Oh, es tan tierno! Quiero decir, es perfecto, ¡gracias jefe!",
    ["**Player** Let me get back to you on this."] = "**Player** Déjame responderte sobre esto.",
    ["**Katarina (student)** Take your time, it's all good."] = "**Katarina (estudiante)** Tómate tu tiempo, todo está bien.",
    ["**Katarina (student)** Ready for research whenever you need me, boss!"] = "**Katarina (estudiante)** ¡Listo para investigar cuando me necesites, jefe!",
    ["You fail to pick the student's pocket."] = "No logras robarle el bolsillo al estudiante.",
    ["You pick the student's pocket..."] = "Escoges el bolsillo del estudiante...",
    ["I am not sure why I am giving this to the student..."] = "No estoy seguro de por qué le doy esto al estudiante...",
    ["You pet Katarina, and take a copy of their pawprint."] = "Acaricias a Katarina y tomas una copia de su huella.",
    ["You have found Katarina."] = "Has encontrado Katarina.",
    ["[You have discovered a new cat!]"] = "[¡Has descubierto un nuevo gato!]",
    ["[You quickly note it down in your logbook.<br><br>'Katarina']"] = "[Lo anotas rápidamente en tu cuaderno de bitácora.<br><br>'Katarina']",
    ["Meow, meow meow."] = "Miau, miau, miau.",
    ["I will get it! I will smash its tiny brains in."] = "¡Lo conseguiré! Le aplastaré sus diminutos cerebros.",
    ["Stupid rat think Katarina is - how you say - a walk in the cake?"] = "¿Rata estúpida cree que Katarina es, como se dice, un paseo por el pastel?",
    ["Katarina will show how wrong rat is. Even if rat is all weird and glowy, like a mouldy candle."] = "Katarina mostrará cuán equivocada está la rata. Incluso si la rata es toda extraña y brillante, como una vela mohosa.",
    ["Oh dear, oh dear, oh dear..."] = "Oh cielos, oh cielos, oh cielos...",
    ["Oh dear?"] = "¿Dios mío?",
    ["It's terrible!"] = "¡Es terrible!",
    ["What's terrible?"] = "¿Qué es terrible?",
    ["Oh, never mind, dearie. <br>What can I do for you?"] = "Oh, no importa, querida. <br>¿Qué puedo hacer por ti?",
    ["Can you take me downstream in your boat?"] = "¿Puedes llevarme río abajo en tu barco?",
    ["Ooh, it's dangerous up there at the moment!"] = "¡Oh, es peligroso ahí arriba en este momento!",
    ["I'm not afraid - let's go!"] = "No tengo miedo, ¡vamos!",
    ["It's dangerous up there for me too, dearie."] = "Ahí arriba también es peligroso para mí, querida.",
    ["Would it help if I gave you some money?"] = "¿Te ayudaría si te diera algo de dinero?",
    ["Ooh, that's better! I'll take you up<br> north for 50 shiny coins."] = "¡Oh, eso está mejor! Te llevaré <br> al norte por 50 brillantes coins.",
    ["I haven't got that much with me."] = "No tengo mucho conmigo.",
    ["Ooh, and you almost had me persuaded!"] = "¡Oh, y casi me convences!",
    ["Alright, I'll pay."] = "Muy bien, pagaré.",
    ["[Kathy Corkat rows you down the river to the sea...]"] = "[Kathy Corkat te lleva río abajo hasta el mar...]",
    ["Not a chance!"] = "¡Ni una sola posibilidad!",
    ["Then you can find your own way north, dearie!"] = "¡Entonces podrás encontrar tu propio camino hacia el norte, querida!",
    ["[Charm] A lady this beautiful shouldn't be so afraid!"] = "[Charm] ¡Una dama así de hermosa no debería tener tanto miedo!",
    ["A lady this beautiful shouldn't be so afraid!"] = "¡Una dama tan hermosa no debería tener tanto miedo!",
    ["Oooh, you shouldn't tease a poor girl so! But I'll take you downstream if you like!"] = "¡Oh, no deberías burlarte de una pobre chica así! ¡Pero te llevaré río abajo si quieres!",
    ["Dangerous? Nah, forget it!"] = "¿Peligroso? ¡No, olvídalo!",
    ["I don't think I want anything, thanks."] = "No creo que quiera nada, gracias.",
    ["Everybody wants something, dearie!"] = "¡Todo el mundo quiere algo, cariño!",
    ["Huh? Oh, forget it!"] = "¿Eh? ¡Olvídalo!",
    ["I'll be glad to get away from this place, dearie! Fancy a lift up the river?"] = "¡Me alegrará alejarme de este lugar, querida! ¿Te apetece un viaje río arriba?",
    ["[Kathy Corkat rows you up the river...]"] = "[Kathy Corkat te lleva río arriba...]",
    ["Hello dearie. Heading up north to the Fishing Colony, are we?"] = "Hola querida. Nos dirigimos hacia el norte, hacia la colonia Fishing, ¿verdad?",
    ["Are ye wantin' a lift up the river, dearie?"] = "¿Quieres que te lleven río arriba, querida?",
    ["Why don't you row right into the Colony?"] = "¿Por qué no remas hasta la Colonia?",
    ["Why don't you row right into the Colony? It'd make it much easier to get in there."] = "¿Por qué no remas directo a la Colonia? Sería mucho más fácil entrar allí.",
    ["Oh, Franklin doesn't like it if I take my boat too close. He says I'll damage the nets and scare the fish. But were you wanting a lift up to the river?"] = "Oh, a Franklin no le gusta que acerque demasiado mi barco. Dice que dañaré las redes y asustaré a los peces. ¿Pero querías que te llevaran hasta el río?",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["It's a private business. Can I help you at all?"] = "Es un negocio privado. ¿Puedo ayudarte en algo?",
    ["What sort of business?"] = "¿Qué tipo de negocio?",
    ["A small, family business. We give financial advice to other companies."] = "Una pequeña empresa familiar. Damos asesoramiento financiero a otras empresas.",
    ["I'm looking for fame and riches."] = "Busco fama y riquezas.",
    ["And you expect to find it up the back streets of Varrock?"] = "¿Y esperas encontrarlo en las calles secundarias de Varrock?",
    ["Farewell."] = "Adiós.",
    ["It's a private business."] = "Es un negocio privado.",
    ["We're undertakers. Ask more questions and I guarantee that your loved ones will be in the ground with a minimum of fuss."] = "Somos empresarios de pompas fúnebres. Haga más preguntas y le garantizo que sus seres queridos estarán bajo tierra con un mínimo de alboroto.",
    ["I'm looking for riches and fame."] = "Busco riquezas y fama.",
    ["Ask any more questions and you'll get stitches and maimed."] = "Haz más preguntas y te darán puntos y te dejarán mutilado.",
    ["What happened to your arm?"] = "¿Qué pasó con tu brazo?",
    ["It ran off and joined the circus. <br>Stop bothering me with ridiculous questions."] = "Se escapó y se unió al circo. <br>Deja de molestarme con preguntas ridículas.",
    ["It's been a pleasure. <br>Try not to get stabbed on the way out."] = "Ha sido un placer. <br>Intenta que no te apuñalen al salir.",
    ["The Shield of Arrav is back in the Museum!"] = "¡El Escudo de Arrav está de vuelta en el Museo!",
    ["Thank heavens. <br>I've been SO worried."] = "Gracias a Dios. <br>I he estado MUY preocupada.",
    ["Stay back. She's armed!"] = "Quédate atrás. ¡Está armada!",
    ["You think that laughing at a missing arm is funny?"] = "¿Crees que reírse de un brazo perdido es gracioso?",
    ["I'm only having a bit of 'armless fun."] = "Sólo me estoy divirtiendo un poco sin brazos.",
    ["We'll see if you're a stand up comedian when you have no legs."] = "Veremos si eres un comediante cuando no tengas piernas.",
    ["My arm came off when I died, if you must know."] = "My arm desapareció cuando morí, si quieres saberlo.",
    ["It was Zemouregal. When the Big Z invaded, he came to us first. Wanted half of some shield that we had in our coffers."] = "Era Zemouregal. Cuando la Gran Z invadió, él vino a nosotros primero. Quería la mitad de algún escudo que teníamos en nuestras arcas.",
    ["I stood my ground. Wasn't going to let him take anything from us."] = "Me mantuve firme. No iba a dejar que nos quitara nada.",
    ["I guess that didn't go down too well?"] = "Supongo que eso no te fue muy bien.",
    ["You think? He ripped off my arm and beat me to death with it. <br>But I died fighting, not quivering in a basement like that yellow-belly Straven."] = "¿Crees? Estafó my arm y me mató a golpes con él. <br>Pero morí luchando, no temblando en un sótano como ese Straven panza amarilla.",
    ["I've lost my lockpick..."] = "He perdido mi ganzúa...",
    ["[Katrine gives you a new lockpick.]"] = "[Katrine te ofrece una nueva ganzúa.]",
    ["Next time, I'll carve your fingers into convenient lock-picking shapes."] = "La próxima vez, tallaré tus dedos en formas convenientes para abrir cerraduras.",
    ["I've lost my crossbow..."] = "He perdido mi ballesta...",
    ["[Katrine replaces your crossbow. She spits and looks menacingly at you.]"] = "[Katrine reemplaza tu ballesta. Ella escupe y te mira amenazadoramente.]",
    ["I've lost my grapple..."] = "He perdido mi agarre...",
    ["[Katrine replaces your grapple. She looks daggers at you.]"] = "[Katrine reemplaza tu garfio. Ella te mira daggers.]",
    ["You've got some cojones coming here, Phoenix [fanboy/fangirl]!"] = "¡Tienes algunos cojones aquí, Phoenix [fanboy/fangirl]!",
    ["Katrine spits."] = "Katrine escupe.",
    ["Now get lost before I mop the floor with your guts."] = "Ahora piérdete antes de que trapee el piso con tus agallas.",
    ["Hi! What can I get you?"] = "¡Hola! ¿Qué puedo conseguirte?",
    ["What ales are you serving?"] = "¿Qué cervezas estás sirviendo?",
    ["Well, we've got Asgarnian Ale, Wizard's Mind Bomb and Dwarven Stout, all for only 3 coins."] = "Bueno, tenemos Asgarnian Ale, Wizard's Mind Bomb y Dwarven Stout, todas por solo 3 coins.",
    ["One Asgarnian Ale, please."] = "Una cerveza Asgarnian, por favor.",
    ["I said 3 coins! You haven't got 3 coins! {{anchor|isaid3coins}}"] = "¡Dije 3 coins! ¡No tienes 3 coins! {{anchor|isaid3coins}}",
    ["Sorry, I'll come back another day."] = "Lo siento, volveré otro día.",
    ["Thanks, Kaylee."] = "Gracias, Kaylee.",
    ["I'll try the Mind Bomb."] = "Probaré la bomba mental.",
    ["Can I have a Dwarven Stout?"] = "¿Puedo tener una Dwarven Stout?",
    ["I don't feel like any of those."] = "No me apetece nada de eso.",
    ["What can you tell me about dwarves and ale?"] = "¿Qué puedes decirme sobre los enanos y la cerveza?",
    ["Oh it's you again. Forgotten the secret already?"] = "Oh, eres tú otra vez. ¿Ya olvidaste el secreto?",
    ["No... I just... misplaced it."] = "No... Simplemente... lo perdí.",
    ["Mmmmm... the secret is in the gold. Drop a gold coin into asgarnian ale and you'll get this weird golden ale that the dwarves seem to love, I think they're genetically attracted to gold."] = "Mmmmm... el secreto está en el oro. Echa una moneda de oro en cerveza asgarniana y obtendrás esta extraña cerveza dorada que parece encantar a los enanos. Creo que se sienten atraídos genéticamente por el oro.",
    ["Thanks, I won't forg...err.. misplace it, this time."] = "Gracias, esta vez no lo olvidaré... err... extravío.",
    ["I was wondering if you could give some feedback on this mead?"] = "Me preguntaba si podrías darnos algún comentario sobre este hidromiel.",
    ["I'd recognise those old kegs anywhere."] = "Reconocería esos viejos barriles en cualquier lugar.",
    ["I'd love to try the next batch of Leslie's mead."] = "Me encantaría probar el próximo lote de hidromiel de Leslie.",
    ["Mead isn't my favourite choice of drink but that's very nice."] = "El hidromiel no es mi bebida favorita, pero es muy agradable.",
    ["That may be the best mead I've ever drunk actually."] = "En realidad, ese puede ser el mejor hidromiel que he bebido.",
    ["The flavours are very subtle. Delicious."] = "Los sabores son muy sutiles. Delicioso.",
    ["Fantastic, I'll pass that on. Thank you!"] = "Fantástico, lo pasaré. ¡Gracias!",
    ["Thanks!"] = "¡Gracias!",
    ["Can I help you at all?"] = "¿Puedo ayudarte en algo?",
    ["Yes please. What are you selling?"] = "Sí por favor. ¿Qué estás vendiendo?",
    ["Hello, surface-dweller."] = "Hola, habitante de la superficie.",
    ["Mistag posted me here when surface-dwellers started visiting the mine. If you have business in the Dorgeshuun mines I will guide you through the tunnels."] = "Mistag me publicó aquí cuando los habitantes de la superficie comenzaron a visitar la mina. Si tienes negocios en las minas de Dorgeshuun, te guiaré a través de los túneles.",
    ["Can you show me the way to the mine?"] = "¿Puedes mostrarme el camino a la mina?",
    ["All right. Follow me."] = "Muy bien. Sígueme.",
    ["Of course! You're always welcome in our mines!"] = "¡Por supuesto! ¡Siempre serás bienvenido en nuestras minas!",
    ["Kazgar shows you the way through the tunnels."] = "Kazgar te muestra el camino a través de los túneles.",
    ["Can you show me the way to the water mill cellar?"] = "¿Puedes mostrarme el camino al sótano del molino de agua?",
    ["Of course!"] = "¡Por supuesto!",
    ["Maybe some other time."] = "Quizás en otro momento.",
    ["Where do you want to go?"] = "¿A dónde quieres ir?",
    ["Dorgeshuun Mines"] = "Minas Dorgeshuun",
    ["Water mill cellar"] = "Bodega del molino de agua",
    ["Nowhere"] = "En ninguna parte",
    ["You should speak with the ruler of this isle, King Gjuki Sorvott IV."] = "Deberías hablar con el gobernante de esta isla, el rey Gjuki Sorvott IV.",
    ["Halt! There are dangerous monsters ahead!"] = "¡Alto! ¡Hay monstruos peligrosos por delante!",
    ["Tell me more about them."] = "Cuéntame más sobre ellos.",
    ["Let me at them!"] = "¡Déjame con ellos!",
    ["What is in that cave?"] = "¿Qué hay en esa cueva?",
    ["Within that cave there are dragons unlike any you may have encountered before."] = "Dentro de esa cueva hay dragones como ninguno que hayas encontrado antes.",
    ["Tipped with gems, they are stronger than the regular dragons you may have faced before."] = "Equipados con gemas, son más fuertes que los dragones normales a los que te hayas enfrentado antes.",
    ["I guard this cave to protect those who may otherwise enter unaware."] = "Guardo esta cueva para proteger a aquellos que, de otro modo, entrarían sin darse cuenta.",
    ["Let me face them."] = "Déjame enfrentarlos.",
    ["I shall only let you through if a Slayer master has instructed you to do so... or if you are willing to make a payment."] = "Sólo te dejaré pasar si un Slayer master te ha indicado que lo hagas... o si estás dispuesto a realizar un pago.",
    ["How much do you want?"] = "¿Cuánto quieres?",
    ["Not in your coins. In gems."] = "No en tu coins. En gemas.",
    ["There are gems all around us. I'll mine some and be right back."] = "Hay joyas a nuestro alrededor. Extraeré un poco y ya vuelvo.",
    ["No. I require some a bit more precious. Bring me uncut dragonstone, onyx or an incomplete hydrix and I shall allow you in. With each gem I will allow you to kill a certain amount before you must leave."] = "No. Necesito algunos un poco más preciosos. Tráeme piedra de dragón sin cortar, ónix o un hidrix incompleto y te permitiré entrar. Con cada gema te permitiré matar una cierta cantidad antes de que debas irte.",
    ["Thanks for letting me know."] = "Gracias por hacérmelo saber.",
    ["Can I enter the cave?"] = "¿Puedo entrar a la cueva?",
    ["I'd like to make a payment to enter the cave."] = "Me gustaría hacer un pago para entrar a la cueva.",
    ["You have already paid Kelhar the maximum number of gems. Kill some gemstone dragons before trying to pay again."] = "Ya le has pagado a Kelhar la cantidad máxima de gemas. Mata algunos dragones de piedras preciosas antes de intentar pagar nuevamente.",
    ["Kelhar will only accept uncut dragonstone, onyx and incomplete hydrix gems as payment to enter the cave."] = "Kelhar solo aceptará piedras de dragón sin cortar, ónix y gemas de hidrix incompletas como pago para ingresar a la cueva.",
    ["WHAT GEM WOULD YOU LIKE TO USE AS PAYMENT?"] = "¿QUÉ GEMA TE GUSTARÍA UTILIZAR COMO PAGO?",
    ["Uncut dragonstone (2 kills per gem)"] = "Piedra de dragón sin cortar (2 muertes por gema)",
    ["How many gems would you like to use?"] = "¿Cuántas gemas te gustaría usar?",
    ["Thank you! You may now kill a total of [number] gemstone dragons."] = "¡Gracias! Ahora puedes matar un total de dragones de piedras preciosas [número].",
    ["I don't want to pay you right now."] = "No quiero pagarte ahora.",
    ["You must pay me in uncut gems before I will allow you to enter the dungeon again."] = "Debes pagarme en gemas sin cortar antes de que te permita ingresar a la mazmorra nuevamente.",
    ["I will allow you to kill another [1-60,000] gemstone dragons before I will request further gem payments."] = "Te permitiré matar otros dragones de piedras preciosas [1-60,000] antes de solicitar más pagos de gemas.",
    ["Hello there, Kennith. How are you today?"] = "Hola, Kennith. ¿Cómo estás hoy?",
    ["Great mister! Thanks again for rescuing me!"] = "¡Gran señor! ¡Gracias de nuevo por rescatarme!",
    ["It was my pleasure Kennith. You take care now."] = "Fue un placer para mí Kennith. Cuídate ahora.",
    ["Sure mister. Goodbye now."] = "Claro señor. Adiós ahora.",
    ["Hey, Dave! You know you're not allowed to use the exchange."] = "¡Hola, Dave! Sabes que no puedes usar el intercambio.",
    ["What? Why?"] = "¿Qué? ¿Por qué?",
    ["You know why!"] = "¡Sabes por qué!",
    ["Let's say for the sake of argument that I don't. Could you explain?"] = "Digamos, a efectos de argumentación, que no. ¿Podrías explicarlo?",
    ["Because last year you bought all that shadow dye! You don't even own anything tough enough to withstand it. You dissolved three of your poor mum's dresses!"] = "¡Porque el año pasado compraste toda esa sombra dye! Ni siquiera tienes nada lo suficientemente resistente como para soportarlo. ¡Has disuelto tres de los vestidos de tu pobre madre!",
    ["Oh, uh, I'm very sorry about that. But look, I really need some runes."] = "Oh, uh, lo siento mucho. Pero mira, realmente necesito algunas runas.",
    ["What for?"] = "¿Para qué?",
    ["I need to stop a friend from making a terrible mistake I'll get blamed for."] = "Necesito evitar que un amigo cometa un terrible error por el que me culparán.",
    ["Okay Dave, seeing as it's you. What kind of runes are you after?"] = "Está bien, Dave, ya que eres tú. ¿Qué tipo de runas buscas?",
    ["Law Runes."] = "Runas de la ley.",
    ["Do I look like I'm made of money?"] = "¿Parece que estoy hecho de dinero?",
    ["Actually, yes."] = "En realidad, sí.",
    ["Well, yes, I suppose I sort of do. But I won't be able to afford any more nice suits if I just hand out law runes left and right."] = "Bueno, sí, supongo que más o menos sí. Pero no podré permitirme más trajes bonitos si reparto runas de ley a diestro y siniestro.",
    ["*(Shows other options)*"] = "*(Muestra otras opciones)*",
    ["Earth Runes."] = "Runas de la Tierra.",
    ["Oh, I don't have any earth runes I'm afraid. You might try speaking to one of the bankers though. I think I heard something about a competition."] = "Oh, me temo que no tengo runas de tierra. Aunque podrías intentar hablar con uno de los banqueros. Creo que escuché algo sobre una competencia.",
    ["Air Runes."] = "Runas de aire.",
    ["Yes, I have a few air runes I might be able to spare for you. I want something in return though."] = "Sí, tengo algunas runas de aire que tal vez pueda prescindir de ti. Aunque quiero algo a cambio.",
    ["What?"] = "¿Qué?",
    ["I really need something to drink. Be a mate and go fetch us one, would you?"] = "Realmente necesito algo de beber. Sé amigo y ve a buscarnos uno, ¿quieres?",
    ["Do you have anything for me to drink?"] = "¿Tienes algo de beber para mí?",
    ["*If you do not have the Emergency flask of stew on you, or if the flask is empty:*"] = "*Si no tienes el frasco de estofado de emergencia contigo, o si el frasco está vacío:*",
    ["*(Dialogue ends)*"] = "*(Termina el diálogo)*",
    ["*If you have the Emergency flask of stew on you:*"] = "*Si tienes el frasco de estofado de emergencia contigo:*",
    ["What's this?"] = "¿Qué es esto?",
    ["I brought you something to drink. Yum yum!"] = "Te traje algo de beber. ¡Mmm ñam!",
    ["Is this... one of your stews?"] = "¿Este es... uno de tus guisos?",
    ["I can only assume so!"] = "¡Solo puedo suponerlo!",
    ["No thank you. They're too spicy for my blood. Maybe you could find some water? Isn't there a fountain around here somewhere?"] = "No, gracias. Son demasiado picantes para mi sangre. ¿Quizás puedas encontrar algo de agua? ¿No hay una fuente por aquí?",
    ["*If you have the Flask of stew-water on you:*"] = "*Si tienes el Frasco de agua para guisar contigo:*",
    ["Some water. Mostly."] = "Un poco de agua. Principalmente.",
    ["*The thirsty clerk gulps down the water, lumps and all.*"] = "*El empleado sediento traga el agua, con grumos y todo.*",
    ["Was that a hint of orange?"] = "¿Fue un toque de naranja?",
    ["Possibly!"] = "¡Posiblemente!",
    ["Delicious. Here's your air runes. Say hi to Doris for me."] = "Delicioso. Aquí están tus runas de aire. Saluda a Doris de mi parte.",
    ["*The clerk drops three air runes into your hand.*"] = "*El empleado deja caer tres runas de aire en tu mano.*",
    ["Brilliant! I have all the runes I need to teleport. Let's give teleporting a go! Tropelet, revoekam egam!"] = "¡Brillante! Tengo todas las runas que necesito para teletransportarme. ¡Vamos a intentar teletransportarnos! ¡Tropelet, revoekam egam!",
    ["Hello there, Player!"] = "¡Hola, Player!",
    ["Hello again Kent."] = "Hola de nuevo Kent.",
    ["I never did get the chance to thank you properly for saving Kennith and myself."] = "Nunca tuve la oportunidad de agradecerte adecuadamente por salvarnos a Kennith y a mí.",
    ["Oh, don't be silly. It was nothing really."] = "Oh, no seas tonto. En realidad no fue nada.",
    ["Play it down if you will. It was a truly brave thing you did."] = "Minimízalo si quieres. Fue algo realmente valiente lo que hiciste.",
    ["I only did what anyone would have done in my position. I have to go now, take care."] = "Solo hice lo que cualquiera habría hecho en mi posición. Me tengo que ir ahora, cuídate.",
    ["You too, Player. Goodbye."] = "Tú también, Player. Adiós.",
    ["Hello, Kent!"] = "¡Hola, Kent!",
    ["Oh, hello, Player. It's great to see you again. You know, Kennith is always talking about you since you rescued him from the sea slugs. I'm sure he'd love to talk to you - he's just downstairs."] = "Ah, hola, Player. Es genial verte de nuevo. Ya sabes, Kennith siempre está hablando de ti desde que lo rescataste de las babosas marinas. Estoy seguro de que le encantaría hablar contigo; está abajo.",
    ["Sure, I might go and say 'Hello'."] = "Claro, podría ir y decir \"Hola\".",
    ["Hello, Kent. How are things in Witchaven with Kennith gone and"] = "Hola, Kent. ¿Cómo van las cosas en Witchaven con Kennith desaparecido y",
    ["Hi, Player. We miss him terribly, but there can be no denying that things are a lot more peaceful for us."] = "Hola, Player. Lo extrañamos muchísimo, pero no se puede negar que las cosas son mucho más pacíficas para nosotros.",
    ["How is he doing out on the Fishing Platform?"] = "¿Cómo le va en la plataforma Fishing?",
    ["Bailey's looking after him well and Kennith seems less, erm, troubled."] = "Bailey lo está cuidando bien y Kennith parece menos, erm, preocupado.",
    ["Maybe Kennith has learnt his lesson."] = "Quizás Kennith haya aprendido la lección.",
    ["Oh, yes, he's grown up, that's for sure. I don't think we'll be seeing him enslaving whole populations of people over a lost toy again."] = "Oh, sí, ha crecido, eso es seguro. No creo que volvamos a verlo esclavizando a poblaciones enteras por un juguete perdido.",
    ["Hello, Kent. Have you seen Kennith lately?"] = "Hola, Kent. ¿Has visto Kennith últimamente?",
    ["He dropped by just before he left. Handsome lad, eh? He certainly takes after his father."] = "Pasó por aquí justo antes de irse. Chico guapo, ¿eh? Ciertamente se parece a su padre.",
    ["Haha, sure."] = "Jaja, claro.",
    ["*Conversation 1:*"] = "*Conversación 1:*",
    ["Are you a surface-dweller?"] = "¿Eres un habitante de la superficie?",
    ["Yes..."] = "Sí...",
    ["Haha! You look funny! All tall and skinny with tiny eyes!"] = "¡Jaja! ¡Te ves gracioso! ¡Todo alto y delgado con ojos diminutos!",
    ["*Conversation 2:*"] = "*Conversación 2:*",
    ["Are you Player? Did you help Zanik save the city?"] = "¿Eres Player? ¿Ayudaste a Zanik a salvar la ciudad?",
    ["Yes, that was me!"] = "¡Sí, ese era yo!",
    ["When I'm older I'm going to be an adventurer, just like Zanik!"] = "Cuando sea mayor seré un aventurero, ¡como Zanik!",
    ["*Conversation 3:*"] = "*Conversación 3:*",
    ["Sorry, I'm not meant to talk to strangers."] = "Lo siento, no debo hablar con extraños.",
    ["*Conversation 4:*"] = "*Conversación 4:*",
    ["Shh! Don't tell anyone!"] = "¡Shh! ¡No se lo digas a nadie!",
    ["Don't tell anyone what?"] = "¿No decirle a nadie qué?",
    ["SHHH!"] = "¡SHHH!",
    ["*Conversation 5:*"] = "*Conversación 5:*",
    ["Help! Help! The surface people are attacking!"] = "¡Ayuda! ¡Ayuda! ¡La gente de la superficie está atacando!",
    ["It's alright, I'm friendly!"] = "¡Está bien, soy amigable!",
    ["Hail and well met, adventurer. Have you come to do battle against the shattered worlds?"] = "Saludo y bien conocido, aventurero. ¿Has venido a luchar contra los mundos destrozados?",
    ["You have returned. With your aid, we shall diminish the threat of the shattered worlds."] = "Has regresado. Con su ayuda, disminuiremos la amenaza de los mundos destrozados.",
    ["As you haven't entered the worlds before, I should tell you a little about how they work."] = "Como nunca antes has entrado en estos mundos, debería contarte un poco sobre cómo funcionan.",
    ["Select an option"] = "Seleccione una opción",
    ["I am the commander of the Abyssal Knights: we are elite soldiers forged from an alliance between the Void Knights and the Temple Knights."] = "Soy el comandante de los Caballeros Abisales: somos soldados de élite forjados a partir de una alianza entre los Caballeros del Vacío y los Caballeros del Templo.",
    ["Much as the Void Knights defend Gielinor from deadly creatures originating from the void, the Abyssal Knights stem the tide of deadly creatures that pour forth from the abyss."] = "Así como los Void Knights defienden Gielinor de criaturas mortales que se originan en el vacío, los Abyssal Knights frenan la marea de criaturas mortales que surgen del abismo.",
    ["Tell me about these 'shattered worlds'."] = "Háblame de estos 'mundos destrozados'.",
    ["Think of them as 'abyssal tumours'. Shattered worlds are a disease of our own making."] = "Piense en ellos como \"tumores abisales\". Los mundos destrozados son una enfermedad que nosotros mismos hemos creado.",
    ["Teleportation magic momentarily pierces the abyss, allowing anima from different worlds to leak in. Over time, this anima has coalesced into twisted amalgams of worlds travellers have visited."] = "La magia de teletransportación atraviesa momentáneamente el abismo, permitiendo que el ánima de diferentes mundos se filtre. Con el tiempo, esta ánima se ha fusionado en retorcidas amalgamas de mundos que los viajeros han visitado.",
    ["These 'shattered worlds' are inhabited by abyssal creatures, transformed and sustained by consuming otherworldly anima. They are highly dangerous and aggressive to all but their own kind."] = "Estos 'mundos destrozados' están habitados por criaturas abisales, transformadas y sostenidas mediante el consumo de ánima de otro mundo. Son muy peligrosos y agresivos con todos menos con los de su propia especie.",
    ["If the inhabitants of the shattered worlds were to infiltrate our own, the result could be catastrophic."] = "Si los habitantes de los mundos destrozados se infiltraran en el nuestro, el resultado podría ser catastrófico.",
    ["Can you explain how shattered worlds work?"] = "¿Puedes explicar cómo funcionan los mundos destrozados?",
    ["The worlds contain unpredictable horrors!"] = "¡Los mundos contienen horrores impredecibles!",
    ["To access the standard shattered worlds use the blue portal to my south."] = "Para acceder a los mundos destrozados estándar, utiliza el portal azul al sur.",
    ["My knights will need you to complete a specific objective on each world to help them gain control of it. Once you complete the objective, find the exit portal to the next world."] = "Mis caballeros necesitarán que completes un objetivo específico en cada mundo para ayudarlos a controlarlo. Una vez que completes el objetivo, encuentra el portal de salida al siguiente mundo.",
    ["Occasionally, you will find extra objectives in a world. You are not required to do these, but you will be rewarded if you do."] = "Ocasionalmente, encontrarás objetivos adicionales en un mundo. No es necesario que los haga, pero será recompensado si lo hace.",
    ["As you climb through the worlds the creatures they contain will get exponentially more powerful. You may find you can progress no further without increasing your power."] = "A medida que avanzas por los mundos, las criaturas que contienen se volverán exponencialmente más poderosas. Es posible que descubras que no puedes progresar más sin aumentar tu poder.",
    ["If my knights notice you moving through worlds quickly enough, they will allow you to skip some to put your skills to use where they are most needed."] = "Si mis caballeros notan que te mueves a través de mundos lo suficientemente rápido, te permitirán saltarte algunos para usar tus habilidades donde más se necesitan.",
    ["Venturing to a new world can trigger a mutator that applies strange effects to the environment or inhabitants of that world and subsequent worlds."] = "Aventurarse a un mundo nuevo puede desencadenar un mutador que aplica efectos extraños al entorno o a los habitantes de ese mundo y los mundos posteriores.",
    ["When this happens you have a choice between three mutators. Some will be beneficial to you, some will inhibit your progress and some will do a little of both - choose wisely!"] = "Cuando esto sucede, puedes elegir entre tres mutadores. Algunos serán beneficiosos para usted, otros inhibirán su progreso y otros harán un poco de ambas cosas: ¡elija sabiamente!",
    ["Any monster affected by mutators will be marked by our squires with a skull symbol."] = "Cualquier monstruo afectado por mutadores será marcado por nuestros escuderos con un símbolo de calavera.",
    ["After every five worlds you will reach the respite of a chest world which will award you some bonus anima. This also acts as a checkpoint and resets your mutators."] = "Después de cada cinco mundos, alcanzarás el respiro de un mundo de cofres que te otorgará algo de ánima adicional. Esto también actúa como un punto de control y reinicia tus mutadores.",
    ["Once a week, there is a chance of powerful challenge worlds spawning. You can attempt these using the red portal. You can claim large sums of anima by completing these."] = "Una vez a la semana, existe la posibilidad de que aparezcan mundos de desafío poderosos. Puedes intentarlos usando el portal rojo. Puedes reclamar grandes sumas de ánima al completarlos.",
    ["The quartermaster can reward you for any anima you collect on your journeys through the worlds."] = "El intendente puede recompensarte por cualquier ánima que recolectes en tus viajes por los mundos.",
    ["Long ago, this temple was constructed to guard a portal to the abyss, and prevent it from opening."] = "Hace mucho tiempo, este templo fue construido para proteger un portal al abismo y evitar que se abra.",
    ["Alas, the anima witch has broken the seals binding these portals, and opened the way to the shattered worlds."] = "Por desgracia, la bruja ánima rompió los sellos que unían estos portales y abrió el camino a los mundos destrozados.",
    ["Tell me about this 'anima witch'."] = "Háblame de esta 'bruja ánima'.",
    ["She is an exiled Void Knight...a powerful magic user who discovered the shattered worlds. She has increased her power and reversed her aging process by siphoning corrupted anima."] = "Ella es una Void Knight exiliada... una poderosa usuaria de magia que descubrió los mundos destrozados. Ha aumentado su poder y ha revertido su proceso de envejecimiento extrayendo ánima corrupta.",
    ["She is also my estranged wife. She blinded me when I caught up to her."] = "Ella también es mi ex esposa. Ella me cegó cuando la alcancé.",
    ["What a shocking twist!"] = "¡Qué giro tan impactante!",
    ["As I am out of action, the Abyssal Knights need your help to travel through world after world, and defeat the monsters therein."] = "Como estoy fuera de combate, los Caballeros Abisales necesitan tu ayuda para viajar de mundo en mundo y derrotar a los monstruos que allí se encuentran.",
    ["Retrieve as much anima as possible, to help close the portals she has opened, and restore Gielinor's leaking supply."] = "Recupera tanta ánima como sea posible para ayudar a cerrar los portales que ha abierto y restaurar el suministro que se está escapando de Gielinor.",
    ["What rewards can I get here?"] = "¿Qué recompensas puedo obtener aquí?",
    ["Ah, of course."] = "Ah, por supuesto.",
    ["What adventurer would aid us out of a sense of duty, honour; dare I say 'heroism'? Not you, it seems."] = "¿Qué aventurero nos ayudaría por sentido del deber, del honor? ¿Me atrevo a decir \"heroísmo\"? Tú no, al parecer.",
    ["If you care not for the abyssal threat, and act only in your own self-interest, then yes, rest assured there is compensation to be found for your 'valuable time'."] = "Si no te importa la amenaza abismal y actúas sólo por tu propio interés, entonces sí, ten la seguridad de que encontrarás una compensación por tu \"valioso tiempo\".",
    ["You shall not find remuneration from me, however. Should that be your motivation, seek out the quartermaster in this camp."] = "Sin embargo, no encontrarás ninguna remuneración de mi parte. Si esa es tu motivación, busca al intendente de este campamento.",
    ["Farewell, adventurer."] = "Adiós, aventurero.",
    ["Adventurer, that portal is dangerous, come and hear what I have to say first!"] = "Aventurero, ese portal es peligroso, ¡ven y escucha lo que tengo que decir primero!",
    ["A rift has formed in the Abyssal Knights. For now at least, we share a common enemy. Grand Master Cemphier has tasked me with keeping order."] = "Se ha formado una grieta en los Caballeros Abisales. Al menos por ahora, compartimos un enemigo común. El Gran Maestro Cemphier me ha encargado mantener el orden.",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["I'm also looking for a new animal, I'm currently after A [animal]"] = "También estoy buscando un nuevo animal, actualmente estoy buscando A [animal]",
    ["If you complete this, I'll give you : Shattered anima x 15000. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Anima destrozada x 15000. ¡Estoy seguro de que también ganarás algo de reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido! Solo estoy aquí por [número] horas y [número] minutos. Para ser exactos.",
    ["[You've received : Shattered anima x 15000 <br>And 2,750 farming reputation.]"] = "[Has recibido: Anima destrozada x 15000 <br>Y 2750 de reputación agrícola.]",
    ["A new request will be available in [time].."] = "Una nueva solicitud estará disponible en [time].",
    ["You've already completed this request, there will be a new daily request in [time].."] = "Ya has completado esta solicitud, habrá una nueva solicitud diaria en [time].",
    ["Hello? Hello? What kind of low-class greeting is this?"] = "¿Hola? ¿Hola? ¿Qué clase de saludo de clase baja es este?",
    ["No matter. Clearly we move in very different social circles. Salutations, [peasant/peon/serf]."] = "No importa. Es evidente que nos movemos en círculos sociales muy diferentes. Saludos, [peasant/peon/serf].",
    ["What did you just call me?"] = "¿Cómo me acabas de llamar?",
    ["I called you a [peasant/peon/serf]. Why, what of it?"] = "Te llamé [peasant/peon/serf]. ¿Por qué? ¿Qué pasa con eso?",
    ["Who are you to go around insulting people like that?"] = "¿Quién eres tú para andar insultando así a la gente?",
    ["I came here with my friends and colleagues from Falador to take advantage of this captive market that we have right here. And let me tell you, business has never been better."] = "Vine aquí con mis amigos y colegas de Falador para aprovechar este mercado cautivo que tenemos aquí. Y déjame decirte que el negocio nunca ha estado mejor.",
    ["What do you mean?"] = "¿Qué quieres decir?",
    ["I mean that with the trolls attacking I've been able to peddle all kinds of goods to these rubes with an astonishing mark-up!"] = "¡Quiero decir que con los trolls atacando he podido vender todo tipo de productos a estos idiotas con un margen de beneficio sorprendente!",
    ["Food, clothing, cake tins, fishing supplies... You name it, I make am making a profit on it."] = "Comida, ropa, moldes para pasteles, suministros de pesca... Lo que sea, estoy obteniendo ganancias con ello.",
    ["But a lot of these people have no homes or money! What about the war effort?"] = "¡Pero muchas de estas personas no tienen casa ni dinero! ¿Qué pasa con el esfuerzo de guerra?",
    ["Pfft. What about it? If the trolls wipe this place out the White Knights and some scruffy tramps with swords calling themselves heroes will take care of it."] = "Pfft. ¿Qué pasa con eso? Si los trolls arrasan con este lugar, los Caballeros Blancos y unos vagabundos desaliñados con espadas que se hacen llamar héroes se encargarán de ello.",
    ["And then the survivors will need even more supplies to reclaim the land!"] = "¡Y luego los supervivientes necesitarán aún más suministros para recuperar la tierra!",
    ["You're all heart, aren't you?"] = "Eres todo corazón, ¿no?",
    ["Oh pipe down. I didn't expect a commoner like you to understand the ways of high finance."] = "Oh, cállate. No esperaba que un plebeyo como tú entendiera las costumbres de las altas finanzas.",
    ["What are you doing here?"] = "¿Qué estás haciendo aquí?",
    ["The folk here are too poor to set up elsewhere, or too thick-headed to give up."] = "La gente de aquí es demasiado pobre para establecerse en otro lugar, o demasiado tonta para darse por vencida.",
    ["My friends and I can sell them a one-coin shirt for fifteen, and they can't exactly shop around!"] = "Mis amigos y yo podemos venderles una camiseta de una moneda por quince, ¡y ellos no pueden comparar precios exactamente!",
    ["So long as this war keeps going, we're going to be raking it in!"] = "¡Mientras esta guerra continúe, vamos a ganar dinero!",
    ["But that's profiting on their misery!"] = "¡Pero eso es sacar provecho de su miseria!",
    ["Well, you might say that, but there's a lot of history between here and my home."] = "Bueno, se podría decir eso, pero hay mucha historia entre aquí y mi casa.",
    ["Wait, what?"] = "Espera, ¿qué?",
    ["You see, Falador and Burthorpe have always had this rivalry going, due to them not liking the White Knights or something equally childish."] = "Verás, Falador y Burthorpe siempre han tenido esta rivalidad, debido a que no les gustan los Caballeros Blancos o algo igualmente infantil.",
    ["So, we're loving this. You may well think were scum here, but back home in Falador - well, they are not quite so eager to judge us."] = "Entonces, nos encanta esto. Puede que pienses que aquí somos escoria, pero en casa, en Falador, bueno, no están tan ansiosos por juzgarnos.",
    ["I get the feeling they don't know all the facts. I'm sure the White Knights would not be happy with you starving refugees to turn a profit."] = "Tengo la sensación de que no conocen todos los hechos. Estoy seguro de que los Caballeros Blancos no estarían contentos con que ustedes, refugiados hambrientos, obtengan ganancias.",
    ["Well what they don't know won't hurt them, will it?"] = "Bueno, lo que no saben no les hará daño, ¿verdad?",
    ["I'll bet you're one of those 'hero' types, aren't you? A bleeding heart and a burning desire to help everyone."] = "Apuesto a que eres uno de esos tipos de 'héroes', ¿no? Un corazón sangrante y un deseo ardiente de ayudar a todos.",
    ["It's numbskulls like you, giving your gear away or dropping it for people to find, that are ruining my business!"] = "¡Son tontos como tú, que regalan tu equipo o lo dejan para que la gente lo encuentre, los que están arruinando mi negocio!",
    ["That's a very fancy outfit."] = "Es un traje muy elegante.",
    ["Theoretically?"] = "¿Teóricamente?",
    ["Well, I had it made from the finest materials, purchased from businesses that I was a partner in, so I got a good discount."] = "Bueno, lo hice con los mejores materiales, lo compré en empresas de las que era socio, así que obtuve un buen descuento.",
    ["Then I had the finest seamstresses in Falador put out of work, and paid them a pittance to make it for me before I would let them seek employment elsewhere."] = "Luego dejé sin trabajo a las mejores costureras de Falador y les pagué una miseria para que me lo hicieran antes de dejarles buscar empleo en otro lugar.",
    ["So in the end I have a very wonderful set of clothes with little or no cost to myself."] = "Así que al final tengo un maravilloso conjunto de ropa con poco o ningún costo para mí.",
    ["Yes, it is quite jaw-droppingly good, isn't it?"] = "Sí, es increíblemente bueno, ¿no?",
    ["I think I'm done here."] = "Creo que ya terminé aquí.",
    ["I saw it. I saw all of it..."] = "Lo vi. Lo vi todo...",
    ["Saw what?"] = "¿Viste qué?",
    ["You don't know! You'll never know what I saw!"] = "¡No lo sabes! ¡Nunca sabrás lo que vi!",
    ["The colours...all the colours...and sometimes NONE of the colours..."] = "Los colores... todos los colores... y a veces NINGUNO de los colores...",
    ["The darkness came to me then...with the stench, it protected my mind."] = "La oscuridad vino a mí entonces... con el hedor, protegió mi mente.",
    ["But the darkness is still there. The smell...The smell of it will never, ever fade..."] = "Pero la oscuridad sigue ahí. El olor... Su olor nunca, jamás se desvanecerá...",
    ["Well...isn't this a bit over the top from seeing Rolo get a little ill?"] = "Bueno... ¿no es un poco exagerado ver a Rolo enfermarse un poco?",
    ["A little ill? A little ill?"] = "¿Un poco enfermo? ¿Un poco enfermo?",
    ["The gods themselves wept tears of blood at the things he brought to light. Things that never should have been!"] = "Los propios dioses lloraron lágrimas de sangre ante las cosas que sacó a la luz. ¡Cosas que nunca debieron haber sido!",
    ["I...see. Well, I'll leave you to your mind babbling now. Have fun!"] = "Ya... veo. Bueno, ahora te dejaré con tu mente balbuceando. ¡Divertirse!",
    ["No! Don't leave me! It will come back for me!"] = "¡No! ¡No me dejes! ¡Volverá por mí!",
    ["Bye! Going away now! Have fun!"] = "¡Adiós! ¡Se va ahora! ¡Divertirse!",
    ["No... Always you... Can't you just let it be, World Guardian?"] = "No... Siempre tú... ¿No puedes simplemente dejarlo así, Guardián Mundial?",
    ["I'll tear right through you."] = "Te atravesaré.",
    ["*One of the following is picked at random*"] = "*Uno de los siguientes es elegido al azar*",
    ["I will put you in your place."] = "Te pondré en tu lugar.",
    ["You will break beneath me."] = "Te romperás debajo de mí.",
    ["Your godly devotion won't save you here, Player."] = "Tu devoción piadosa no te salvará aquí, Player.",
    ["Witness the raw power of the Staff."] = "Sea testigo del poder puro del Staff.",
    ["No. I control the threads of time."] = "No. Yo controlo los hilos del tiempo.",
    ["The time threads have split!"] = "¡Los hilos del tiempo se han dividido!",
    ["I... can... contain... ALL. ITS. POWER."] = "Yo... puedo... contener... TODO. ES. FUERZA.",
    ["If the needle won't heed my command. Then I'll use a greater weapon. The staff of Armadyl."] = "Si la aguja no obedece mi orden. Entonces usaré un arma mayor. El staff de Armadyl.",
    ["Look at what you've done! You've fractured the threads of time!"] = "¡Mira lo que has hecho! ¡Has roto los hilos del tiempo!",
    ["We did it! He's dead!"] = "¡Lo logramos! ¡Está muerto!",
    ["NO! Let me die! JUST LET ME DIE!"] = "¡NO! ¡Déjame morir! ¡DÉJAME MORIR!",
    ["Pitiful."] = "Lamentable.",
    ["We will all be free."] = "Todos seremos libres.",
    ["Your timeline ends here."] = "Su línea de tiempo termina aquí.",
    ["Hi. Do you need anything?"] = "Hola. ¿Necesitas algo?",
    ["No, not really. I just have a habit of interacting with people I see nearby. I'm not sure why."] = "No, en realidad no. Simplemente tengo la costumbre de interactuar con las personas que veo cerca. No estoy seguro de por qué.",
    ["Oh. Well, while I'm stressing about my studies, wondering whether I'm good enough to even finish becoming a seasinger, trying not to become a social outcast because of my slightly odd outlook on life..."] = "Ah. Bueno, mientras me estreso por mis estudios, me pregunto si soy lo suficientemente bueno como para terminar de convertirme en cantante marino, intento no convertirme en un paria social debido a mi visión ligeramente extraña de la vida...",
    ["I guess I could spare some time to have a normal conversation with you."] = "Supongo que podría dedicar algo de tiempo a tener una conversación normal contigo.",
    ["Fair enough. So... How are things?"] = "Muy bien. Entonces... ¿Cómo van las cosas?",
    ["Things are terrible."] = "Las cosas están terribles.",
    ["I'm worried that I'm too old to be here. The other students are four years my junior. And better than me!"] = "Me preocupa ser demasiado mayor para estar aquí. Los otros estudiantes son cuatro años menores que yo. ¡Y mejor que yo!",
    ["I'm worried that I'm allergic to the salad I had earlier and I'm scared my stomach will explode."] = "Me preocupa ser alérgico a la ensalada que comí antes y tengo miedo de que me explote el estómago.",
    ["I'm worried that I haven't met a decent partner yet and that clock is always ticking, you know?"] = "Me preocupa no haber conocido todavía a una pareja decente y ese reloj siempre corre, ¿sabes?",
    ["I'm worried that I spend too much time here that my friends back home will feel like strangers."] = "Me preocupa pasar demasiado tiempo aquí y que mis amigos en casa se sientan como extraños.",
    ["I'm worried that I haven't made the right choices in life. Is this where I want to be?"] = "Me preocupa no haber tomado las decisiones correctas en la vida. ¿Es aquí donde quiero estar?",
    ["I'm worried that when others ask me how I am that I just go off on a tirade of anxiety."] = "Me preocupa que cuando los demás me preguntan cómo estoy, simplemente lance una diatriba de ansiedad.",
    ["Where were you on the full moon?"] = "¿Dónde estabas en la luna llena?",
    ["I was here, drinking alone. I just wanted some quiet time away from the kids."] = "Estaba aquí, bebiendo solo. Sólo quería un momento de tranquilidad lejos de los niños.",
    ["They. Never. Sleep."] = "Ellos. Nunca. Dormir.",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["Did you see anything suspicious?"] = "¿Viste algo sospechoso?",
    ["When I left the pub, I saw two hooded figured running past me. Their faces were super blurry, so I couldn't see them."] = "Cuando salí del pub, vi dos figuras encapuchadas corriendo a mi lado. Sus rostros estaban súper borrosos, así que no podía verlos.",
    ["Who do you suspect of being the werewolf?"] = "¿De quién sospechas que es el hombre lobo?",
    ["Grace is really weird. She keeps humming to herself - it's really annoying."] = "Grace es realmente rara. Ella sigue tarareando para sí misma, es realmente molesto.",
    ["[Accuse Kevin of being the werewolf.]"] = "[Acusa a Kevin de ser el hombre lobo.]",
    ["Kevin! I accuse you of being a werewolf! Reveal your wolfish ways!"] = "¡Kevin! ¡Te acuso de ser un hombre lobo! ¡Revela tus costumbres lobunas!",
    ["*(Kevin dies.)*"] = "*(Kevin muere.)*",
    ["Your erroneous accusation has resulted in the death of an innocent bystander. The monster remains at large!"] = "Su acusación errónea ha resultado en la muerte de un espectador inocente. ¡El monstruo sigue prófugo!",
    ["Ah...oops. Guess I was wrong."] = "Ah... Ups. Supongo que estaba equivocado.",
    ["*Kevin dies*"] = "*Kevin muere*",
    ["Stunning the Volatile scarab akh has made it susceptible to damage."] = "Aturdir al escarabajo volátil akh lo ha hecho susceptible a sufrir daños.",
    ["Kezalam is pulling power from the obelisks. Destroy them!"] = "Kezalam está sacando poder de los obeliscos. ¡Destrúyelos!",
    ["These old bones will be dust soon enough. I feel the night air cutting through my hip."] = "Estos viejos huesos pronto se convertirán en polvo. Siento el aire de la noche cortando mi cadera.",
    ["How dare you make such a mockery!"] = "¡Cómo te atreves a hacer semejante burla!",
    ["Is this your idea of humour?"] = "¿Es esta tu idea del humor?",
    ["This conversation can continue after you remove that ridiculous outfit."] = "Esta conversación puede continuar después de que te quites ese ridículo atuendo.",
    ["Do you know where I can find blueberries?"] = "¿Sabes dónde puedo encontrar arándanos?",
    ["Blueberries? Don't be daft, there's no such thing!"] = "¿Arándanos? ¡No seas tonto, no existe tal cosa!",
    ["That's what I thought. I only know of redberries."] = "Eso es lo que pensé. Sólo conozco redberries.",
    ["Maybe if such a place of opposites existed, you'd have more luck!"] = "¡Tal vez si existiera un lugar así de opuestos, tendrías más suerte!",
    ["You might be onto something..."] = "Puede que tengas algo en claro...",
    ["Hmm... A place of opposites, and a cat called Evil Bob. Maybe Kili can point me in the right direction?"] = "Hmm... Un lugar de opuestos y un gato llamado Evil Bob. ¿Quizás Kili pueda indicarme la dirección correcta?",
    ["I'm busy at the moment."] = "Estoy ocupado en este momento.",
    ["Would you like to return to the City of Um?"] = "¿Te gustaría volver al City of Um?",
    ["**Return to the City of Um?**"] = "**¿Volver al City of Um?**",
    ["Do you ever like to just...dance? It's certainly an affordable hobby."] = "¿Alguna vez te ha gustado simplemente... bailar? Sin duda es un pasatiempo asequible.",
    ["*Occasionally Kharl will talk to himself in overhead dialogue.*"] = "*Ocasionalmente, Kharl habla solo en un diálogo aéreo.*",
    ["Please...spare some time. I need some help."] = "Por favor... dedica algo de tiempo. Necesito ayuda.",
    ["Would you like to help?"] = "¿Quieres ayudar?",
    ["Ah...so kind!"] = "Ah... ¡qué amable!",
    ["Not right now."] = "No ahora mismo.",
    ["Nevermind."] = "No importa.",
    ["I've been tasked to procure supplies for the war effort."] = "Me han encomendado la tarea de conseguir suministros para el esfuerzo bélico.",
    ["Who are we- Who are YOU at war with?"] = "¿Quiénes somos? ¿Con quién estás en guerra TÚ?",
    ["All will be revealed. First up I need [number] [items]. Can I rely on you?"] = "Todo será revelado. Primero necesito [número] [items]. ¿Puedo confiar en ti?",
    ["Affirmative."] = "Afirmativo.",
    ["Negative."] = "Negativo.",
    ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
    ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
    ["Oh, well, maybe someone else will pop along."] = "Oh, bueno, tal vez aparezca alguien más.",
    ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
    ["Talk about your current task."] = "Hable sobre su tarea actual.",
    ["Do you have the [number] [item] at hand, soldier? ([number] remaining)"] = "¿Tienes el [número] [item] a mano, soldado? ([número] restantes)",
    ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
    ["Number of [item] given to Kharl ([number]/[number])"] = "Número de [item] dado a Kharl ([número]/[número])",
    ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
    ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
    ["Great. Thank you."] = "Genial. Gracias.",
    ["Yes, I have the [item]."] = "Sí, tengo el [item].",
    ["Good work, soldier!"] = "¡Buen trabajo, soldado!",
    ["Now that's done, we need the next block of supplies."] = "Ahora que está hecho, necesitamos el siguiente bloque de suministros.",
    ["The next supplies I require are a load of [item]."] = "Los siguientes suministros que necesito son una carga de [item].",
    ["Right. Why [item]?"] = "Correcto. ¿Por qué [item]?",
    ["Have you ever tried to fight a war without [item]? I didn't think so."] = "¿Alguna vez has intentado pelear una guerra sin [item]? No lo creo.",
    ["The war effort requires [number] [item]. I assume I can trust you to obtain the [item]?"] = "El esfuerzo de guerra requiere [número] [item]. ¿Asumo que puedo confiar en usted para obtener el [item]?",
    ["You sure can."] = "Seguro que puedes.",
    ["No, sorry."] = "No, lo siento.",
    ["Do you have the supplies, soldier? This war won't fund itself! We need [number] [item]! ([number] remaining)"] = "¿Tienes los suministros, soldado? ¡Esta guerra no se financiará sola! ¡Necesitamos [número] [item]! ([número] restantes)",
    ["Great! Now we are ready to drive the offensive home!"] = "¡Genial! ¡Ahora estamos listos para llevar la ofensiva a casa!",
    ["Can I ask why you're talking like this?"] = "¿Puedo preguntar por qué hablas así?",
    ["Whatever do you mean, soldier?"] = "¿Qué quieres decir, soldado?",
    ["You're talking like an imperial general. It's a bit off-putting."] = "Estás hablando como un general imperial. Es un poco desagradable.",
    ["The guards are always watching. I have to keep up appearances."] = "Los guardias siempre están mirando. Tengo que guardar las apariencias.",
    ["Right...fair enough. What else do...we...need for the war effort?"] = "Cierto... bastante justo. ¿Qué más... nosotros... necesitamos para el esfuerzo bélico?",
    ["Now is the time you have been waiting for, soldier! The killing!"] = "¡Ahora es el momento que estabas esperando, soldado! ¡La matanza!",
    ["We will finally vanquish our dreaded enemy, the [monster]!"] = "¡Finalmente venceremos a nuestro temido enemigo, el [monster]!",
    ["Yes, kill [number] [monster] in the name of the Pharaoh himself!"] = "¡Sí, mata a [número] [monster] en nombre del propio Faraón!",
    ["Okay."] = "Está bien.",
    ["Nope."] = "No.",
    ["Have you killed [number] kalphites? They're found inside Kalphite hives under the desert sands. We might win this war yet! ([number] remaining)"] = "¿Has matado a los calfitos de [número]? Se encuentran dentro de colmenas calfitas bajo las arenas del desierto. ¡Podríamos ganar esta guerra todavía! ([número] restante)",
    ["Have you killed [number] plague frogs? They're usually sliming around Sophanem. We might win this war yet! ([number] remaining)"] = "¿Has matado las ranas plaga [número]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! ([número] restante)",
    ["Have you killed [number] plague frogs? They're usually sliming around Sophanem. We might win this war yet! (0 remaining)"] = "¿Has matado las ranas plaga [número]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! (0 restante)",
    ["Yes, I have killed the [monster]."] = "Sí, he matado al [monster].",
    ["Have you danced, as they say, in the blood of your enemies? Have you sent the souls of [number] [monster] to the Underworld?"] = "¿Has bailado, como dicen, en la sangre de tus enemigos? ¿Has enviado las almas de [número] [monster] al Inframundo?",
    ["Not that those [monster] have souls, I believe they are truly beyond help."] = "No es que esos [monster] tengan alma, creo que realmente no pueden recibir ayuda.",
    ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
    ["I fear you still need a lot more help."] = "Me temo que todavía necesitas mucha más ayuda.",
    ["Nothing. It was my pleasure."] = "Nada. Fue un placer.",
    ["I want to talk about Children of Mah."] = "Quiero hablar de Hijos de Mah.",
    ["What an adventure, Player. Our race is saved from the threat of extinction! Now I must look towards my own future."] = "Qué aventura, Player. ¡Nuestra raza está salvada de la amenaza de extinción! Ahora debo mirar hacia mi propio futuro.",
    ["It appears you lost my tome of knowledge upon your travels."] = "Parece que perdiste mi tomo de conocimientos en tus viajes.",
    ["Kharshai hands you a tome of knowledge."] = "Kharshai te entrega un tomo de conocimientos.",
    ["I want to talk about V."] = "Quiero hablar de V.",
    ["Yes, I have heard of his passing. A shame, perhaps, but such is the danger of godhood."] = "Sí, me enteré de su fallecimiento. Quizás sea una pena, pero tal es el peligro de la divinidad.",
    ["Take solace in the knowledge that he has inspired countless heroes across numerous worlds."] = "Consuélate sabiendo que ha inspirado a innumerables héroes en numerosos mundos.",
    ["Those heroes have, in turn, saved lives that would have been otherwise lost and defeated evils that would have threatened entire civilisations."] = "Esos héroes, a su vez, salvaron vidas que de otro modo se habrían perdido y derrotaron males que habrían amenazado a civilizaciones enteras.",
    ["Mourn his passing, as is proper, but know that the universe is a better place because of him."] = "Llora su fallecimiento, como es debido, pero debes saber que el universo es un lugar mejor gracias a él.",
    ["What can you tell me about banite ore?"] = "¿Qué puedes decirme sobre el mineral de banito?",
    ["I am not the metallurgist that you need for an in depth analysis."] = "No soy el metalúrgico que necesitas para un análisis en profundidad.",
    ["Suffice to say the potential of this banite ore is staggering. It can be attuned to hate a particular creature type."] = "Basta decir que el potencial de este mineral de banita es asombroso. Puede estar en sintonía para odiar a un tipo de criatura en particular.",
    ["You mean attuned to be more damaging?"] = "¿Quieres decir en sintonía para ser más dañino?",
    ["No my friend, I mean the metal hates that creature. It wants to hurt it, wants to make it suffer."] = "No, amigo mío, quiero decir que el metal odia a esa criatura. Quiere hacerle daño, quiere hacerlo sufrir.",
    ["Increased damage is just a side effect."] = "El aumento del daño es solo un efecto secundario.",
    ["What can you tell me about the dragonkin?"] = "¿Qué puedes decirme sobre los dragonantes?",
    ["Forgive me, but I’m afraid I doubtless know far less than you."] = "Perdóname, pero me temo que sin duda sé mucho menos que tú.",
    ["They are powerful, dangerous and they are not concerned with the plight of anyone but themselves."] = "Son poderosos, peligrosos y no les preocupa la situación de nadie más que ellos mismos.",
    ["Be careful trusting any of them my friend, for they doubtless can never trust you."] = "Ten cuidado al confiar en cualquiera de ellos, amigo mío, porque sin duda nunca podrán confiar en ti.",
    ["What can you tell me about gods?"] = "¿Qué puedes decirme sobre los dioses?",
    ["No more than you already know. The gods are powerful, yes, but they are not inherently better than any of us."] = "No más de lo que ya sabes. Los dioses son poderosos, sí, pero no son inherentemente mejores que cualquiera de nosotros.",
    ["A single rock can dam a river, but so can many pebbles."] = "Una sola roca puede represar un río, pero también pueden hacerlo muchos guijarros.",
    ["Together we are as powerful, if not stronger, than any god. Remember this."] = "Juntos somos tan poderosos, si no más fuertes, que cualquier dios. Recuerda esto.",
    ["Goodbye"] = "Adiós",
    ["I want to talk about the Mahjarrat memories."] = "Quiero hablar de los recuerdos de Mahjarrat.",
    ["Thank you for recovering the memories for me, my friend."] = "Gracias por recuperarme los recuerdos, amigo mío.",
    ["I need the engrammeter."] = "Necesito el engramametro.",
    ["[Kharshai hands you a small box.]"] = "[Kharshai te entrega una pequeña caja.]",
    ["You're welcome. Goodbye."] = "De nada. Adiós.",
    ["I want to talk about your identity crisis."] = "Quiero hablar de tu crisis de identidad.",
    ["You have questions, Player. Speak."] = "Tienes preguntas, Player. Hablar.",
    ["Whose side are you on, Kharshai?"] = "¿De qué lado estás, Kharshai?",
    ["I intend to stay neutral. If the balance between the Mahjarrat were to be disturbed, it would be disastrous. We have already lost many to sacrifices and assassinations."] = "Tengo la intención de mantenerme neutral. Si se perturbara el equilibrio entre los Mahjarrat, sería desastroso. Ya hemos perdido a muchos por sacrificios y asesinatos.",
    ["What about beyond the Mahjarrat?"] = "¿Qué pasa más allá del Mahjarrat?",
    ["All the Mahjarrat will be keeping an eye on what is going on, but their primary concerns are Zamorak and Zaros. My neutrality will maintain the balance."] = "Todos los Mahjarrat estarán atentos a lo que sucede, pero sus principales preocupaciones son Zamorak y Zaros. Mi neutralidad mantendrá el equilibrio.",
    ["What will you do now?"] = "¿Qué harás ahora?",
    ["I will remain here. The Fremennik people have treated me well, and while they have lost their deathless warrior, they have gained a new friend."] = "Me quedaré aquí. El pueblo Fremennik me ha tratado bien y, aunque han perdido a su guerrero inmortal, han ganado un nuevo amigo.",
    ["About that jewel..."] = "Sobre esa joya...",
    ["Blue jewel memory"] = "Memoria de joya azul",
    ["Interesting, this blue jewel has unlocked another memory."] = "Interesante, esta joya azul ha desbloqueado otro recuerdo.",
    ["I now know who erased my memory."] = "Ahora sé quién borró mi memoria.",
    ["Who? Who did that to you?"] = "¿Quién? ¿Quién te hizo eso?",
    ["I did."] = "Lo hice.",
    ["What? You deliberately erased your own memory?"] = "¿Qué? ¿Borraste deliberadamente tu propia memoria?",
    ["Yes. It was the only way to conceal myself from the other Mahjarrat. Simply transforming myself would not protect me from the Mahjarrat's innate ability to sense each other."] = "Sí. Era la única manera de ocultarme del otro Mahjarrat. Simplemente transformarme no me protegería de la capacidad innata de Mahjarrat de sentirnos unos a otros.",
    ["If you didn't know you were a Mahjarrat, how could they?"] = "Si no sabías que eras un Mahjarrat, ¿cómo podrían saberlo ellos?",
    ["Exactly. Thank you again for helping me."] = "Exactamente. Gracias de nuevo por ayudarme.",
    ["Red jewel memory"] = "Memoria de joya roja",
    ["Interesting, this red jewel has unlocked another memory."] = "Interesante, esta joya roja ha desbloqueado otro recuerdo.",
    ["I now know how Balmung came to be."] = "Ahora sé cómo surgió Balmung.",
    ["It was an experiment. I wanted to see if I could enhance bane ore to make a fearsome weapon."] = "Fue un experimento. Quería ver si podía mejorar el mineral de perdición para crear un arma temible.",
    ["Then why wasn't it enchanted when the Fremennik found it?"] = "Entonces, ¿por qué no estaba encantado cuando el Fremennik lo encontró?",
    ["I had not yet completed the spell. I was travelling to the Fremennik Isles for dagannoth blood."] = "Aún no había completado el hechizo. Viajaba a las islas Fremennik en busca de sangre de dagannoth.",
    ["And it came into contact with the blood when I used it to slay dagannoths in defense of Rellekka."] = "Y entró en contacto con la sangre cuando la usé para matar dagannoths en defensa de Rellekka.",
    ["Precisely. This allowed me to complete the enhancement. Thank you for assisting me."] = "Precisamente. Esto me permitió completar la mejora. Gracias por ayudarme.",
    ["Green jewel memory"] = "Memoria joya verde",
    ["This green jewel has unlocked another memory."] = "Esta joya verde ha desbloqueado otro recuerdo.",
    ["What did you discover?"] = "¿Qué descubriste?",
    ["I know why I am still powerful after all this time."] = "Sé por qué sigo siendo poderoso después de todo este tiempo.",
    ["There must have been a good reason."] = "Debe haber habido una buena razón.",
    ["As you know, the Mahjarrat sacrifice one of their own to maintain their power. Usually, the weakest is selected."] = "Como sabes, los Mahjarrat sacrifican a uno de los suyos para mantener su poder. Generalmente se selecciona al más débil.",
    ["Yes. I was present at the last one."] = "Sí. Estuve presente en el último.",
    ["The assassination attempt weakened me. Coupled with my neutral stance towards the factions, I would have been considered as the sacrifice."] = "El intento de asesinato me debilitó. Junto con mi postura neutral hacia las facciones, me habrían considerado el sacrificio.",
    ["So you chose not to attend the ritual?"] = "¿Entonces decidiste no asistir al ritual?",
    ["That was the best way to avoid being killed. But by not attending the ritual, I missed out on the rejuvenation, and risked falling behind the others in terms of power."] = "Esa fue la mejor manera de evitar que lo mataran. Pero al no asistir al ritual, me perdí el rejuvenecimiento y corrí el riesgo de quedarme atrás de los demás en términos de poder.",
    ["That would have been a problem."] = "Eso habría sido un problema.",
    ["However, the drain on my power when in the form of Koschei was almost zero."] = "Sin embargo, el consumo de mi poder cuando estaba en la forma de Koschei era casi nulo.",
    ["The other Mahjarrat became weaker, even in human form. Why didn't you?"] = "El otro Mahjarrat se debilitó, incluso en forma humana. ¿Por qué no lo hiciste?",
    ["The sealing of my memory was the key. Even in human form, Mahjarrat can still use their powers."] = "El sellado de mi memoria fue la clave. Incluso en forma humana, Mahjarrat todavía puede usar sus poderes.",
    ["As you didn't know you had the power, you were not using it."] = "Como no sabías que tenías el poder, no lo estabas usando.",
    ["Indeed, Player. This information will interest all Mahjarrat. I suspect they are already working on a way to locate anyone hidden using this method, in case someone else attempts it."] = "De hecho, Player. Esta información interesará a todos los Mahjarrat. Sospecho que ya están trabajando en una manera de localizar a cualquier persona oculta usando este método, en caso de que alguien más lo intente.",
    ["May I have a look at the jewel?"] = "¿Puedo echar un vistazo a la joya?",
    ["Can I have a look at the jewel I found?"] = "¿Puedo echar un vistazo a la joya que encontré?",
    ["You may, although it will not leave this cavern, for it is bound to me. I feel that it has more to reveal."] = "Puedes, aunque no saldrá de esta caverna, porque está ligado a mí. Siento que tiene más que revelar.",
    ["I'll come back another time."] = "Volveré en otra ocasión.",
    ["Sorry, I didn't mean to disturb you. I'll be going now."] = "Lo siento, no era mi intención molestarte. Me iré ahora.",
    ["Have you got Balmung?"] = "¿Tienes Balmung?",
    ["I seem to have misplaced Balmung."] = "Parece que he perdido a Balmung.",
    ["I do, but you don't appear to have enough room for it."] = "Sí, pero parece que no tienes suficiente espacio para ello.",
    ["This weapon is very powerful. Please don't let it fall into the wrong hands. If you lose it again, I will ask you to make a 300,000 gold coin donation to the Fremennik people."] = "Esta arma es muy poderosa. Por favor, no dejes que caiga en las manos equivocadas. Si lo vuelves a perder, te pediré que hagas una donación de 300.000 monedas de oro al pueblo Fremennik.",
    ["You lost it again? I will return it to you, for a 300,000 gold coin donation to the Fremennik people."] = "¿Lo perdiste otra vez? Te lo devolveré a cambio de una donación de 300.000 monedas de oro al pueblo Fremennik.",
    ["Do you want to claim Balmung back for 300,000 coins?"] = "¿Quieres recuperar Balmung por 300.000 coins?",
    ["This weapon is very powerful. Please don't lose it again."] = "Esta arma es muy poderosa. Por favor, no lo vuelvas a perder.",
    ["I cannot afford that right now."] = "No puedo permitirme eso en este momento.",
    ["Sorry to disturb you."] = "Perdón por molestarte.",
    ["I want to ask you about the epic of Bukalla."] = "Quiero preguntarte sobre the epic of Bukalla.",
    ["Ah yes, I noted your presence in the audience. What would you like to know?"] = "Ah, sí, noté tu presencia entre la audiencia. ¿Qué te gustaría saber?",
    ["What would you like to know?"] = "¿Qué te gustaría saber?",
    ["Ask about Bukalla's Balmung"] = "Pregunte por el Balmung de Bukalla",
    ["The song mentioned Bukalla having Balmung. Wasn't it you who forged it, and in the recent past?"] = "La canción mencionaba que Bukalla tenía a Balmung. ¿No fuiste tú quien lo forjó, y en el pasado reciente?",
    ["Ah, I realise how that might seem confusing."] = "Ah, me doy cuenta de que eso puede parecer confuso.",
    ["As you say, Balmung as you know it is a greataxe that I forged myself. Bukalla's Balmung was a huge sword."] = "Como dices, Balmung, como sabes, es una gran hacha que yo mismo forjé. El Balmung de Bukalla era una espada enorme.",
    ["Both are dagannoth-slaying weapons. I named my weapon in honour of Bukalla."] = "Ambas son armas que matan dagannoth. Le puse a mi arma el nombre de Bukalla.",
    ["Oh, that makes more sense now."] = "Oh, eso tiene más sentido ahora.",
    ["What exactly happened to Bukalla and the Dagannoth king?"] = "¿Qué pasó exactamente con Bukalla y el rey Dagannoth?",
    ["Ah, Akranoth dagnathi, otherwise known as Dagannoth Supreme. It’s not clear if the current Supreme is the same individual or a successor."] = "Ah, Akranoth dagnathi, también conocido como Dagannoth Supremo. No está claro si el Supremo actual es el mismo individuo o un sucesor.",
    ["Either way, the bearer of that title no longer takes the Fremennik lightly."] = "De cualquier manera, el portador de ese título ya no toma al Fremennik a la ligera.",
    ["Bukalla died as a result of the raid, but it’s not clear whether he fell in battle with the Dagannoth king, or as a result of his wounds on the way home."] = "Bukalla murió como resultado del ataque, pero no está claro si cayó en batalla con el rey Dagannoth o como resultado de sus heridas en el camino a casa.",
    ["Neither of their fates really matter though. What is important in this tale is that Bukalla and the Fremennik stood up and fought back against those that would threaten and endanger their people."] = "Sin embargo, ninguno de sus destinos importa realmente. Lo importante de esta historia es que Bukalla y los Fremennik se levantaron y lucharon contra aquellos que amenazaban y ponían en peligro a su pueblo.",
    ["This is heroism, a key value taught to the Fremennik people and a noble one at that."] = "Esto es heroísmo, un valor clave enseñado al pueblo Fremennik y, además, noble.",
    ["I see, it’s not just an exciting story then."] = "Ya veo, entonces no es solo una historia emocionante.",
    ["Indeed. You should reflect upon what you have heard and try to apply it to yourself where you can."] = "De hecho. Debes reflexionar sobre lo que has oído y tratar de aplicarlo a ti mismo siempre que puedas.",
    ["I’ll definitely give it a good think over."] = "Definitivamente lo pensaré bien.",
    ["Were there any other famous Fremennik in the party?"] = "¿Había algún otro Fremennik famoso en el grupo?",
    ["Of course! Perhaps you will have heard some of their names, perhaps not. Their stories are for another day, though."] = "¡Por supuesto! Quizás hayas escuchado algunos de sus nombres, quizás no. Sin embargo, sus historias son para otro día.",
    ["Sorry, I didn’t mean to disturb you. I’ll be going now."] = "Lo siento, no quise molestarte. Me iré ahora.",
    ["Does this needle belong to you?"] = "¿Esta aguja te pertenece?",
    ["Now, how in the world did you come by this? It is, indeed, one of mine. Might I have it back? I could give you something of greater value in return..."] = "Ahora, ¿cómo diablos llegaste a esto? De hecho, es uno de los míos. ¿Puedo recuperarlo? Podría darte algo de mayor valor a cambio...",
    ["Return Koschei's needle to him?"] = "¿Devolverle la aguja a Koschei?",
    ["As promised. This relic is akin to the ones I used to, shall we say, not suffer the penalties of dying. This particular egg is bonded with Daemonheim, back when I had reasons to be involved there, but I no longer have need for it."] = "Como prometí. Esta reliquia es similar a las que solía, digamos, no sufrir la pena de morir. Este huevo en particular está vinculado con Daemonheim, cuando tenía razones para estar involucrado allí, pero ya no lo necesito.",
    ["If you change your mind, you know where to find me."] = "Si cambias de opinión, ya sabes dónde encontrarme.",
    ["Not Right Now"] = "No ahora mismo",
    ["I thought we had developed a friendship... I hope I was not mistaken. Return to me if you change your mind."] = "Pensé que habíamos desarrollado una amistad... Espero no haberme equivocado. Vuelve conmigo si cambias de opinión.",
    ["Accept Quest"] = "Aceptar misión",
    ["You do not meet the requirements to start : 'Children of Mah'."] = "No cumples los requisitos para empezar : 'Hijos de Mah'.",
    ["The chariot driven by a crazy charioteer knows, he loves to keep greedy rats on their toes. While rushing on a path of woes, it crushes alike; friends and foes."] = "El carro conducido por un auriga loco lo sabe, le encanta mantener alerta a las ratas codiciosas. Mientras corre por un camino de aflicciones, aplasta por igual; amigos y enemigos.",
    ["*Khattak will occasionally produce overhead dialogue.*"] = "*Khattak ocasionalmente producirá diálogos generales.*",
    ["Greetings. I am known by Khattak. I need a kind soul to release a valve that is building up pressure in my mind. Could you assist?"] = "Saludos. Soy conocido por Khattak. Necesito un alma bondadosa que libere una válvula que está acumulando presión en mi mente. ¿Podrías ayudar?",
    ["My appreciation. I shall write another stanza depicting your kind deed..."] = "Mi agradecimiento. Escribiré otra estrofa que describa tu amable acto...",
    ["Maybe someone else will cast a rope into this gaping void..."] = "Tal vez alguien más arroje una cuerda a este enorme vacío...",
    ["The teenage son of a good friend of mine is slowly dying. Now it is not the time to let the sands take him from us."] = "El hijo adolescente de un buen amigo mío está muriendo lentamente. Ahora no es el momento de dejar que la arena nos lo quite.",
    ["Sure thing."] = "Claro.",
    ["Do you have [number] [item]? The boy really needs help. ([number] remaining)"] = "¿Tienes [número] [item]? El niño realmente necesita ayuda. ([número] restantes)",
    ["Do you have [number] of [item]? The boy really needs help. ([number] remaining)"] = "¿Tienes [número] de [item]? El niño realmente necesita ayuda. ([número] restantes)",
    ["Number of [item] given to Khattak ([number]/[number])"] = "Número de [item] dado a Khattak ([número]/[número])",
    ["Fantastic, thank you."] = "Fantástico, gracias.",
    ["Good, thank you so much."] = "Bien, muchas gracias.",
    ["The thaumaturge tells us that we need [item]. We didn't think it wise to argue."] = "El taumaturgo nos dice que necesitamos [item]. No nos pareció prudente discutir.",
    ["Right. If this... thaumaturge thinks that a [item] could help, then I guess we should search for [item]."] = "Correcto. Si este... taumaturgo cree que un [item] podría ayudar, entonces supongo que deberíamos buscar a [item].",
    ["I will make the preparations while you are away; is it a reasonable request?"] = "Haré los preparativos mientras no estás; ¿Es una petición razonable?",
    ["Do you have [number] [item]? The boy needs help. ([number] remaining)"] = "¿Tienes [número] [item]? El niño necesita ayuda. ([número] restantes)",
    ["I am grateful. Helping me with the [item 1] and now some [item 2], I appreciate it."] = "Estoy agradecido. Ayudándome con el [item 1] y ahora un poco de [item 2], se lo agradezco.",
    ["Oh no..."] = "Oh, no...",
    ["I am...hopeful. I worry that you have given us hope, only for the sands to snatch it from us."] = "Tengo... esperanzas. Me preocupa que nos hayas dado esperanza, sólo para que la arena nos la arrebate.",
    ["No matter. I will take this brief moment of solace for what it is."] = "No importa. Tomaré este breve momento de consuelo por lo que es.",
    ["A good idea. How else can I help?"] = "Una buena idea. ¿De qué otra manera puedo ayudar?",
    ["We have everything we need. If you still want to help: while we've been caring for the young boy, we've neglected our daily duties."] = "Tenemos todo lo que necesitamos. Si aún quieres ayudar: mientras cuidamos al niño, hemos descuidado nuestras tareas diarias.",
    ["Getting hold of [number] [item] should be sufficient."] = "Conseguir [número] [item] debería ser suficiente.",
    ["I don't have time right now."] = "No tengo tiempo ahora.",
    ["Do you have [number] [item]? ([number] remaining)"] = "¿Tienes [número] [item]? ([número] restantes)",
    ["Do you have [number] of [item]? ([number] remaining)"] = "¿Tienes [número] de [item]? ([número] restantes)",
    ["Yes, I have the [item]. I hope these will do."] = "Sí, tengo el [item]. Espero que esto sirva.",
    ["I am grateful. We all appreciate it."] = "Estoy agradecido. Todos lo apreciamos.",
    ["*When talking to the two Khazard Guards carrying beers in the Fight Arena Bar.*"] = "*Al hablar con los dos Guardias Khazard que llevan cervezas en el bar Fight Arena.*",
    ["*The Khazard Guard at the bar will always have the following dialogue:*"] = "*La Guardia Khazard en el bar siempre tendrá el siguiente diálogo:*",
    ["This guard is singing."] = "Este guardia está cantando.",
    ["Badly."] = "Malo.",
    ["Shoooow mee the waaay to go home!"] = "¡Muéstrame la manera de volver a casa!",
    ["Very badly."] = "Muy mal.",
    ["I'm tired and I wanna go to bed."] = "Estoy cansado y quiero irme a la cama.",
    ["I think that would be a good idea, you need to sleep. And have a bath."] = "Creo que sería una buena idea, necesitas dormir. Y tomar un baño.",
    ["*The Khazard Guard at the table will always have the following dialogue:*"] = "*La Guardia Khazard en la mesa siempre tendrá el siguiente diálogo:*",
    ["Hello. What are you doing here?"] = "Hola. ¿Qué estás haciendo aquí?",
    ["I want the finest wines available to humanity. I want them here, and I want them now."] = "Quiero los mejores vinos disponibles para la humanidad. Los quiero aquí y los quiero ahora.",
    ["Hmmm..."] = "Mmm...",
    ["*When attempting to speak to Khazard Guard (sleeping) in the Fight Arena Bar*"] = "*Al intentar hablar con Khazard Guard (durmiendo) en el Fight Arena Bar*",
    ["I was wondering..."] = "Me preguntaba...",
    ["*sigh*...*yawn*"] = "*suspiro*...*bostezo*",
    ["Really? That's fascinating."] = "¿En serio? Eso es fascinante.",
    ["*SNORE*"] = "*ronquido*",
    ["I see. Well, thanks anyway."] = "Ya veo. Bueno, gracias de todos modos.",
    ["I just do the washing around here."] = "Yo solo lavo la ropa por aquí.",
    ["What can I do for you?"] = "¿Qué puedo hacer por ti?",
    ["I mainly take in washing and make sure it's good and clean for my customers. Times are tough, though. Not everyone can afford such a service and it's affecting my takings."] = "Principalmente me ocupo del lavado y me aseguro de que esté bien y limpio para mis clientes. Sin embargo, los tiempos son difíciles. No todo el mundo puede permitirse ese servicio y eso está afectando a mis ingresos.",
    ["Do you find that very fulfilling?"] = "¿Lo encuentras muy satisfactorio?",
    ["Ah, well, it can be a bit monotonous and the pay isn't good, but I set myself some goals and deliver my washing clean. My customers rarely complain, so I guess I must be doing something right."] = "Ah, bueno, puede ser un poco monótono y la paga no es buena, pero me pongo algunas metas y entrego mi ropa limpia. Mis clientes rara vez se quejan, así que supongo que algo debo estar haciendo bien.",
    ["Either that or they're afraid of you!"] = "¡O eso o te tienen miedo!",
    ["Aha, yes, good one. Many of my customers are pretty important, I'm sure they'd have a word with me if they thought that quality was slipping."] = "Ajá, sí, buena. Muchos de mis clientes son bastante importantes, estoy seguro de que hablarían conmigo si pensaran que la calidad está disminuyendo.",
    ["Do you know someone called Movario?"] = "¿Conoces a alguien llamado Movario?",
    ["Oh, yes, Movario..."] = "Oh, sí, Movario...",
    ["Oh...er, well, sorry, I'm not really supposed to divulge client details. Times are tough enough as it is; I can do without losing customers because of my gossiping!"] = "Oh... bueno, lo siento, se supone que no debo divulgar detalles del cliente. Los tiempos ya son bastante difíciles; ¡Puedo prescindir de perder clientes por culpa de mis chismes!",
    ["*(If the player does not have dirty laundry in inventory:)* Do you have more dirty clothes belonging to Movario I could have?"] = "*(Si el player no tiene ropa sucia en el inventario:)* ¿Tienes más ropa sucia perteneciente a Movario que podría tener?",
    ["You're in luck: here you go, but look after them this time."] = "Estás de suerte: aquí tienes, pero esta vez cuídalos.",
    ["[You're handed some stinky clothes.]"] = "[Te entregan ropa apestosa.]",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["Hello, how are you?"] = "Hola, ¿cómo estás?",
    ["Don't speak to me you insignificant wretch! Die in the name of Khazard!"] = "¡No me hables, miserable insignificante! ¡Muere en nombre de Khazard!",
    ["If I just... stretch... a bit more... I can ALMOST touch the bottom of the oasis!"] = "Si tan sólo... me estiro... un poco más... ¡CASI puedo tocar el fondo del oasis!",
    ["Couldn't you just swim to the bottom?"] = "¿No podrías simplemente nadar hasta el fondo?",
    ["Of course, but that's no fun!"] = "Por supuesto, ¡pero eso no es divertido!",
    ["Yummy!"] = "¡Delicioso!",
    ["Khemu gobbles the steak up in the blink of an eye."] = "Khemu devora el filete en un abrir y cerrar de ojos.",
    ["Khemu! Where are your manners?"] = "¡Khemu! ¿Dónde están tus modales?",
    ["Oops, sorry. Thank you, Player!"] = "Ups, lo siento. ¡Gracias, Player!",
    ["Glad you enjoyed it!"] = "¡Me alegra que lo hayas disfrutado!",
    ["Oh it's you, the [artful dodger/enforcer/Don/swindler]."] = "Oh, eres tú, el [artful dodger/enforcer/Don/swindler].",
    ["Ha! You may not have been on my side, but you certainly earned your title..."] = "¡Ja! Puede que no hayas estado de mi lado, pero ciertamente te ganaste tu título...",
    ["You are now known to others as [Player the Artful Dodger/Player the Enforcer/Don Player/Player the Swindler]!"] = "¡Ahora los demás te conocen como [Player the Artful Dodger/Player the Enforcer/Don Player/Player the Swindler]!",
    ["Look - I don't like you, and I'm guessing you don't like me. I don't regret my actions, but..."] = "Mira, no me gustas y supongo que yo tampoco te agrado a ti. No me arrepiento de mis acciones, pero...",
    ["if you see Ozan, please tell him I'm sorry."] = "si ves a Ozan, por favor dile que lo siento.",
    ["Not happy with my assessment of your character, eh? Well, what sort of low-life scum DO you see yourself as, hmm?"] = "No estoy contento con mi evaluación de tu personaje, ¿eh? Bueno, ¿qué clase de escoria de mala muerte te ves a ti mismo?",
    ["You are now known to others as Player the Artful Dodger!"] = "¡Ahora los demás te conocen como Player, el Artful Dodger!",
    ["Ha! If you say so."] = "¡Ja! Si tú lo dices.",
    ["You are now known to others as Player the Enforcer!"] = "¡Ahora otros te conocen como Player the Enforcer!",
    ["You are now known to others as Don Player!"] = "¡Ahora otros te conocen como Don Player!",
    ["You are now known to others as Player the Swindler!"] = "¡Ahora otros te conocen como Player el Estafador!",
    ["*braaak* Hello, friend. *raaawwwwk*"] = "*braaak* Hola amigo. *raaawwwwww*",
    ["*braaak* Forgot an adventure? Ask the parrot. *raaawwwwk*"] = "*braaak* ¿Olvidaste una aventura? Pregúntale al loro. *raaawwwwww*",
    ["Mention a desert adventure to Khoochak?"] = "¿Mencionar una aventura en el desierto a Khoochak?",
    ["Choose an option:{{anchor"] = "Elige una opción:{{anchor",
    ["Stolen Hearts"] = "Corazones robados",
    ["Diamond in the Rough"] = "Diamante en bruto",
    ["Icthlarin's Little Helper"] = "El pequeño ayudante de Icthlarin",
    ["Missing my Mummy"] = "Extrañando a mi mamá",
    ["The Golem"] = "El Golem",
    ["Spirits of the Elid"] = "Espíritus de los Elid",
    ["Tourist Trap"] = "Trampa para turistas",
    ["Smoking Kills"] = "Fumar mata",
    ["A Tail of Two Cats"] = "Una cola de dos gatos",
    ["Enakhra's Lament"] = "El lamento de Enakhra",
    ["Dealing with Scabaras"] = "Lidiando con Scabaras",
    ["Do No Evil"] = "No hacer el mal",
    ["Crocodile Tears"] = "Crocodile Lágrimas",
    ["Our Man in the North"] = "Nuestro hombre en el norte",
    ["Phite Club"] = "Club de Fito",
    ["Pharaoh's Folly"] = "La locura del faraón",
    ["*braaak* Get lost, bucko. *raawwwwk*"] = "*braaak* Piérdete, muchacho. *raawwwwww*",
    ["Stumbled across kidnapping!"] = "¡Me encontré con un secuestro!",
    ["Broke into my palace!"] = "¡Entró en mi palacio!",
    ["Stole my lucky diamond!"] = "¡Me robé el diamante de la suerte!",
    ["Killed the Emir! Killed the Emir!"] = "¡Mató al Emir! ¡Mató al Emir!",
    ["Naughty naughty naughty!"] = "¡Travieso, travieso, travieso!",
    ["Ask about another adventure?"] = "¿Preguntar por otra aventura?",
    ["Stole my diamond again!"] = "¡Me robé el diamante otra vez!",
    ["Played around in Kalphite poo!"] = "¡Jugué con caca de Kalphite!",
    ["Saved the Prince! Saved the Prince!"] = "¡Salvó al Príncipe! ¡Salvó al Príncipe!",
    ["Old Khoochak reckons...*braaak*"] = "El viejo Khoochak calcula...*braaak*",
    ["...that you shoulda drowned in quicksand!"] = "... ¡que deberías haberte ahogado en arenas movedizas!",
    ["Sophanem is full of plagues!"] = "¡Sophanem está lleno de plagas!",
    ["Talked to wanderer! Talked to sphinx!"] = "¡Hablé con el vagabundo! ¡Hablé con la esfinge!",
    ["Raided a tomb! Defiled a corpse!"] = "¡Asaltó una tumba! ¡Profanado un cadáver!",
    ["Mind control! Mind control!"] = "¡Control mental! ¡Control mental!",
    ["Like that'll hold up in court!"] = "¡Como si eso se mantuviera en la corte!",
    ["Wanderer was Amascut. Fooled again! Fooled again!"] = "Wanderer era Amascut. ¡Engañado de nuevo! ¡Engañado de nuevo!",
    ["Raided a pyramid!"] = "¡Asaltó una pirámide!",
    ["But did good for a change!"] = "¡Pero estuvo bien para variar!",
    ["Restored the tomb! Rebuilt the mummy!"] = "¡Restaurado la tumba! ¡Reconstruyó la momia!",
    ["Bet you still stole something, though!"] = "¡Apuesto a que aun así robaste algo!",
    ["Mummy too wrapped up in things to care."] = "Mamá está demasiado absorta en cosas como para que le importe.",
    ["Went to Pollnivneach!"] = "¡Fui a Pollnivneach!",
    ["Became a thief! Started a gang war!"] = "¡Conviértete en ladrón! ¡Comenzó una guerra de pandillas!",
    ["Beard and a blackjack!"] = "¡Barba y cachiporra!",
    ["Morrisanes are scammers!"] = "¡Los morrisanos son unos estafadores!",
    ["Found a demon dimension!"] = "¡Encontré una dimensión demoníaca!",
    ["Repaired a damaged golem!"] = "¡Reparamos un golem dañado!",
    ["Washed its brain! Washed its brain!"] = "¡Le lavó el cerebro! ¡Se lavó el cerebro!",
    ["Bet you broke it in the first place!"] = "¡Apuesto a que lo rompiste en primer lugar!",
    ["Did you go back to steal the gems?"] = "¿Volviste a robar las gemas?",
    ["Drought in Nardah! Wayward Nardah!"] = "¡Sequía en Nardah! ¡Nardah díscolo!",
    ["Restored shrine to Elidinis!"] = "¡Santuario restaurado a Elidinis!",
    ["Genie in a bottle! Rubbed it right way!"] = "¡Genio en una botella! ¡Lo froté de la manera correcta!",
    ["Turned the water back on!"] = "¡Volví a abrir el agua!",
    ["You're a sole-less golem killer!"] = "¡Eres un asesino de golems sin suela!",
    ["Crying lady at Shantay Pass!"] = "¡Señora llorando en Shantay Pass!",
    ["Her daughter taken as slave!"] = "¡Su hija tomada como esclava!",
    ["Ana in a barrel! Ana in a barrel!"] = "¡Ana en un barril! ¡Ana en un barril!",
    ["A mine full of tourist slaves."] = "Una mina llena de turistas esclavos.",
    ["But you only saved one, lazybones!"] = "¡Pero solo salvasteis a uno, vagos!",
    ["Evil Dave and his numbskull friends!"] = "¡Evil Dave y sus amigos tontos!",
    ["Summoned a demon: Agrith Naar!"] = "Invocó a un demonio: ¡Agrith Naar!",
    ["Silverlight! Darklight!"] = "¡Luz plateada! ¡Luz oscura!",
    ["You're a heathen demon summoner!"] = "¡Eres un invocador de demonios paganos!",
    ["Sumona's twisted. Save her sister!"] = "Sumona está retorcido. ¡Salva a su hermana!",
    ["But she just wants you dead!"] = "¡Pero ella sólo te quiere muerto!",
    ["Big smoking dungeon!"] = "¡Gran mazmorra humeante!",
    ["Banshee mistress! Banshee mistress!"] = "¡Amante alma en pena! ¡Ama alma en pena!",
    ["Hope she gets you next time!"] = "¡Espero que te atrape la próxima vez!",
    ["Bob the Cat, stuck up a tree!"] = "¡Bob el gato, atascado en un árbol!",
    ["Kissing N-e-i-t-e!"] = "¡Besando a N-e-i-t-e!",
    ["Took Bob to Sphinx! Cleaned out Unferth!"] = "¡Llevó Bob a Sphinx! ¡Limpiado Unferth!",
    ["Robert the Strong! Robert the Strong!"] = "¡Robert el Fuerte! ¡Roberto el Fuerte!",
    ["Spray cats with water! Stinking cats!"] = "¡Rocía a los gatos con agua! ¡Gatos apestosos!",
    ["Build a statue, find a temple!"] = "¡Construye una estatua, encuentra un templo!",
    ["Two Mahjarrat in a stalemate!"] = "¡Dos Mahjarrat en un punto muerto!",
    ["You let 'em both free, stupid!"] = "¡Los dejaste a ambos libres, estúpido!",
    ["You've got a face like a camel!"] = "¡Tienes cara de camello!",
    ["Osman's agents! Maisa and Kaleef!"] = "¡Agentes de Osman! Maisa y Kaleef!",
    ["Scabarites under Sophanem!"] = "¡Scabaritas bajo Sophanem!",
    ["You killed their giant scarab!"] = "¡Mataste a su escarabajo gigante!",
    ["Stick Keris where the sun don't shine!"] = "¡Pega a Keris donde el sol no brilla!",
    ["Rediscovered Ullek!"] = "¡Ullek redescubierto!",
    ["Broke into the city!"] = "¡Irrumpió en la ciudad!",
    ["Killed loads of Scabarites!"] = "¡Mataste a muchos Scabarites!",
    ["That priest's a nutter!"] = "¡Ese cura está loco!",
    ["Killed four beasties! Stole their diamonds!"] = "¡Mataste a cuatro bestias! ¡Les robaron los diamantes!",
    ["Freed a dangerous prisoner!"] = "¡Liberó a un prisionero peligroso!",
    ["All for a new spellbook!"] = "¡Todo por un nuevo libro de hechizos!",
    ["Talking of Ancients..."] = "Hablando de Antiguos...",
    ["...you're getting on a bit!"] = "...¡estás mejorando un poco!",
    ["Playing with monkeys! Flinging choc-ices!"] = "¡Jugando con monos! ¡Lanzando chocolates!",
    ["Built a colony! Monkey massacre!"] = "¡Construiste una colonia! ¡Masacre de monos!",
    ["Hear no evil, see no evil, speak no evil!"] = "¡No escuches el mal, no veas el mal, no hables el mal!",
    ["But you smell pretty evil!"] = "¡Pero hueles bastante mal!",
    ["Flew to Menaphos! On a carpet!"] = "¡Volé a Menaphos! ¡Sobre una alfombra!",
    ["Met some nasty people."] = "Conocí gente desagradable.",
    ["Jack of Spades! Jack of Spades!"] = "¡Jota de espadas! ¡Jota de espadas!",
    ["Ozan's worse than the lot of 'em."] = "Ozan es peor que todos ellos.",
    ["Met with Crondis, greedy Crondis."] = "Me reuní con Crondis, el codicioso Crondis.",
    ["Brought her a croc ice!"] = "¡Le traje un helado de cocodrilo!",
    ["That joke got old quick! Bored now."] = "¡Ese chiste envejeció rápidamente! Aburrido ahora.",
    ["She spat something up! Disgusting, gross - kill it with fire!"] = "¡Escupió algo! Asqueroso, asqueroso: ¡mátalo con fuego!",
    ["I'm talking about you now."] = "Estoy hablando de ti ahora.",
    ["Made noise in a library, you heathen! Stole a book!"] = "¡Hiciste ruido en una biblioteca, pagano! ¡Robé un libro!",
    ["Jabari unhappy! Jabari assassin!"] = "¡Jabari infeliz! ¡Asesino Jabari!",
    ["Osman is Pharaoh! Osman is traitor!"] = "¡Osman es el faraón! ¡Osman es un traidor!",
    ["Nothing bad to say about you for once."] = "Por una vez, no hay nada malo que decir sobre ti.",
    ["Other than you stink."] = "Aparte de que apestas.",
    ["Revolution! Revolution!"] = "¡Revolución! ¡Revolución!",
    ["Workers, sailors, merchants, guards!"] = "¡Trabajadores, marineros, comerciantes, guardias!",
    ["Pharaoh is dead! Long live the Pharaoh!"] = "¡El faraón ha muerto! ¡Viva el Faraón!",
    ["Amascut has daddy issues!"] = "¡Amascut tiene problemas con papá!",
    ["Bug attack!"] = "¡Ataque de error!",
    ["Found Scabaras, finally!"] = "¡Por fin encontré a Scabaras!",
    ["Osman's arrogant! Who knew? Tried to kill a god!"] = "¡Osman es arrogante! ¿Quién lo sabía? ¡Intentó matar a un dios!",
    ["Amascut's angry! Attack coming!"] = "¡Amascut está enojado! ¡Attack viene!",
    ["Nice knowing you..."] = "Encantado de conocerte...",
    ["Not!"] = "¡No!",
    ["Osman's angry! Threw you in the tombs."] = "¡Osman está enojado! Os arrojé a las tumbas.",
    ["Escaped. Found Ozan. Planned a coup. Again."] = "Escapó. Encontrado Ozan. Planeó un golpe de estado. De nuevo.",
    ["Objection! The Pharaoh's on trial!"] = "¡Objeción! ¡El faraón está siendo juzgado!",
    ["Leela's in charge. See how long this one lasts!"] = "Leela está a cargo. ¡Mira cuánto dura este!",
    ["Amascut's coming! Amascut's coming!"] = "¡Amascut viene! ¡Amascut viene!",
    ["Gods get together. Find the tomb. Find the bau!"] = "Los dioses se juntan. Encuentra la tumba. ¡Encuentra el bau!",
    ["Soul beacon got dirty. Fixed now."] = "La baliza del alma se ensució. Corregido ahora.",
    ["Fight! Fight! Fight! Meow!"] = "¡Lucha! ¡Lucha! ¡Lucha! ¡Miau!",
    ["She kicked the puppy, boo!"] = "¡Le dio una patada al cachorro, abucheo!",
    ["He got better."] = "Mejoró.",
    ["And they all live happily ever after!"] = "¡Y todos viven felices para siempre!",
    ["Ooooh, heeellooo! Anyshing a bright dwarf like me can help you with?"] = "¡Ooooh, holahola! ¿En qué te puede ayudar un enano brillante como yo?",
    ["The only thing you can help me with is finding the nearest place to get a drink, I think..."] = "Lo único en lo que puedes ayudarme es en encontrar el lugar más cercano para tomar una copa, creo...",
    ["That ish shimple! Help yourshelf to the dwarvern shtout! I mean dwarfen! I mean... I'm not shure what I mean."] = "¡Eso es shimple! ¡Ayúdate a luchar contra los enanos! ¡Quiero decir enano! Quiero decir... no estoy seguro de lo que quiero decir.",
    ["Hello Player, what can I do for you today?"] = "Hola Player, ¿qué puedo hacer por ti hoy?",
    ["Talk about active equipment upgrade task."] = "Hable sobre la tarea de actualización de equipo activo.",
    ["I don't have any upgrade tasks available for you at the moment."] = "No tengo ninguna tarea de actualización disponible para usted en este momento.",
    ["[You need level [number] Necromancy for the next upgrade task.]"] = "[Necesita el nivel [número] Necromancy para la siguiente tarea de actualización.]",
    ["[You need level [number] Necromancy, and must have completed 'The Spirit of War' for the next upgrade task.]"] = "[Necesita el nivel [número] Necromancy y debe haber completado 'El Spirit de War' para la siguiente tarea de actualización.]",
    ["Which upgrade would you like to work on?"] = "¿En qué actualización te gustaría trabajar?",
    ["Tier 70"] = "Nivel 70",
    ["Tier 70 (power)"] = "Nivel 70 (potencia)",
    ["Tier 80"] = "Nivel 80",
    ["Tier 80 (power)"] = "Nivel 80 (potencia)",
    ["Tier 90"] = "Nivel 90",
    ["Tier 90 (power)"] = "Nivel 90 (potencia)",
    ["Talk about equipment upgrades."] = "Hable sobre actualizaciones de equipos.",
    ["I'd like to know more about equipment upgrades."] = "Me gustaría saber más sobre las actualizaciones de equipos.",
    ["Equipment upgrades... What would you like to know about them?"] = "Mejoras de equipos... ¿Qué te gustaría saber sobre ellas?",
    ["How can I learn more upgrades?"] = "¿Cómo puedo obtener más actualizaciones?",
    ["How can I learn more equipment upgrades?"] = "¿Cómo puedo obtener más actualizaciones de equipo?",
    ["As you grow more powerful as a necromancer, just return to me and ask about equipment upgrade tasks."] = "A medida que te vuelvas más poderoso como nigromante, regresa conmigo y pregúntame sobre las tareas de mejora del equipo.",
    ["If you haven't grown much since completing your last task, I won't have anything more for you to do."] = "Si no has crecido mucho desde que completaste tu última tarea, no tendré nada más que hacer.",
    ["How many tasks are there?"] = "¿Cuántas tareas hay?",
    ["Hmm... I can teach you how to upgrade your necromancer's equipment from tier 20, all the way up to tier 90."] = "Hmm... Puedo enseñarte cómo mejorar el equipo de tu nigromante desde el nivel 20 hasta el nivel 90.",
    ["Once you've reached tier 70 and above, I can also teach you how to craft power armour... So that would make for a total of 10 tasks altogether!"] = "Una vez que hayas alcanzado el nivel 70 y superior, también puedo enseñarte cómo fabricar servoarmaduras... ¡Eso daría un total de 10 tareas en total!",
    ["I've already taught you everything there is to know!"] = "¡Ya te he enseñado todo lo que hay que saber!",
    ["How can I apply the upgrades I've learned?"] = "¿Cómo puedo aplicar las actualizaciones que he aprendido?",
    ["How can I apply the equipment upgrades that I've learned to my necromancer's equipment?"] = "¿Cómo puedo aplicar las mejoras de equipo que aprendí al equipo de mi nigromante?",
    ["It's simple. You'll just want to take your necromancer's equipment to my soul forge that's just over there. It will tell you what materials you'll need."] = "Es simple. Sólo querrás llevar el equipo de tu nigromante a mi forja de almas que está justo por allí. Le dirá qué materiales necesitará.",
    ["Do you need me to give you directions to the soul forge?"] = "¿Necesitas que te dé indicaciones para llegar a Soul Forge?",
    ["Would you like directions to the soul forge?"] = "¿Quieres indicaciones para llegar a Soul Forge?",
    ["No thanks, I can find it myself."] = "No gracias, puedo encontrarlo yo mismo.",
    ["Where can I get the materials needed?"] = "¿Dónde puedo conseguir los materiales necesarios?",
    ["Where can I get the materials needed to upgrade my necromancer's equipment?"] = "¿Dónde puedo conseguir los materiales necesarios para mejorar el equipo de mi nigromante?",
    ["The main things you'll need are ensouled materials - cloth, thread, and bars. These come in lesser, normal, and greater variants."] = "Lo principal que necesitarás son materiales con alma: tela, hilo y barras. Estos vienen en variantes menores, normales y mayores.",
    ["As I taught you, you'll be able to get ahold of these by performing ensoul rituals on various items from the overworld, to imbue them with necromantic energy."] = "Como te enseñé, podrás conseguirlos realizando rituales de alma en varios objetos del supramundo, para imbuirlos de energía nigromántica.",
    ["It's worth mentioning that to ensoul bars, you'll first need to smelt a variety of metals together in a furnace."] = "Vale la pena mencionar que para darle vida a las barras, primero necesitarás fundir una variedad de metales juntos en un horno.",
    ["Some upgrades may also need necromancy runes, which you can get by runecrafting impure essence to the northeast of Um, or through trading with other players."] = "Algunas mejoras también pueden necesitar runas de nigromancia, que puedes obtener elaborando runas con esencia impura al noreste de Um o intercambiando con otros jugadores.",
    ["What about a Hermodic plate?"] = "¿Qué tal un plato hermódico?",
    ["Ah yes, a Hermodic plate. You'll only need those for the higher tiered upgrades - defeating Hermod should get you some."] = "Ah, sí, un plato hermódico. Solo los necesitarás para las actualizaciones de niveles superiores; derrotar a Hermod debería conseguir algunas.",
    ["Show me the hard Underworld tasks I can do."] = "Muéstrame las tareas difíciles de Underworld que puedo hacer.",
    ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
    ["I've completed all the tasks in the hard Underworld task set."] = "He completado todas las tareas del conjunto de tareas difíciles de Underworld.",
    ["Well done Player, I've kept some rewards aside for you."] = "Bien hecho Player, he reservado algunas recompensas para ti.",
    ["Lupe has also agreed to provide you with a daily supply of dragon bones, greater ghostly ink and greater ritual candles in recognition of your efforts. She's also started selling a small amount of buckets of slime."] = "Lupe también acordó proporcionarte un suministro diario de huesos de dragón, tinta fantasmal mayor y velas rituales mayores en reconocimiento a tus esfuerzos. También empezó a vender una pequeña cantidad de cubos de baba.",
    ["I'm afraid you don't have enough backpack space to claim all your rewards. Speak to me again when you have 2 spaces."] = "Me temo que no tienes suficiente espacio backpack para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 2 espacios.",
    ["[You are given some rewards for completing the hard Underworld task set!]"] = "[¡Recibirás algunas recompensas por completar el difícil conjunto de tareas de Underworld!]",
    ["There you go, looks like that's everything."] = "Ahí lo tienes, parece que eso es todo.",
    ["You don't have any rewards to claim!"] = "¡No tienes ninguna recompensa que reclamar!",
    ["I lost the Underworld Grimoire 3 you gave me..."] = "Perdí el Underworld Grimoire 3 que me diste...",
    ["You don't seem to have any room for a new one, come back to me when you do."] = "Parece que no tienes espacio para uno nuevo, vuelve conmigo cuando lo tengas.",
    ["Lucky for you I have a spare. Take better care of this one."] = "Por suerte para ti, tengo uno de repuesto. Cuida mejor este.",
    ["[You're handed another Underworld Grimoire 3.]"] = "[Te entregan otro Underworld Grimoire 3.]",
    ["Ask about the Task System."] = "Pregunta por el Sistema de Tareas.",
    ["Tell me about the Task System."] = "Cuéntame sobre el sistema de tareas.",
    ["For completing the Underworld set, you are presented with the Underworld Grimoire."] = "Por completar el conjunto Underworld, se te presenta el Grimorio de Underworld.",
    ["This book will become increasingly useful with each difficulty level of the set that you complete."] = "Este libro será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
    ["[You may also see what rewards a set item provides by hovering over the rewards icon on its corresponding achievement in the Achievements interface.]"] = "[También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de recompensas en su logro correspondiente en la interfaz de Logros.]",
    ["You need to complete all of the tasks in the set of a particular difficulty, then you can claim your reward. Some of the Underworld tasks are straightforward, some will require skill levels, and some might require quests to be started or completed."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. Algunas de las tareas de Underworld son sencillas, algunas requerirán skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["To claim the Underworld set reward, speak to Icthlarin, Frank, Crunchy or myself."] = "Para reclamar la recompensa del conjunto Underworld, habla con Icthlarin, Frank, Crunchy o conmigo mismo.",
    ["Underworld Grimoire 1"] = "Grimorio del inframundo 1",
    ["You'll need space in your inventory."] = "Necesitarás espacio en tu inventario.",
    ["Underworld Grimoire 1? Yes, but I'm afraid it would cost you 5,000 coins."] = "¿Grimorio del inframundo 1? Sí, pero me temo que te costaría 5.000 coins.",
    ["Purchase another for 5,000 coins?"] = "¿Comprar otro por 5.000 coins?",
    ["It doesn't look like you can afford it right now, though. Come back to me when you can."] = "Sin embargo, no parece que puedas permitírtelo en este momento. Vuelve conmigo cuando puedas.",
    ["[You're handed another Underworld Grimoire 1.]"] = "[Te entregan otro Grimorio 1 de Underworld.]",
    ["Underworld Grimoire 2"] = "Grimorio del inframundo 2",
    ["Underworld Grimoire 2? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Grimorio del inframundo 2? Sí, pero me temo que te costaría 10.000 coins.",
    ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
    ["[You're handed another Underworld Grimoire 2.]"] = "[Te entregan otro Underworld Grimoire 2.]",
    ["Underworld Grimoire 3"] = "Grimorio del inframundo 3",
    ["Underworld Grimoire 3? Yes, but I'm afraid it would cost you 25,000 coins."] = "¿Grimorio del inframundo 3? Sí, pero me temo que te costaría 25.000 coins.",
    ["Purchase another for 25,000 coins?"] = "¿Comprar otro por 25.000 coins?",
    ["Underworld Grimoire 4"] = "Grimorio del inframundo 4",
    ["Underworld Grimoire 4? Yes, but I'm afraid it would cost you 50,000 coins."] = "¿Grimorio del inframundo 4? Sí, pero me temo que te costaría 50.000 coins.",
    ["Purchase another for 505,000 coins?"] = "¿Comprar otro por 505.000 coins?",
    ["[You're handed another Underworld Grimoire 4.]"] = "[Te entregan otro Underworld Grimoire 4.]",
    ["Choose an Option:"] = "Elige una opción:",
    ["Talk about Kili."] = "Habla de Kili.",
    ["Can you tell me a bit about yourself?"] = "¿Puedes contarme un poco sobre ti?",
    ["Ha! There's not much to know."] = "¡Ja! No hay mucho que saber.",
    ["Well, er, what do you like about Um?"] = "Bueno, ejem, ¿qué es lo que te gusta de Um?",
    ["It's nice that I get to be the sole blacksmith..."] = "Es bueno poder ser el único herrero...",
    ["Soul blacksmith?"] = "¿Herrero del alma?",
    ["As I was saying, it's nice that I get to be the only blacksmith here in the city - I get to provide for all sorts of people that pass through here!"] = "Como decía, es bueno poder ser el único herrero aquí en la ciudad. ¡Puedo atender a todo tipo de personas que pasan por aquí!",
    ["And Thalmund, ever the traveller, gets to explore all over the Underworld."] = "Y Thalmund, siempre el viajero, puede explorar todo el inframundo.",
    ["Have you ever thought of passing on?"] = "¿Alguna vez has pensado en fallecer?",
    ["Thalmund and I talk about it every now and again. Um has been our home for so long, that makes it hard to leave."] = "Thalmund y yo hablamos de ello de vez en cuando. Um ha sido nuestro hogar durante tanto tiempo que hace que sea difícil salir.",
    ["I'm sure we'll pass over at some point, but not just yet."] = "Estoy seguro de que lo pasaremos por alto en algún momento, pero no todavía.",
    ["Ask when Thalmund is visiting."] = "Pregunte cuando Thalmund esté de visita.",
    ["When is Thalmund next visiting?"] = "¿Cuándo será la próxima visita de Thalmund?",
    ["He'll be popping by in [number] days."] = "Pasará por aquí en los días [número].",
    ["He'll be popping by in 1 day."] = "Llegará en 1 día.",
    ["He's here today, just over there with his cart."] = "Hoy está aquí, justo por allá con su carrito.",
    ["Make sure to visit! He always has a good stock of wares from his travels across the Underworld."] = "¡Asegúrate de visitarlo! Siempre tiene un buen stock de mercancías de sus viajes por el inframundo.",
    ["What can I help you with?"] = "¿En qué puedo ayudarte?",
    ["I'd like to learn more equipment upgrades, please!"] = "¡Me gustaría conocer más actualizaciones de equipos, por favor!",
    ["Let's get started then! The next step is to learn the tier 30 upgrade."] = "¡Empecemos entonces! El siguiente paso es aprender la actualización de nivel 30.",
    ["What's the maximum tier I can upgrade my equipment to?"] = "¿Cuál es el nivel máximo al que puedo actualizar mi equipo?",
    ["You can upgrade it every 10 tiers until it's tier 90. For tiers 70, 80, and 90 I can also give you the option of power armour, or the standard tank armour."] = "Puedes actualizarlo cada 10 niveles hasta que sea el nivel 90. Para los niveles 70, 80 y 90 también puedo darte la opción de servoarmadura o armadura de tanque estándar.",
    ["But let's not get ahead of ourselves just yet!"] = "¡Pero no nos adelantemos todavía!",
    ["Right, so where were we... Tier 30."] = "Bien, entonces, ¿dónde estábamos?... Nivel 30.",
    ["Similar to when I taught you the first upgrade, I'll need you to take this soul urn and fill it with some souls."] = "Al igual que cuando te enseñé la primera actualización, necesitaré que tomes esta urna de almas y la llenes con algunas almas.",
    ["This urn will only accept souls from killing trolls using necromancy, or completing lesser communion rituals. I need 25 troll souls, or 3 lesser communion souls."] = "Esta urna solo aceptará almas provenientes de matar trolls usando nigromancia o completando rituales de comunión menores. Necesito 25 almas troll, o 3 almas de comunión menor.",
    ["Ah, it looks like you don't have space for the soul urn. Come back when you do."] = "Ah, parece que no tienes espacio para la urna del alma. Vuelve cuando lo hagas.",
    ["Kili gives you a soul urn."] = "Kili te regala una urna para el alma.",
    ["Easy peasy. Let me just find a pen and paper to write this down..."] = "Fácil. Déjame buscar papel y lápiz para escribir esto...",
    ["Way ahead of you! I've already noted it down on a list so you can easily keep track of what's needed."] = "¡Muy por delante de ti! Ya lo he anotado en una lista para que puedas realizar un seguimiento de lo que se necesita fácilmente.",
    ["Ah, it looks like you don't have space for the equipment upgrade task list. Come back when you do."] = "Ah, parece que no tienes espacio para la lista de tareas de actualización de equipo. Vuelve cuando lo hagas.",
    ["Kili gives you an equipment upgrade task list."] = "Kili le ofrece una lista de tareas de actualización de equipos.",
    ["Nevermind then! I'll go and get those souls for you."] = "¡No importa entonces! Iré a buscar esas almas para ti.",
    ["**Select an Option**"] = "**Seleccione una opción**",
    ["Ask about your current task."] = "Pregunta sobre tu tarea actual.",
    ["I need to reclaim my equipment upgrade task list."] = "Necesito recuperar mi lista de tareas de actualización de equipo.",
    ["I can replace it for you, but you'll need to come back when you have a free space in your backpack."] = "Puedo reemplazarlo por ti, pero tendrás que regresar cuando tengas espacio libre en tu backpack.",
    ["Kili hands you a new equipment upgrade task list."] = "Kili le entrega una nueva lista de tareas de actualización de equipos.",
    ["I need to reclaim my soul urn."] = "Necesito recuperar la urna de mi alma.",
    ["Kili hands you a new soul urn."] = "Kili te entrega una nueva urna para el alma.",
    ["What do I need to do again?"] = "¿Qué debo hacer de nuevo?",
    ["Don't you have the list I gave you?"] = "¿No tienes la lista que te di?",
    ["Well, yes, but I prefer the human interaction."] = "Bueno, sí, pero prefiero la interacción humana.",
    ["Er, human-dwarf-ghost interaction."] = "Er, interacción humano-enano-fantasma.",
    ["Alright, well, I just need you to bring me some souls in that soul urn I gave you."] = "Muy bien, solo necesito que me traigas algunas almas en esa urna de almas que te di.",
    ["The urn is modified to only accept souls from killing trolls using necromancy, or completing lesser communion rituals. I need 25 troll souls, or 3 lesser communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar trolls usando nigromancia o completando rituales de comunión menores. Necesito 25 almas troll, o 3 almas de comunión menor.",
    ["Ok! I'll be off again then."] = "¡Vale! Entonces me iré de nuevo.",
    ["I filled up the soul urn!"] = "¡Lléne la urna del alma!",
    ["Great!"] = "¡Genial!",
    ["Kili takes the soul urn."] = "Kili toma la urna del alma.",
    ["So, er, what now?"] = "Entonces, eh, ¿y ahora qué?",
    ["More or less the same as the first upgrade."] = "Más o menos igual que la primera actualización.",
    ["Just follow me over to the soul forge and I'll teach you what you need to know..."] = "Sígueme hasta Soul Forge y te enseñaré lo que necesitas saber...",
    ["Kili imbues her forge with energy from the soul urn. She then explains the tier 30 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma. Luego explica con gran profundidad el proceso de actualización al nivel 30.",
    ["...You'll want to hold the fabric this way around, that way you won't lose a finger..."] = "...Querrás sujetar la tela de esta manera, así no perderás ni un dedo...",
    ["You take notes, ensuring you won't forget anything."] = "Toma notas, asegurándote de no olvidar nada.",
    ["... And that should be everything. Easy as redberry pie!"] = "... Y eso debería ser todo. ¡Tan fácil como pastel de frutos rojos!",
    ["Ah, there's nothing to worry about! All you need to remember is to gather the ensouled items required for your upgrade, and then return to the soul forge to perform it."] = "¡Ah, no hay nada de qué preocuparse! Todo lo que necesitas recordar es reunir los elementos con alma necesarios para tu actualización y luego regresar a la forja de almas para realizarla.",
    ["Come and check in with me whenever you want to learn the next upgrade!"] = "¡Ven y consúltame cuando quieras conocer la próxima actualización!",
    ["Congratulations! You have completed: 'Kili's Knowledge I' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 30 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento I de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 30 de Kili.",
    ["Cancel your current task."] = "Cancela tu tarea actual.",
    ["Are you sure you want to stop working on your current upgrade task?"] = "¿Está seguro de que desea dejar de trabajar en su tarea de actualización actual?",
    ["Yes, I want to stop working on my current upgrade task."] = "Sí, quiero dejar de trabajar en mi tarea de actualización actual.",
    ["No problem. You can come back anytime to work on a new task."] = "No hay problema. Puede volver en cualquier momento para trabajar en una nueva tarea.",
    ["No, I want to continue working on my current upgrade task."] = "No, quiero seguir trabajando en mi tarea de actualización actual.",
    ["Great. You know where to find me if you need any help."] = "Genial. Ya sabes dónde encontrarme si necesitas ayuda.",
    ["Ok, time to teach you tier 40!"] = "Ok, ¡es hora de enseñarte el nivel 40!",
    ["As before, you'll need to go and fill this soul urn up with some souls."] = "Como antes, tendrás que ir y llenar esta urna de almas con algunas almas.",
    ["This time, the urn will only accept souls from killing any undead creatures using necromancy, or completing lesser communion rituals. I need 50 undead souls, or 5 lesser communion souls."] = "Esta vez, la urna solo aceptará almas provenientes de matar criaturas no muertas usando nigromancia o completando rituales de comunión menores. Necesito 50 almas de no-muertos o 5 almas de comunión menor.",
    ["Also, I'd like a meat pie."] = "Además, me gustaría un pastel de carne.",
    ["A meat pie?"] = "¿Un pastel de carne?",
    ["A meat pie."] = "Un pastel de carne.",
    ["Not that there's anything wrong with a meat pie, but why not a redberry pie?"] = "No es que haya nada malo con un pastel de carne, pero ¿por qué no un pastel de frutos rojos?",
    ["Well, I don't want to go diving in head first."] = "Bueno, no quiero lanzarme de cabeza.",
    ["It's been so long since I've had any sort of pie, so I'll start off by dipping my toes in the water."] = "Ha pasado mucho tiempo desde que comí algún tipo de pastel, así que comenzaré sumergiendo los dedos de los pies en el agua.",
    ["Right. And this will help upgrade my equipment how, exactly?"] = "Correcto. ¿Y esto ayudará a mejorar mi equipo, cómo exactamente?",
    ["Everyone needs a bit of sustenance, don't they? Even ghosts."] = "Todo el mundo necesita un poco de sustento, ¿no? Incluso fantasmas.",
    ["Moving on. Here's the task list for you."] = "Continuando. Aquí está la lista de tareas para usted.",
    ["Oh, and one last thing. Only bring me what I need once you have everything, rather than in dribs and drabs. We like to keep our home tidy, and Thalmund gets grumpy when the living room is full of items from adventurers."] = "Ah, y una última cosa. Sólo tráeme lo que necesito una vez que lo tengas todo, en lugar de poco a poco. Nos gusta mantener nuestra casa ordenada y Thalmund se pone de mal humor cuando la sala está llena de objetos de aventureros.",
    ["Noted. I guess I'll go get those souls and that pie, then."] = "Anotado. Supongo que entonces iré a buscar esas almas y ese pastel.",
    ["Don't you have that list I gave you?"] = "¿No tienes esa lista que te di?",
    ["Well, yes, but I guess I just wanted to see your face."] = "Bueno, sí, pero supongo que solo quería ver tu cara.",
    ["Er, well, I just need you to bring me some souls in that soul urn I gave you."] = "Er, bueno, solo necesito que me traigas algunas almas en esa urna de almas que te di.",
    ["The urn is modified to only accept souls from killing any undead creatures using necromancy, or completing lesser communion rituals. I need 50 undead souls, or 5 lesser communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar criaturas no muertas usando nigromancia o completando rituales de comunión menores. Necesito 50 almas de no-muertos o 5 almas de comunión menor.",
    ["Oh, and a meat pie!"] = "¡Ah, y un pastel de carne!",
    ["Ok! Goodbye then."] = "¡Vale! Adiós entonces.",
    ["I've got the full soul urn and that meat pie for you."] = "Tengo la urna de alma llena y ese pastel de carne para ti.",
    ["Lovely stuff."] = "Cosas preciosas.",
    ["Kili takes the meat pie and the soul urn."] = "Kili se lleva el pastel de carne y la urna del alma.",
    ["Kili chows down on the meat pie."] = "Kili come el pastel de carne.",
    ["How was it?"] = "¿Cómo estuvo?",
    ["A good first choice, I'd say. You can't go wrong with the rich flavours of the meat, combined with the milder flaky crust."] = "Una buena primera opción, diría yo. No te puedes equivocar con los ricos sabores de la carne, combinados con la corteza hojaldrada más suave.",
    ["Now, time to teach you the upgrade!"] = "¡Ahora es el momento de enseñarte la actualización!",
    ["Kili imbues her forge with energy from the soul urn and explains the tier 40 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 40 con gran profundidad.",
    ["Her hands shine with greasy meat drippings."] = "Sus manos brillan con la grasa de la carne.",
    ["...You'll want to sew the thread in this direction, so you don't poke an eye out..."] = "...Querrás coser el hilo en esta dirección, para no sacar un ojo...",
    ["...And that's it! There's a little more work required, but nothing too challenging."] = "...¡Y listo! Se requiere un poco más de trabajo, pero nada demasiado desafiante.",
    ["Shouldn't be much harder than the last upgrade."] = "No debería ser mucho más difícil que la última actualización.",
    ["Come back and let me know when you're ready to learn tier 50."] = "Vuelve y avísame cuando estés listo para aprender el nivel 50.",
    ["Congratulations! You have completed: 'Kili's Knowledge II' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 40 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento II de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 40 de Kili.",
    ["Will do!"] = "¡Lo haré!",
    ["So, now for tier 50."] = "Entonces, ahora para el nivel 50.",
    ["You know the drill - I need you to gather some souls in this soul urn."] = "Ya conoces el procedimiento: necesito que reúnas algunas almas en esta urna de almas.",
    ["The urn will only accept souls from killing demons using necromancy, or completing lesser communion rituals. I need 75 demon souls, or 10 lesser communion souls."] = "La urna solo aceptará almas provenientes de matar demonios usando nigromancia o completando rituales de comunión menores. Necesito 75 almas de demonios, o 10 almas de comunión menor.",
    ["There's a couple of additional things this time as well..."] = "Esta vez también hay un par de cosas adicionales...",
    ["Let me guess, another pie?"] = "Déjame adivinar, ¿otro pastel?",
    ["Indeed! An apple pie this time, though."] = "¡Efectivamente! Pero esta vez, una tarta de manzana.",
    ["I'm not very familiar with, I guess you'd call them, 'dessert pies'. And so I'd like to try one."] = "No estoy muy familiarizado con, supongo que los llamarías, 'pasteles de postre'. Y entonces me gustaría probar uno.",
    ["That's not it, though!"] = "¡Pero eso no es todo!",
    ["Two pies?!"] = "¡¿Dos pasteles?!",
    ["No, not two pies. I'm only a small dwarf!"] = "No, dos pasteles no. ¡Soy sólo un pequeño enano!",
    ["I also need you to get some necromancer's flippers."] = "También necesito que consigas unas aletas de nigromante.",
    ["Er... what?"] = "Er... ¿qué?",
    ["You know, flippers? The things you wear on your feet?"] = "Ya sabes, ¿aletas? ¿Las cosas que usas en tus pies?",
    ["Yes, I know what flippers are, but what on Gielinor are necromancer's flippers? And where am I meant to get them from?"] = "Sí, sé qué son las aletas, pero ¿qué son las aletas de nigromante en Gielinor? ¿Y de dónde debo sacarlos?",
    ["Well, they're just like normal flippers, but to wear if you're a necromancer."] = "Bueno, son como aletas normales, pero para usar si eres un nigromante.",
    ["Mogres will probably drop them, if you kill them using necromancy."] = "Mogres probablemente los dejará caer si los matas usando nigromancia.",
    ["I guess I'll go and get these flippers then."] = "Supongo que entonces iré a buscar estas aletas.",
    ["Here's a list of everything so you don't forget!"] = "¡Aquí tienes una lista de todo para que no lo olvides!",
    ["Thanks."] = "Gracias.",
    ["Well, yes, but it's less boring talking to you than looking at a sheet of paper."] = "Bueno, sí, pero es menos aburrido hablar contigo que mirar una hoja de papel.",
    ["Thanks. Well, I just need you to bring me some souls in that soul urn I gave you."] = "Gracias. Bueno, sólo necesito que me traigas algunas almas en esa urna que te di.",
    ["The urn is modified to only accept souls from killing demons using necromancy, or completing lesser communion rituals. I need 75 undead souls, or 10 lesser communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar demonios usando nigromancia o completando rituales de comunión menores. Necesito 75 almas de no-muertos o 10 almas de comunión menor.",
    ["I'd also like an apple pie, and some necromancer's flippers, which you should be able to get by killing mogres with necromancy."] = "También me gustaría una tarta de manzana y unas aletas de nigromante, que deberías poder conseguir matando mogres con nigromancia.",
    ["Got it!"] = "¡Entendido!",
    ["I've filled up the soul urn, got your apple pie, and the er, necromancer's flippers."] = "Llené la urna del alma, compré tu pastel de manzana y, eh, las aletas del nigromante.",
    ["You actually managed to get the flippers, eh? I'm impressed."] = "De hecho lograste conseguir las aletas, ¿eh? Estoy impresionado.",
    ["Kili takes the necromancer's flippers, the apple pie, and the soul urn."] = "Kili se lleva las aletas del nigromante, la tarta de manzana y la urna del alma.",
    ["So, what do you need the flippers for?"] = "Entonces, ¿para qué necesitas las aletas?",
    ["Don't you worry about that. Ah, best try out this pie before it gets cold!"] = "No te preocupes por eso. ¡Ah, será mejor que pruebes este pastel antes de que se enfríe!",
    ["Kili digs into the apple pie."] = "Kili se sumerge en la tarta de manzana.",
    ["Pretty good. Not sure I prefer it over savoury pies, but I'm glad I tried it nonetheless."] = "Bastante bien. No estoy seguro de preferirlo a los pasteles salados, pero de todos modos me alegro de haberlo probado.",
    ["Now, let's teach you that upgrade."] = "Ahora, vamos a enseñarte esa actualización.",
    ["Kili imbues her forge with energy from the soul urn and explains the tier 50 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 50 con gran profundidad.",
    ["Her apple pie breath wafts over to you, smothering you."] = "Su aliento a tarta de manzana flota hacia ti, asfixiándote.",
    ["...You'll want to hammer the bar into this shape, so you don't accidentally whack your fingernails off..."] = "...Querrás martillar la barra para darle esta forma, para no arrancarte las uñas accidentalmente...",
    ["...And that's all there is to it!"] = "... ¡Y eso es todo!",
    ["Come back and let me know when you're ready to learn tier 60."] = "Vuelve y avísame cuando estés listo para aprender el nivel 60.",
    ["Congratulations! You have completed: 'Kili's Knowledge III' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 50 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento III de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 50 de Kili.",
    ["It's time for tier 60 then!"] = "¡Entonces es hora del nivel 60!",
    ["As always, you'll need to gather some souls in this soul urn."] = "Como siempre, necesitarás reunir algunas almas en esta urna de almas.",
    ["The urn will only accept souls from killing any monster that is at least level 70 using necromancy, or completing greater communion rituals. I need 50 monster souls, or 10 greater communion souls."] = "La urna solo aceptará almas provenientes de matar cualquier monstruo que tenga al menos nivel 70 usando nigromancia o completando rituales de comunión mayores. Necesito 50 almas de monstruos, o 10 almas de comunión mayores.",
    ["I also need some more things... And yes, one of the things is a pie."] = "También necesito algunas cosas más... Y sí, una de ellas es un pastel.",
    ["A garden pie!"] = "¡Un pastel de jardín!",
    ["The meat pie you got me a while back was lovely, but I'd like to try out the vegetarian option this time."] = "El pastel de carne que me regalaste hace un tiempo estaba delicioso, pero esta vez me gustaría probar la opción vegetariana.",
    ["Fair enough, the Lumbridge cow population is getting a bit sparse. What else?"] = "Es cierto, la población de Lumbridge cow se está volviendo un poco escasa. ¿Qué otra cosa?",
    ["Nothing as ridiculous as flippers this time, I hope..."] = "Nada tan ridículo como las aletas esta vez, espero...",
    ["No no, not to worry! I just need you to take this device and use it on an ankou."] = "¡No, no, no te preocupes! Sólo necesito que tomes este dispositivo y lo uses en un ankou.",
    ["Ah, it looks like you don't have space for the ankou agitator. Come back when you do."] = "Ah, parece que no tienes espacio para el agitador ankou. Vuelve cuando lo hagas.",
    ["Kili gives you an ankou agitator."] = "Kili te ofrece un agitador ankou.",
    ["It's a device I fiddled with that measures what kind of necromantic magic is being used on them. You might need to use it on a few to get what's needed... I think 10 should do it."] = "Es un dispositivo con el que jugué y que mide qué tipo de magia nigromántica se está usando en ellos. Es posible que necesites usarlo en algunos para obtener lo que se necesita... Creo que 10 deberían ser suficientes.",
    ["I suppose that sounds more purposeful than flippers."] = "Supongo que eso suena más útil que las aletas.",
    ["Ok. So, 50 souls, a garden pie, and... something from ankou."] = "Vale. Entonces, 50 almas, un pastel de jardín y... algo de ankou.",
    ["And that's it! Don't forget your list."] = "¡Y listo! No olvides tu lista.",
    ["I'll be back later."] = "Volveré más tarde.",
    ["I need to reclaim my ankou agitator."] = "Necesito recuperar mi agitador ankou.",
    ["Kili hands you a new ankou agitator."] = "Kili te entrega un nuevo agitador ankou.",
    ["Well, yes, but you smell much nicer than a sheet of paper."] = "Bueno, sí, pero hueles mucho mejor que una hoja de papel.",
    ["I try. Well, I need you to bring me some souls in that soul urn I gave you."] = "Lo intento. Bueno, necesito que me traigas algunas almas en esa urna que te di.",
    ["The urn is modified to only accept souls from killing monsters that are at least level 70 using necromancy, or completing greater communion rituals. I need 50 monster souls, or 10 greater communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar monstruos que tengan al menos nivel 70 usando nigromancia o completando rituales de comunión mayores. Necesito 50 almas de monstruos, o 10 almas de comunión mayores.",
    ["I'd also like a garden pie, and for you to use that ankou agitator on a few  for me... Around 10 should do it."] = "También me gustaría un pastel de jardín, y si usas ese agitador ankou en algunos para mí... Alrededor de las 10 deberían ser suficientes.",
    ["Righto."] = "Correcto.",
    ["Ok, I'm back with the full soul urn, a garden pie, and some... residue from an ankou. It was left behind by one after using your agitator doodad on it, so I think it's what you need?"] = "Ok, he vuelto con la urna del alma llena, un pastel de jardín y algunos... residuos de un ankou. Uno lo dejó atrás después de usar su adorno agitador, así que creo que es lo que necesita.",
    ["It dropped some residue? Er... great! I'll just take all of that then."] = "¿Se le cayó algún residuo? Eh... ¡genial! Entonces me quedo con todo eso.",
    ["Kili takes the ankou residue, the garden pie, and the soul urn."] = "Kili toma el residuo de ankou, el pastel de jardín y la urna del alma.",
    ["Will the residue give you the information you needed? Will it help improve my equipment?"] = "¿El residuo le dará la información que necesitaba? ¿Ayudará a mejorar mi equipo?",
    ["Yep! It'll uh, give it a magical protection-y boost that your equipment was missing."] = "¡Sí! Le dará un impulso mágico de protección que le faltaba a su equipo.",
    ["Well, I'm glad it has some value then."] = "Bueno, entonces me alegro de que tenga algún valor.",
    ["It sure does. Now, let's try out this pie."] = "Seguro que sí. Ahora, probemos este pastel.",
    ["Kili munches on the garden pie."] = "Kili mastica el pastel de la huerta.",
    ["Hmm."] = "Mmm.",
    ["A good 'hmm'? A bad 'hmm'?"] = "¿Un buen 'hmm'? ¿Un mal 'hmm'?",
    ["It's actually pretty good! The tomatoes are lovely and juicy, and the onion gives a nice crunch."] = "¡En realidad es bastante bueno! Los tomates son deliciosos y jugosos, y la cebolla queda crujiente.",
    ["Better than the meat pie?"] = "¿Mejor que el pastel de carne?",
    ["Possibly not, but a strong contender at least."] = "Posiblemente no, pero al menos es un fuerte contendiente.",
    ["Anyway! Enough about pies, let's teach you the upgrade."] = "¡De todos modos! Ya basta de pasteles, vamos a enseñarte la actualización.",
    ["Kili imbues her forge with energy from the soul urn and explains the tier 60 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 60 con gran profundidad.",
    ["Her hands drip with tomato juice, and her breath stinks of onion."] = "Sus manos gotean jugo de tomate y su aliento apesta a cebolla.",
    ["...Make sure to imbue the runic energy for this exact amount of time, so you don't burn your hair off..."] = "...Asegúrate de imbuir la energía rúnica durante este período de tiempo exacto, para no quemarte el cabello...",
    ["...That should be all!"] = "... ¡Eso debería ser todo!",
    ["Come back and let me know when you're ready to learn tier 70."] = "Vuelve y avísame cuando estés listo para aprender el nivel 70.",
    ["See you later!"] = "¡Hasta luego!",
    ["Alright, so you want to upgrade to tier 70."] = "Muy bien, entonces quieres actualizar al nivel 70.",
    ["Of course, I'll need some more souls in this soul urn."] = "Por supuesto, necesitaré más almas en esta urna de almas.",
    ["The urn will only accept souls from killing dragons using necromancy, or completing greater communion rituals. I need 100 dragon souls, or 20 greater communion souls."] = "La urna solo aceptará almas provenientes de matar dragones usando nigromancia o completando rituales de comunión mayores. Necesito 100 almas de dragón, o 20 almas de comunión mayor.",
    ["This time, I'd also like to try a fish pie."] = "Esta vez también me gustaría probar un pastel de pescado.",
    ["Back when I was living, fish pies were one of my favourites. I'm curious if they taste any better now that I'm dead."] = "Cuando yo vivía, los pasteles de pescado eran uno de mis favoritos. Tengo curiosidad por saber si saben mejor ahora que estoy muerto.",
    ["Ok, soul urn and pie. Standard. What's the last thing you need?"] = "Ok, urna del alma y pastel. Estándar. ¿Qué es lo último que necesitas?",
    ["Am I that predictable?"] = "¿Soy tan predecible?",
    ["A little."] = "Un poco.",
    ["Well, the last thing I need is some necroplasm. Necroplasm from the original Barrows brothers, specifically."] = "Bueno, lo último que necesito es algo de necroplasma. Necroplasma de los hermanos Barrows originales, específicamente.",
    ["How can I get it?"] = "¿Cómo puedo conseguirlo?",
    ["Firstly, you'll need some greater necroplasm. Around 20 for each brother should be enough."] = "En primer lugar, necesitarás un necroplasma mayor. Unas 20 por cada hermano deberían ser suficientes.",
    ["Once you have that, take it to their crypts. The energy from their sarcophagi should be enough to transform the necroplasm."] = "Una vez que tengas eso, llévalo a sus criptas. La energía de sus sarcófagos debería ser suficiente para transformar el necroplasma.",
    ["But... I don't want the individual brothers' necroplasm. You'll need to find a way to combine them into a singular necroplasm."] = "Pero... No quiero el necroplasma de los hermanos individuales. Necesitarás encontrar una manera de combinarlos en un necroplasma singular.",
    ["That sounds doable, I think."] = "Creo que eso parece factible.",
    ["Perfect. Here's the list."] = "Perfecto. Aquí está la lista.",
    ["Be back soon!"] = "¡Vuelve pronto!",
    ["Well, yes, but I was hoping you might have some leftover pie to share."] = "Bueno, sí, pero esperaba que te sobrara algo de pastel para compartir.",
    ["I do not."] = "No lo hago.",
    ["But, to answer your question, I need you to bring me some souls in that soul urn I gave you."] = "Pero, para responder a tu pregunta, necesito que me traigas algunas almas en esa urna de almas que te di.",
    ["The urn is modified to only accept souls from killing dragons using necromancy, or completing greater communion rituals. I need 100 dragon souls, or 20 greater communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar dragones usando nigromancia o completando rituales de comunión mayores. Necesito 100 almas de dragón, o 20 almas de comunión mayor.",
    ["I'd also like a fish pie, and some necroplasm from the Barrows brothers."] = "También me gustaría un pastel de pescado y un poco de necroplasma de los hermanos Barrows.",
    ["You'll need 20 greater necroplasm for each brother, and to take it to each of their sarcophagi."] = "Necesitarás 20 necroplasmas mayores para cada hermano, y llevarlos a cada uno de sus sarcófagos.",
    ["After that, you're a bit on your own - I want the necroplasm to be combined, rather than individual ones."] = "Después de eso, estarás un poco solo. Quiero que los necroplasmas estén combinados, en lugar de individualmente.",
    ["I'll see what I can do."] = "Veré qué puedo hacer.",
    ["Alright! I have your soul urn, fish pie, and I figured out how to combine the necroplasm."] = "¡Muy bien! Tengo tu urna del alma, pastel de pescado y descubrí cómo combinar el necroplasma.",
    ["Amazing!"] = "¡Increíble!",
    ["Kili takes the barrows necroplasm, the fish pie, and the soul urn."] = "Kili se lleva el necroplasma de los túmulos, el pastel de pescado y la urna del alma.",
    ["So, what will you use the necroplasm for?"] = "Entonces, ¿para qué usarás el necroplasma?",
    ["Ah, you know, to imbue the forge! And such."] = "¡Ah, ya sabes, para imbuir la fragua! Y tal.",
    ["Anyway, I can't wait to try out the pie any longer."] = "De todos modos, no puedo esperar más para probar el pastel.",
    ["Kili horks down the fish pie."] = "Kili devora el pastel de pescado.",
    ["Wonderful. Simply wonderful."] = "Maravilloso. Simplemente maravilloso.",
    ["Better than when you were living?"] = "¿Mejor que cuando vivías?",
    ["I think so? The aroma of the fish. The butteriness of the pastry..."] = "¿Creo que sí? El aroma del pescado. La mantecosidad de la masa...",
    ["Or maybe it tastes so good because I haven't had it for so long."] = "O tal vez sabe tan bien porque hace mucho que no lo pruebo.",
    ["Or maybe it IS because I'm dead, and my senses are heightened..."] = "O tal vez ES porque estoy muerto y mis sentidos están intensificados...",
    ["OR maybe the batch you brought me just used especially high-quality fish..."] = "O tal vez el lote que me trajiste solo usaba pescado de especialmente alta calidad...",
    ["OR-"] = "O-",
    ["Er, can you teach me the upgrade now?"] = "Er, ¿puedes enseñarme la actualización ahora?",
    ["Kili snaps out of her pie-induced trance."] = "Kili sale del trance inducido por el pastel.",
    ["Sorry, yes, come with me..."] = "Lo siento, sí, ven conmigo...",
    ["Kili imbues her forge with energy from the soul urn and explains the tier 70 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 70 con gran profundidad.",
    ["Vague scents of cod and trout fill the air around you."] = "Vagos aromas a bacalao y trucha llenan el aire a tu alrededor.",
    ["...Be careful to measure out this exact length of thread, so it doesn't get tangled around your ears..."] = "...Ten cuidado de medir esta longitud exacta de hilo, para que no se enrede alrededor de tus orejas...",
    ["...There we go!"] = "... ¡Allá vamos!",
    ["Come back and let me know when you're ready to learn tier 80."] = "Vuelve y avísame cuando estés listo para aprender el nivel 80.",
    ["Bye for now."] = "Adiós por ahora.",
    ["Congratulations! You have completed: 'Kili's Knowledge V' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 70 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento V de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 70 de Kili.",
    ["Alright, so you want to upgrade to tier 70, into some power armour."] = "Muy bien, entonces quieres actualizar al nivel 70 y ponerte una servoarmadura.",
    ["So, this time you'll need a soul urn, a pie, and..."] = "Entonces, esta vez necesitarás una urna para el alma, un pastel y...",
    ["Not this time!"] = "¡Esta vez no!",
    ["The power armour works a little differently, so no soul urn needed. And I can do without the pie for a bit."] = "La servoarmadura funciona un poco diferente, por lo que no se necesita una urna de alma. Y puedo prescindir del pastel por un tiempo.",
    ["Instead, you'll need to get some materials from some of the great beasts of Gielinor."] = "En su lugar, necesitarás conseguir algunos materiales de algunas de las grandes bestias de Gielinor.",
    ["I need you to get me 5 royal chitin, which can be obtained from the Kalphite Queen, and 5 hideous moleskins, which can be obtained from the Giant Mole."] = "Necesito que me consigas 5 quitina real, que se pueden obtener del Kalphite Queen, y 5 horribles pieles de topo, que se pueden obtener del topo gigante.",
    ["You should know that they'll only shed them when fought with necromancy, though."] = "Sin embargo, debes saber que solo los arrojarán cuando luchen contra la nigromancia.",
    ["Kalphite Queen... Giant Mole... Necromancy... Got it."] = "Kalphite Queen... Topo gigante... Necromancy... Entendido.",
    ["Anything else? You're really sure you don't want a pie?"] = "¿Algo más? ¿Estás realmente seguro de que no quieres un pastel?",
    ["Nope. That's all!"] = "No. ¡Eso es todo!",
    ["A drop of sweat falls from Kili's forehead as she shows great restraint in turning down your offer of a pie."] = "Una gota de sudor cae de la frente de Kili mientras muestra gran moderación al rechazar tu oferta de un pastel.",
    ["Be off, before I change my mind. Here's the list."] = "Vete antes de que cambie de opinión. Aquí está la lista.",
    ["Whatever you say!"] = "¡Lo que tú digas!",
    ["Well, yes, but I thought I'd check that you really don't want a pie this time."] = "Bueno, sí, pero pensé en comprobar que esta vez realmente no quieres un pastel.",
    ["No. No pie!"] = "No. ¡Sin pastel!",
    ["Moving on, you'll need to get me 5 royal chitin from the Kalphite Queen, and 5 hideous moleskins from the Giant Mole."] = "Continuando, necesitarás conseguirme 5 quitina real del Kalphite Queen y 5 horribles pieles de topo del topo gigante.",
    ["They should only shed them when fought with necromancy, though."] = "Sin embargo, solo deberían deshacerse de ellos cuando luchen con nigromancia.",
    ["Thanks, I'll be off then."] = "Gracias, entonces me voy.",
    ["I'm back with the royal chitin and hideous moleskins!"] = "¡Estoy de vuelta con la quitina real y las horribles pieles de topo!",
    ["Nice work!"] = "¡Buen trabajo!",
    ["Kili takes the royal chitin and the hideous moleskins."] = "Kili toma la quitina real y las horribles pieles de topo.",
    ["Onto the upgrade!"] = "¡A la actualización!",
    ["Wait, what are you going to do with the chitin and moleskins?"] = "Espera, ¿qué vas a hacer con la quitina y las pieles de topo?",
    ["It's a secret."] = "Es un secreto.",
    ["A secret?"] = "¿Un secreto?",
    ["Yes. Top secret knowledge that only dwarves of the Imcando clan can know."] = "Sí. Conocimiento ultrasecreto que sólo los enanos del clan Imcando pueden conocer.",
    ["Back to what I was saying, let's teach you the upgrade!"] = "Volviendo a lo que estaba diciendo, ¡vamos a enseñarte la actualización!",
    ["Kili explains the tier 70 upgrade process for power armour in great depth."] = "Kili explica con gran profundidad el proceso de actualización de nivel 70 para servoarmadura.",
    ["...Make sure you cut the fabric to this specific size, so you don't have any overhang that could trip you up and cause a nasty concussion..."] = "...Asegúrate de cortar la tela a este tamaño específico, para que no quede ningún saliente que pueda hacerte tropezar y causar una conmoción cerebral desagradable...",
    ["...And that's all!"] = "... ¡Y eso es todo!",
    ["Congratulations! You have completed: 'Kili's Knowledge V (power)' - Learn how to upgrade your Death Skull equipment to tier 70, and upgrade your Deathwarden equipment to tier 70 Deathdealer from Kili."] = "¡Felicitaciones! Ha completado: 'Conocimiento V (poder) de Kili': aprenda cómo actualizar su equipo Death Skull al nivel 70 y actualizar su equipo Deathwarden al nivel 70 Deathdealer de Kili.",
    ["So, you want to upgrade to tier 80."] = "Entonces, deseas actualizar al nivel 80.",
    ["First off, I'll need some more souls in this soul urn."] = "En primer lugar, necesitaré más almas en esta urna de almas.",
    ["The urn will only accept souls from killing monsters assigned as your Slayer task using necromancy, or completing greater communion rituals. I need 150 Slayer task souls, or 30 greater communion souls."] = "La urna solo aceptará almas provenientes de matar monstruos asignados como tu tarea Slayer usando nigromancia o completando rituales de comunión mayores. Necesito 150 almas de tarea Slayer, o 30 almas de comunión mayor.",
    ["I also need you to recharge this special hammer of mine, with some powerful soul energy."] = "También necesito que recargues este martillo especial mío, con una poderosa energía del alma.",
    ["Ah, it looks like you don't have space for the spiritbound hammer (uncharged). Come back when you do."] = "Ah, parece que no tienes espacio para el martillo vinculado al espíritu (sin carga). Vuelve cuando lo hagas.",
    ["Kili gives you a spiritbound hammer (uncharged)."] = "Kili te da un martillo vinculado al espíritu (sin carga).",
    ["Powerful, eh? Do I need to defeat an elder god? An average god? A demi-god?"] = "Potente, ¿eh? ¿Necesito derrotar a un dios mayor? ¿Un dios promedio? ¿Un semidiós?",
    ["Er, not exactly. Just some of their followers."] = "Er, no exactamente. Sólo algunos de sus seguidores.",
    ["Powerful followers, though! I was thinking of the four generals in God Wars Dungeon."] = "¡Pero poderosos seguidores! Estaba pensando en los cuatro generales de God Wars Dungeon.",
    ["Defeat them, and then charge up my hammer with residual energy from their altars. It depletes quickly after their defeat though, so you'll have to be fast."] = "Derrótalos y luego carga mi martillo con la energía residual de sus altares. Sin embargo, se agota rápidamente después de su derrota, así que tendrás que ser rápido.",
    ["Fast as lightning, noted."] = "Rápido como un rayo, señaló.",
    ["And last but not least..."] = "Y por último, pero no menos importante...",
    ["A pie?"] = "¿Un pastel?",
    ["A pie!"] = "¡Un pastel!",
    ["But not any old pie..."] = "Pero no cualquier pastel viejo...",
    ["A redberry pie!"] = "¡Un pastel de frutos rojos!",
    ["I was wondering how long it would take for you to ask for one."] = "Me preguntaba cuánto tiempo te tomaría pedir uno.",
    ["I've exercised a lot of restraint by trying the other pies first, but I think it's time."] = "He ejercido mucha moderación al probar los otros pasteles primero, pero creo que es el momento.",
    ["Now here's your list."] = "Ahora aquí está tu lista.",
    ["Hurry back!"] = "¡Vuelve rápido!",
    ["I need to reclaim my spiritbound hammer (uncharged)."] = "Necesito recuperar mi martillo vinculado al espíritu (descargado).",
    ["Kili hands you a new spiritbound hammer (uncharged)."] = "Kili te entrega un nuevo martillo vinculado al espíritu (sin carga).",
    ["Well, yes, but I was hoping you might have changed your mind and are now willing to teach me the upgrade for no effort on my behalf."] = "Bueno, sí, pero esperaba que hubieras cambiado de opinión y ahora estés dispuesto a enseñarme la actualización sin ningún esfuerzo por mi parte.",
    ["The urn is modified to only accept souls from killing monsters assigned as your Slayer task using necromancy, or completing greater communion rituals. I need 150 Slayer task souls, or 30 greater communion souls."] = "La urna se modifica para aceptar solo almas provenientes de matar monstruos asignados como tu tarea Slayer usando nigromancia o completando rituales de comunión mayores. Necesito 150 almas de tarea Slayer, o 30 almas de comunión mayor.",
    ["I also need you to charge up my hammer from the altars of the four God Wars Dungeon generals. You'll have to be quick after defeating them, though."] = "También necesito que cargues mi martillo desde los altares de los cuatro generales de God Wars Dungeon. Sin embargo, tendrás que ser rápido después de derrotarlos.",
    ["And, most important of all, I need you to get me a redberry pie."] = "Y, lo más importante de todo, necesito que me traigas una tarta de frutos rojos.",
    ["I'll continue getting your things."] = "Seguiré recogiendo tus cosas.",
    ["Ok, I'm back with the filled soul urn, charged hammer, and redberry pie."] = "Ok, he vuelto con la urna del alma llena, el martillo cargado y el pastel de frutos rojos.",
    ["Pie..."] = "Pastel...",
    ["Kili takes the charged hammer, the redberry pie, and the soul urn."] = "Kili toma el martillo cargado, el pastel de frutos rojos y la urna del alma.",
    ["Be careful, the pie is quite ho-"] = "Cuidado, el pastel está bastante ho-",
    ["Kili gobbles up the redberry pie before you have a chance to react."] = "Kili devora el pastel de frutos rojos antes de que tengas oportunidad de reaccionar.",
    ["Ahh. That hits the spot."] = "Ahh. Eso da en el clavo.",
    ["As I was trying to say, the pie was quite hot. Just wanted to make sure you didn't burn yourself."] = "Como intentaba decir, el pastel estaba bastante caliente. Sólo quería asegurarme de que no te quemaras.",
    ["Kili pokes around her mouth."] = "Kili se asoma alrededor de la boca.",
    ["Ah, I guess I did burn myself. Well you know what they say, no pain, no gain!"] = "Ah, supongo que me quemé. Bueno, ya sabes lo que dicen, ¡sin dolor no hay ganancia!",
    ["I mean, you could have waited for the pie to cool down, and then just had the gain without the pain but..."] = "Quiero decir, podrías haber esperado a que el pastel se enfriara y luego obtener la ganancia sin el dolor, pero...",
    ["I think the molten hot redberry sauce added to the gain, though."] = "Sin embargo, creo que la salsa picante de frutos rojos fundida contribuyó a la ganancia.",
    ["Suit yourself."] = "Haz lo que quieras.",
    ["Pie aside, let's go and teach you the upgrade."] = "Dejando a un lado el pastel, vamos a enseñarte la actualización.",
    ["Kili imbues her forge with energy from the soul urn and explains the tier 80 upgrade process in great depth."] = "Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 80 con gran profundidad.",
    ["A rich scent of redberry coats the air around you."] = "Un rico aroma a frutos rojos envuelve el aire que te rodea.",
    ["...You'll want to stand in this exact position when hammering, so you don't fracture a bone..."] = "...Querrás pararte exactamente en esta posición al martillar, para no fracturarte un hueso...",
    ["...And that's all done!"] = "... ¡Y listo!",
    ["One last thing I should mention. If you choose to upgrade your equipment from an augmented version, you should know that any augmentations will also be applied to the upgraded version."] = "Una última cosa que debo mencionar. Si elige actualizar su equipo desde una versión aumentada, debe saber que cualquier aumento también se aplicará a la versión mejorada.",
    ["So no need to worry about losing anything."] = "Así que no hay necesidad de preocuparse por perder nada.",
    ["Come back and let me know when you're ready to learn tier 90."] = "Vuelve y avísame cuando estés listo para aprender el nivel 90.",
    ["Congratulations! You have completed: 'Kili's Knowledge VI' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 80 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento VI de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 80 desde Kili.",
    ["Right. You want to learn tier 80, power armour."] = "Correcto. Quieres aprender servoarmadura de nivel 80.",
    ["So, as it's power armour, I won't need you to gather me any souls."] = "Entonces, como es una servoarmadura, no necesitaré que me recojas almas.",
    ["Phew."] = "Uf.",
    ["Instead, you'll need to defeat Nex and the Queen Black Dragon!"] = "¡En lugar de eso, tendrás que derrotar a Nex y a la Reina Dragón Negro!",
    ["So much for an easy task."] = "Hasta aquí es una tarea fácil.",
    ["First of all, I'm in need of 5 Zaryte fragments. You should be able to get these from Nex."] = "Primero que nada, necesito 5 fragmentos de Zaryte. Debería poder obtenerlos de Nex.",
    ["Second of all, I'd like 5 tortured soul essences. I believe the Queen Black Dragon will possess these."] = "En segundo lugar, me gustaría 5 esencias de almas torturadas. Creo que la Reina Dragón Negro los poseerá.",
    ["Poor souls."] = "Pobres almas.",
    ["Another thing to note, is that they'll probably only drop the things I need if you defeat them with necromancy."] = "Otra cosa a tener en cuenta es que probablemente solo dejarán caer las cosas que necesito si los derrotas con nigromancia.",
    ["Probably?"] = "¿Probablemente?",
    ["Almost certainly, according to my research..."] = "Casi seguro, según mi investigación...",
    ["A definite guarantee would be appreciated, before I charge in all gung-ho."] = "Se agradecería una garantía definitiva antes de cargar con todo entusiasmo.",
    ["Well, we don't always get what we want in life. Or the afterlife."] = "Bueno, no siempre conseguimos lo que queremos en la vida. O la otra vida.",
    ["...And that should be all I need! Here's the list."] = "...¡Y eso debería ser todo lo que necesito! Aquí está la lista.",
    ["I'll go and prepare to get your things then."] = "Entonces iré y me prepararé para recoger tus cosas.",
    ["Well, yes, but I just wanted to come and bother you."] = "Bueno, sí, pero solo quería venir a molestarte.",
    ["Well, you need to get me 5 Zaryte fragments from Nex, and 5 tortured soul essences from the Queen Black Dragon."] = "Bueno, necesitas conseguirme 5 fragmentos de Zaryte de Nex y 5 esencias de alma torturadas de la Reina Dragón Negro.",
    ["You should also know that they'll only drop them when defeated using necromancy."] = "También debes saber que solo los soltarán cuando sean derrotados usando nigromancia.",
    ["I've got those Zaryte fragments and tortured soul essences for you!"] = "¡Tengo esos fragmentos de Zaryte y esencias de almas torturadas para ti!",
    ["Good job."] = "Buen trabajo.",
    ["Kili takes the Zaryte fragments and the tortured soul essences."] = "Kili toma los fragmentos de Zaryte y las esencias del alma torturada.",
    ["What are you going to do with them?"] = "¿Qué vas a hacer con ellos?",
    ["Ah, I'm glad you asked! You see..."] = "¡Ah, me alegra que lo hayas preguntado! Ya ves...",
    ["Kili starts talking about some extremely in depth Smithing-related gobbledygook."] = "Kili comienza a hablar sobre algunas palabrerías extremadamente profundas relacionadas con Smithing.",
    ["...And then I'll instil the essence into the alloys, whilst infusing the fragments into the welding bucket..."] = "...Y luego infundiré la esencia en las aleaciones, mientras infundo los fragmentos en el cubo de soldadura...",
    ["She continues to talk in terms you hadn't heard before. You assume you don't know of these terms because she's the master smith here, not you."] = "Ella continúa hablando en términos que no habías escuchado antes. Asumes que no conoces estos términos porque ella es la maestra herrera aquí, no tú.",
    ["You regret asking in the first place."] = "Te arrepientes de haber preguntado en primer lugar.",
    ["...And that's how we'll make you the best armour to ever exist!"] = "... ¡Y así es como te haremos la mejor armadura que jamás haya existido!",
    ["Oop, sorry, I must have zoned out. What was that?"] = "Vaya, lo siento, debo haberme desconectado. ¿Qué fue eso?",
    ["Nevermind. Now follow me, and I'll teach you the upgrade..."] = "No importa. Ahora sígueme y te enseñaré la actualización...",
    ["Kili explains the tier 80 upgrade process for power armour in great depth."] = "Kili explica con gran profundidad el proceso de actualización de nivel 80 para servoarmadura.",
    ["...Don't forget to put on goggles before bashing the bars, otherwise you might make yourself blind..."] = "...No olvides ponerte gafas antes de golpear las barras, de lo contrario podrías quedar ciego...",
    ["...And that should be it!"] = "... ¡Y eso debería ser todo!",
    ["Congratulations! You have completed: 'Kili's Knowledge VI (power)' - Learn how to upgrade your Death Skull and Deathdealer equipment to tier 80 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento VI (poder) de Kili': aprende cómo actualizar tu equipo Death Skull y Deathdealer al nivel 80 de Kili.",
    ["So you've chosen to upgrade to tier 90."] = "Entonces has elegido actualizar al nivel 90.",
    ["To start, you'll need to fill up this soul urn for me."] = "Para empezar, tendrás que llenar esta urna del alma por mí.",
    ["The urn will only accept souls from powerful communion rituals, of which I need 50. Alternatively, you can fill it up by just completing a Soul Reaper task using necromancy."] = "La urna solo aceptará almas de poderosos rituales de comunión, de las cuales necesito 50. Alternativamente, puedes llenarla simplemente completando una tarea de Soul Reaper usando nigromancia.",
    ["[Kili gives you a soul urn.]"] = "[Kili te regala una urna para el alma.]",
    ["Next, I need 10 empowered necromantic seals from each of the generals of the Heart of Gielinor."] = "A continuación, necesito 10 sellos nigrománticos potenciados de cada uno de los generales del Corazón de Gielinor.",
    ["This is a complex process that's taken a lot of time to perfect, so pay attention."] = "Este es un proceso complejo que requiere mucho tiempo para perfeccionarse, así que preste atención.",
    ["First off, you'll need to defeat the boss to gain the unpowered seals. Make sure to bring along 25 greater necroplasm too."] = "En primer lugar, tendrás que derrotar al jefe para obtener los sellos sin poder. Asegúrate de llevar también 25 necroplasmas mayores.",
    ["Now, once you have a bunch of their seals, they'll each require a different process to empower..."] = "Ahora, una vez que tengas varios de sus sellos, cada uno necesitará un proceso diferente para potenciarlos...",
    ["The seals from Helwyr should be empowered through opening a crystal chest."] = "Los sellos de Helwyr deben potenciarse abriendo un cofre de cristal.",
    ["Gregorovic's seals will need you to craft some miasmic runes."] = "Los sellos de Gregorovic necesitarán que crees algunas runas miasmáticas.",
    ["Vindicta's seals will need you to use Bone Shield against a dragonfire attack."] = "Los sellos de Vindicta necesitarán que uses Escudo óseo contra un ataque de fuego de dragón.",
    ["And last but not least, the Twin Furies seals will need you to restore some Zamorakian artefacts."] = "Y por último, pero no menos importante, los sellos de las Furias Gemelas necesitarán que restaures algunos artefactos zamorakianos.",
    ["That is... a lot of work."] = "Eso es... mucho trabajo.",
    ["Oh, I'm not finished yet!"] = "¡Oh, todavía no he terminado!",
    ["I also need a pulsating onyx. You'll be able to craft this by combining an uncut onyx and a special crystal."] = "También necesito un ónix pulsante. Podrás crear esto combinando un ónix sin cortar y un cristal especial.",
    ["Lucky for you, I already have the crystal here with me."] = "Por suerte para ti, ya tengo el cristal aquí conmigo.",
    ["Ah, it looks like you don't have space for the inert necromantic crystal. Come back when you do."] = "Ah, parece que no tienes espacio para el cristal nigromántico inerte. Vuelve cuando lo hagas.",
    ["[Kili gives you an inert necromantic crystal.]"] = "[Kili te ofrece un cristal nigromántico inerte.]",
    ["Unlucky for you, it needs powering up. The energies from defeating TzTok-Jad in the TzHaar Fight Cave should be enough for that."] = "Por desgracia para ti, es necesario encenderlo. Las energías obtenidas al derrotar a TzTok-Jad en la cueva de lucha de TzHaar deberían ser suficientes para eso.",
    ["Great."] = "Genial.",
    ["So that's it, right? I'll be off now!"] = "Entonces eso es todo, ¿verdad? ¡Me voy ahora!",
    ["Not so fast!"] = "¡No tan rápido!",
    ["Lastly, I would like a blueberry pie."] = "Por último, me gustaría un pastel de arándanos.",
    ["A BLUEberry pie?"] = "¿Un pastel de arándanos?",
    ["I'm not sure exactly what Gielinor was like during your time alive, but I can tell you now that we don't have such a thing as a blueberry."] = "No estoy seguro exactamente de cómo era Gielinor durante tu época de vida, pero puedo decirte ahora que no tenemos algo llamado arándano.",
    ["I'm sure you can figure it out. Maybe some inhabitants around the city can help you."] = "Estoy seguro de que puedes resolverlo. Quizás algunos habitantes de la ciudad puedan ayudarte.",
    ["So that's..."] = "Así que eso es...",
    ["[You take a deep breath.]"] = "[Respiras profundamente.]",
    ["A full soul urn, 10 empowered necromantic seals from each of the 4 Heart of Gielinor generals, a pulsating onyx..."] = "Una urna de alma llena, 10 sellos nigrománticos potenciados de cada uno de los 4 generales del Corazón de Gielinor, un ónix pulsante...",
    ["[You breathe out.]"] = "[Exhalas.]",
    ["... And a blueberry pie."] = "... Y una tarta de arándanos.",
    ["That's everything!"] = "¡Eso es todo!",
    ["You've got a lot of work ahead of you, so no need to hang around. Here's the list."] = "Tienes mucho trabajo por delante, así que no necesitas perder el tiempo. Aquí está la lista.",
    ["I'd best get started then."] = "Entonces será mejor que empiece.",
    ["I'm back with some information that may help me find some blueberries."] = "Regresé con información que puede ayudarme a encontrar algunos arándanos.",
    ["Oh?"] = "¿Ah?",
    ["Someone suggested that as blue is the opposite of red, then I would simply have to find a land of opposites."] = "Alguien sugirió que como el azul es lo opuesto al rojo, entonces simplemente tendría que encontrar una tierra de opuestos.",
    ["They were joking, but I also talked to someone else who mentioned a land where things work backwards."] = "Estaban bromeando, pero también hablé con alguien más que mencionó una tierra donde las cosas funcionan al revés.",
    ["Something about an evil cat, and uncooked fish..."] = "Algo sobre un gato malvado y pescado crudo...",
    ["Oh no."] = "Oh, no.",
    ["You know something?"] = "¿Sabes algo?",
    ["A pest. Evil Bob."] = "Una plaga. Evil Bob.",
    ["He resides in a land of opposites, reigning over humans. A place called ScapeRune."] = "Reside en una tierra de opuestos, reinando sobre los humanos. Un lugar llamado ScapeRune.",
    ["More than once has he tried to imprison me over there."] = "Más de una vez ha intentado encarcelarme allí.",
    ["But you should be fine! Just do as he says."] = "¡Pero deberías estar bien! Simplemente haz lo que él dice.",
    ["How can I get there?"] = "¿Cómo puedo llegar?",
    ["That I can't help you with, as I never actually visited myself. It's a different realm to Gielinor, though, so it should be accessible via magical means."] = "En eso no puedo ayudarte, ya que nunca fui a visitarme. Sin embargo, es un reino diferente a Gielinor, por lo que debería ser accesible a través de medios mágicos.",
    ["Thanks for the help."] = "Gracias por la ayuda.",
    ["I need to reclaim my inert necromantic crystal."] = "Necesito recuperar mi cristal nigromántico inerte.",
    ["Kili hands you a new inert necromantic crystal."] = "Kili te entrega un nuevo cristal nigromántico inerte.",
    ["Well, yes, but I just wanted to talk to a friend."] = "Bueno, sí, pero solo quería hablar con un amigo.",
    ["First of all, I need you to bring me some souls in that soul urn I just gave you."] = "Primero que nada, necesito que me traigas algunas almas en esa urna de almas que te acabo de dar.",
    ["It can be filled through 50 powerful communion rituals, or completing a Soul Reaper task with necromancy."] = "Se puede completar a través de 50 poderosos rituales de comunión o completando una tarea de Soul Reaper con nigromancia.",
    ["Next, I need 10 empowered necromantic seals from the general of the Heart of Gielinor."] = "A continuación, necesito 10 sellos nigrománticos potenciados del general del Corazón de Gielinor.",
    ["Then, to empower them, each requires a different process."] = "Luego, para potenciarlos, cada uno requiere un proceso diferente.",
    ["The Twin Furies seals will need you to restore some Zamorakian artefacts."] = "Los sellos de las Furias Gemelas necesitarán que restaures algunos artefactos zamorakianos.",
    ["Secondly, I need a pulsating onyx. You'll be able to craft this by combining an uncut onyx and that crystal I gave you."] = "En segundo lugar, necesito un ónix pulsante. Podrás crear esto combinando un ónix sin cortar y el cristal que te di.",
    ["The crystal first needs charging up by defeating TzTok-Jad in the TzHaar Fight Cave, though."] = "Sin embargo, primero es necesario cargar el cristal al derrotar a TzTok-Jad en la cueva de lucha de TzHaar.",
    ["And last but not least, I want a blueberry pie. Some inhabitants of the city may be able to help you figure that one out."] = "Y por último, pero no menos importante, quiero una tarta de arándanos. Algunos habitantes de la ciudad pueden ayudarte a resolverlo.",
    ["I'll get back to it then."] = "Volveré a ello entonces.",
    ["Ok, I finally managed to gather all the things you needed."] = "Ok, finalmente logré reunir todas las cosas que necesitabas.",
    ["So you did manage to find a blueberry?"] = "Entonces, ¿conseguiste encontrar un arándano?",
    ["I could barely believe it myself, but yes. I did manage to find a blueberry."] = "Yo mismo apenas podía creerlo, pero sí. Logré encontrar un arándano.",
    ["[Kili takes the pulsating onyx, the necromantic seals, the blueberry pie, and the soul urn.]"] = "[Kili toma el ónix pulsante, los sellos nigrománticos, el pastel de arándanos y la urna del alma.]",
    ["What did you need this abundance of items for?"] = "¿Para qué necesitabas esta abundancia de artículos?",
    ["Something very exciting."] = "Algo muy emocionante.",
    ["That I can't tell you about yet."] = "Eso no puedo contarte todavía.",
    ["Really? I went to all that effort, you could at least give me a crumb of knowledge."] = "¿En serio? Hice todo ese esfuerzo, al menos podrías darme una migaja de conocimiento.",
    ["That's true..."] = "Eso es cierto...",
    ["I suppose I can tell you after you've learnt all of the upgrades."] = "Supongo que podré decírtelo después de que hayas aprendido todas las actualizaciones.",
    ["Fine."] = "Bien.",
    ["Can we eat the pie now?"] = "¿Podemos comer el pastel ahora?",
    ["We?"] = "¿Nosotros?",
    ["I've never tasted a blueberry. I didn't even know they existed until this task."] = "Nunca he probado un arándano. Ni siquiera sabía que existían hasta esta tarea.",
    ["Alright, I guess we can share the pie this time."] = "Muy bien, supongo que esta vez podemos compartir el pastel.",
    ["[Kili chomps down half of the pie, leaving the remaining half for you.]"] = "[Kili muerde la mitad del pastel y deja la mitad restante para ti.]",
    ["[You chomp down on the other half of the pie, leaving nothing but crumbs.]"] = "[Muerdes la otra mitad del pastel, dejando nada más que migajas.]",
    ["Thoughts?"] = "¿Pensamientos?",
    ["Hmm. That was pretty good! A hint of sourness, combined with a unique tinge of sugary goodness."] = "Mmm. ¡Eso estuvo bastante bien! Un toque de acidez, combinado con un matiz único de bondad azucarada.",
    ["I couldn't have said it better myself."] = "Ni yo mismo podría haberlo dicho mejor.",
    ["Now! Let's head over to the workshop so I can teach you the upgrade."] = "¡Ahora! Vayamos al taller para poder enseñarte la actualización.",
    ["[Kili imbues her forge with energy from the soul urn and explains the tier 90 upgrade process in great depth.]"] = "[Kili imbuye su forja con la energía de la urna del alma y explica el proceso de actualización al nivel 90 con gran profundidad.]",
    ["[A novel fragrance fills your nose. You can only assume that it's blueberry.]"] = "[Una fragancia novedosa llena tu nariz. Sólo puedes asumir que es arándano.]",
    ["...Make sure to hydrate before starting the process, so you don't pass out..."] = "...Asegúrate de hidratarte antes de iniciar el proceso, para no desmayarte...",
    ["[You take notes, ensuring you won't forget anything.]"] = "[Toma notas, asegurándote de no olvidar nada.]",
    ["...And that's it!"] = "...¡Y listo!",
    ["I haven't taught you all there is to know yet, so come back whenever you'd like to learn more."] = "Aún no te he enseñado todo lo que hay que saber, así que vuelve cuando quieras aprender más.",
    ["Will do."] = "Lo haré.",
    ["Congratulations! You have completed: 'Kili's Knowledge VII' - Learn how to upgrade your Death Skull and Deathwarden equipment to tier 90 from Kili."] = "¡Felicidades! Has completado: 'Conocimiento VII de Kili': aprende cómo actualizar tu equipo Death Skull y Deathwarden al nivel 90 de Kili.",
    ["Hmm.."] = "Mmmm..",
    ["Tier 70... tank.... power... Tier 80... Tier 90...."] = "Nivel 70... tanque... potencia... Nivel 80... Nivel 90....",
    ["And with that, I believe I've taught you everything you need to know!"] = "¡Y con eso, creo que te he enseñado todo lo que necesitas saber!",
    ["The student becomes the master!"] = "¡El alumno se convierte en el maestro!",
    ["You were a wonderful student, Player. I'll see you around!"] = "Fuiste un estudiante maravilloso, Player. ¡Nos vemos por ahí!",
    ["Hold on a minute."] = "Espera un minuto.",
    ["Yes?"] = "¿Sí?",
    ["What exactly did you end up doing with all the miscellaneous items I painstakingly collected for you?"] = "¿Qué terminaste haciendo exactamente con todos los artículos diversos que recopilé minuciosamente para ti?",
    ["The residue, the flippers, the chitin, the fragments?"] = "¿El residuo, las aletas, la quitina, los fragmentos?",
    ["Ah. But didn't I tell you at the time?"] = "Ah. ¿Pero no te lo dije en ese momento?",
    ["You really expected me to believe the things you were telling me? Things like 'only the Imcando are allowed to know of some top secret use for hideous moleskins'?"] = "¿Realmente esperabas que creyera las cosas que me decías? ¿Cosas como 'sólo los Imcando pueden conocer algún uso ultrasecreto de horribles pieles de topo'?",
    ["You got me."] = "Me tienes.",
    ["I just wanted to see how far you'd go to learn the upgrades, really."] = "Sólo quería ver hasta dónde llegarías para aprender las actualizaciones, de verdad.",
    ["Turns out, quite far!"] = "¡Resulta que está bastante lejos!",
    ["Unnecessarily slaughtering mogres... Annoying ankou... You even went and defeated the Ambassador!"] = "Matando mogres innecesariamente... Ankou molesto... ¡Incluso fuiste y derrotaste a the Ambassador!",
    ["After all those pies I gathered for you, and this is how you repaid me."] = "Después de todos esos pasteles que reuní para ti, y así es como me pagaste.",
    ["The pies were much appreciated."] = "Los pasteles fueron muy apreciados.",
    ["Well, at least I can fully upgrade my equipment now. Thanks, I guess."] = "Bueno, al menos ahora puedo actualizar completamente mi equipo. Gracias, supongo.",
    ["Anytime!"] = "¡En cualquier momento!",
    ["I'm not going anywhere, so you know where to find me should you need anything."] = "No voy a ir a ningún lado, así que ya sabes dónde encontrarme si necesitas algo.",
    ["See you around!"] = "¡Nos vemos!",
    ["So, now we're onto tier 90, power armour."] = "Entonces, ahora estamos en el nivel 90, servoarmadura.",
    ["This time you won't need to fill up any soul urns for me."] = "Esta vez no necesitarás llenar ninguna urna de almas para mí.",
    ["Instead, I need a few items which will require some challenging tasks."] = "En cambio, necesito algunos elementos que requerirán algunas tareas desafiantes.",
    ["I'm up for anything."] = "Estoy dispuesto a cualquier cosa.",
    ["That's the spirit!"] = "¡Ese es el espíritu!",
    ["To start with then, I need a piece of greater ensouled cloth, dripping with venom."] = "Entonces, para empezar, necesito un trozo de tela con mayor alma, que gotea veneno.",
    ["Using the cloth on the corpse of Araxxi should be sufficient."] = "Usar la tela sobre el cadáver de Araxxi debería ser suficiente.",
    ["The next thing I need is a fragment of anima. You should just be able to get one of these from defeating either Vorago, Telos, or Solak, with necromancy."] = "Lo siguiente que necesito es un fragmento de ánima. Deberías poder obtener uno de estos al derrotar a Vorago, Telos o Solak con nigromancia.",
    ["A piece of cake."] = "Pan comido.",
    ["Really? Well, I still need one more thing..."] = "¿En serio? Bueno, todavía necesito una cosa más...",
    ["A special pie infused with the power of the gods, which I can only get by defeating Zamorak?"] = "¿Un pastel especial infundido con el poder de los dioses, que solo puedo obtener derrotando a Zamorak?",
    ["I wish!"] = "¡Ojalá!",
    ["But no. The last thing I need is some ulthven necroplasm, which you'll be able to get from defeating the Ambassador with necromancy."] = "Pero no. Lo último que necesito es un poco de necroplasma ultimo, que podrás obtener al derrotar a the Ambassador con nigromancia.",
    ["I hope this upgrade is worth it."] = "Espero que esta actualización valga la pena.",
    ["Maybe. Before you go, here's the list."] = "Quizás. Antes de irte, aquí tienes la lista.",
    ["I'll go and get started then."] = "Entonces iré y empezaré.",
    ["[Kili hands you a new equipment upgrade task list.]"] = "[Kili le entrega una nueva lista de tareas de actualización de equipos.]",
    ["Well, yes, but I missed looking at your dazzling eyes and glowing hair."] = "Bueno, sí, pero extrañaba tus ojos deslumbrantes y tu cabello resplandeciente.",
    ["Or, glowing everything I guess."] = "O, supongo que brillando todo.",
    ["I'll take that as a compliment."] = "Lo tomaré como un cumplido.",
    ["So, first thing I need is some greater ensouled cloth, dripping in venom."] = "Entonces, lo primero que necesito es una tela con mayor alma, goteando veneno.",
    ["Using the cloth on the corpse of Araxxi should do the job."] = "Usar la tela sobre el cadáver de Araxxi debería funcionar.",
    ["The second thing I need is a fragment of anima. Defeating Vorago, Telos, or Solak, with necromancy, should yield one of these."] = "Lo segundo que necesito es un fragmento de ánima. Derrotar a Vorago, Telos o Solak con nigromancia debería dar como resultado uno de estos.",
    ["The third and final thing I need is some ulthven necroplasm. You'll be able to get this by defeating the Ambassador with necromancy."] = "La tercera y última cosa que necesito es un necroplasma definitivo. Podrás conseguirlo derrotando a the Ambassador con nigromancia.",
    ["Alright!"] = "¡Muy bien!",
    ["I've got the venomous cloth, fragment of anima, and ulthven necroplasm for you!"] = "¡Tengo la tela venenosa, el fragmento de ánima y el último necroplasma para ti!",
    ["Good work."] = "Buen trabajo.",
    ["[Kili takes the venomous greater ensouled cloth, fragment of anima, and ulthven necroplasm.]"] = "[Kili toma la venenosa tela con alma mayor, un fragmento de ánima y el último necroplasma.]",
    ["Sorry, what was that?"] = "Lo siento, ¿qué fue eso?",
    ["I asked what you're going to do w-"] = "Te pregunté qué vas a hacer con-",
    ["Player, I think you're breaking up."] = "Player, creo que estás rompiendo.",
    ["What? I'm right next to you."] = "¿Qué? Estoy justo a tu lado.",
    ["Maybe their amulet of ghostspeak stopped working."] = "Quizás su amuleto de habla fantasmal dejó de funcionar.",
    ["I don't even need that in the underworld!"] = "¡Ni siquiera necesito eso en el inframundo!",
    ["Maybe they've faded out from the underworld, because they're not dead."] = "Tal vez se hayan desvanecido del inframundo, porque no están muertos.",
    ["Nope, I'm still fully here."] = "No, todavía estoy completamente aquí.",
    ["Well, it was nice to know them."] = "Bueno, fue un placer conocerlos.",
    ["Hey! I'm still here! Can we just get the upgrade out of the way?"] = "¡Oye! ¡Todavía estoy aquí! ¿Podemos eliminar la actualización?",
    ["Ah, Player, there you are! Great suggestion, let's teach you the upgrade."] = "¡Ah, Player, ahí estás! Gran sugerencia, vamos a enseñarte la actualización.",
    ["[Kili explains the tier 90 upgrade process for power armour in great depth.]"] = "[Kili explica con gran detalle el proceso de actualización de nivel 90 para servoarmadura.]",
    ["...Make sure you wear some steel-toed boots, so you don't burn your toes off..."] = "...Asegúrate de usar botas con punta de acero para no quemarte los dedos...",
    ["I haven't taught you everything there is to know yet, so come back whenever you'd like to learn more."] = "Aún no te he enseñado todo lo que hay que saber, así que vuelve cuando quieras aprender más.",
    ["Congratulations! You have completed: 'Kili's Knowledge VII (power)' - Learn how to upgrade your Death Skull and Deathdealer equipment to tier 90 from Kili."] = "¡Felicitaciones! Has completado: 'Conocimiento VII de Kili (poder)': aprende cómo actualizar tu equipo Death Skull y Deathdealer al nivel 90 de Kili.",
    ["Congratulations! You have completed: 'Student Becomes the Master' - Learn all of Kili's equipment upgrade tasks."] = "¡Felicitaciones! Ha completado: 'El estudiante se convierte en maestro': aprenda todas las tareas de actualización de equipos de Kili.",
    ["How are you?"] = "¿Cómo estás?",
    ["Busy."] = "Ocupado.",
    ["Hello Kilron."] = "Hola Kilron.",
    ["Hello traveller. Do you need to go back over?"] = "Hola viajero. ¿Necesitas volver?",
    ["Not yet Kilron."] = "Aún no Kilron.",
    ["Okay, just give me the word."] = "Está bien, solo dame la palabra.",
    ["Yes I do."] = "Sí, lo hago.",
    ["Okay, quickly now!"] = "¡Bien, rápido!",
    ["Looks like you won't be needing the rope ladder any more, adventurer. I heard it was you who started the revolution and freed West Ardougne!"] = "Parece que ya no necesitarás la escalera de cuerda, aventurero. ¡Escuché que fuiste tú quien inició la revolución y liberó a West Ardougne!",
    ["Hi! I'm Kimberly, I'm new around here."] = "¡Hola! Soy Kimberly, soy nuevo por aquí.",
    ["Hi, Kimberly. Pleased to meet you. How do you like living in Witchaven?"] = "Hola, Kimberly. Encantado de conocerte. ¿Qué te parece vivir en Witchaven?",
    ["Well, it's a bit slug-y, and the locals aren't that friendly, but it's mostly fine. I guess."] = "Bueno, es un poco lento y los lugareños no son tan amigables, pero en general está bien. Supongo.",
    ["I'm glad to hear that. Well, I have to be going, but it was nice to meet you."] = "Me alegra oír eso. Bueno, tengo que irme, pero fue un placer conocerte.",
    ["Sure, I'll see you later."] = "Claro, nos vemos luego.",
    ["Hello, Kimberly. How are you doing?"] = "Hola, Kimberly. ¿Cómo estás?",
    ["I'm doing well, thank you, Player. Things are much better down here. No sea slugs and no horrid little boys to scare me. Although, I do miss the sky and the fresh air."] = "Estoy bien, gracias, Player. Las cosas están mucho mejor aquí abajo. No hay babosas marinas ni niños horribles que me asusten. Aunque sí extraño el cielo y el aire fresco.",
    ["I can imagine. Hopefully soon, your parents will feel safe enough to move back up to Witchaven."] = "Me lo imagino. Con suerte, pronto tus padres se sentirán lo suficientemente seguros como para regresar a Witchaven.",
    ["That would be nice. Maybe the sea slugs will go away soon?"] = "Eso estaría bien. ¿Quizás las babosas marinas desaparezcan pronto?",
    ["*(Before Salt in the Wound:)*"] = "*(Antes de Sal en la Herida:)*",
    ["I hope so, Kimberly. I hope so."] = "Eso espero, Kimberly. Eso espero.",
    ["*(After Salt in the Wound:)*"] = "*(Después de Sal en la herida:)*",
    ["Perhaps they're already gone."] = "Quizás ya se hayan ido.",
    ["Thank you for retrieving the Grail! You shall long be remembered as one of the greatest heroes amongst the Knights of the Round Table!"] = "¡Gracias por recuperar el Grial! ¡Serás recordado durante mucho tiempo como uno de los mayores héroes entre los Caballeros de la Mesa Redonda!",
    ["Welcome, brave knight. I am always happy to see you back at my court. Please feel free to roam the castle and make use of the training grounds."] = "Bienvenido, valiente caballero. Siempre me alegro de verte de nuevo en mi corte. Siéntete libre de recorrer el castillo y utilizar los campos de entrenamiento.",
    ["You have chosen...poorly."] = "Has elegido... mal.",
    ["Excuse me?"] = "¿Perdón?",
    ["Sorry, I meant to say 'thank you'. Most refreshing."] = "Lo siento, quería decir \"gracias\". Lo más refrescante.",
    ["Are you sure that stuff is safe to drink?"] = "¿Estás seguro de que es seguro beber esas cosas?",
    ["Oh yes, Stankers' creations may be dangerous for those with weak constitutions, but, personally, I find them rather invigorating."] = "Oh, sí, las creaciones de Stankers pueden ser peligrosas para aquellos con constituciones débiles, pero, personalmente, las encuentro bastante estimulantes.",
    ["Hello again Bolren."] = "Hola de nuevo Bolren.",
    ["Well hello, it's good to see you again."] = "Bueno, hola, es un placer verte de nuevo.",
    ["I've lost my amulet."] = "He perdido mi amuleto.",
    ["Oh dear. Here, take another. We are truly indebted to you."] = "Dios mío. Toma, toma otro. Estamos realmente en deuda con usted.",
    ["You do not meet the requirements to start : 'The Path of Glouphrie'."] = "No cumples los requisitos para empezar: 'El Camino de Glouphrie'.",
    ["I think I know where Arposandra is now!"] = "¡Creo que ya sé dónde está Arposandra!",
    ["Really? Have you been there?"] = "¿En serio? ¿Has estado allí?",
    ["Not exactly. I've found a way in, although I can't open the vent to get in there yet."] = "No exactamente. Encontré una manera de entrar, aunque todavía no puedo abrir el respiradero para entrar.",
    ["So, you haven't actually been there. Well, I'm still not convinced that it's a real place. There's something about lost cities that gets explorers and adventurers obsessed."] = "Entonces, en realidad no has estado allí. Bueno, todavía no estoy convencido de que sea un lugar real. Hay algo en las ciudades perdidas que obsesiona a los exploradores y aventureros.",
    ["I'm not obsessed, but I *will* find a way in. Eventually."] = "No estoy obsesionado, pero *encontraré* una manera de entrar. Con el tiempo.",
    ["Of course you will."] = "Por supuesto que sí.",
    ["I found Arposandra!"] = "¡Encontré a Arposandra!",
    ["Really? You've actually been there?"] = "¿En serio? ¿De verdad has estado allí?",
    ["Briefly, yes. It really is a dangerous place."] = "Brevemente, sí. Realmente es un lugar peligroso.",
    ["I don't believe you! You've got to be joking."] = "¡No te creo! Tienes que estar bromeando.",
    ["Maybe, one day, you'll believe me."] = "Quizás algún día me creas.",
    ["Congratulations, human!"] = "¡Felicitaciones, humano!",
    ["[King Bolren has given you your next clue scroll!]"] = "[¡King Bolren te ha dado tu próximo pergamino de pistas!]",
    ["Thank you. I don't have any gnome cooks here. I should really do something about that."] = "Gracias. Aquí no tengo cocineros gnomos. Realmente debería hacer algo al respecto.",
    ["Hello King Lathas."] = "Hola King Lathas.",
    ["Adventurer, thank Saradomin or your arrival!"] = "¡Aventurero, gracias a Saradomin por tu llegada!",
    ["Have your scouts found a way through the mountains?"] = "¿Tus exploradores han encontrado un camino a través de las montañas?",
    ["Not quite, we found a path to where we expected to find the Well of Voyage, an ancient portal to the western mainland. However during recent times a cluster of cultists have settled there, run by a madman named Iban."] = "No del todo, encontramos un camino hacia donde esperábamos encontrar el Pozo del Viaje, un antiguo portal al continente occidental. Sin embargo, recientemente se ha establecido allí un grupo de cultistas, dirigidos por un loco llamado Iban.",
    ["*(Quest acceptance screen)*"] = "*(Pantalla de aceptación de misión)*",
    ["*Before obtaining the Letter from the Messenger*"] = "*Antes de obtener la Carta del Mensajero*",
    ["Well hello there traveller. The magi are still resurrecting the Well of Voyage, but I'll have word sent to you as soon as it's ready."] = "Bueno, hola viajero. Los magos todavía están resucitando el Pozo del Viaje, pero te avisaré tan pronto como esté listo.",
    ["Ok then, take care."] = "Ok, entonces, cuídate.",
    ["You too."] = "Tú también.",
    ["Good day my lord."] = "Buenos días mi señor.",
    ["Hello Player. I've got nothing for you right now."] = "Hola Player. No tengo nada para ti ahora mismo.",
    ["Good day."] = "Buenos días.",
    ["What are you doing here? All Mourners should know that if they need to contact me, they need to use the proper channels!"] = "¿Qué haces aquí? ¡Todos los dolientes deben saber que si necesitan comunicarse conmigo, deben utilizar los canales adecuados!",
    ["Sorry, I'm a new recruit."] = "Lo siento, soy un nuevo recluta.",
    ["Well do not let it happen again."] = "Bueno, no dejes que vuelva a suceder.",
    ["Hello, Your Highness!"] = "¡Hola, alteza!",
    ["Well, hello again Traveller! How are you?"] = "Bueno, ¡hola de nuevo, Viajero! ¿Cómo estás?",
    ["I'm good thanks, how's the tree?"] = "Estoy bien gracias, ¿cómo está el árbol?",
    ["Better than ever, thanks to you!"] = "¡Mejor que nunca, gracias a ti!",
    ["Hello there, King Narnode."] = "Hola, Rey Narnode.",
    ["Good of you to stop by, human."] = "Qué bueno que pasaste por aquí, humano.",
    ["How fares the kingdom today?"] = "¿Cómo le va al reino hoy?",
    ["Everything seems fine, as far as I can tell... I will let you know if there is trouble."] = "Todo parece estar bien, hasta donde sé... Te avisaré si hay algún problema.",
    ["Greetings, your majesty."] = "Saludos, majestad.",
    ["Well hello there. What do you want?"] = "Bueno, hola. ¿Qué deseas?",
    ["I am looking for a quest!"] = "¡Estoy buscando una misión!",
    ["Talk about Priest in Peril."] = "Habla sobre Sacerdote en peligro.",
    ["Ah, it's you again. Hello there."] = "Ah, eres tú otra vez. Hola.",
    ["Hello, Your Majesty. I am happy to report that the situation at the Temple of Paterdomus has been sorted. Misthalin's borders should once again be fully protected against the threats from Morytania."] = "Hola, Su Majestad. Me complace informarles que la situación en el Templo de Paterdomus se ha solucionado. Las fronteras de Misthalin deberían volver a estar completamente protegidas contra las amenazas de Morytania.",
    ["Excellent, excellent. The Kingdom of Misthalin is in your debt."] = "Excelente, excelente. El Reino de Misthalin está en deuda contigo.",
    ["In my debt? Does that mean you're going to give me fabulous rewards for my efforts?"] = "¿Estás en deuda conmigo? ¿Eso significa que me vas a dar fabulosas recompensas por mis esfuerzos?",
    ["Of course not; however, if it's rewards you're after, it occurs to me that you could be of even more service to the kingdom."] = "Por supuesto que no; sin embargo, si lo que buscas son recompensas, se me ocurre que podrías ser de aún más servicio para el reino.",
    ["Although, you might need a little more experience tending fires, first. If you're interested, come talk to me when you've had a bit more practice."] = "Aunque es posible que primero necesites un poco más de experiencia en el cuidado de incendios. Si estás interesado, ven a hablar conmigo cuando hayas practicado un poco más.",
    ["[You need to have at least 43 Firemaking to start All Fired Up.]"] = "[Necesitas tener al menos 43 Firemaking para iniciar All Fired Up.]",
    ["Greet the king."] = "Saluda al rey.",
    ["What do you want to do?{{anchor"] = "¿Qué quieres hacer?{{anchor",
    ["Talk about River of Blood."] = "Hablando de Río de Sangre.",
    ["Varrock has survived many attacks since its founding, but I'm thankful this vampyre situation was resolved peacefully."] = "Varrock ha sobrevivido a muchos ataques desde su fundación, pero estoy agradecido de que esta situación de vampyre se haya resuelto pacíficamente.",
    ["For now, at least. The brokered peace may not hold."] = "Al menos por ahora. Es posible que la paz negociada no se mantenga.",
    ["And if it doesn't, we shall deal with the situation. I am taking steps that, should it not hold, Varrock will be in a much stronger position to deal with it."] = "Y si no es así, nos ocuparemos de la situación. Estoy tomando medidas que, si no se cumplen, Varrock estará en una posición mucho más fuerte para afrontarlo.",
    ["For example, Aeonisig is offering aid to the citizens of Meiyerditch in exchange for shipments of blisterwood."] = "Por ejemplo, Aeonisig ofrece ayuda a los ciudadanos de Meiyerditch a cambio de envíos de blisterwood.",
    ["Truth be told, my worries have moved on to other matters. If it's not one thing, it's another, so they say."] = "La verdad es que mis preocupaciones han pasado a otros asuntos. Si no es una cosa, es otra, eso dicen.",
    ["Such as?"] = "¿Por ejemplo?",
    ["It appears that your intervention at the Salve targets only vampyres. Werewolves, on the other hand, are free to cross."] = "Parece que su intervención en Salve está dirigida únicamente a vampyres. Los hombres lobo, por otro lado, son libres de cruzar.",
    ["The reports state that they have effectively declared independence from the vampyres. We shall need to keep a close watch on what they do with this newfound freedom."] = "Los informes afirman que efectivamente han declarado su independencia de vampyres. Tendremos que vigilar de cerca lo que hacen con esta nueva libertad.",
    ["Replay Cutscene - Would you like to replay the Siege of Paterdomus?"] = "Repetir escena: ¿Te gustaría volver a reproducir el asedio de Paterdomus?",
    ["Cancel"] = "Cancelar",
    ["Ask about the beacons."] = "Pregunta por las balizas.",
    ["Do you have anything of importance to say?"] = "¿Tienes algo importante que decir?",
    ["...Not really."] = "...En realidad no.",
    ["You will have to excuse me, I am very busy."] = "Tendrás que disculparme, estoy muy ocupado.",
    ["I must keep a fixed eye on Morytania to the east."] = "Debo mantener un ojo fijo en Morytania al este.",
    ["Or both eyes, perhaps?"] = "¿O quizás ambos ojos?",
    ["Indeed, we cannot all be heroes, wandering from one crisis to another."] = "De hecho, no todos podemos ser héroes y pasar de una crisis a otra.",
    ["Ever since Kara-Meir and her friends became famous, adventuring has become a career of choice amongst our youth. Yet, people forget that her tale is a cautionary one."] = "Desde que Kara-Meir y sus amigos se hicieron famosos, las aventuras se han convertido en una carrera preferida entre nuestros jóvenes. Sin embargo, la gente olvida que su historia es una advertencia.",
    ["Why? What happened to her?"] = "¿Por qué? ¿Qué pasó con ella?",
    ["She withheld important information about one of her associates, and it very nearly led to disaster for all of us: every man, woman and child."] = "Ocultó información importante sobre uno de sus asociados, y eso estuvo a punto de provocar un desastre para todos nosotros: cada hombre, mujer y niño.",
    ["And?"] = "¿Y?",
    ["And what? I have spent enough time on you, adventurer. You will have to excuse me, I have a kingdom to run."] = "¿Y qué? He dedicado suficiente tiempo a ti, aventurero. Tendrás que disculparme, tengo un reino que administrar.",
    ["I was wondering if you could tell me more about the beacons."] = "Me preguntaba si podría contarme más sobre las balizas.",
    ["Of course. What would you like to know?"] = "Por supuesto. ¿Qué te gustaría saber?",
    ["I'm here to claim my reward."] = "Estoy aquí para reclamar mi recompensa.",
    ["I'm here to claim my reward!"] = "¡Estoy aquí para reclamar mi recompensa!",
    ["For keeping six beacons alight simultaneously, I present you with the Ring of Fire."] = "Para mantener seis balizas encendidas simultáneamente, te presento el Anillo de Fuego.",
    ["Thank you very much!"] = "¡Muchas gracias!",
    ["Lost the Ring of Fire have you? Luckily I seem to have a spare."] = "¿Perdiste el Anillo de Fuego, verdad? Por suerte parece que tengo uno de repuesto.",
    ["Hmm, you seem to have misplaced your Flame Gloves, good thing we have more!"] = "Hmm, parece que has extraviado tus guantes Flame, ¡qué bueno que tenemos más!",
    ["This recently turned up in the lost and found, your Inferno Adze."] = "Esto apareció recientemente en el objeto perdido y encontrado, tu Inferno Adze.",
    ["Thank you again, Player. Misthalin is truly in your debt."] = "Gracias de nuevo, Player. Misthalin está verdaderamente en deuda contigo.",
    ["Is there anything else you'd like to ask me?"] = "¿Hay algo más que quieras preguntarme?",
    ["What else needs to be done to test the beacon network?"] = "¿Qué más hay que hacer para probar la red de balizas?",
    ["What *doesn't* need to be done is more like it! We need to make sure the entire beacon network is as robust as possible."] = "¡Lo que *no* es necesario hacer es más bien! Necesitamos asegurarnos de que toda la red de balizas sea lo más sólida posible.",
    ["I'd be extremely grateful if you'd help us by trying to keep as many beacons alight simultaneously as you possibly can."] = "Le agradecería mucho que nos ayudara intentando mantener encendidas tantas balizas simultáneamente como sea posible.",
    ["How does that help?"] = "¿Cómo ayuda eso?",
    ["Well, obviously, it helps us verify that all the beacons are in good working order, of course."] = "Bueno, obviamente, nos ayuda a verificar que todas las balizas estén en buen estado de funcionamiento, por supuesto.",
    ["The more testing, the better, Player. I have generous rewards for you if you manage to keep six, ten and all fourteen beacons alight simultaneously."] = "Cuantas más pruebas, mejor, Player. Tengo generosas recompensas para ti si logras mantener seis, diez y catorce balizas encendidas simultáneamente.",
    ["However, I'd be positively delighted if you continued on testing them day and night, over and over, relentlessly and without ceasing!"] = "Sin embargo, estaría encantado si continuaras probándolos día y noche, una y otra vez, sin descanso y sin cesar.",
    ["I see this means a great deal to you."] = "Veo que esto significa mucho para ti.",
    ["Oh, it does. The safety of one's kingdom is of paramount importance, you know."] = "Oh, así es. La seguridad del reino de uno es de suma importancia, ¿sabes?",
    ["Do you have any other questions for me, Player?"] = "¿Tienes alguna otra pregunta para mí, Player?",
    ["Tell me about rewards."] = "Cuéntame sobre las recompensas.",
    ["Talk to me about rewards."] = "Háblame sobre las recompensas.",
    ["Ahem, well. It's all well and good having a network of beacons, but it's important to make sure it works properly...and remains working. Thus, I'm willing to offer various rewards if you are willing to help me out. There are rewards available for keeping six, ten and all fourteen beacons alight simultaneously."] = "Ejem, bueno. Está muy bien tener una red de balizas, pero es importante asegurarse de que funcione correctamente... y siga funcionando. Por lo tanto, estoy dispuesto a ofrecer varias recompensas si estás dispuesto a ayudarme. Hay recompensas disponibles por mantener encendidas seis, diez y catorce balizas simultáneamente.",
    ["For keeping six beacons alight, I'm prepared to grant you a ring that will aid you in Firemaking."] = "Por mantener seis balizas encendidas, estoy dispuesto a otorgarte un anillo que te ayudará en Firemaking.",
    ["I've granted you the Ring of Fire for keeping six beacons alight."] = "Te he concedido el Anillo de Fuego por mantener encendidas seis balizas.",
    ["For keeping ten beacons alight, I will grant you a pair of gloves that will work in combination with the ring."] = "Por mantener diez balizas encendidas, te daré un par de guantes que funcionarán en combinación con el anillo.",
    ["You've already claimed the Flame Gloves for keeping ten beacons alight."] = "Ya has reclamado los guantes de llamas por mantener encendidas diez balizas.",
    ["For keeping all fourteen beacons alight, well, I have the magnificent Inferno Adze - a fire-enchanting tool for both Woodcutting and Mining - that I'm prepared to part with. I think you'll find it of great use."] = "Para mantener encendidas las catorce balizas, bueno, tengo el magnífico Inferno Adze, una herramienta de encantamiento de fuego tanto para Woodcutting como para Mining, de la que estoy dispuesto a desprenderme. Creo que lo encontrarás de gran utilidad.",
    ["For keeping all fourteen beacons alight simultaneously, you've been granted the Inferno Adze. Is there anything else?"] = "Por mantener las catorce balizas encendidas simultáneamente, se te ha otorgado el Inferno Adze. ¿Hay algo más?",
    ["I'd like a few more details, please."] = "Me gustaría tener más detalles, por favor.",
    ["Why have you created all these beacons?"] = "¿Por qué has creado todas estas balizas?",
    ["You've already had a glimpse of the dangers we face from Morytania. Further dangers threaten from the Wilderness in the north."] = "Ya has vislumbrado los peligros que enfrentamos desde Morytania. Más peligros amenazan desde el Wilderness en el norte.",
    ["Because of these mounting threats, the southern kingdoms have banded together to take action."] = "Debido a estas crecientes amenazas, los reinos del sur se han unido para tomar medidas.",
    ["We have constructed a network of beacons that stretch all the way from the source of the River Salve to the northwestern-most edge of the Wilderness."] = "Hemos construido una red de balizas que se extiende desde el nacimiento del río Salve hasta el extremo noroeste del Wilderness.",
    ["Should there be any threat from these uncivilised lands, we'll be able to spread the word as fast as the light of the flames can travel."] = "Si hubiera alguna amenaza proveniente de estas tierras incivilizadas, podremos correr la voz tan rápido como la luz de las llamas pueda viajar.",
    ["How will these beacons work in an emergency?"] = "¿Cómo funcionarán estas balizas en caso de emergencia?",
    ["Simple. I've equipped each fire tender with a stockpile of gnomish firelighters. In the case of a real emergency, the beacons will burn with coloured flame."] = "Sencillo. He equipado a cada bombero con una reserva de encendedores gnomos. En caso de una emergencia real, las balizas arderán con llamas de colores.",
    ["I see. I don't suppose you have any extra firelighters lying around that you want to get rid of, do you?"] = "Ya veo. Supongo que no tendrás ningún encendedor extra por ahí del que quieras deshacerte, ¿verdad?",
    ["Don't bother me with idle chatter. Is there anything else?"] = "No me molestes con charlas ociosas. ¿Hay algo más?",
    ["Who are these fire tenders?"] = "¿Quiénes son estos bomberos?",
    ["These are special recruits from all around the civilised world. They've been carefully selected for their sharp eyes and long-distance vision."] = "Estos son reclutas especiales de todo el mundo civilizado. Han sido cuidadosamente seleccionados por sus ojos agudos y su visión de larga distancia.",
    ["Not to mention their dedication and reliability. We couldn't entrust such an important job to just anyone, you know!"] = "Sin mencionar su dedicación y confiabilidad. No podíamos confiar un trabajo tan importante a cualquiera, ¿sabes?",
    ["I don't have anything more to talk about, actually."] = "En realidad, no tengo nada más de qué hablar.",
    ["Then begone; I am a busy man."] = "Entonces vete; Soy un hombre ocupado.",
    ["Is there a reason for you being here?"] = "¿Hay alguna razón para que estés aquí?",
    ["Well, I'm on a Treasure Trail."] = "Bueno, estoy siguiendo la pista del tesoro.",
    ["Oh! Good, then you can answer this question for me."] = "¡Oh! Bien, entonces puedes responderme esta pregunta.",
    ["[King Roald has given you a challenge scroll!]"] = "[¡King Roald te ha dado un pergamino de desafío!]",
    ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
    ["Err, that sounds a little wrong to me."] = "Err, eso me suena un poco mal.",
    ["[King Roald has given you another clue scroll!]"] = "[¡King Roald te ha dado otro pergamino de pistas!]",
    ["Ask about the kingdom."] = "Pregunta sobre el reino.",
    ["Greetings, your majesty. How fares the kingdom?"] = "Saludos, majestad. ¿Cómo le va al reino?",
    ["It's terrible! Have you not heard? Zamorak and Saradomin are fighting near Lumbridge! They've destroyed much of the castle! That's royal property! I'm very annoyed."] = "¡Es terrible! ¿No lo has oído? ¡Zamorak y Saradomin están peleando cerca de Lumbridge! ¡Han destruido gran parte del castillo! ¡Eso es propiedad real! Estoy muy molesto.",
    ["I've tasked Duke Horacio with sorting out the problem, and he claims he needs more troops."] = "Le he encargado a Duke Horacio que solucione el problema y él afirma que necesita más tropas.",
    ["So as you can see I'm very busy right now. Please don't waste my time."] = "Como puedes ver, estoy muy ocupado en este momento. Por favor, no me hagas perder el tiempo.",
    ["The kingdom is at peace again after the battle of Lumbridge! I'm glad to see Saradomin and Zamorak are both gone from there now."] = "¡El reino vuelve a estar en paz después de la batalla de Lumbridge! Me alegra ver que Saradomin y Zamorak ya no están allí.",
    ["I really hope that sort of thing doesn't happen again in my kingdom! There is a lot to tidy up!"] = "¡Realmente espero que ese tipo de cosas no vuelvan a suceder en mi reino! ¡Hay mucho que ordenar!",
    ["Ask about the protected tree."] = "Pregunta por el árbol protegido.",
    ["Your majesty, I bring troubling news. The tree you are protecting near Varrock's west bank has become diseased!"] = "Su majestad, traigo noticias preocupantes. ¡El árbol que estás protegiendo cerca de la ribera occidental de Varrock ha enfermado!",
    ["Thank you for bringing this to my attention. I have already sent for a master gardener to restore it."] = "Gracias por informarme sobre esto. Ya he mandado llamar a un maestro jardinero para restaurarlo.",
    ["Oh good. I'd hate for anything else to happen to that tree."] = "Oh, bien. Odiaría que le pasara algo más a ese árbol.",
    ["Your majesty, I bring troubling news. The tree you are protecting near Varrock's west bank has died!"] = "Su majestad, traigo noticias preocupantes. ¡El árbol que estás protegiendo cerca de la ribera occidental de Varrock ha muerto!",
    ["How did this happen? I sent for a master gardener to restore it over a week ago! He's got some explaining to do. Once he shows up, at least."] = "¿Cómo sucedió esto? ¡Mandé llamar a un maestro jardinero para restaurarlo hace más de una semana! Tiene algunas explicaciones que dar. Una vez que él aparezca, al menos.",
    ["Another tree gone..."] = "Otro árbol desaparecido...",
    ["Greetings, your majesty. How fares the tree west of Varrock bank?"] = "Saludos, majestad. ¿Cómo le va al árbol al oeste del banco Varrock?",
    ["I received reports that the tree had died. I visited the tree myself and have seen a healthy tree growing."] = "Recibí informes de que el árbol había muerto. Yo mismo visité el árbol y vi crecer un árbol sano.",
    ["Yes, that is because Farmer Jimbo replaced the dead tree!"] = "Sí, ¡eso es porque Farmer Jimbo reemplazó el árbol muerto!",
    ["Silence! I'll hear no more of this rumour-mongering."] = "¡Silencio! No volveré a oír más rumores sobre estos rumores.",
    ["You are part of the problem."] = "Eres parte del problema.",
    ["You are part of the solution."] = "Eres parte de la solución.",
    ["This isn't working out..."] = "Esto no está funcionando...",
    ["You should go check out the crates of explosives near the wizards."] = "Deberías ir a revisar las cajas de explosivos cerca de los magos.",
    ["Alright."] = "Muy bien.",
    ["I have decided to accept our new slime overlord."] = "He decidido aceptar a nuestro nuevo señor supremo del limo.",
    ["GLOOP GLOOP GLOOP!"] = "¡GLOOP GLOOP GLOOP!",
    ["Would you like to try and communicate with King Slime?"] = "¿Te gustaría intentar comunicarte con King Slime?",
    ["You should try and deal with the mini slimes today."] = "Deberías intentar lidiar con los mini slimes hoy.",
    ["GLOOP GLOOP GLOOP GLOOP GLOOP!"] = "¡GLOOP GLOOP GLOOP GLOOP GLOOP!",
    ["Do you have any final words for King Slime?"] = "¿Tiene alguna última palabra para King Slime?",
    ["It's about slime you left us alone!"] = "¡Se trata de limo que nos dejaste en paz!",
    ["You should help the wizards by channelling the portal!"] = "¡Deberías ayudar a los magos canalizando el portal!",
    ["I have prepared a poem."] = "He preparado un poema.",
    ["Roses are red. We are almost free. The question we're all asking... Where is the tree?"] = "Las rosas son rojas. Somos casi libres. La pregunta que todos nos hacemos... ¿Dónde está el árbol?",
    ["I've enjoyed our time together."] = "He disfrutado nuestro tiempo juntos.",
    ["I've enjoyed our time together. Don't forget to write!"] = "He disfrutado nuestro tiempo juntos. ¡No olvides escribir!",
    ["Thank you for your work in bringing back peace to these islands, [Fremennik Name]."] = "Gracias por tu trabajo para devolver la paz a estas islas, [Fremennik Name].",
    ["I hear that the Etceterians have also pledged to give you some of their resources, as thanks for preventing war once again."] = "He oído que los etceterianos también se han comprometido a darte algunos de sus recursos, como agradecimiento por evitar la guerra una vez más.",
    ["How is the kingdom faring?"] = "¿Cómo le va al reino?",
    ["Everything is fine, Your Majesty."] = "Todo está bien, Su Majestad.",
    ["Remember, speak to Ghrim if you require assistance."] = "Recuerda, habla con Ghrim si necesitas ayuda.",
    ["Do you really think you can skip 'Pieces of Hate'? You can't. There is a swashbuckling grind against which your soul shall be lathed. And this is meow cat."] = "¿De verdad crees que puedes saltarte 'Piezas de odio'? No puedes. Hay una rutina de capa y espada contra la cual tu alma será torneada. Y este es el gato maullido.",
    ["Get out of here, outerlander!"] = "¡Fuera de aquí, extranjero!",
    ["The barbarian village. Go away."] = "El pueblo bárbaro. Irse.",
    ["My name is Kjell. Go away."] = "Mi nombre es Kjell. Irse.",
    ["What is in this hut that you're guarding?"] = "¿Qué hay en esta cabaña que estás custodiando?",
    ["Nothing yet. Once there is, no one will get in or out! Go away!"] = "Nada todavía. Una vez que lo haya, ¡nadie entrará ni saldrá! ¡Irse!",
    ["Goodbye then."] = "Adiós entonces.",
    ["*(Kjell opens with one of the following lines:)*"] = "*(Kjell se abre con una de las siguientes líneas:)*",
    ["...love you like the stars above..."] = "...te amo como las estrellas de arriba...",
    ["...fall for pretty strangers..."] = "...enamórate de lindas desconocidas...",
    ["...but I'd do anything for you..."] = "...pero haría cualquier cosa por ti...",
    ["...there's a place for us..."] = "...hay un lugar para nosotros...",
    ["...you exploded into my heart..."] = "...explotaste en mi corazón...",
    ["...I dreamed your dream for you..."] = "...Soñé tu sueño para ti...",
    ["...fall for chains of gold..."] = "...enamórate de las cadenas de oro...",
    ["...when you gonna realise..."] = "...cuando te vas a dar cuenta...",
    ["Blast!"] = "¡Explosión!",
    ["Having trouble there?"] = "¿Tienes problemas allí?",
    ["I don't need the advice of an outerlander."] = "No necesito el consejo de un extranjero.",
    ["This music isn't very restful."] = "Esta música no es muy relajante.",
    ["Get out of here!"] = "¡Fuera de aquí!",
    ["Maybe you should take some lessons."] = "Quizás deberías tomar algunas lecciones.",
    ["I'll leave you in peace."] = "Te dejaré en paz.",
    ["Kebabs! Get your kebabs here! One gold each!"] = "¡Kebabs! ¡Consigue tus kebabs aquí! ¡Un oro cada uno!",
    ["Sure, one kebab please."] = "Claro, un kebab, por favor.",
    ["You have no money, effendi."] = "No tienes dinero, effendi.",
    ["I'm looking for a drunken dwarf."] = "Estoy buscando un drunken dwarf.",
    ["Just go out in the streets, they can't be hard to find!"] = "Simplemente sal a la calle, ¡no puede ser difícil encontrarlos!",
    ["No, a specific drunken dwarf, he keeps harassing me."] = "No, un drunken dwarf específico, sigue acosándome.",
    ["That's still not very helpful. But let me see. There is one particularly drunken dwarf just to the northeast of here."] = "Eso todavía no es muy útil. Pero déjame ver. Hay uno particularmente drunken dwarf justo al noreste de aquí.",
    ["He's scaring away my customers, he says there's something wrong with my kebabs. Quite annoying fellow."] = "Está ahuyentando a mis clientes, dice que algo anda mal con mis kebabs. Un tipo bastante molesto.",
    ["I don't think that's who I mean."] = "No creo que me refiero a eso.",
    ["Well, he does have a relative who wanders all over Gielinor. Comes back from time to time to buy more kebabs. Don't see him very often though."] = "Bueno, tiene un pariente que deambula por todo Gielinor. Vuelve de vez en cuando para comprar más kebabs. Aunque no lo veo muy a menudo.",
    ["Do you think I'll have any chance of catching him here?"] = "¿Crees que tendré alguna posibilidad de atraparlo aquí?",
    ["I think he was back here quite recently, so I doubt he'll be back any time soon."] = "Creo que estuvo aquí hace poco, así que dudo que regrese pronto.",
    ["I thought you would know plenty!"] = "¡Pensé que sabrías muchas cosas!",
    ["How do you mean?"] = "¿Qué quieres decir?",
    ["Oh come on! You in the Laughing Miner? The whole city knows about you and your dwarven drinking buddies!"] = "¡Oh, vamos! ¿Estás en el Minero Risueño? ¡Toda la ciudad sabe de ti y de tus compañeros de bebida enanos!",
    ["Right, right."] = "Bien, bien.",
    ["Do you have any quests?"] = "¿Tienes alguna misión?",
    ["Not really! I have a steady supply of meat coming in through the carts and I don't really need anything else!"] = "¡En realidad no! ¡Tengo un suministro constante de carne que llega a través de los carros y realmente no necesito nada más!",
    ["Hey, do you mind? That's my property!"] = "Oye, ¿te importa? ¡Esa es mi propiedad!",
    ["Hey, what are you trying to put into my kebabs? Get away from there, get your own fireplace!"] = "Oye, ¿qué intentas poner en mis kebabs? ¡Aléjate de allí y consigue tu propia chimenea!",
    ["Hello Klank."] = "Hola Klank.",
    ["Hello again adventurer, so you're still around?"] = "Hola de nuevo aventurero, ¿todavía estás por aquí?",
    ["Still here!"] = "¡Aún aquí!",
    ["Have you anymore"] = "¿Tienes más?",
    ["Have you any more gauntlets?"] = "¿Tienes más guanteletes?",
    ["Well..yes, but they're not cheap to make. I'll have to sell you a pair..."] = "Bueno... sí, pero no son baratos de hacer. Tendré que venderte un par...",
    ["How much?"] = "¿Cuánto?",
    ["5000, you must be joking!"] = "5000, ¡debes estar bromeando!",
    ["5,000, you must be joking!"] = "5000, ¡debes estar bromeando!",
    ["We don't joke down here friend..."] = "Aquí no bromeamos amigo...",
    ["Okay then, I'll take a pair."] = "Está bien, entonces tomaré un par.",
    ["You give Klank 5000 coins..."] = "Le das Klank 5000 coins...",
    ["There you go... I hope they help."] = "Ahí lo tienes... Espero que te ayuden.",
    ["I'll see you around Klank."] = "Nos vemos en Klank.",
    ["Sorry, I can't sell them any cheaper than that."] = "Lo siento, no puedo venderlos más baratos que eso.",
    ["Take care Klank."] = "Cuídate Klank.",
    ["You too adventurer..."] = "Tú también aventurero...",
    ["Welcome to NovtumberFest! Don't drink and dive!"] = "¡Bienvenido a NovtumberFest! ¡No bebas y bucees!",
    ["What's this all about?"] = "¿De qué se trata todo esto?",
    ["Glad you asked!"] = "¡Me alegra que hayas preguntado!",
    ["In here you can improve your constitution by having a run around the track."] = "Aquí puedes mejorar tu constitución corriendo por la pista.",
    ["Is that all? That sounds easy."] = "¿Eso es todo? Eso suena fácil.",
    ["There's a little more to it than that. Our friend inside will explain the details."] = "Hay algo más que eso. Nuestro amigo de dentro te explicará los detalles.",
    ["Cough... Hey, over here."] = "Cough... Oye, por aquí.",
    ["Who are you? What are you doing here in the snow?"] = "¿Quién eres? ¿Qué haces aquí en la nieve?",
    ["My name is...Sir Gerry. I am...a member of a secret...society of knights. My time is short and I need...your help."] = "Mi nombre es... Sir Gerry. Soy... miembro de una... sociedad secreta de caballeros. Mi tiempo es corto y necesito...tu ayuda.",
    ["A secret society of knights? What a surprise! Is there an old charter or decree that says if you're a knight you have to belong to a secret order?"] = "¿Una sociedad secreta de caballeros? ¡Qué sorpresa! ¿Existe algún estatuto o decreto antiguo que diga que si eres caballero debes pertenecer a una orden secreta?",
    ["I'm sorry, my friend... I do not understand your meaning. Please, time is short... Take this scroll to Sir Tiffy. You will find him in Falador park... You should not...read it... It contains information for his eyes only."] = "Lo siento, amigo mío... No entiendo lo que quieres decir. Por favor, el tiempo apremia... Llévale este pergamino a Sir Tiffy. Lo encontrarás en el parque Falador... No deberías... leerlo... Contiene información sólo para sus ojos.",
    ["A secret society of knights? You don't mean the Temple Knights, do you?"] = "¿Una sociedad secreta de caballeros? No te refieres a los Caballeros del Templo, ¿verdad?",
    ["Yes! Praise Saradomin! You...have been sent in...my hour of need. Please, take...this scroll to Sir Tiffy in Falador park... You should not...read it."] = "¡Sí! ¡Alabado sea Saradomin! Tú... has sido enviado en... mi hora de necesidad. Por favor, lleva... este pergamino a Sir Tiffy en el parque Falador... No deberías... leerlo.",
    ["I'm afraid I'm already carrying everything that I possibly can."] = "Me temo que ya estoy cargando con todo lo que puedo.",
    ["I beg you ... drop something you don't need. This is of utmost importance... I will conserve what little strength I have and await your return... Please hurry!"] = "Te lo ruego... deja caer algo que no necesites. Esto es de suma importancia... Conservaré las pocas fuerzas que tengo y esperaré tu regreso... ¡Por favor, date prisa!",
    ["[The knight hands you a scroll.]"] = "[El caballero te entrega un pergamino.]",
    ["He's still alive, but in no condition to talk. He appears to be almost unconscious."] = "Todavía está vivo, pero no está en condiciones de hablar. Parece estar casi inconsciente.",
    ["You find some handwritten notes, but your hands are too full to pick them up."] = "Encuentra algunas notas escritas a mano, pero tiene las manos demasiado ocupadas para cogerlas.",
    ["[You find some handwritten notes on the knight.]"] = "[Encuentras algunas notas escritas a mano sobre el caballero.]",
    ["You find nothing of value on the knight."] = "No encuentras nada de valor sobre el caballero.",
    ["Hi, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
    ["I'm a Void Knight, one of the order of Guthix. We are warriors of balance who do Guthix's work in Gielinor."] = "Soy un Void Knight, uno de la orden de Guthix. Somos guerreros del equilibrio que hacemos el trabajo de Guthix en Gielinor.",
    ["Wow, can I join?"] = "Vaya, ¿puedo unirme?",
    ["Entry is strictly invite only, however we do need help continuing Guthix's work."] = "La entrada es estrictamente solo por invitación, sin embargo, necesitamos ayuda para continuar con el trabajo de Guthix.",
    ["What kind of work?"] = "¿Qué tipo de trabajo?",
    ["Ah well you see we try to keep Gielinor as Guthix intended, it's very challenging. Actually we've been having some problems recently, maybe you could help us?"] = "Ah, bueno, verás, intentamos mantener Gielinor como pretendía Guthix, es un gran desafío. De hecho, hemos tenido algunos problemas recientemente, ¿quizás podrías ayudarnos?",
    ["What's the problem?"] = "¿Cuál es el problema?",
    ["Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "Bueno, el orden ha disminuido bastante con los años, es un proceso muy largo aprender las habilidades de un Void Knight. Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar, y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
    ["How can I help?"] = "¿Cómo puedo ayudar?",
    ["We send launchers from our outpost to the nearby islands. If you go and wait in the lander there that'd really help."] = "Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas en el módulo de aterrizaje, eso sería de gran ayuda.",
    ["Sorry, but I can't."] = "Lo siento, pero no puedo.",
    ["What's 'Gielinor'?"] = "¿Qué es 'Gielinor'?",
    ["It is the name that Guthix gave to this world, so we honour him with its use."] = "Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
    ["I'd rather not, sorry."] = "Preferiría no hacerlo, lo siento.",
    ["Good luck with that."] = "Buena suerte con eso.",
    ["Uh huh, sure."] = "Ajá, claro.",
    ["This is our outpost. From here we send launches out to the nearby islands to beat back the invaders."] = "Este es nuestro puesto de avanzada. Desde aquí enviamos lanchas a las islas cercanas para hacer retroceder a los invasores.",
    ["What invaders?"] = "¿Qué invasores?",
    ["Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
    ["I'm fine, thanks."] = "Estoy bien, gracias.",
    ["Hmm, if we were to deploy in this formation-"] = "Hmm, si tuviéramos que desplegarnos en esta formación-",
    ["Erm, excuse me?"] = "Erm, ¿disculpa?",
    ["Woah! Don't sneak up on me like that!"] = "¡Guau! ¡No me acerques así!",
    ["I was standing right here!"] = "¡Estaba parado justo aquí!",
    ["Yes, yes. Can I help you with something?"] = "Sí, sí. ¿Puedo ayudarte con algo?",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["This is the Conquest training facility. If you want to learn more, best speak with Captain Ethar, to my right. He's more of a talker."] = "Este es el centro de entrenamiento de Conquest. Si quieres saber más, mejor habla con Captain Ethar, a mi derecha. Es más hablador.",
    ["I help organise recruits' forces so they can take them into Conquest training exercises."] = "Ayudo a organizar las fuerzas de los reclutas para que puedan participar en ejercicios de entrenamiento de Conquista.",
    ["I see."] = "Ya veo.",
    ["Can I help you with anything else?"] = "¿Puedo ayudarte con algo más?",
    ["How do I recruit forces?"] = "¿Cómo recluto fuerzas?",
    ["There are two steps to recruiting your forces. First, you form a squad; second, you choose which Commands to take with you."] = "Hay dos pasos para reclutar tus fuerzas. Primero, formas un escuadrón; en segundo lugar, eliges qué comandos llevar contigo.",
    ["How does that work?"] = "¿Cómo funciona eso?",
    ["I can help you with both steps. I'm the person to talk to if you want to select troops and Commands for a Conquest."] = "Puedo ayudarte con ambos pasos. Soy la persona con quien debes hablar si quieres seleccionar tropas y comandos para una conquista.",
    ["There are several different types of troop, each with their own strengths and weaknesses."] = "Hay varios tipos diferentes de tropas, cada una con sus propias fortalezas y debilidades.",
    ["Bear in mind that powerful troops cost more. You must consider this when choosing the troops for your squad."] = "Ten en cuenta que las tropas poderosas cuestan más. Debes tener esto en cuenta a la hora de elegir las tropas para tu escuadrón.",
    ["Can you give me an example?"] = "¿Puedes darme un ejemplo?",
    ["Well, you could recruit several smaller troops, such as Scouts, for the cost of a larger trooper, such as a Knight."] = "Bueno, podrías reclutar varias tropas más pequeñas, como Exploradores, por el costo de un soldado más grande, como un Caballero.",
    ["So, how much is this going to cost me, recruiting these troops?"] = "Entonces, ¿cuánto me va a costar reclutar estas tropas?",
    ["Oh don't worry about your bank balance, you don't need to 'pay' anything. This is just a training exercise, recruit."] = "Oh, no te preocupes por tu saldo bancario, no necesitas \"pagar\" nada. Esto es sólo un ejercicio de entrenamiento, recluta.",
    ["We have assigned the various troops an arbitrary resource cost, just to simulate the expense of maintaining them in the field."] = "Hemos asignado a las distintas tropas un costo de recursos arbitrario, solo para simular el gasto de mantenerlas en el campo.",
    ["It's up to you to decide how you wish to balance your squad based on their cost."] = "Depende de ti decidir cómo deseas equilibrar tu equipo en función de su costo.",
    ["What about if some of my troops fall in battle...how do I go about replacing them?"] = "¿Qué pasa si algunas de mis tropas caen en batalla... cómo hago para reemplazarlas?",
    ["We're not about to go killing off our own forces! Remember, this is just a training exercise."] = "¡No vamos a matar a nuestras propias fuerzas! Recuerde, esto es sólo un ejercicio de entrenamiento.",
    ["Troops defeated in combat will simply be removed from the Conquest and will be ready to fight again when you face a new opponent."] = "Las tropas derrotadas en combate simplemente serán eliminadas de la Conquista y estarán listas para luchar nuevamente cuando te enfrentes a un nuevo oponente.",
    ["Right, I think I understand."] = "Bien, creo que lo entiendo.",
    ["Great! Did you want to take a look at the recruitment options now?"] = "¡Genial! ¿Querías echar un vistazo a las opciones de contratación ahora?",
    ["Here, take a look."] = "Aquí, echa un vistazo.",
    ["Very well. Was there anything else I could help you with?"] = "Muy bien. ¿Había algo más en lo que pudiera ayudarte?",
    ["How do I deploy forces?"] = "¿Cómo despliego fuerzas?",
    ["I can help you to develop a formation, organising the positions of your troops in a Conquest."] = "Puedo ayudarte a desarrollar una formación, organizando las posiciones de tus tropas en una Conquista.",
    ["Once you have recruited troops for your squad, you can come and see me to organise where - and in what formation - they are deployed on the battlefield."] = "Una vez que hayas reclutado tropas para tu escuadrón, puedes venir a verme para organizar dónde y en qué formación se desplegarán en el campo de batalla.",
    ["Would you like to try it now?"] = "¿Te gustaría probarlo ahora?",
    ["Could you set me up with the default squad?"] = "¿Podrías configurarme con el equipo predeterminado?",
    ["Very well, just let me make the arrangements here..."] = "Muy bien, sólo déjame hacer los arreglos aquí...",
    ["There we are, you should be all set to go now."] = "Ahí estamos, ya deberías estar listo para comenzar.",
    ["I'd like to spend some of my Commendations."] = "Me gustaría gastar algunos de mis elogios.",
    ["Certainly."] = "Por supuesto.",
    ["Ah, hello again. Can I help you with something?"] = "Ah, hola de nuevo. ¿Puedo ayudarte con algo?",
    ["Koftik doesn't seem interested in talking."] = "Koftik no parece interesado en hablar.",
    ["Hello Koftik."] = "Hola Koftik.",
    ["Hello Adventurer, how's things?"] = "Hola Aventurero, ¿cómo van las cosas?",
    ["Not bad, yourself?"] = "¿No estás mal, verdad?",
    ["I'm good... just keeping an eye out."] = "Estoy bien... solo estoy atento.",
    ["Hello Player. How's things?"] = "Hola Player. ¿Cómo van las cosas?",
    ["I got pretty hurt getting here. These traps don't get any easier."] = "Me dolió mucho llegar aquí. Estas trampas no son más fáciles.",
    ["Nope, they don't. Here eat this, it should help."] = "No, no es así. Toma, come esto, debería ayudar.",
    ["Thanks Koftik."] = "Gracias Koftik.",
    ["No problem."] = "No hay problema.",
    ["These traps don't get any easier. But I'm alright, thanks."] = "Estas trampas no pueden ser más fáciles. Pero estoy bien, gracias.",
    ["Good to hear."] = "Es bueno escucharlo.",
    ["Underground Pass tours! Solve fiendish puzzles beneath the mountains! See Iban's throne room!"] = "¡Visitas Underground Pass! ¡Resuelve acertijos diabólicos bajo las montañas! ¡Vea la sala del trono de Iban!",
    ["Oh, hello, Player. Now that the Dark Lord is defeated, I'm trying to turn my cave guide skills into a new business."] = "Ah, hola, Player. Ahora que el Señor Oscuro ha sido derrotado, estoy intentando convertir mis habilidades de guía de cuevas en un nuevo negocio.",
    ["I haven't found anyone interested yet, though."] = "Aunque todavía no he encontrado a nadie interesado.",
    ["Hi, can I help you?"] = "Hola, ¿puedo ayudarte?",
    ["Keep your voice down! This is a library!"] = "¡Baja la voz! ¡Esto es una biblioteca!",
    ["*whispers* What is this place?"] = "*susurra* ¿Qué es este lugar?",
    ["I just told you, this is a library. Well, what's left of one anyway. When he's not ruling the land, the Pharaoh likes to let off some steam with a good old-fashioned book burning."] = "Te acabo de decir que esto es una biblioteca. Bueno, lo que queda de uno al menos. Cuando no está gobernando la tierra, al faraón le gusta desahogarse con una buena quema de libros a la antigua usanza.",
    ["We've lost far too much, including all of the Menaphite history, sociology and adult romance. He's not a complete barbarian, however, and has been burning by issue number, so we still have a complete set."] = "Hemos perdido demasiado, incluida toda la historia, la sociología y el romance adulto menafita. Sin embargo, no es un completo bárbaro y ha estado buscando números de ejemplar, por lo que todavía tenemos un conjunto completo.",
    ["Kind of considerate, really."] = "Muy considerado, de verdad.",
    ["Suit yourself!"] = "¡Haz lo que quieras!",
    ["*whispers* Who are you?"] = "*susurra* ¿Quién eres?",
    ["I am the watchful protector of the literary realm, Kohnen the librarian. There comes a time when jewels cease to sparkle, when gold loses its lustre, when the throne room becomes a prison and all that is left is love for a good parse through quality census data."] = "Soy el vigilante protector del ámbito literario, Kohnen the librarian. Llega un momento en el que las joyas dejan de brillar, en el que el oro pierde su lustre, en el que el salón del trono se convierte en una prisión y lo único que queda es el amor por un buen análisis a través de datos censales de calidad.",
    ["I just told you, it's a library. The greatest hub of literature and learning in the desert."] = "Te acabo de decir que es una biblioteca. El mayor centro de literatura y aprendizaje en el desierto.",
    ["Now we have a Pharaoh who shows the proper respect for history, this venerable institution will soon return to its former glory - I'm sure of it."] = "Ahora que tenemos un faraón que muestra el debido respeto por la historia, esta venerable institución pronto volverá a su antigua gloria, estoy seguro de ello.",
    ["Though my requests for extra funding haven't yet been answered. Something about the dread Devourer coming for our souls?"] = "Aunque mis solicitudes de financiación adicional aún no han sido respondidas. ¿Algo sobre el temible Devorador que viene por nuestras almas?",
    ["Anyway, I'm sure once that's all sorted, the great restocking can begin."] = "De todos modos, estoy seguro de que una vez que todo esté solucionado, podrá comenzar la gran reposición.",
    ["Ah I found this inside a book with your name on it."] = "Ah, encontré esto dentro de un libro con tu nombre.",
    ["You need more inventory space to receive your clue casket."] = "Necesitas más espacio en el inventario para recibir tu cofre de pistas.",
    ["[You are handed a casket!]"] = "[¡Te entregan un ataúd!]",
    ["Task System"] = "Sistema de tareas",
    ["For completing the Wilderness set, you are presented with Wilderness sword."] = "Por completar el conjunto Wilderness, se te presenta la espada Wilderness.",
    ["This sword will become increasingly useful with each difficulty level of the set that you complete."] = "Esta espada será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
    ["You may also select a set Task (denoted in the main Task System interface by a small shield icon) and choose 'Rewards' to see what rewards a set item provides."] = "También puede seleccionar una tarea determinada (indicada en la interfaz principal del sistema de tareas mediante un pequeño icono de escudo) y elegir 'Recompensas' para ver qué recompensas proporciona un elemento determinado.",
    ["You need to complete all the Tasks in the set of a particular difficulty, then you can claim your reward. Most of the Wilderness set's Tasks are straightforward, although you might find some require quests to be"] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Wilderness son sencillas, aunque es posible que algunas requieran misiones.",
    ["started, if not finished."] = "iniciado, si no terminado.",
    ["To claim the Wilderness set reward, speak to Mr Ex, Mandrith, Quercus or myself."] = "Para reclamar la recompensa del conjunto Wilderness, habla con Mr Ex, Mandrith, Quercus o conmigo mismo.",
    ["You don't have any more rewards to claim!"] = "¡Ya no tienes más recompensas para reclamar!",
    ["I'm afraid you don't have enough inventory space to claim all your rewards. Speak to me again when you have 3 spaces."] = "Me temo que no tienes suficiente espacio en el inventario para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 3 espacios.",
    ["I've completed all the tasks in the elite Wilderness task set."] = "He completado todas las tareas del conjunto de tareas de élite Wilderness.",
    ["[You are given some rewards for completing the elite Wilderness task set!]"] = "[¡Recibirás algunas recompensas por completar el conjunto de tareas de élite Wilderness!]",
    ["I lost the Wilderness sword 4 you gave me..."] = "Perdí la espada Wilderness 4 que me diste...",
    ["Lucky for you I have a spare... I'm afraid it's going to cost you 100,000 coins though."] = "Por suerte para ti, tengo uno de repuesto... Aunque me temo que te va a costar 100.000 coins.",
    ["Reclaim for 100,000 coins?"] = "¿Reclamar 100.000 coins?",
    ["But it doesn't look like you have enough money for that. Come back to me when you do."] = "Pero no parece que tengas suficiente dinero para eso. Vuelve conmigo cuando lo hagas.",
    ["[You're handed another Wilderness sword 4.]"] = "[Te entregan otra espada Wilderness 4.]",
    ["Wilderness sword 1"] = "Wilderness espada 1",
    ["Wilderness sword 1? Yes, but I'm afraid it would cost you 50,000 coins."] = "Wilderness espada 1? Sí, pero me temo que te costaría 50.000 coins.",
    ["Purchase another for 50,000 coins?"] = "¿Comprar otro por 50.000 coins?",
    ["[You're handed another Wilderness sword 1.]"] = "[Te entregan otra espada Wilderness 1.]",
    ["Wilderness sword 2"] = "Wilderness espada 2",
    ["Wilderness sword 2? Yes, but I'm afraid it would cost you 65,000 coins."] = "Wilderness espada 2? Sí, pero me temo que te costaría 65.000 coins.",
    ["Purchase another for 65,000 coins?"] = "¿Comprar otro por 65.000 coins?",
    ["[You're handed another Wilderness sword 2.]"] = "[Te entregan otra espada Wilderness 2.]",
    ["Wilderness sword 3"] = "Wilderness espada 3",
    ["Wilderness sword 3? Yes, but I'm afraid it would cost you 80,000 coins."] = "Wilderness espada 3? Sí, pero me temo que te costaría 80.000 coins.",
    ["Purchase another for 80,000 coins?"] = "¿Comprar otro por 80.000 coins?",
    ["[You're handed another Wilderness sword 3.]"] = "[Te entregan otra espada Wilderness 3.]",
    ["Wilderness sword 4"] = "Wilderness espada 4",
    ["Wilderness sword 4? Yes, but I'm afraid it would cost you 100,000 coins."] = "Wilderness espada 4? Sí, pero me temo que te costaría 100.000 coins.",
    ["Purchase another for 100,000 coins?"] = "¿Comprar otro por 100.000 coins?",
    ["Something else"] = "algo mas",
    ["Hello there. What is this place?"] = "Hola. ¿Qué es este lugar?",
    ["Do not waste my time with trivial questions. I am the Great Kolodion, master of battle magic. I have an arena to run."] = "No me hagas perder el tiempo con preguntas triviales. Soy el Gran Kolodion, maestro de la magia de batalla. Tengo una arena para correr.",
    ["Can I enter?"] = "¿Puedo participar?",
    ["Hah! A wizard of your level? Don't be absurd."] = "¡Ja! ¿Un mago de tu nivel? No seas absurdo.",
    ["I am the great Kolodion, master of battle magic, and this is my battle arena. Top wizards travel from all over Gielinor to fight here."] = "Soy el gran Kolodion, maestro de la magia de batalla, y este es mi campo de batalla. Los mejores magos viajan desde todo Gielinor para luchar aquí.",
    ["Can I fight here?"] = "¿Puedo pelear aquí?",
    ["My arena is open to any high level wizard, but this is no game. Many wizards fall in this arena, never to rise again. The strongest mages have been destroyed."] = "Mi campo está abierto a cualquier mago de alto nivel, pero esto no es un juego. Muchos magos caen en esta arena y nunca más vuelven a levantarse. Los magos más fuertes han sido destruidos.",
    ["If you're sure you want in?"] = "¿Estás seguro de que quieres participar?",
    ["What's the point of that?"] = "¿Cuál es el punto de eso?",
    ["We learn how to use our magic to its fullest and how to channel the forces of the cosmos into our world..."] = "Aprendemos cómo usar nuestra magia al máximo y cómo canalizar las fuerzas del cosmos en nuestro mundo...",
    ["But mainly, I just like blasting people into dust."] = "Pero principalmente, me gusta convertir a la gente en polvo.",
    ["That's barbaric!"] = "¡Eso es bárbaro!",
    ["Nope, it's magic. But I know what you mean. So do you want to join us?"] = "No, es mágico. Pero sé lo que quieres decir. ¿Quieres unirte a nosotros?",
    ["Yes indeedy."] = "Sí, de hecho.",
    ["Good, good. You have a healthy sense of competition."] = "Bien, bien. Tienes un sano sentido de competencia.",
    ["Remember, traveller - in my arena, hand-to-hand combat is useless. Your strength will diminish as you enter the arena, but the spells you can learn are amongst the most powerful in all of Gielinor."] = "Recuerda, viajero: en mi arena, el combate cuerpo a cuerpo es inútil. Tu fuerza disminuirá a medida que entres a la arena, pero los hechizos que puedes aprender se encuentran entre los más poderosos de todo Gielinor.",
    ["Before I can accept you in, we must duel."] = "Antes de que pueda aceptarte, debemos batirnos en duelo.",
    ["Okay, let's fight."] = "Está bien, peleemos.",
    ["**Player:{{anchor|lets-fight}}** Okay, let's fight."] = "**Player:{{anchor|lets-fight}}** Está bien, peleemos.",
    ["I must first check that you are up to scratch."] = "Primero debo comprobar que estás a la altura.",
    ["You don't need to worry about that."] = "No necesitas preocuparte por eso.",
    ["Not just any magician can enter - only the most powerful and most feared. Before you can use the power of this arena, you must prove yourself against me."] = "No cualquier mago puede entrar, solo los más poderosos y temidos. Antes de que puedas usar el poder de esta arena, debes probar tu valía contra mí.",
    ["No I don't."] = "No, no lo sé.",
    ["Your loss."] = "Tú te lo pierdes.",
    ["Well done, young adventurer; you truly are a worthy battle mage."] = "Bien hecho, joven aventurero; Realmente eres un digno mago de batalla.",
    ["What now?"] = "¿Y ahora qué?",
    ["**Kolodion:{{anchor|step-into-pool}}** Step into the magic pool. It will take you to a chamber. There, you must decide which god you will represent in the arena."] = "**Kolodion:{{anchor|step-into-pool}}** Entra en la piscina mágica. Te llevará a una cámara. Allí deberás decidir a qué dios representarás en la arena.",
    ["Thanks, Kolodion."] = "Gracias, Kolodion.",
    ["That's what I'm here for."] = "Para eso estoy aquí.",
    ["Hello, Kolodion."] = "Hola, Kolodion.",
    ["Hello, young mage. You're a tough one."] = "Hola, joven mago. Eres una persona dura.",
    ["Hey there, how are you? Are you enjoying the bloodshed?"] = "Hola, ¿cómo estás? ¿Estás disfrutando del derramamiento de sangre?",
    ["I think I've had enough for now."] = "Creo que ya he tenido suficiente por ahora.",
    ["A shame. You're a good battle mage. I hope to see you soon."] = "Una pena. Eres un buen mago de batalla. Espero verte pronto.",
    ["Player! Good timing. Commodore Tyr was looking for you."] = "¡Player! Buen momento. El comodoro Tyr te estaba buscando.",
    ["Hello, you look like a bold adventurer. You've come to the right place for adventurers' equipment."] = "Hola, pareces un aventurero audaz. Has venido al lugar correcto para encontrar equipo para aventureros.",
    ["Oh, that sounds interesting."] = "Oh, eso suena interesante.",
    ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
    ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
    ["No, sorry, I've come to the wrong place."] = "No, lo siento, he venido al lugar equivocado.",
    ["Hmph. Well, perhaps next time you'll need something from me?"] = "Hmph. Bueno, ¿quizás la próxima vez necesites algo de mí?",
    ["Isn't Banky cute?<br/>An explorer found him on one of the uncharted isles. Not sure how he wound up with a chest on his back, but I've put him to good use."] = "¿No es lindo Banky?<br/>Un explorador lo encontró en una de las islas inexploradas. No estoy seguro de cómo terminó con un cofre en la espalda, pero le he dado un buen uso.",
    ["Have you seen Banky?<br/>I really need to put a leash on that little fella."] = "¿Has visto a Banky? <br/>Realmente necesito ponerle una correa a ese pequeño.",
    ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
    ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["I might. Which one were you thinking of?"] = "Podría hacerlo. ¿En cuál estabas pensando?",
    ["The northern allotment."] = "La parcela del norte.",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["Okay, it's a deal."] = "Está bien, es un trato.",
    ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["No, that's too much."] = "No, eso es demasiado.",
    ["The southern allotment."] = "La parcela del sur.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it."] = "Olvídalo.",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    ["You hear a howling in the distance!"] = "¡Se oye un aullido a lo lejos!",
    ["You manage to catch the runaway beast!"] = "¡Logras atrapar a la bestia fugitiva!",
    ["You have unlocked a new pet!"] = "¡Has desbloqueado una nueva mascota!",
    ["One of these things is handful enough, trying to deal with two of them would be madness!"] = "Una de estas cosas es bastante difícil, ¡tratar de lidiar con dos de ellas sería una locura!",
    ["Do you miss your home?"] = "¿Extrañas tu hogar?",
    ["Grooaoar brrrr, hisssss!"] = "¡Groooar brrrr, sissss!",
    ["I SAID, DO YOU MISS YOUR HOME?"] = "DIJE, ¿Extrañas tu casa?",
    ["What do you want to do today?"] = "¿Qué quieres hacer hoy?",
    ["I SAID, WHAT DO YOU WANT TO DO TODAY?"] = "DIJE, ¿QUÉ QUIERES HACER HOY?",
    ["How are you today, Krar Jnr?"] = "¿Cómo estás hoy, Krar Jnr?",
    ["I SAID, HOW ARE YOU?"] = "DIJE, ¿CÓMO ESTÁS?",
    ["Category:NPC dialogue"] = "Categoría: Diálogo NPC",
    ["You hear the spiritual warrior's voice in your head: \"Uu'Son."] = "Escuchas la voz del guerrero espiritual en tu cabeza: \"Uu'Son\".",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["Me very busy. No have time to talk to puny creature like you."] = "Estoy muy ocupado. No tengo tiempo para hablar con una criatura insignificante como tú.",
    ["Well, excuse me!"] = "Bueno, ¡disculpe!",
    ["No excuse for you - you in my way."] = "No hay excusa para ti, estás en mi camino.",
    ["I would offer haircut, but it hard to do style for puny human with puny head."] = "Ofrecería un corte de pelo, pero es difícil hacer un estilo para un humano insignificante con una cabeza insignificante.",
    ["Me know. You want wig intead? Me give you big-big discount!"] = "Ya lo sé. ¿Quieres peluca en su lugar? ¡Te doy un gran descuento!",
    ["Would you like to buy an ogre wig for 50 gp?"] = "¿Te gustaría comprar una peluca de ogro por 50 po?",
    ["Yes, please."] = "Sí, por favor.",
    ["You no have enough shiny pretties, human."] = "No tienes suficientes bellezas brillantes, humano.",
    ["There you go. Nice wig for you, made from de freshest wolfsie bones."] = "Ahí lo tienes. Bonita peluca para ti, hecha con los huesos de lobo más frescos.",
    ["You no have enough room to hold it, human. Come back when you have space."] = "No tienes suficiente espacio para sostenerlo, humano. Vuelve cuando tengas espacio.",
    ["So, how do you like what's, um, being done to your head?"] = "Entonces, ¿qué te parece lo que te están haciendo en la cabeza?",
    ["Quit talking to goblin, Player. If she moves her head, she mess up work."] = "Deja de hablar con el duende, Player. Si mueve la cabeza, arruina el trabajo.",
    ["Oh, sorry! I would never dream of interfering in the creative process."] = "¡Oh, lo siento! Nunca se me ocurriría interferir en el proceso creativo.",
    ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
    ["My name is Kristlin, and this is the tent where I tell fortunes. What is your name, seeker of truth?"] = "Mi nombre es Kristlin y esta es la tienda donde cuento la buenaventura. ¿Cómo te llamas, buscador de la verdad?",
    ["Player{{Sic}}"] = "Jugador{{Sic}}",
    ["Glad tidings to you, Player, may your path be clear and guide you towards happiness."] = "Buenas noticias para ti, Player, que tu camino sea claro y te guíe hacia la felicidad.",
    ["I'd like my fortune read."] = "Me gustaría que leyeran mi fortuna.",
    ["*(If not enough tokens are owned:)*"] = "*(Si no tienes suficientes tokens:)*",
    ["You're welcome to a reading but first you have to cross my palm with forty tokens. Helps get the mystic forces flowing."] = "Eres bienvenido a una lectura, pero primero tienes que cruzar mi palma con cuarenta fichas. Ayuda a que las fuerzas místicas fluyan.",
    ["You can get more fayre tokens and tickets from the stall by the Bucking Baroo."] = "Puede obtener más fichas y boletos de Fayre en el puesto junto al Bucking Baroo.",
    ["*(If enough tokens are owned, and there isn't currently an active cloud of destiny:)*"] = "*(Si se poseen suficientes tokens y actualmente no hay una nube de destino activa:)*",
    ["*(If the warning hasn't been toggled off:)*"] = "*(Si la advertencia no se ha desactivado:)*",
    ["This activity will cost 40 fayre attraction tokens. Are you sure you want to continue?"] = "Esta actividad costará 40 fichas de atracción de Fayre. ¿Estás seguro de que quieres continuar?",
    ["Get a fortune?"] = "¿Conseguir una fortuna?",
    ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
    ["*(If the warning has been toggled off:)*"] = "*(Si la advertencia se ha desactivado:)*",
    ["*(If enough tokens are owned, and there is currently an active cloud of destiny:)*"] = "*(Si se poseen suficientes tokens y actualmente hay una nube de destino activa:)*",
    ["Would you like to buy a new reading?"] = "¿Quieres comprar una nueva lectura?",
    ["*(Dialogue from getting a fortune occurs.)*"] = "*(Se produce un diálogo sobre cómo conseguir una fortuna.)*",
    ["Why are you here?"] = "¿Por qué estás aquí?",
    ["I travel with Menowin, and his group of friends. It allows me to talk to many different people, and to impart my knowledge as I go. In fact, meeting so many different people seems to increase my abilities. The more I travel the clearer my fortunes become."] = "Viajo con Menowin y su grupo de amigos. Me permite hablar con muchas personas diferentes e impartir mis conocimientos sobre la marcha. De hecho, conocer tanta gente diferente parece aumentar mis habilidades. Cuanto más viajo, más clara se vuelve mi suerte.",
    ["What abilities do you have?"] = "¿Qué habilidades tienes?",
    ["I have only one ability, and that is to read the fortunes of people; to know what their destiny is. It's still only in the short-term at the moment, but as my powers increase so does the length of time I can see into the future for people."] = "Sólo tengo una habilidad, y es leer la suerte de las personas; saber cuál es su destino. Por el momento, todavía es solo a corto plazo, pero a medida que mis poderes aumentan, también aumenta el tiempo que puedo ver el futuro de las personas.",
    ["How do you read fortunes?"] = "¿Cómo se lee la fortuna?",
    ["I have a deck of fortune cards. All you need to do is choose the three cards that call to you the strongest after I spread them out on the table. You should go with your instinct. There are no right or wrong answers."] = "Tengo una baraja de cartas de la fortuna. Todo lo que necesitas hacer es elegir las tres cartas que te llamen más fuerte después de que las extienda sobre la mesa. Debes seguir tu instinto. No hay respuestas correctas o incorrectas.",
    ["Where did you get your cards from?"] = "¿De dónde sacaste tus tarjetas?",
    ["I created my deck of fortune cards myself. The names and images of the cards came to me in my dreams, over several months. I realized when I focused on those images my ability to read the future for people became stronger, and clearer. This was the best way I could think of to hone my focus. It seems to work quite well."] = "Yo mismo creé mi mazo de cartas de la fortuna. Los nombres y las imágenes de las tarjetas me llegaron en sueños durante varios meses. Me di cuenta de que cuando me concentraba en esas imágenes mi capacidad para leer el futuro de las personas se hacía más fuerte y más clara. Esta fue la mejor manera que se me ocurrió para perfeccionar mi enfoque. Parece funcionar bastante bien.",
    ["Are you cards based on anything in-particular?"] = "¿Están sus tarjetas basadas en algo en particular?",
    ["Just the flashes of images and concepts that come to me as I dream. They have been coming to me since I was a little girl. I believe one day I will understand what they truly are, but until that day I am a{{Sic}} happy to be a servant to their power."] = "Sólo los destellos de imágenes y conceptos que me vienen mientras sueño. Han estado viniendo a mí desde que era niña. Creo que algún día entenderé lo que realmente son, pero hasta ese día estoy muy feliz de ser un servidor de su poder.",
    ["What is your fortune?"] = "¿Cuál es tu fortuna?",
    ["Alas, I dont now know that. I cannnot read my own fortune. I have tried many times, but the cards never give me a clear answer. I have come to accept this, though, and believe that my future is wrapped up in the fortunes of others, and through my work I am fulfilling my destiny."] = "Por desgracia, ahora no lo sé. No puedo leer mi propia fortuna. Lo he intentado muchas veces, pero las tarjetas nunca me dan una respuesta clara. Sin embargo, he llegado a aceptar esto y creo que mi futuro está envuelto en la suerte de los demás y que a través de mi trabajo estoy cumpliendo mi destino.",
    ["What does my fortune mean?"] = "¿Qué significa mi fortuna?",
    ["*(If a cloud of destiny isn't active:)*"] = "*(Si una nube del destino no está activa:)*",
    ["Ah well, to understand your fortune you would first need to get a reading. Would you like me to read your fortune?"] = "Ah, bueno, para entender tu fortuna primero necesitarás hacer una lectura. ¿Quieres que te lea la fortuna?",
    ["*(If a cloud of destiny is active:)*"] = "*(Si una nube del destino está activa:)*",
    ["Your fortune is your own, and can only truly be deciphered by you. All answers will come in time."] = "Tu fortuna es tuya y solo tú puedes descifrarla verdaderamente. Todas las respuestas llegarán con el tiempo.",
    ["However, looking at your aura, you appear to be in a positive state, and I am sure that the fortune will become clear to you and will be a rewarding experience."] = "Sin embargo, al observar tu aura, pareces estar en un estado positivo y estoy seguro de que la fortuna se te aclarará y será una experiencia gratificante.",
    ["What does cloud of destiny mean?"] = "¿Qué significa nube del destino?",
    ["Ah! Lucky people, when they receive a fortune, receive a 'cloud of destiny'. If they then do what the cloud of destiny portends, they receive a boon."] = "¡Ah! Las personas afortunadas, cuando reciben una fortuna, reciben una \"nube del destino\". Si luego hacen lo que presagia la nube del destino, recibirán una bendición.",
    ["More."] = "Más.",
    ["How did you meet Menowin?"] = "¿Cómo conociste a Menowin?",
    ["He and his band of friends came through my village one day, looking for shelter as they traveled on to the next city. I was working in a bar the the time. Menowin was the last customer to leave that night, and as I was clearing up I offered to read his fortune. It was the strongest feeling I had ever got from a fortune and it was like fate was pushing me towards him. I believe he felt the same as he offered to let me join him on his travels."] = "Él y su grupo de amigos pasaron por mi pueblo un día en busca de refugio mientras viajaban hacia la siguiente ciudad. Estaba trabajando en un bar en ese momento. Menowin fue el último cliente en irse esa noche y, mientras estaba limpiando, me ofrecí a leer su fortuna. Fue el sentimiento más fuerte que jamás había tenido de una fortuna y era como si el destino me estuviera empujando hacia él. Creo que él sintió lo mismo cuando se ofreció a dejarme acompañarlo en sus viajes.",
    ["*(Only if nothing has been asked before:)*"] = "*(Solo si no se ha preguntado nada antes:)*",
    ["Do you have any cookies?"] = "¿Tienes galletas?",
    ["*(If the player does not have a cookie in their inventory or bank:)*"] = "*(Si el player no tiene una cookie en su inventario o banco:)*",
    ["Would you like a cookie?"] = "¿Quieres una galleta?",
    ["Is there a fortune inside the cookie?"] = "¿Hay una fortuna dentro de la galleta?",
    ["What a strange idea. I might have to look into that for the future."] = "Qué idea más extraña. Quizás tenga que investigar eso para el futuro.",
    ["*(If the player already has a cookie in their inventory or bank:)*"] = "*(Si el player ya tiene una cookie en su inventario o banco:)*",
    ["I'd offer you another, but it looks like you haven't eaten your last one."] = "Te ofrecería otro, pero parece que no te has comido el último.",
    ["*(Only after asking something else:)*"] = "*(Solo después de preguntar algo más :)*",
    ["Bye."] = "Adiós.",
    ["May your path be clear and guide you towards happiness."] = "Que tu camino sea claro y te guíe hacia la felicidad.",
    ["*(If a tarot card token isn't owned, and there isn't currently an active cloud of destiny:)*"] = "*(Si no se posee una ficha de carta del tarot y actualmente no hay una nube del destino activa:)*",
    ["You're welcome to a reading but first you have to cross my palm with a tarot card token. Helps get the mystic forces flowing."] = "Eres bienvenido a una lectura, pero primero tienes que cruzar mi palma con una ficha de carta del tarot. Ayuda a que las fuerzas místicas fluyan.",
    ["You can get tarot card tokens by taking part in activities at the fayre."] = "Puedes conseguir fichas de cartas del tarot participando en actividades en la feria.",
    ["*(If a tarot card token isn't owned, and there is currently an active cloud of destiny:)*"] = "*(Si no se posee una ficha de carta del tarot y actualmente hay una nube del destino activa:)*",
    ["Use a tarot card to reroll your fortune?"] = "¿Usar una carta del tarot para volver a tirar tu fortuna?",
    ["*(If a tarot card token is owned, and there isn't currently an active cloud of destiny:)*"] = "*(Si se posee una ficha de carta del tarot y actualmente no hay una nube del destino activa:)*",
    ["*(If a tarot card token is owned, and there is currently an active cloud of destiny:)*"] = "*(Si se posee una ficha de carta del tarot y actualmente hay una nube de destino activa:)*",
    ["What happened to the cavern of tainted memories?"] = "¿Qué pasó con la caverna de los recuerdos contaminados?",
    ["The portal became too unstable and broke down."] = "El portal se volvió demasiado inestable y se rompió.",
    ["I believe that the cavern is there, waiting for brave adventurers to find it again, but I do not know when it might make itself visible again."] = "Creo que la caverna está ahí, esperando que valientes aventureros la encuentren nuevamente, pero no sé cuándo podrá volver a hacerse visible.",
    ["Cross my palm with tokens to know your future."] = "Cruza mi palma con fichas para conocer tu futuro.",
    ["*(If enough tokens are owned:)*"] = "*(Si tienes suficientes tokens:)*",
    ["Cross my palm with a tarot card token to know your future."] = "Cruza mi palma con una ficha de carta del tarot para conocer tu futuro.",
    ["*(If a tarot card token isn't owned:)*"] = "*(Si no tienes una ficha de carta del tarot:)*",
    ["*(If a tarot card token is owned:)*"] = "*(Si posee una ficha de carta del tarot:)*",
    ["*(If a cookie isn't owned:)*"] = "*(Si una cookie no es de su propiedad:)*",
    ["*(If a cookie is owned:)*"] = "*(Si es propiedad de una cookie:)*",
    ["Hello there my darling! I seem to have uncovered a special cavern in my quest to further my divining knowledge!"] = "¡Hola, cariño! ¡Parece que he descubierto una caverna especial en mi búsqueda por ampliar mis conocimientos de adivinación!",
    ["What makes this cavern so special?"] = "¿Qué hace que esta caverna sea tan especial?",
    ["It appears to be home to a certain kind of rare wisp. They have been corrupted with the evil memories of the world."] = "Parece ser el hogar de cierto tipo de brizna poco común. Han sido corrompidos por los malos recuerdos del mundo.",
    ["However it isn't all doom and gloom. It turns out these wisps can be harvested for a type of essence that can be cleansed and forged into some rather lovely weaponry."] = "Sin embargo, no todo es pesimismo. Resulta que estos mechones se pueden recolectar para obtener un tipo de esencia que se puede limpiar y convertir en un arma bastante encantadora.",
    ["That sounds pretty awesome!"] = "¡Eso suena increíble!",
    ["Quite. But I can't just be allowing this precious resource to be harvested unchecked. We don't know whether it is finite or not."] = "Bastante. Pero no puedo simplemente permitir que este valioso recurso sea cosechado sin control. No sabemos si es finito o no.",
    ["I will allove you a short period of time in there in each day. If you bring me a cavern entry token, I'll allow you in again!"] = "Te dejaré un breve período de tiempo allí cada día. ¡Si me traes una ficha de entrada a la caverna, te permitiré entrar otra vez!",
    ["When entering the cavern, you will have 2 minutes 30 seconds to collect as much tainted essence as you can before you are removed from the area. <span style=\"color:#008C2A\">Stand in multiplier locations to recieve{{Sic}} increased XP and essence. Collect tainted chronicles from afar to gather a lump of essence.</span>"] = "Al ingresar a la caverna, tendrás 2 minutos y 30 segundos para recolectar tanta esencia contaminada como puedas antes de que te retiren del área. <span style=\"color:#008C2A\">Párate en ubicaciones multiplicadoras para recibir {{Sic}} mayor XP y esencia. Recoge crónicas contaminadas desde lejos para reunir un trozo de esencia.</span>",
    ["If you don't want to receive Divination XP from the cavern, I could give you a bundle of other rewards instead."] = "Si no quieres recibir XP Divination de la caverna, podría darte un paquete de otras recompensas.",
    ["Would you like to receive Divination XP or mystery rewards?"] = "¿Le gustaría recibir Divination XP o recompensas misteriosas?",
    ["Divination XP"] = "DivinationXP",
    ["Very well. You will now receive Divination XP whilst you are in the cavern."] = "Muy bien. Ahora recibirás Divination XP mientras estés en la caverna.",
    ["Mystery rewards"] = "Recompensas misteriosas",
    ["Very well. You will now receive some mystery rewards when you leave the cavern."] = "Muy bien. Ahora recibirás algunas recompensas misteriosas cuando salgas de la caverna.",
    ["<span style=\"color:red\">Note :</span> You will still have to earn your rewards. The amount you receive will be based on the amount of XP you would have earned."] = "<span style=\"color:red\">Nota: </span> Aún tendrás que ganar tus recompensas. La cantidad que reciba se basará en la cantidad de XP que habría ganado.",
    ["*(Continues as above.)*"] = "*(Continúa como arriba.)*",
    ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
    ["*Dialogue 1*"] = "*Diálogo 1*",
    ["Out of my way, punk."] = "Fuera de mi camino, punk.",
    ["*Dialogue 2*"] = "*Diálogo 2*",
    ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
    ["*Dialogue 3*"] = "*Diálogo 3*",
    ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
    ["*Dialogue 4*"] = "*Diálogo 4*",
    ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
    ["Strange how?"] = "¿Qué extraño cómo?",
    ["Like a human!"] = "¡Como un humano!",
    ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
    ["*Dialogue 5*"] = "*Diálogo 5*",
    ["Get lost!"] = "¡Piérdete!",
    ["*Dialogue 6*"] = "*Diálogo 6*",
    ["Leave me alone."] = "Déjame en paz.",
    ["*Dialogue 7*"] = "*Diálogo 7*",
    ["Have you no manners?"] = "¿No tienes modales?",
    ["*Dialogue 8*"] = "*Diálogo 8*",
    ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
    ["*Dialogue 9*"] = "*Diálogo 9*",
    ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
    ["*Dialogue 10*"] = "*Diálogo 10*",
    ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
    ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
    ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
    ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
    ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
    ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
    ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
    ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
    ["Good day to you, my friend."] = "Buenos días, amigo mío.",
    ["You smell familiar..."] = "Hueles familiar...",
    ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    ["Heya, can I help you?"] = "Oye, ¿puedo ayudarte?",
    ["I need another assignment."] = "Necesito otra tarea.",
    ["Sorry, but you're not strong enough to be taught by me."] = "Lo siento, pero no eres lo suficientemente fuerte para que yo te enseñe.",
    ["Can we talk about items and incentives?"] = "¿Podemos hablar de artículos e incentivos?",
    ["Of course, what would you like to discuss: items for sale or incentives?"] = "Por supuesto, ¿de qué le gustaría hablar: artículos en venta o incentivos?",
    ["Let's talk items."] = "Hablemos de elementos.",
    ["I have a wide selection of Slayer equipment - take a look!"] = "Tengo una amplia selección de equipos Slayer. ¡Échale un vistazo!",
    ["Let's talk incentives."] = "Hablemos de incentivos.",
    ["View rewards."] = "Ver recompensas.",
    ["How do I earn co-op points to spend on rewards?"] = "¿Cómo gano puntos cooperativos para gastarlos en recompensas?",
    ["You'll gain co-op reward points if you complete at least half of your contribution to a task with a friend. That means you need to be in a group for most of the time you're working on the task, but it doesn't matter if your friend beats you to the majority of kills! You'll still have been in a group for most of your contribution, so you're still entitled to a co-op reward point."] = "Obtendrás puntos de recompensa cooperativa si completas al menos la mitad de tu contribución a una tarea con un amigo. Eso significa que debes estar en un grupo la mayor parte del tiempo que estés trabajando en la tarea, ¡pero no importa si tu amigo te gana en la mayoría de las muertes! Aún habrás estado en un grupo durante la mayor parte de tu contribución, por lo que aún tendrás derecho a un punto de recompensa cooperativa.",
    ["Where can I use the co-op food and potion rewards?"] = "¿Dónde puedo usar las recompensas cooperativas de comida y pociones?",
    ["The rewards can be used in most of the areas we commonly send you to complete your tasks."] = "Las recompensas se pueden usar en la mayoría de las áreas que comúnmente te enviamos para completar tus tareas.",
    ["Tell me about your skillcape, please."] = "Cuéntame sobre tu skillcape, por favor.",
    ["This is a Slayer's Skillcape. Only a true Slayer master is permitted to wear one. You need more training before you earn that honour."] = "Este es un Skillcape de Slayer. Sólo un verdadero Slayer master puede usar uno. Necesitas más entrenamiento antes de ganar ese honor.",
    ["Can you sell me a Slayer skillcape?"] = "¿Puedes venderme un Slayer skillcape?",
    ["Well you have performed well as a student. I guess you have earned the right to wear such a prestigious cape now. That will be 99,000 coins, please."] = "Bueno, te has desempeñado bien como estudiante. Supongo que ahora te has ganado el derecho a llevar una capa tan prestigiosa. Serán 99.000 coins, por favor.",
    ["99,000 coins? That's much too expensive. ((or 92,000 coins with Ring of charos (a)))"] = "¿99.000 coins? Eso es demasiado caro. ((o 92.000 coins con Ring of charos (a)))",
    ["Not at all; there are many other adventurers who would love the opportunity to purchase such a prestigious item! You can find me here if you change your mind."] = "En absoluto; ¡Hay muchos otros aventureros a quienes les encantaría tener la oportunidad de comprar un artículo tan prestigioso! Puedes encontrarme aquí si cambias de opinión.",
    ["*(If the player has at least two free backpack spaces:)*"] = "*(Si el player tiene al menos dos espacios backpack libres:)*",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some inventory space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en el inventario antes de que pueda venderte uno.",
    ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Slayer master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderte una capa Slayer master.",
    ["Buy Slayer master cape for 120,000 coins?"] = "¿Comprar capa Slayer master por 120.000 coins?",
    ["*(If the player has at least one free backpack space:)*"] = "*(Si el player tiene al menos un espacio backpack libre:)*",
    ["*(If the player does not have at least one free backpack space:)*"] = "*(Si el player no tiene al menos un espacio libre en backpack:)*",
    ["You do not have enough room in your inventory. Please come back when you have some more."] = "No tienes suficiente espacio en tu inventario. Por favor regresa cuando tengas más.",
    ["I've noticed there are a couple versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["*(If the player has chosen the new skillcape models:)*"] = "*(Si el player ha elegido los nuevos modelos skillcape :)*",
    ["Yes, I would like to wear the old version of the skillcape."] = "Sí, me gustaría usar la versión antigua del skillcape.",
    ["Would you like to wear the old model for just this cape, or for the Quest point cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo antiguo solo para esta capa, o para la capa de puntos Quest y todos los skillcapes que tienes?",
    ["I would just like to change the Slayer skillcape."] = "Solo me gustaría cambiar el Slayer skillcape.",
    ["No problem, you will now use the older model for your Slayer skillcape."] = "No hay problema, ahora utilizarás el modelo anterior para tu Slayer skillcape.",
    ["No problem, you will now use the older model for all of your skillcapes!"] = "No hay problema, ¡ahora usarás el modelo anterior para todos tus skillcapes!",
    ["Great! I'm glad you're enjoying our new version!"] = "¡Genial! ¡Me alegra que estés disfrutando de nuestra nueva versión!",
    ["*(If the player is using the old skillcape models except for the Slayer cape:)*"] = "*(Si el player está usando los modelos skillcape antiguos excepto la capa Slayer :)*",
    ["If you want, I can make it so you use the newer model for all of the skillcapes you own!"] = "¡Si quieres, puedo hacerlo para que uses el modelo más nuevo para todos los skillcapes que tienes!",
    ["Ok, I'd like to wear the newer version for all my skillcapes."] = "Ok, me gustaría usar la versión más nueva para todos mis skillcapes.",
    ["Great, you will now use the newer model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo más nuevo para todos tus skillcapes!",
    ["*(If the player has chosen the old skillcape models:)*"] = "*(Si el player ha elegido los modelos antiguos skillcape :)*",
    ["It looks like you're currently using the old model for your Slayer skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Slayer skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["Yes, I would like to wear the new version of the skillcape."] = "Sí, me gustaría usar la nueva versión del skillcape.",
    ["Would you like to wear the newer model for just this cape, or all of the skillcapes you own?"] = "¿Te gustaría usar el modelo más nuevo solo para esta capa o para todos los skillcapes que tienes?",
    ["No problem, you will now use the newer model for your Slayer skillcape."] = "No hay problema, ahora utilizarás el modelo más nuevo para tu Slayer skillcape.",
    ["No problem, you will now use the newer model for all of your skillcapes!"] = "No hay problema, ¡ahora usarás el modelo más nuevo para todos tus skillcapes!",
    ["Great! I'm glad you're still enjoying the old version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión anterior!",
    ["*(If the player is using the new skillcape models except for the Slayer cape:)*"] = "*(Si el player está usando los nuevos modelos skillcape excepto la capa Slayer :)*",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own!"] = "¡Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas!",
    ["Let's talk about you."] = "Hablemos de ti.",
    ["I'm Kuradal, daughter of Duradel. What more would you like to know?"] = "Soy Kuradal, hija de Duradel. ¿Qué más te gustaría saber?",
    ["Tell me more about your background."] = "Cuéntame más sobre tus antecedentes.",
    ["If you so desire. As I said, I am Kuradal, daughter of Duradel - another great master of Slayer. Unlike the others, though, I ventured out not only to slay, but also to capture. I've caught many different types of creatures and I hold them within this dungeon, reserved exclusively for my pupils to slay."] = "Si así lo deseas. Como dije, soy Kuradal, hija de Duradel - otro gran maestro de Slayer. Sin embargo, a diferencia de los demás, me aventuré no sólo a matar, sino también a capturar. He capturado muchos tipos diferentes de criaturas y las mantengo dentro de esta mazmorra, reservada exclusivamente para que mis alumnos las maten.",
    ["So slaying runs in the family, then?"] = "Entonces, ¿matar es cosa de familia?",
    ["Of course. One cannot simply 'grow up' with someone like my father. My childhood was all combat training, taking on the beasts of this land side by side with my father."] = "Por supuesto. Uno no puede simplemente \"crecer\" con alguien como mi padre. Mi infancia fue toda entrenamiento de combate, enfrentándome a las bestias de esta tierra al lado de mi padre.",
    ["So who is your mother?"] = "Entonces, ¿quién es tu madre?",
    ["I'd rather not say. Can we talk about something else?"] = "Preferiría no decirlo. ¿Podemos hablar de otra cosa?",
    ["About your father..."] = "Sobre tu padre...",
    ["*(Same as below)*"] = "*(Igual que a continuación)*",
    ["That's all for now."] = "Eso es todo por ahora.",
    ["Fine. I'll be here if you need me."] = "Bien. Estaré aquí si me necesitas.",
    ["Sounds like you had a hectic childhood!"] = "¡Parece que tuviste una infancia agitada!",
    ["You could say that, but I am thankful for it as it made me the person I am today."] = "Se podría decir eso, pero estoy agradecido por ello, ya que me convirtió en la persona que soy hoy.",
    ["*(Same as above)*"] = "*(Igual que arriba)*",
    ["*If you have not yet completed While Guthix Sleeps*"] = "*Si aún no has completado Mientras Guthix duerme*",
    ["About your father... How come you aren't with him now?"] = "Sobre tu padre... ¿Cómo es que no estás con él ahora?",
    ["We are still close, but combat and competition runs deep in both our veins. I strive to be the best, so took up a Slayer Master position and want to give people a greater challenge than that of my father."] = "Todavía estamos cerca, pero el combate y la competencia corren profundamente en nuestras venas. Me esfuerzo por ser el mejor, por eso asumí un puesto en Slayer Master y quiero brindarles a las personas un desafío mayor que el de mi padre.",
    ["*If you have completed Ritual of the Mahjarrat*"] = "*Si has completado el Ritual del Mahjarrat*",
    ["About your father... Lucien is dead!"] = "Acerca de tu padre... ¡Lucien está muerto!",
    ["I know. I saw his corpse up at the ritual site."] = "Lo sé. Vi su cadáver en el lugar del ritual.",
    ["What? You were there? I didn't see you."] = "¿Qué? ¿Estabas allí? No te vi.",
    ["Nor I you, but I was there, fighting off Mahjarrat and their minions. None of them were Lucien, though. I chased one of them into a cave, full of ice elementals called glacors. After killing a couple hundred of those, I managed to escape, but by then it was all over: everyone had gone."] = "Yo tampoco, pero yo estaba allí, luchando contra Mahjarrat y sus secuaces. Sin embargo, ninguno de ellos era Lucien. Perseguí a uno de ellos hasta una cueva llena de elementales de hielo llamados glacors. Después de matar a un par de cientos de ellos, logré escapar, pero para entonces todo había terminado: todos se habían ido.",
    ["You sound angry. I'd have thought you'd be glad he's dead!"] = "Suenas enojado. ¡Pensé que te alegrarías de que estuviera muerto!",
    ["I am, but Lucien was my kill! Mine alone! No one had the right to take that from me! No one! ... How will I honour my father's memory?"] = "Lo soy, ¡pero Lucien fue mi presa! ¡Solo mío! ¡Nadie tenía derecho a quitarme eso! ¡Nadie! ... ¿Cómo honraré la memoria de mi padre?",
    ["You honour him every day."] = "Lo honras todos los días.",
    ["Bah! Any more of that touchy-feely nonsense and I'll be forced to revoke your Slayer licence..."] = "¡Bah! Si sigues con esas tonterías sensibleras me veré obligado a revocar tu licencia de Slayer...",
    ["But, yo-"] = "Pero, yo-",
    ["Hahaha! The look on your face! That cheered me up some. Thanks, Player. 'You honour him every day."] = "¡Jajaja! ¡La expresión de tu cara! Eso me animó un poco. Gracias, Player. \"Lo honras todos los días\".",
    ["I'm, er, glad I could help."] = "Me alegro de poder ayudar.",
    ["Now, can I help with anything else?"] = "Ahora, ¿puedo ayudar con algo más?",
    ["By helping to defeat what killed Lucien!"] = "¡Ayudando a derrotar a lo que mató a Lucien!",
    ["Which was what, exactly?"] = "¿Qué era exactamente?",
    ["A dragonkin. Three of them, in fact."] = "Un dragonante. De hecho, tres de ellos.",
    ["Hmm, now that sounds like a challenge worthy of a slayer master. I've got some preparations to make. Collecting those for a dungeon could be tricky..."] = "Hmm, eso suena como un desafío digno de un slayer master. Tengo algunos preparativos que hacer. Recolectarlos para una mazmorra podría ser complicado...",
    ["Collecting them? You're crazy!"] = "¿Coleccionarlos? ¡Estás loco!",
    ["So what's in this dungeon then?"] = "Entonces, ¿qué hay en esta mazmorra?",
    ["Well, I've been all over and managed to capture hellhounds, greater demons, gargoyles, abyssal demons, airut, dark beasts, blue, iron, and steel dragons."] = "Bueno, estuve por todas partes y logré capturar perros del infierno, demonios mayores, gárgolas, demonios abisales, airut, bestias oscuras, dragones azules, de hierro y de acero.",
    ["*If you're playing as male character* **Player:** You caught them single-handedly?"] = "*Si juegas como un personaje masculino* **Player:** ¿Los atrapaste sin ayuda de nadie?",
    ["You doubt my skills?"] = "¿Dudas de mis habilidades?",
    ["I didn't mean anything by it."] = "No quise decir nada con eso.",
    ["I'm glad to hear so. *(continues as below)*"] = "Me alegra saberlo. *(continúa como a continuación)*",
    ["Well, come on. You are just a girl and I'm a tough warrior!"] = "Bueno, vamos. ¡Tú eres solo una niña y yo soy un guerrero duro!",
    ["Just a girl, am I? Right? *(Kuradal knocks you out, and you wake up outside the ancient caverns.)*"] = "Sólo una niña, ¿verdad? ¿Bien? *(Kuradal te noquea y te despiertas fuera de las antiguas cavernas.)*",
    ["So is there anything else that's special about this dungeon?"] = "Entonces, ¿hay algo más que sea especial en esta mazmorra?",
    ["I'm glad you asked. You might find creatures inside the dungeon drop something called a ferocious ring - they must have foraged them from remains in the area."] = "Me alegra que lo hayas preguntado. Es posible que encuentres criaturas dentro de la mazmorra que dejen caer algo llamado anillo feroz; deben haberlos recolectado de los restos del área.",
    ["Well, that's great and all, but what exactly does it do?"] = "Bueno, eso es genial y todo, pero ¿qué hace exactamente?",
    ["Well, for one thing, they are bound to these caves, so you'll find it has teleport charges that will return you to this place if you command it."] = "Bueno, por un lado, están vinculados a estas cuevas, por lo que encontrarás que tiene cargas de teletransporte que te devolverán a este lugar si lo ordenas.",
    ["Sounds good, but is that it?"] = "Suena bien, pero ¿es eso todo?",
    ["Oh, no. As I said, it is bound to this area, so you'll find that you do more damage to creatures in the dungeon if you are wearing it. Also, if you happen to be near death in the dungeon, it'll save you in a similar manner to a ring of life, teleporting you back to the safety of my presence."] = "Oh, no. Como dije, está vinculado a esta área, por lo que encontrarás que haces más daño a las criaturas en la mazmorra si lo llevas puesto. Además, si estás cerca de la muerte en la mazmorra, te salvará de manera similar a un anillo de vida, teletransportándote de regreso a la seguridad de mi presencia.",
    ["Even if I'm using ranged or magical combat? And what if I'm not in the dungeon when I die wearing it?"] = "¿Incluso si estoy usando combate a distancia o mágico? ¿Y qué pasa si no estoy en el calabozo cuando muera usándolo?",
    ["Calm down, one question at a time. First, it is a powerful artefact and will affect all combat styles. Second, I would be careful about dying outside wearing it. I do not believe it will work anywhere but inside the dungeon here."] = "Cálmate, una pregunta a la vez. Primero, es un artefacto poderoso y afectará a todos los estilos de combate. En segundo lugar, tendría cuidado de no morir afuera usándolo. No creo que funcione en ningún otro lugar que no sea dentro de la mazmorra aquí.",
    ["Thanks for your help, Kuradal."] = "Gracias por tu ayuda, Kuradal.",
    ["No problem. Anything else?"] = "No hay problema. ¿Algo más?",
    ["Can I receive special slayer assignments again?"] = "¿Puedo volver a recibir asignaciones especiales de asesino?",
    ["Sure, I will now start giving you special slayer assignments again."] = "Claro, ahora comenzaré a darte tareas especiales de cazador nuevamente.",
    ["Er...nothing..."] = "Eh... nada...",
    ["*Without a task from her:*"] = "*Sin tarea de ella:*",
    ["Sorry, my dungeon is exclusive only to those who need to go in there."] = "Lo siento, mi mazmorra es exclusiva solo para aquellos que necesitan entrar allí.",
    ["Exclusive?"] = "¿Exclusivo?",
    ["Yes, I only allow pupils of Slayer into this dungeon and only if they need to slayer the creatures I've caught inside."] = "Sí, solo permito que los alumnos de Slayer entren en esta mazmorra y solo si necesitan matar a las criaturas que he atrapado dentro.",
    ["I see. So what creatures do I need to be assigned to kill; what creatures are inside?"] = "Ya veo. Entonces, ¿qué criaturas necesito que me asignen para matar? ¿Qué criaturas hay dentro?",
    ["Well, I took a holiday tour of Gielinor and brought back some 'souvenirs'. Of course, as a Slayer master, 'souvenirs' means hellhounds, greater demons, gargoyles, abyssal demons, airut, dark beasts, and blue, iron, and steel dragons."] = "Bueno, hice un recorrido navideño por Gielinor y traje algunos 'souvenirs'. Por supuesto, como Slayer master, \"souvenirs\" significa perros del infierno, demonios mayores, gárgolas, demonios abisales, airut, bestias oscuras y dragones azules, de hierro y acero.",
    ["I'd usually keep it simple with a postcard."] = "Normalmente lo mantendría sencillo con una postal.",
    ["What was that?"] = "¿Qué fue eso?",
    ["I said that must have been hard."] = "Dije que debe haber sido difícil.",
    ["*With a cannon:*"] = "*Con un cañón:*",
    ["Sorry, no cannons allowed in there. Now I've rounded all these creatures up, I don't particularly want their lair being blasted apart."] = "Lo sentimos, no se permiten cañones allí. Ahora que he reunido a todas estas criaturas, no quiero particularmente que destruyan su guarida.",
    ["Hello there, Player, what can I help you with?"] = "Hola, Player, ¿en qué puedo ayudarte?",
    ["How am I doing so far?"] = "¿Cómo estoy hasta ahora?",
    ["*If you are currently on a Slayer task that is not yet complete: *"] = "*Si actualmente estás en una tarea Slayer que aún no está completa: *",
    ["You're currently assigned to kill [assigned creatures]; only X more to go."] = "Actualmente estás asignado para matar a [assigned creatures]; sólo faltan X más.",
    ["Where are you?"] = "¿Dónde estás?",
    ["Got any tips for me?"] = "¿Tienes algún consejo para mí?",
    ["That's all thanks."] = "Eso es todo gracias.",
    ["*If you have completed your most recent Slayer task: *"] = "*Si has completado tu tarea Slayer más reciente: *",
    ["My name is Kuradal; I'm a Slayer Master."] = "Mi nombre es Kuradal; Soy un Slayer Master.",
    ["You'll find me in the ancient cavern, near the Dragonkin Forge. I'll be here when you need a new task."] = "Me encontrarás en la caverna antigua, cerca de Dragonkin Forge. Estaré aquí cuando necesites una nueva tarea.",
    ["The last [assigned creature] I killed I found [weapons] took them down effectively."] = "El último [assigned creature] que maté descubrí que [weapons] los derribó de manera efectiva.",
    ["[Task hint]"] = "[sugerencia de tarea]",
    ["Nothing really."] = "En realidad, nada.",
    ["Ello, who's this?"] = "Hola, ¿quién es?",
    ["It's Player. I'm using my magic to communicate with you."] = "Soy Player. Estoy usando mi magia para comunicarme contigo.",
    ["A useful application of magical talent. How can I help?"] = "Una aplicación útil del talento mágico. ¿Cómo puedo ayudar?",
    ["Er...nothing."] = "Eh... nada.",
    ["Aberrant spectres are fetid, vile ghosts. The very smell of them will paralyse and harm you. A nosepeg will help ignore their stink when fighting them. They can be found in the Slayer Tower near Canifis and I have heard rumours that they also live beneath Pollnivneach in the desert."] = "Los espectros aberrantes son fantasmas fétidos y viles. El solo olor de ellos te paralizará y te hará daño. Una clavija ayudará a ignorar su hedor cuando luches contra ellos. Se pueden encontrar en la Torre Slayer cerca de Canifis y he escuchado rumores de que también viven debajo de Pollnivneach en el desierto.",
    ["Abyssal demons are nasty creatures to deal with. They aren't really part of this realm and are able to move very quickly to trap their prey. I've managed to trap a few in the dungeon I'm guarding."] = "Los demonios abisales son criaturas desagradables con las que lidiar. En realidad, no son parte de este reino y pueden moverse muy rápidamente para atrapar a sus presas. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
    ["Acheron Mammoths are honourable yet powerful beasts from the frozen north. When they charge you, get out of the way! They can be found on an iceberg that is accessible from a dock near Rellekka."] = "Los mamuts de Acheron son bestias honorables pero poderosas del norte helado. Cuando te cobren, ¡apártate del camino! Se pueden encontrar en un iceberg al que se puede acceder desde un muelle cerca de Rellekka.",
    ["Adamant dragons are even more dangerous than mithril dragons. Look for them in Brimhaven dungeon, beneath a staircase north-west of the iron and steel dragons."] = "Los dragones Adamant son incluso más peligrosos que los dragones de mithril. Búscalos en la mazmorra Brimhaven, debajo de una escalera al noroeste de los dragones de hierro y acero.",
    ["The Airut are aggressive creatures from another world. They have powerful arms and attack with great vigour, certain abilities are able to counter and stun the Airut."] = "Los Airut son criaturas agresivas de otro mundo. Tienen brazos poderosos y atacan con gran vigor, ciertas habilidades son capaces de contrarrestar y aturdir al Airut.",
    ["Aquanites are amphibious creatures that attract prey using the glowing lures on their heads. They attack stronger opponents from a distance with water magic, and dislike those who pray against it. They dwell in the Fremennik Slayer Dungeon, in a chamber past the kurasks."] = "Los acuanitas son criaturas anfibias que atraen a sus presas utilizando los señuelos brillantes que tienen en la cabeza. Atacan a oponentes más fuertes desde la distancia con magia de agua y no les agradan aquellos que rezan en contra de ella. Habitan en la mazmorra Fremennik Slayer, en una cámara más allá de los kurasks.",
    ["The Order of Ascension are magic users. It is strongly suggested you use ranged attacks. Their tactics can make them tough one-on-one, so bringing a friend along would be beneficial."] = "La Orden de la Ascensión son usuarios de magia. Se recomienda encarecidamente utilizar ataques a distancia. Sus tácticas pueden hacerlos difíciles uno a uno, por lo que sería beneficioso traer a un amigo.",
    ["Aviansies can be found in the Godwars Dungeon north of Trollheim. As they are flying, you'll find melee attacks are not going to cut it."] = "Los aviansies se pueden encontrar en Godwars Dungeon al norte de Trollheim. Mientras vuelan, descubrirás que los ataques cuerpo a cuerpo no serán suficientes.",
    ["Black demons are weak to ranged attacks. They're still the strongest demon and very dangerous, however. Seek them out in the Edgeville or Brimhaven dungeons."] = "Los demonios negros son débiles ante los ataques a distancia. Sin embargo, siguen siendo el demonio más fuerte y muy peligroso. Búscalos en las mazmorras Edgeville o Brimhaven.",
    ["Black dragons are among the strongest dragons and are very fierce. Watch out for their fiery breath. I am sure you will have seen them in your travels and have honed your techniques on lesser dragons."] = "Los dragones negros se encuentran entre los dragones más fuertes y son muy feroces. Cuidado con su aliento de fuego. Estoy seguro de que los habrás visto en tus viajes y habrás perfeccionado tus técnicas con dragones menores.",
    ["Bloodvelds are strange, demonic creatures. They use their long, rasping tongue to feed on just about anything they can find. Remember that their tongues are magical in nature, but, more so, they deserve to die."] = "Los Bloodvelds son criaturas extrañas y demoníacas. Utilizan su lengua larga y áspera para alimentarse de casi cualquier cosa que encuentren. Recuerda que sus lenguas son de naturaleza mágica, pero, más aún, merecen morir.",
    ["Blue dragons aren't as strong as other dragons, but they're still very powerful. I've managed to trap a few in the dungeon I'm guarding."] = "Los dragones azules no son tan fuertes como otros dragones, pero siguen siendo muy poderosos. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
    ["Camel warriors can use ancient magics to attack you. They also have the blessings of Akthanakos and can create powerful, disorientating mirages.  They can be found in the deep desert."] = "Los guerreros Camel pueden usar magia antigua para atacarte. También cuentan con las bendiciones de Akthanakos y pueden crear espejismos poderosos y desorientadores.  Se pueden encontrar en lo profundo del desierto.",
    ["Celestial dragons are one of the strangest dragons I assign. They use melee but have a powerful dragonfire as well as a fascinating ability to momentarily stop time. You can find them in the depths of Dragontooth Island."] = "Los dragones celestiales son uno de los dragones más extraños que asigno. Usan combate cuerpo a cuerpo pero tienen un poderoso fuego de dragón, así como una habilidad fascinante para detener el tiempo momentáneamente. Puedes encontrarlos en las profundidades de la isla Dragontooth.",
    ["You can find Chaos giants out in the Barendir tunnels, beyond Keldagrim. Be careful, as they can launch their Dragon throwing axe at range or take a swipe at you if you get close. Perhaps you could recover some."] = "Puedes encontrar gigantes del Caos en los túneles de Barendir, más allá de Keldagrim. Ten cuidado, ya que pueden lanzar su hacha arrojadiza Dragón a distancia o golpearte si te acercas. Quizás puedas recuperar algo.",
    ["You can find corrupted creatures in the Sophanem Slayer Dungeon."] = "Puedes encontrar criaturas corruptas en la mazmorra Sophanem Slayer.",
    ["Without their master, Cres's automatons roam Guthix's chambers, attacking any who enter. They are programmed to use magic, melee or ranged and do a violent area-of-effect attack. Guthix's chambers may be reached via his shrine, or the excavation west of the Legends' Guild."] = "Sin su maestro, los autómatas de Cres deambulan por las cámaras de Guthix, atacando a cualquiera que entre. Están programados para usar magia, cuerpo a cuerpo o a distancia y realizar un violento ataque de área de efecto. Se puede llegar a las cámaras de Guthix a través de su santuario o de la excavación al oeste de Legends' Guild.",
    ["Dagannoth are large, sea-dwelling creatures that are very aggressive. You'll often find them in caves near sea water. There is no joy so great as to cleanse these from the face of Gielinor."] = "Los Dagannoth son criaturas marinas grandes que son muy agresivas. A menudo los encontrarás en cuevas cerca del agua de mar. No hay alegría tan grande como limpiar estos de the face de Gielinor.",
    ["The last Dark beast I killed I found a crossbow with bolts took them down effectively."] = "La última bestia oscura que maté encontré una ballesta con pernos que los derribó de manera efectiva.",
    ["[Dark beasts are large, dog-like predators with massively muscled bodies that protect them from crushing weapons. I've managed to trap a few in the dungeon I'm guarding.]"] = "[Las bestias oscuras son depredadores grandes, parecidos a perros, con cuerpos enormemente musculosos que los protegen de las armas aplastantes. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.]",
    ["You'll find these East of Al Kharid, atop the mountain. Watch out for their vicious ranged attacks!"] = "Los encontrarás al este de Al Kharid, en la cima de la montaña. ¡Cuidado con sus feroces ataques a distancia!",
    ["Dust devils use clouds of dust, sand, ash and whatever else they can inhale to blind and disorientate their victims. Good luck on obtaining a dragon chainmail from their dusty remains."] = "Los remolinos de polvo utilizan nubes de polvo, arena, cenizas y cualquier otra cosa que puedan inhalar para cegar y desorientar a sus víctimas. Buena suerte para obtener una cota de malla de dragón a partir de sus restos polvorientos.",
    ["Edimmu are ghosts which failed to escape their body. They're ghosts and zombies, yet somehow different altogether. They use ranged attacks and are highly aggressive. You can find them in a resource dungeon, which the Meilyr clan in Prifddinas has access to."] = "Edimmu son fantasmas que no lograron escapar de su cuerpo. Son fantasmas y zombis, pero de alguna manera completamente diferentes. Usan ataques a distancia y son muy agresivos. Puedes encontrarlos en una mazmorra de recursos a la que tiene acceso el clan Meilyr en Prifddinas.",
    ["Elves are skilled fighters across all disciplines from whom you could learn a lot. I recommend challenging only one type of elf combatant at a time."] = "Los elfos son luchadores expertos en todas las disciplinas de los que puedes aprender mucho. Recomiendo desafiar sólo a un tipo de combatiente elfo a la vez.",
    ["Like other giants, fire giants often wield large weapons. Learn to recognise what kind of weapon it is and act accordingly. Remember the days when these were a challenge to you and laugh."] = "Al igual que otros gigantes, los gigantes de fuego suelen empuñar armas grandes. Aprende a reconocer qué tipo de arma es y actúa en consecuencia. Recuerda los días en que estos eran un desafío para ti y ríe.",
    ["Ganodermic beasts and runts live in the depths of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Las bestias ganodermicas y los enanos viven en las profundidades de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que debes luchar contra ellas desde la distancia. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
    ["Gargoyles are winged creatures of stone. You'll need to fight them until they are close to death before breaking them apart with a rock hammer. I've managed to trap a few in the dungeon I'm guarding."] = "Las gárgolas son criaturas aladas de piedra. Tendrás que luchar contra ellos hasta que estén al borde de la muerte antes de romperlos con un martillo de piedra. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
    ["You can find gemstone dragons beneath the gem mine in Shilo Village."] = "Puedes encontrar dragones de piedras preciosas debajo de la mina de gemas en Shilo Village.",
    ["Glacors were brought to this world by Lucien. They use magic, ranged and melee attacks. You can find them in an underground cavern on the Frozen Plateau."] = "Lucien trajo los glacors a este mundo. Usan ataques mágicos, a distancia y cuerpo a cuerpo. Puedes encontrarlos en una caverna subterránea en Frozen Plateau.",
    ["Greater demons are weak to ranged attacks. Though not the strongest of demons, they are still dangerous. I've managed to trap a few in the dungeon I'm guarding."] = "Los demonios mayores son débiles ante los ataques a distancia. Aunque no son los demonios más fuertes, siguen siendo peligrosos. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
    ["Grifolapines live in the depths of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance, and dodge when they charge at you. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Los grifolapinos viven en las profundidades de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que debes luchar contra ellas desde la distancia y esquivar cuando cargan contra ti. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
    ["Grifolaroos live in the depths of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance, although they'll try to hop over obstacles towards you. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Los grifolaroos viven en las profundidades de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que deberás luchar contra ellas desde la distancia, aunque intentarán saltar los obstáculos hacia ti. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
    ["Grotworms have recently been spotted in a cave near Rimmington. They will bite and attack with some sort of acid spit. Be careful - they are very aggressive."] = "Recientemente se han visto gusanos grot en una cueva cerca de Rimmington. Morderán y atacarán con una especie de saliva ácida. Tenga cuidado, son muy agresivos.",
    ["Hellhounds are a cross between dogs and demons; they are also dangerous with a fierce bite. I've managed to trap a few in the dungeon I'm guarding."] = "Los Hellhounds son un cruce entre perros y demonios; También son peligrosos con un mordisco feroz. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
    ["The coldest of their kind, they are found beneath the Fremennik mountains. As they are beings of ice, I've found that fire spells inflict far more damage against them."] = "Los más fríos de su tipo, se encuentran debajo de las montañas Fremennik. Como son seres de hielo, descubrí que los hechizos de fuego les infligen mucho más daño.",
    ["Iron dragons are some of the weaker metallic dragons, with iron scales that are far thicker than normal iron armour. Their fiery breath and sharp claws can be negated by a number of means. I've managed to trap a few in the dungeon I'm guarding."] = "Los dragones de hierro son algunos de los dragones metálicos más débiles, con escamas de hierro que son mucho más gruesas que las armaduras de hierro normales. Su aliento de fuego y sus afiladas garras pueden anularse de diversas formas. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
    ["These tricky creatures burrow beneath the jungle north west of Oo'glog. Be careful, as these poisonous jungle wyrms like to use magical attacks from a distance, while they should be weak to stab attacks."] = "Estas engañosas criaturas se esconden bajo la jungla al noroeste de Oo'glog. Ten cuidado, ya que a estos venenosos wyrms de la jungla les gusta usar ataques mágicos desde la distancia, mientras que deberían ser débiles para apuñalar ataques.",
    ["Kal'gerion demons are powerful creatures that use both magic and melee. They reside in a storage dungeon near Daemonheim. I would recommend you take cover when they smash the ground, or when they use magic to pull you towards them."] = "Los demonios Kal'gerion son criaturas poderosas que usan tanto magia como cuerpo a cuerpo. Residen en un calabozo de almacenamiento cerca de Daemonheim. Te recomendaría que te cubrieras cuando rompan el suelo o cuando usen magia para atraerte hacia ellos.",
    ["Kalphites are large insects that live in hives under the desert sands. I am sure that, by now, you have seen them to the south-west of Shantay Pass."] = "Los calfitos son insectos grandes que viven en colmenas bajo las arenas del desierto. Estoy seguro de que ya los habrás visto al suroeste del paso Shantay.",
    ["Lava strykewyrms are the most powerful of their kind. They attack with all combat styles and are weak to nothing. They can be found deep within the Wilderness so I would watch your back while slaying them."] = "Los strykewyrms de lava son los más poderosos de su tipo. Atacan con todos los estilos de combate y son débiles o nada. Se pueden encontrar en lo profundo de Wilderness, por lo que yo te cuidaría las espaldas mientras los mato.",
    ["Found beneath the Dwarven mines, these are tough beings of rock. They can use ranged or melee attacks against you, so plan accordingly!"] = "Estos son seres duros de roca que se encuentran debajo de las minas enanas. Pueden usar ataques a distancia o cuerpo a cuerpo contra ti, ¡así que planifica en consecuencia!",
    ["Living wyverns breathe a poison that will kill you rapidly unless you are freezing. But watch out; the colder you are the harder their regular attacks will hit you.  They can be found in the Asgarnia Ice dungeon."] = "Los wyverns vivos respiran un veneno que te matará rápidamente a menos que te congeles. Pero cuidado; cuanto más frío tengas, más duro te golpearán sus ataques habituales.  Se pueden encontrar en la mazmorra de hielo de Asgarnia.",
    ["Mithril dragons are very dangerous opponents. They live just north of where we are now. You are a battle master - test your skills."] = "Los dragones de mitril son oponentes muy peligrosos. Viven justo al norte de donde estamos ahora. Eres un maestro de batalla: prueba tus habilidades.",
    ["Muspah are creatures born of nightmares. Ancient magic is the most effective thing to use against them. You can find them by travelling to Freneskae. They'll be aggressive unless you wear your shard of Zaros."] = "Los muspah son criaturas nacidas de pesadillas. La magia antigua es lo más eficaz que se puede utilizar contra ellos. Puedes encontrarlos viajando a Freneskae. Serán agresivos a menos que uses tu fragmento de Zaros.",
    ["These warped jade vine creatures will not hesitate to use their environment to help them in combat if they cannot retaliate otherwise. The baby jadinkos are easiest to kill, but the males offer the greatest rewards. Ranged weapons made from vines are best against them."] = "Estas criaturas deformadas de enredadera de jade no dudarán en utilizar su entorno para ayudarles en el combate si no pueden tomar represalias de otra manera. Las crías de jadinkos son más fáciles de matar, pero los machos ofrecen las mayores recompensas. Las armas Ranged hechas de enredaderas son mejores contra ellos.",
    ["Nechryael are demons of decay that summon small winged beings to help them fight their victims. They can be found in the Chaos Tunnels or in Canifis Slayer Tower."] = "Nechryael son demonios de la decadencia que convocan a pequeños seres alados para que les ayuden a luchar contra sus víctimas. Se pueden encontrar en los Túneles del Caos o en la Torre Canifis Slayer.",
    ["You can find nightmare creatures on Freneskae, which can be accessed through the world gate."] = "Puedes encontrar criaturas de pesadilla en Freneskae, a las que se puede acceder a través de la puerta del mundo.",
    ["The surviving subjects of Zaros's experiments. They have powerful charge attacks and fight in packs of four. You can find them by travelling to Freneskae. They'll be aggressive unless you wear your shard of Zaros."] = "Los sujetos supervivientes de los experimentos de Zaros. Tienen poderosos ataques cargados y luchan en grupos de cuatro. Puedes encontrarlos viajando a Freneskae. Serán agresivos a menos que uses tu fragmento de Zaros.",
    ["Ripper Demons are driven crazy by the scent of blood. They will hit you harder the worse your injuries are. And watch out; they can sometimes drop on you from above, which is lethal.  They can be found in a fissure near Al Kharid."] = "Los demonios destripadores se vuelven locos por el olor a sangre. Te golpearán más fuerte cuanto peores sean tus lesiones. Y cuidado; A veces pueden caer sobre ti desde arriba, lo cual es letal.  Se pueden encontrar en una fisura cerca de Al Kharid.",
    ["The last Sanguine werewolf I killed I found earth spells took them down effectively."] = "El último hombre lobo Sanguine que maté descubrí que los hechizos de tierra los derribaron de manera efectiva.",
    ["[Sanguine werewolves are werewolves twisted by the Sanguine. You will find them in Berylbrook on Havenhythe.]"] = "[Los hombres lobo sanguinarios son hombres lobo retorcidos por los sanguinarios. Los encontrarás en Berylbrook en Havenhythe.]",
    ["Skeletal wyverns are extremely dangerous, and they are hard to hit with arrows as they slip right through. To stand a good chance of surviving, you'll need some elemental shielding from their icy breath."] = "Los wyverns esqueléticos son extremadamente peligrosos y es difícil golpearlos con flechas cuando se deslizan a través de ellos. Para tener buenas posibilidades de sobrevivir, necesitarás algo de protección elemental contra su aliento helado.",
    ["You can find soul devourers in the Sophanem Slayer Dungeon."] = "Puedes encontrar devoradores de almas en la mazmorra Sophanem Slayer.",
    ["Spiritual mages are the strongest of the spiritual guardians. They are devastating against warriors, but a smart ranger can sometimes defeat them. Of course, Prayer might serve you well, too. They can be found in the icy caverns near Trollheim, supporting the cause of their chosen god."] = "Los magos espirituales son los más fuertes de los guardianes espirituales. Son devastadores contra los guerreros, pero un explorador inteligente a veces puede derrotarlos. Por supuesto, Prayer también podría resultarle útil. Se pueden encontrar en las cavernas heladas cerca de Trollheim, apoyando la causa de su dios elegido.",
    ["The last Soulgazer I killed I found a bow and arrows took them down effectively."] = "El último Soulgazer que maté encontré un arco y las flechas lo derribaron de manera efectiva.",
    ["[You can find stalker creatures within Zamorak's hideout.]"] = "[Puedes encontrar criaturas acosadoras dentro del escondite de Zamorak.]",
    ["Steel dragons are dangerous and metallic, with steel scales that are far thicker than normal steel armour. I've managed to trap a few in the dungeon I'm guarding."] = "Los dragones de acero son peligrosos y metálicos, con escamas de acero que son mucho más gruesas que las armaduras de acero normales. Me las arreglé para atrapar a algunos en la mazmorra que estoy custodiando.",
    ["Suqahs can only be found on the mystical Lunar Isle. They use melee and magical attacks, and they often drop hide, teeth and herbs."] = "Las suqahs solo se pueden encontrar en el místico Lunar Isle. Usan ataques cuerpo a cuerpo y mágicos y, a menudo, dejan caer piel, dientes y hierbas.",
    ["Terror dogs are, unsurprisingly, dogs that terrorise the weak. You'll find them in the Haunted Mine, near Tarn's lair."] = "Los perros del terror son, como era de esperar, perros que aterrorizan a los débiles. Los encontrarás en la Mina Encantada, cerca de la guarida de Tarn.",
    ["Tormented demons are powerful creatures that use magic, ranged and melee attacks. They also have the ability to shield themselves. You can find them below the Tears of Guthix cave."] = "Los demonios atormentados son criaturas poderosas que usan ataques mágicos, a distancia y cuerpo a cuerpo. También tienen la capacidad de protegerse. Puedes encontrarlos debajo de la cueva Lágrimas de Guthix.",
    ["The TzHaar contains some mighty warriors, prove yourself against them. You'll find them deep within the Karamja volcano."] = "El TzHaar contiene algunos guerreros poderosos, ponte a prueba contra ellos. Los encontrarás en lo profundo del volcán Karamja.",
    ["These are the creatures that live within the TzHaar fightcaves. You'll have to venture down into the cave in the Karamja volcano to take them on."] = "Estas son las criaturas que viven dentro de las cuevas de lucha de TzHaar. Tendrás que aventurarte en la cueva del volcán Karamja para enfrentarte a ellos.",
    ["These foul creatures can be found throughout Meiyerditch and Darkmeyer in Morytania. They have a telepathic ability which enables them to dodge incoming attacks, so you'll need a weapon specially created to harm them."] = "Estas repugnantes criaturas se pueden encontrar en Meiyerditch y Darkmeyer en Morytania. Tienen una habilidad telepática que les permite esquivar los ataques entrantes, por lo que necesitarás un arma especialmente creada para dañarlos.",
    ["Warped tortoises are creatures tainted by magical waste. They are vulnerable to an elven chime. I know you have seen them in your adventures, so go crack some carapace."] = "Las tortugas deformadas son criaturas contaminadas por desechos mágicos. Son vulnerables a un timbre élfico. Sé que los has visto en tus aventuras, así que ve a romper un caparazón.",
    ["Waterfiends are creatures of water that live just north of us. Those followed by familiars are keen to slay these elemental forces."] = "Los Waterfiends son criaturas acuáticas que viven justo al norte de nosotros. Aquellos seguidos por familiares están deseosos de acabar con estas fuerzas elementales.",
    ["I KILL YOU!"] = "¡TE MATÉ!",
    ["No, I kill you!"] = "¡No, te mato!",
    ["UUUHRG! Now I kill you!"] = "¡UUUURG! ¡Ahora te mato!",
    ["How are you going to do that? You're just a head on a wall!"] = "¿Cómo vas a hacer eso? ¡Eres sólo una cabeza en la pared!",
    ["Uhhhhrrr..."] = "Uhhhhrr...",
    ["Why are you so violent?"] = "¿Por qué eres tan violento?",
    ["You kill me! Uuurgh! That make me angry!"] = "¡Me matas! ¡Uuugh! ¡Eso me hace enojar!",
    ["You seemed pretty angry before I killed you."] = "Parecías bastante enojado antes de que te matara.",
    ["I like angry!"] = "¡Me gusta estar enojado!",
    ["I'm sorry I killed you."] = "Lamento haberte matado.",
    ["I hate sorry! Makes me more angry! WANT TO KILL YOU!"] = "¡Odio lo siento! ¡Me enoja más! ¡QUIERO MATARTE!",
    ["Please try to calm down."] = "Por favor, intenta calmarte.",
    ["Hate calm! Smash it! Hur hur hur!"] = "¡Odio la calma! ¡Aplastalo! ¡Hurra, hur, hur!",
    ["I'm not really sorry."] = "Realmente no lo siento.",
    ["That make me more angry! Uuuurgh!"] = "¡Eso me enoja más! ¡Uuuurgh!",
    ["Is there anything that doesn't make you angry?"] = "¿Hay algo que no te haga enojar?",
    ["No! I like angry! Hur hur hur!"] = "¡No! ¡Me gusta enojado! ¡Hurra, hur, hur!",
    ["I killed you really easily!"] = "¡Te maté muy fácilmente!",
    ["Yeah! I could kill you again in my sleep!I think I might go off and kill some other kurask!"] = "¡Sí! ¡Podría volver a matarte mientras duermo! ¡Creo que podría salir y matar a algún otro kurask!",
    ["Uuuurrrh! Hate you!"] = "¡Uuuurrra! ¡Te odio!",
    ["What are you going to do about it? Eh? I totally owned you!"] = "¿Qué vas a hacer al respecto? ¿Eh? ¡Te poseo totalmente!",
    ["Hate you hate you hate you!"] = "¡Odio, te odio, te odias!",
    ["What do you think about up there?"] = "¿Qué piensas de allá arriba?",
