    ["What have the bugs done to you?"] = "¿Qué te han hecho los errores?",
    ["Skitter skitter through head noise in ears behind eyes."] = "Skitter se desliza a través del ruido de la cabeza en los oídos detrás de los ojos.",
    ["HATE THEM! Kill kill kill!"] = "¡LOS ODIO! ¡Mata, mata, mata!",
    ["You can't, you've got no feet!"] = "¡No puedes, no tienes pies!",
